expectedClusterOperationPolicy ::
  ClusterCommand.ClusterOperation ->
  (Int, Subprocess.RetryPolicy, Subprocess.FailureClass)
expectedClusterOperationPolicy operation =
  case operation of
    ClusterCommand.KindReadOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.KindCreateOperation -> minutes 30 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.KindDeleteOperation -> minutes 10 (Subprocess.BoundedRetry 3 2000000) Subprocess.IdempotentAbsence
    ClusterCommand.NvkindCreateOperation -> minutes 30 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.KubectlReadOperation -> minutes 10 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.KubectlApplyOperation -> minutes 10 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.KubectlDeleteOperation -> minutes 10 Subprocess.NeverRetry Subprocess.IdempotentAbsence
    ClusterCommand.KubectlWaitOperation -> minutes 25 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.KubectlExecOperation -> minutes 10 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.OperatorKubectlOperation -> minutes 10 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.HelmUpgradeOperation -> minutes 35 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.HelmDependencyOperation -> minutes 20 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.HelmRepositoryOperation -> minutes 5 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.HelmRenderOperation -> minutes 10 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerExecOperation -> minutes 15 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerProbeOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerBuildOperation -> minutes 45 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerInspectOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerPullOperation -> minutes 20 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerTagOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerCopyOperation -> minutes 15 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerStreamImportOperation -> minutes 20 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.DockerNetworkOperation -> minutes 2 Subprocess.NeverRetry Subprocess.IdempotentAbsence
    ClusterCommand.ContainerRuntimePullOperation -> minutes 15 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.HostProbeOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.HostMutationOperation -> minutes 15 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.CurlProbeOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.ArchiveReadOperation -> minutes 10 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.GpuUserspaceSyncOperation -> minutes 20 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.ImagePublicationLoginOperation ->
      minutes
        2
        (Subprocess.BoundedRetry 6 6000000)
        Subprocess.TransientThenFatal
    ClusterCommand.ImagePublicationInspectOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.ImagePublicationPullOperation -> minutes 20 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.ImagePublicationVerifyOperation ->
      minutes
        15
        (Subprocess.BoundedRetry 6 6000000)
        Subprocess.TransientThenFatal
    ClusterCommand.ImagePublicationTagOperation -> minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.ImagePublicationPushOperation ->
      minutes
        40
        (Subprocess.BoundedRetry 30 50000000)
        Subprocess.TransientThenFatal
    ClusterCommand.ImagePublicationRemoveOperation -> minutes 2 Subprocess.NeverRetry Subprocess.IdempotentAbsence
    ClusterCommand.ImagePublicationCopyOperation ->
      minutes
        40
        (Subprocess.BoundedRetry 30 50000000)
        Subprocess.TransientThenFatal
    -- Sprint 6.44: the model-weight snapshot bootstrap reuses the
    -- image-publication copy policy, so its expected tuple is identical.
    ClusterCommand.ModelSnapshotBootstrapOperation ->
      minutes
        40
        (Subprocess.BoundedRetry 30 50000000)
        Subprocess.TransientThenFatal
    -- Sprint 6.44 follow-on: the tracked-source inventory (`git ls-files -z`)
    -- and the host node version probe reuse the host-probe policy; the web
    -- dependency install reuses the Docker build policy's long deadline.
    ClusterCommand.SourceInventoryOperation ->
      minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.WebToolchainProbeOperation ->
      minutes 2 Subprocess.NeverRetry Subprocess.FatalFailure
    ClusterCommand.WebDependencyInstallOperation ->
      minutes 45 Subprocess.NeverRetry Subprocess.FatalFailure
  where
    minutes count = policyTuple (count * 60 * 1000000)
    policyTuple timeoutMicros retryPolicy failureClass =
      (timeoutMicros, retryPolicy, failureClass)

dispatchCappedEngineMemoryFixture :: IO ()
dispatchCappedEngineMemoryFixture = do
  arguments <- getArgs
  case arguments of
    ["__infernix_unit_linux_memory_breach_fixture"] -> runLinuxMemoryBreachFixture
    ["__infernix_unit_linux_memory_small_fixture"] -> runSmallMemoryFixture
    ["__infernix_unit_nvidia_no_context_fixture"] -> runSmallMemoryFixture
    -- The Apple cases re-exec this image rather than forking it, because the
    -- Apple watchdog loop consumes a `ProcessHandle` and driving it without one
    -- would exercise a different loop than production runs.
    ["__infernix_unit_apple_memory_breach_fixture"] -> runAppleMemoryBreachFixture
    ["__infernix_unit_apple_memory_small_fixture"] -> runAppleSmallMemoryFixture
    _ -> pure ()

runLinuxMemoryBreachFixture :: IO ()
runLinuxMemoryBreachFixture = do
  let payload = BS.replicate (64 * 1024 * 1024) 65
  BS.length payload `seq` threadDelay (60 * 1000000)
  BS.length payload `seq` exitSuccess

-- | The Apple breach child. Darwin's @phys_footprint@ counts dirty anonymous
-- pages, so the payload is written rather than merely reserved, and it is held
-- live across the sleep so the watchdog samples it rather than racing a
-- collection. 512 MiB clears this image's own resident baseline by a wide
-- enough margin that the breach is attributable to the allocation.
runAppleMemoryBreachFixture :: IO ()
runAppleMemoryBreachFixture = do
  let payload = BS.replicate (512 * 1024 * 1024) 65
  BS.length payload `seq` threadDelay (60 * 1000000)
  BS.length payload `seq` exitSuccess

runSmallMemoryFixture :: IO ()
runSmallMemoryFixture = do
  threadDelay 250000
  exitSuccess

-- | The Apple non-breaching child. One Apple sample spawns @top@ once and
-- @footprint@ once per group member, so it costs far more wall clock than a
-- @\/proc@ walk; a 250 ms child could exit before the first complete sample and
-- turn "no breach" into "never looked". Three seconds guarantees the sampler
-- observes this image's real resident baseline.
runAppleSmallMemoryFixture :: IO ()
runAppleSmallMemoryFixture = do
  threadDelay 3000000
  exitSuccess

-- | Phase 1 Sprint 1.21 — the bounded host build-memory kernel.
--
-- Every case that installs a ceiling runs in a spawned child, never in this
-- process image, and the reason is the property the module documents: a
-- process cannot lower its own address-space limit below a reservation its
-- runtime has already taken. This suite's own image reserves the default
-- 1024.65 GiB, so lowering @RLIMIT_AS@ here would succeed and then kill the
-- suite on its next allocation. The children are therefore re-execs of this
-- same binary with an explicit @+RTS -xr@ reservation, which is exactly the
-- shape the built @infernix@ executable bakes through @-with-rtsopts@.
--
-- The installed bound is also one-way within a process: 'establishBoundedBuildMemory'
-- lowers the hard limit as well as the soft one, so it cannot be restored.
-- That is deliberate — a bound a child can raise back is not a bound — and it
-- is the second reason these cases are not run in-process.
buildMemoryFixturePlan :: Int -> Int -> IO BuildMemoryPlan
buildMemoryFixturePlan budgetMib jobs =
  case mkBuildMemoryBudget budgetMib of
    Left reason -> fail reason
    Right budget ->
      case mkBuildConcurrency jobs of
        Left reason -> fail reason
        Right concurrency ->
          either fail pure (deriveBuildMemoryPlan budget concurrency)

-- | The refusal has to name the spawning surface, so an unbounded process
-- image is attributable from one line of output rather than from a compile
-- that quietly grows to a third of the machine.
buildMemoryRefusalNamesSurface :: Either IOException value -> Bool
buildMemoryRefusalNamesSurface outcome =
  case outcome of
    Left failure ->
      "unit build-memory negative case" `isInfixOf` displayException failure
    Right _ -> False

-- | A clean refusal is a positive exit status. GHC reports a signal death as a
-- /negative/ 'ExitFailure', so this also rejects the process being killed
-- rather than failing.
isCleanFailureExit :: ExitCode -> Bool
isCleanFailureExit exitCode =
  case exitCode of
    ExitFailure status -> status > 0
    ExitSuccess -> False

softAddressLimitMib :: IO (Maybe Integer)
softAddressLimitMib = do
  limits <- getResourceLimit ResourceTotalMemory
  pure $
    case softLimit limits of
      ResourceLimit value -> Just (value `div` (1024 * 1024))
      ResourceLimitInfinity -> Nothing
      ResourceLimitUnknown -> Nothing

dispatchBuildMemoryFixture :: IO ()
dispatchBuildMemoryFixture = do
  arguments <- getArgs
  case arguments of
    ["__infernix_unit_build_memory_bound_fixture", scratchDirectory] ->
      runBuildMemoryBoundFixture scratchDirectory
    ["__infernix_unit_build_memory_report_fixture"] -> do
      observed <- softAddressLimitMib
      putStrLn (maybe "unbounded" show observed)
      exitSuccess
    ["__infernix_unit_build_memory_overallocation_fixture"] -> do
      -- Twice the ceiling the parent installed. Under the inherited limit the
      -- runtime's reservation is clamped below the ceiling, so this request is
      -- refused before a single page is touched: the failure is a non-zero
      -- exit, not host memory pressure.
      let payload = BS.replicate (24 * 1024 * 1024 * 1024) 65
      BS.length payload `seq` exitSuccess
    ["__infernix_unit_darwin_heap_cap_overallocation_fixture"] -> do
      activeFlags <- RTSFlags.getRTSFlags
      let activeMaxHeapBlocks =
            RTSFlags.maxHeapSize (RTSFlags.gcFlags activeFlags)
      print activeMaxHeapBlocks
      System.IO.hFlush System.IO.stdout
      unless
        (fromIntegral activeMaxHeapBlocks == darwinHeapCapFixtureExpectedBlocks)
        exitFailure
      -- One 128 MiB GHC-heap ByteArray under an observed 64 MiB RTS heap cap.
      -- A strict ByteString would allocate outside the GHC heap and would not
      -- exercise -M. This request is only twice the cap and cannot create the
      -- historical multi-GiB host-pressure incident even if the RTS regressed.
      let payload =
            ShortByteString.replicate
              (2 * darwinHeapCapFixtureMib * 1024 * 1024)
              65
      ShortByteString.length payload `seq` exitSuccess
    ["__infernix_unit_darwin_build_memory_normal_cleanup_fixture"] -> do
      -- Close the relayed streams while this process-group leader remains
      -- alive. The parent must continue footprint sampling until group absence
      -- instead of treating EOF as the process terminal boundary.
      System.IO.hClose System.IO.stdout
      System.IO.hClose System.IO.stderr
      threadDelay (3 * 1000000)
      exitSuccess
    ["__infernix_unit_darwin_build_memory_exceptional_cleanup_fixture"] -> do
      threadDelay (60 * 1000000)
      exitSuccess
    ["__infernix_unit_toolchain_heap_driver_fixture"] ->
      runToolchainHeapDriverFixture
    ["__infernix_unit_toolchain_heap_helper_fixture"] -> do
      activeRtsMaxHeapBlocks >>= print
      exitSuccess
    _ -> pure ()

-- | Exercise the invocation-borne cap across two Haskell process images. The
-- driver's cap comes from its own @+RTS@ arguments; the helper gets neither RTS
-- arguments nor an inherited environment cap, so it falls back to the cap its
-- own component is linked with. This pins the boundary Sprint 1.21 drew: the
-- caps that bind are the ones passed on the invocation or baked into a
-- component, and nothing crosses the process boundary by inheritance.
runToolchainHeapDriverFixture :: IO ()
runToolchainHeapDriverFixture = do
  driverMaxHeapBlocks <- activeRtsMaxHeapBlocks
  executable <- getExecutablePath
  (helperExit, helperOutput, helperError) <-
    readCreateProcessWithExitCode
      (proc executable ["__infernix_unit_toolchain_heap_helper_fixture"])
      ""
  case (helperExit, readMaybe (takeWhile (not . isSpace) helperOutput) :: Maybe Integer) of
    (ExitSuccess, Just helperMaxHeapBlocks) -> do
      print driverMaxHeapBlocks
      print helperMaxHeapBlocks
      exitSuccess
    _ -> do
      System.IO.hPutStrLn
        System.IO.stderr
        ( "inherited helper heap-cap fixture failed: "
            <> show helperExit
            <> ": "
            <> helperError
        )
      exitFailure

activeRtsMaxHeapBlocks :: IO Integer
activeRtsMaxHeapBlocks =
  fromIntegral . RTSFlags.maxHeapSize . RTSFlags.gcFlags
    <$> RTSFlags.getRTSFlags

darwinHeapCapFixtureMib :: Int
darwinHeapCapFixtureMib = 64

-- 'GHC.RTS.Flags.maxHeapSize' is reported in the RTS's 4096-byte blocks.
darwinHeapCapFixtureExpectedBlocks :: Integer
darwinHeapCapFixtureExpectedBlocks =
  toInteger darwinHeapCapFixtureMib * 1024 * 1024 `div` 4096

closedToolchainTestSuites :: [ToolchainTestSuite]
closedToolchainTestSuites = allToolchainTestSuites

closedToolchainTestSuiteNames :: [String]
closedToolchainTestSuiteNames =
  map toolchainTestSuiteName closedToolchainTestSuites

closedDarwinAppleMaterializerTests :: [DarwinAppleMaterializerTest]
closedDarwinAppleMaterializerTests =
  [ DarwinProductionAudiverisCancellation,
    DarwinInstalledPythonSourceIsolation
  ]

closedDarwinAppleMaterializerTestOptions :: [String]
closedDarwinAppleMaterializerTestOptions =
  [ "--darwin-production-audiveris-cancellation",
    "--darwin-installed-python-source-isolation"
  ]

-- | The control cap this test component is linked with
-- (@-with-rtsopts=-M1024M@ in @infernix.cabal@).
--
-- Named here because the driver/helper fixture below is only discriminating if
-- the cap it passes differs from the one the component already carries.
unitSuiteLinkedHeapMib :: Int
unitSuiteLinkedHeapMib = 1024

-- | The reason text of a refusal, or an empty string when the value was not a
-- refusal at all. Keeps the admission assertions readable without a hanging
-- @case@ inside an argument position.
refusalReason :: Either String a -> String
refusalReason outcome =
  case outcome of
    Left reason -> reason
    Right _ -> ""

-- | The pure half of the Sprint 1.21 admission observations.
--
-- Both refusals the spawn boundary can raise are decided on data, so the
-- malformed, truncated, and populated cases are deterministic here rather than
-- depending on what happens to be resident on the machine running the suite.
runToolchainAdmissionObservationFixture :: IO ()
runToolchainAdmissionObservationFixture = do
  let vmStatPayload =
        unlines
          [ "Mach Virtual Memory Statistics: (page size of 16384 bytes)",
            "Pages free:                                  1000.",
            "Pages active:                                2000.",
            "Pages inactive:                              3000.",
            "Pages speculative:                             500.",
            "Pages throttled:                                 0.",
            "Pages wired down:                              400.",
            "Pages purgeable:                                24."
          ]
  assert
    (parseDarwinVmStatAvailableMib vmStatPayload == Right 70)
    "the Darwin availability parser counts free, speculative, purgeable, and reclaimable inactive pages at the reported page size, the same quantity the Linux lane reads from MemAvailable"
  assert
    ( isLeft
        ( parseDarwinVmStatAvailableMib
            (unlines (filter (not . isInfixOf "Pages inactive") (lines vmStatPayload)))
        )
    )
    "a vm_stat payload missing its inactive counter is a named refusal rather than a smaller availability"
  assert
    ( isLeft
        ( parseDarwinVmStatAvailableMib
            (unlines (filter (not . isInfixOf "Pages purgeable") (lines vmStatPayload)))
        )
    )
    "a vm_stat payload missing a counter is a named refusal rather than a smaller availability"
  assert
    ( isLeft
        ( parseDarwinVmStatAvailableMib
            (unlines (drop 1 (lines vmStatPayload)))
        )
    )
    "a vm_stat payload with no page-size header is a named refusal rather than an assumed page size"
  assert
    ( parseLinuxMemAvailableMib
        (unlines ["MemTotal:       65536000 kB", "MemAvailable:    2097152 kB"])
        == Right 2048
    )
    "the Linux availability parser reads MemAvailable in kB"
  assert
    (isLeft (parseLinuxMemAvailableMib "MemTotal:       65536000 kB\n"))
    "a /proc/meminfo payload with no MemAvailable line is a named refusal"
  let processTablePayload =
        unlines
          [ "    1     0  32624 /sbin/launchd",
            "  100     1  10000 /Users/operator/.ghcup/bin/cabal",
            "  200   100  20000 ghc-9.12.4",
            "  300     1  30000 cabal",
            "  400   300  40000 ghc"
          ]
  assert
    ( fmap (map processRowPid) (parseDarwinProcessTable processTablePayload)
        == Right [1, 100, 200, 300, 400]
    )
    "the Darwin process-table parser reads every row of the fixed ps vector"
  assert
    (isLeft (parseDarwinProcessTable "not a process table row\n"))
    "a malformed process-table row fails the census rather than being skipped"
  assert
    ( fmap
        (foreignToolchainClaimants 100)
        (parseDarwinProcessTable processTablePayload)
        == Right
          [ ForeignToolchainClaimant
              { claimantPid = 300,
                claimantImage = "cabal",
                claimantResidentKib = 30000
              },
            ForeignToolchainClaimant
              { claimantPid = 400,
                claimantImage = "ghc",
                claimantResidentKib = 40000
              }
          ]
    )
    "the census names toolchain images outside this process tree and excludes its own descendants"
  assert
    ( fmap
        (foreignToolchainClaimants 200)
        (parseDarwinProcessTable processTablePayload)
        == Right
          [ ForeignToolchainClaimant
              { claimantPid = 300,
                claimantImage = "cabal",
                claimantResidentKib = 30000
              },
            ForeignToolchainClaimant
              { claimantPid = 400,
                claimantImage = "ghc",
                claimantResidentKib = 40000
              }
          ]
    )
    "the census excludes the toolchain ancestors that started this process, so the account cannot refuse itself"
  assert
    ( foreignToolchainClaimants
        999
        [ ProcessRow
            { processRowPid = 10,
              processRowParentPid = 11,
              processRowResidentKib = 1,
              processRowImage = "ghc"
            },
          ProcessRow
            { processRowPid = 11,
              processRowParentPid = 10,
              processRowResidentKib = 1,
              processRowImage = "cabal"
            }
        ]
        == [ ForeignToolchainClaimant
               { claimantPid = 10,
                 claimantImage = "ghc",
                 claimantResidentKib = 1
               },
             ForeignToolchainClaimant
               { claimantPid = 11,
                 claimantImage = "cabal",
                 claimantResidentKib = 1
               }
           ]
    )
    "a cyclic parent map terminates the ancestry walk instead of hanging the gate"
  assert
    ( all
        isToolchainImageName
        ["cabal", "ghc", "ghc-9.12.4", "ghci", "ghc-pkg", "haddock", "hsc2hs"]
        && not
          ( any
              isToolchainImageName
              ["ghcup", "clang", "ld", "infernix", "node", "python3.12"]
          )
    )
    "the census recognizes Haskell toolchain images and not the native helpers any build runs"

-- | The whole ceiling story, inside one child that installed it.
--
-- Which story that is depends on the lane, so the fixture resolves the mechanism
-- rather than assuming an address-space rlimit exists. Darwin has no such limit
-- at all, and asserting one there is what took every gate command down.
runBuildMemoryBoundFixture :: FilePath -> IO ()
runBuildMemoryBoundFixture scratchDirectory = do
  plan <- buildMemoryFixturePlan (minimumProcessHeapMib * 2) 1
  widerPlan <- buildMemoryFixturePlan (minimumProcessHeapMib * 4) 1
  let sameHeapBudgetMib =
        2 * planRtsHeapMib plan + 3 * toolchainControlHeapMib
  sameHeapDifferentJobsPlan <-
    buildMemoryFixturePlan sameHeapBudgetMib 2
  createDirectoryIfMissing True scratchDirectory

  -- These plans have the same compiler heap and address reservation but one
  -- versus two compiler workers. Observing only either per-compiler number
  -- therefore accepts stale concurrency and recreates the oversubscription
  -- this authority exists to prevent.
  let projectPath = scratchDirectory </> "cabal.project.local"
  writeFile projectPath (renderCabalProjectLocal sameHeapDifferentJobsPlan)
  staleConcurrencyMint <-
    try @IOException
      ( withToolchainSpawnAuthority scratchDirectory plan $ \_authority ->
          pure ()
      )
  assert
    ( planRtsHeapMib sameHeapDifferentJobsPlan == planRtsHeapMib plan
        && planProcessAddressMib sameHeapDifferentJobsPlan
          == planProcessAddressMib plan
        && planJobs sameHeapDifferentJobsPlan /= planJobs plan
    )
    "the stale-concurrency fixture differs only in the job count"
  assert
    (isLeft staleConcurrencyMint)
    "spawn authority cannot be minted from a matching heap cap with stale concurrency"

  let correctProject = renderCabalProjectLocal plan
      expectedReservation =
        "-xr" <> show (planProcessAddressMib plan) <> "M"
      staleReservation =
        "-xr" <> show (planProcessAddressMib plan + 1) <> "M"
  writeFile
    projectPath
    (replaceFirstSubstring expectedReservation staleReservation correctProject)
  staleReservationMint <-
    try @IOException
      ( withToolchainSpawnAuthority scratchDirectory plan $ \_authority ->
          pure ()
      )
  assert
    (isLeft staleReservationMint)
    "spawn authority requires the generated runtime reservation as well as jobs and heap"

  -- Minting consumes one observation, and the spawn boundary re-observes it:
  -- changing the generated settings inside the rank-2 region cannot turn the
  -- already-minted authority into permission to launch under a different plan.
  writeFile projectPath correctProject
  changedAfterMint <-
    try @IOException
      ( withToolchainSpawnAuthority scratchDirectory plan $ \authority -> do
          writeFile
            projectPath
            (renderCabalProjectLocal sameHeapDifferentJobsPlan)
          withBoundedToolchainChild authority (pure ())
      )
  assert
    (isLeft changedAfterMint)
    "the production spawn boundary refuses generated settings changed after authority minting"

  writeFile projectPath correctProject
  productionBoundReached <-
    withToolchainSpawnAuthority scratchDirectory plan $ \authority ->
      withBoundedToolchainChild authority (pure True)
  assert
    productionBoundReached
    "the production authority-to-child path admits the exact generated jobs/heap/address triple"

  let cabalFormatProjectRoot = scratchDirectory </> "test" </> "cabal-format"
      cabalFormatLocalPath = cabalFormatProjectRoot </> "cabal.project.local"
      cabalFormatFreezePath = cabalFormatProjectRoot </> "cabal.project.freeze"
  createDirectoryIfMissing True cabalFormatProjectRoot
  cabalFormatOverlayGate <-
    withToolchainSpawnAuthority scratchDirectory plan $ \authority -> do
      cleanState <-
        try @IOException
          (requireToolchainInvocationProjectState authority ToolchainCabalFormat)
      writeFile cabalFormatLocalPath "packages: unreviewed-local.cabal\n"
      localState <-
        try @IOException
          (requireToolchainInvocationProjectState authority ToolchainCabalFormat)
      removeFile cabalFormatLocalPath
      writeFile cabalFormatFreezePath "constraints: Cabal ==0\n"
      freezeState <-
        try @IOException
          (requireToolchainInvocationProjectState authority ToolchainCabalFormat)
      removeFile cabalFormatFreezePath
      pure (cleanState, localState, freezeState)
  let cabalFormatOverlayGatePassed =
        case cabalFormatOverlayGate of
          (Right (), Left _, Left _) -> True
          _ -> False
  assert
    cabalFormatOverlayGatePassed
    "the Cabal-format invocation fails closed on either sibling project overlay and admits their proven absence"

  -- One authority is one in-process scheduler slot. Coordinate both threads
  -- until the contender is observably blocked on the private MVar; a timing
  -- delay alone could pass without ever scheduling the contender.
  writeFile projectPath correctProject
  withToolchainSpawnAuthority scratchDirectory plan $ \authority -> do
    firstEntered <- MVar.newEmptyMVar
    releaseFirst <- MVar.newEmptyMVar
    firstResult <- MVar.newEmptyMVar
    secondAttempting <- MVar.newEmptyMVar
    secondEntered <- MVar.newEmptyMVar
    secondResult <- MVar.newEmptyMVar
    _ <-
      forkIO
        ( try @SomeException
            ( withBoundedToolchainChild authority $ do
                MVar.putMVar firstEntered ()
                MVar.takeMVar releaseFirst
            )
            >>= MVar.putMVar firstResult
        )
    MVar.takeMVar firstEntered
    secondThread <-
      forkIO
        ( do
            MVar.putMVar secondAttempting ()
            try @SomeException
              (withBoundedToolchainChild authority (MVar.putMVar secondEntered ()))
              >>= MVar.putMVar secondResult
        )
    MVar.takeMVar secondAttempting
    let awaitSingleFlightBlock remainingAttempts
          | remainingAttempts <= 0 = pure False
          | otherwise = do
              contenderStatus <- threadStatus secondThread
              if contenderStatus == ThreadBlocked BlockedOnMVar
                then pure True
                else do
                  yield
                  awaitSingleFlightBlock (remainingAttempts - 1)
    secondBlocked <- awaitSingleFlightBlock (2000 :: Int)
    prematureSecondEntry <- MVar.tryReadMVar secondEntered
    MVar.putMVar releaseFirst ()
    completedFirst <- timeout 2000000 (MVar.takeMVar firstResult)
    completedSecond <- timeout 2000000 (MVar.takeMVar secondResult)
    let completedSuccessfully outcome =
          case outcome of
            Just (Right ()) -> True
            _ -> False
    assert
      ( secondBlocked
          && isNothing prematureSecondEntry
          && completedSuccessfully completedFirst
          && completedSuccessfully completedSecond
      )
      "one toolchain authority serializes concurrent child lifecycle regions until the first exits"
    injectedFailure <-
      try @IOException
        ( withBoundedToolchainChild
            authority
            (ioError (userError "injected toolchain single-flight action failure"))
        )
    entryAfterFailure <-
      withBoundedToolchainChild authority (pure True)
    assert
      (isLeft injectedFailure && entryAfterFailure)
      "an exceptional toolchain child lifecycle releases the authority's single-flight token"

  -- The observation and child creation cannot be one atomic operation: Cabal
  -- reads cabal.project.local after createProcess returns in the parent. The
  -- production argument vector is therefore derived from the opaque authority,
  -- not from that later child read. Replacing the file after the wrapper's
  -- recheck cannot change any member of the bound passed on Cabal's command
  -- line.
  writeFile projectPath correctProject
  postObservationAuthoritySurface <-
    withToolchainSpawnAuthority scratchDirectory plan $ \authority ->
      withBoundedToolchainChild authority $ do
        writeFile
          projectPath
          (renderCabalProjectLocal sameHeapDifferentJobsPlan)
        pure
          ( toolchainInvocationArguments authority ToolchainBuildAll,
            map
              (toolchainInvocationArguments authority . ToolchainTest)
              closedToolchainTestSuites,
            toolchainInvocationArguments authority ToolchainCabalFormat,
            toolchainInvocationLabel authority ToolchainCabalFormat,
            map
              ( toolchainInvocationArguments authority
                  . ToolchainDarwinAppleMaterializerTest
              )
              closedDarwinAppleMaterializerTests
          )
  let ( postObservationArguments,
        postObservationTestArguments,
        postObservationCabalFormatArguments,
        postObservationCabalFormatLabel,
        postObservationDarwinArguments
        ) =
          postObservationAuthoritySurface
  assert
    ( postObservationArguments
        == [ "+RTS",
             "-M" <> show (planControlHeapMib plan) <> "M",
             "-RTS",
             "build",
             "all",
             "--enable-tests",
             "--jobs=" <> show (planJobs plan),
             "--ghc-options=+RTS -M"
               <> show (planRtsHeapMib plan)
               <> "M -xr"
               <> show (planProcessAddressMib plan)
               <> "M -RTS"
           ]
    )
    "the production Cabal argument vector stays bound after the final file observation"
  assert
    ( postObservationTestArguments
        == map
          ( \suiteName ->
              [ "+RTS",
                "-M" <> show (planControlHeapMib plan) <> "M",
                "-RTS",
                "test",
                suiteName,
                "--enable-tests",
                "--jobs=" <> show (planJobs plan),
                "--ghc-options=+RTS -M"
                  <> show (planRtsHeapMib plan)
                  <> "M -xr"
                  <> show (planProcessAddressMib plan)
                  <> "M -RTS"
              ]
          )
          closedToolchainTestSuiteNames
    )
    "every focused Haskell suite has an exact closed authority-derived Cabal vector"
  assert
    ( postObservationCabalFormatArguments
        == [ "+RTS",
             "-M" <> show (planControlHeapMib plan) <> "M",
             "-RTS",
             "test",
             "--project-file=test/cabal-format/cabal.project",
             "--builddir=" <> (scratchDirectory </> ".build" </> "cabal-format"),
             "infernix-cabal-format:test:infernix-cabal-format",
             "--enable-tests",
             "--jobs=" <> show (planJobs plan),
             "--ghc-options=+RTS -M"
               <> show (planRtsHeapMib plan)
               <> "M -xr"
               <> show (planProcessAddressMib plan)
               <> "M -RTS"
           ]
    )
    "the solver-isolated Cabal-format package has one exact closed authority-derived vector"
  assert
    ( postObservationCabalFormatLabel
        == "cabal test --project-file=test/cabal-format/cabal.project --builddir="
          <> (scratchDirectory </> ".build" </> "cabal-format")
          <> " infernix-cabal-format:test:infernix-cabal-format --enable-tests"
    )
    "the Cabal-format diagnostic label carries the exact authority-root build directory"
  assert
    ( postObservationDarwinArguments
        == map
          ( \testOption ->
              [ "+RTS",
                "-M" <> show (planControlHeapMib plan) <> "M",
                "-RTS",
                "test",
                "infernix-apple-materializer",
                "--enable-tests",
                "--test-show-details=direct",
                "--test-options=" <> testOption,
                "--jobs=" <> show (planJobs plan),
                "--ghc-options=+RTS -M"
                  <> show (planRtsHeapMib plan)
                  <> "M -xr"
                  <> show (planProcessAddressMib plan)
                  <> "M -RTS"
              ]
          )
          closedDarwinAppleMaterializerTestOptions
    )
    "both Darwin-only Apple materializer gates have exact non-caller-supplied test-option vectors"
  assert
    ( admitToolchainAccount plan (planBudgetMib plan - 1) []
        == Left
          ( "refusing to start the governed toolchain: the host has "
              <> show (planBudgetMib plan - 1)
              <> " MiB of available memory, below the "
              <> show (planBudgetMib plan)
              <> " MiB account this plan claims ("
              <> show (planJobs plan)
              <> " jobs x "
              <> show (planRtsHeapMib plan)
              <> " MiB compiler heap plus "
              <> show (planJobs plan + 1)
              <> " x "
              <> show (planControlHeapMib plan)
              <> " MiB control/helper claims)"
          )
    )
    "an account larger than observed available host memory is a named admission refusal"
  let namedClaimantRefusal =
        refusalReason
          ( admitToolchainAccount
              plan
              (planBudgetMib plan)
              ["pid 61617 `cabal` (137 MiB resident, attributed not measured)"]
          )
  assert
    ( all
        (`isInfixOf` namedClaimantRefusal)
        ["pid 61617 `cabal`", "did not start", "rather than killed"]
    )
    "a foreign toolchain claimant is a named admission refusal that leaves it running"
  assert
    ( fmap admissionAvailableMib (admitToolchainAccount plan (planBudgetMib plan) [])
        == Right (planBudgetMib plan)
    )
    "an account exactly funded by observed availability with an empty census is admitted"
  runToolchainAdmissionObservationFixture
  assert
    ( ("--jobs=" <> show (planJobs sameHeapDifferentJobsPlan))
        `notElem` postObservationArguments
    )
    "a same-heap stale job count cannot enter the production Cabal argument vector"
  writeFile projectPath correctProject

  -- The top-level image receives the cap on its own invocation. Its Haskell
  -- helper receives no RTS arguments and — since Sprint 1.21 retired the
  -- build-only environment cap that does not bind — no inherited environment
  -- cap either, so it observes the runtime default. That asymmetry is the
  -- honest statement of the ledger: the worker-associated control/helper claim
  -- is a declared account slot, not a cap the kernel inherits into the helper.
  executable <- getExecutablePath
  homeDirectory <- getHomeDirectory
  temporaryDirectory <- getTemporaryDirectory
  -- An explicit environment carrying only the two variables a child always
  -- needs. It is what the authority no longer adds to that matters here: no
  -- RTS cap reaches either image except the one on the driver's own
  -- invocation.
  let childEnvironmentWithoutRtsCap =
        [("HOME", homeDirectory), ("TMPDIR", temporaryDirectory)]
  -- Drive the parent at twice the linked cap deliberately. Passing the linked
  -- value would make an inherited cap and the component's own baked cap
  -- indistinguishable, which is what let the earlier form of this fixture read
  -- as an inheritance proof while proving only the linkage.
  let driverHeapMib = 2 * planControlHeapMib plan
  inheritedHeapCap <-
    timeout
      (30 * 1000000)
      ( readCreateProcessWithExitCode
          ( proc
              executable
              [ "+RTS",
                "-M" <> show driverHeapMib <> "M",
                "-RTS",
                "__infernix_unit_toolchain_heap_driver_fixture"
              ]
          )
            { env = Just childEnvironmentWithoutRtsCap
            }
          ""
      )
  case inheritedHeapCap of
    Nothing ->
      fail "the closed driver/helper heap-cap fixture exceeded its 30-second deadline"
    Just (heapExit, heapOutput, heapError) -> do
      let heapBlocksOf heapMib = toInteger heapMib * 1024 * 1024 `div` 4096
          observedMaxHeapBlocks =
            traverse readMaybe (lines heapOutput) :: Maybe [Integer]
      assert
        (heapExit == ExitSuccess)
        ( "the closed driver/helper heap-cap fixture exits successfully: "
            <> heapError
        )
      assert
        ( observedMaxHeapBlocks
            == Just [heapBlocksOf driverHeapMib, heapBlocksOf unitSuiteLinkedHeapMib]
        )
        "the driver observes the cap on its own invocation and its helper falls back to its linked cap rather than inheriting one"

  darwinEvidenceSurface <-
    withToolchainSpawnAuthority scratchDirectory plan $ \authority ->
      case requireDarwinBuildMemoryValidationAuthority authority of
        Left reason -> pure (Left reason)
        Right darwinAuthority -> do
          buildArguments <-
            either fail pure $
              darwinBuildMemoryInvocationArguments
                darwinAuthority
                DarwinBuildAllWithTests
                scratchDirectory
          installArguments <-
            either fail pure $
              darwinBuildMemoryInvocationArguments
                darwinAuthority
                DarwinInstallAllExecutables
                scratchDirectory
          -- Recheck the exact generated file first, then replace it in the
          -- remaining recheck-to-child-read window. Both validation vectors
          -- must still come only from the retained authority.
          postObservationBuildArguments <-
            withDarwinBuildMemoryValidationChild darwinAuthority $ do
              writeFile
                projectPath
                (renderCabalProjectLocal sameHeapDifferentJobsPlan)
              either fail pure $
                darwinBuildMemoryInvocationArguments
                  darwinAuthority
                  DarwinBuildAllWithTests
                  scratchDirectory
          writeFile projectPath correctProject
          let oneGibibyte = 1024 * 1024 * 1024 :: Word64
          firstSample <-
            either fail pure $
              recordDarwinBuildMemorySample oneGibibyte emptyDarwinBuildMemorySamples
          secondSample <-
            either fail pure $
              recordDarwinBuildMemorySample (2 * oneGibibyte) firstSample
          samples <-
            either fail pure $
              recordDarwinBuildMemorySample (oneGibibyte + oneGibibyte `div` 2) secondSample
          buildEvidence <-
            either fail pure $
              mkDarwinBuildMemoryInvocationEvidence
                DarwinBuildAllWithTests
                0
                123
                samples
          installEvidence <-
            either fail pure $
              mkDarwinBuildMemoryInvocationEvidence
                DarwinInstallAllExecutables
                0
                45
                emptyDarwinBuildMemorySamples
          installedCliIsolation <-
            either fail pure $
              mkDarwinInstalledCliIsolationEvidence 0
          -- The account is a claim that it bounded what the build took, so a
          -- sampled peak that reaches it must refuse rather than render a
          -- multiple at or below 1.00x and exit zero.
          overAccountSamples <-
            either fail pure $
              recordDarwinBuildMemorySample
                (fromIntegral (planToolchainAccountMib plan) * 1024 * 1024)
                emptyDarwinBuildMemorySamples
          overAccountInvocation <-
            either fail pure $
              mkDarwinBuildMemoryInvocationEvidence
                DarwinBuildAllWithTests
                0
                123
                overAccountSamples
          let overAccountSampledPeak =
                mkDarwinBuildMemoryEvidence
                  65536
                  16384
                  49152
                  darwinAuthority
                  darwinBuildMemorySampleIntervalMicros
                  [overAccountInvocation]
                  Nothing
          let missingInstalledCliIsolation =
                mkDarwinBuildMemoryEvidence
                  65536
                  16384
                  49152
                  darwinAuthority
                  darwinBuildMemorySampleIntervalMicros
                  [buildEvidence, installEvidence]
                  Nothing
          assert
            (isLeft missingInstalledCliIsolation)
            "a successful install cannot produce Darwin evidence without the installed-CLI GHCRTS isolation proof"
          evidence <-
            either fail pure $
              mkDarwinBuildMemoryEvidence
                65536
                16384
                49152
                darwinAuthority
                darwinBuildMemorySampleIntervalMicros
                [buildEvidence, installEvidence]
                (Just installedCliIsolation)
          pure
            ( Right
                ( buildArguments,
                  installArguments,
                  postObservationBuildArguments,
                  overAccountSampledPeak,
                  renderDarwinBuildMemoryEvidence evidence
                )
            )
  case (System.Info.os, darwinEvidenceSurface) of
    ("darwin", Right (buildArguments, installArguments, postObservationBuildArguments, overAccountPeakRefusal, report)) -> do
      let driverRtsArguments =
            [ "+RTS",
              "-M" <> show (planControlHeapMib plan) <> "M",
              "-RTS"
            ]
          authorityArguments =
            [ "--jobs=" <> show (planJobs plan),
              "--ghc-options=+RTS -M"
                <> show (planRtsHeapMib plan)
                <> "M -xr"
                <> show (planProcessAddressMib plan)
                <> "M -RTS"
            ]
          buildRoot = scratchDirectory </> "dist-newstyle"
          installRoot = scratchDirectory </> "bin"
      assert
        ( buildArguments
            == driverRtsArguments
              <> [ "build",
                   "all",
                   "--enable-tests",
                   "--builddir=" <> buildRoot
                 ]
              <> authorityArguments
        )
        "Darwin validation build arguments end in the exact authority-derived jobs and RTS limits"
      assert
        ( installArguments
            == driverRtsArguments
              <> [ "install",
                   "all:exes",
                   "--installdir=" <> installRoot,
                   "--install-method=copy",
                   "--overwrite-policy=always",
                   "--builddir=" <> buildRoot
                 ]
              <> authorityArguments
        )
        "Darwin validation install arguments reuse the scratch root and exact authority-derived limits"
      assert
        (postObservationBuildArguments == buildArguments)
        "Darwin validation arguments cannot change after the final committed-file observation"
      assert
        ( "at or above its 8192 MiB claimant account"
            `isInfixOf` refusalReason overAccountPeakRefusal
        )
        "Darwin evidence whose sampled peak reaches the account is not constructible"
      assert
        ( "sampleMetric: sampled peak aggregate physical footprint" `isInfixOf` report
            && "sampleCount: 3" `isInfixOf` report
            && "sampledPeakAggregatePhysicalFootprintBytes: 2147483648" `isInfixOf` report
            && "planAccountToSampledPeakMultiple: 4.00x" `isInfixOf` report
            && "activeColimaPledgeMib: 49152" `isInfixOf` report
            && "planCompilerJobsTimesHeapMib: 6144" `isInfixOf` report
            && "planControlHeapMib: 1024" `isInfixOf` report
            && "planControlClaimCount: 2" `isInfixOf` report
            && "planControlAccountMib: 2048" `isInfixOf` report
            && "planAccountMib: 8192" `isInfixOf` report
            && "installedRuntimeCliInheritedGhcrts: ignored (proved with adversarial invalid GHCRTS)" `isInfixOf` report
            && "excludedHostReserveClaimants: operator CLI parent and fixed observer tools" `isInfixOf` report
            && "invocation.1.exitStatus: 0" `isInfixOf` report
            && "invocation.2.durationMicros: 45" `isInfixOf` report
            && "invocation.2.samplingOutcome: terminal-before-first-fixed-cadence-probe" `isInfixOf` report
            && "invocation.2.sampleCount: 0" `isInfixOf` report
            && "RSS" `notElem` words report
        )
        "Darwin validation renders the typed host, plan, sample, exit, duration, and caveat evidence"
      assert
        (isLeft (mkDarwinInstalledCliIsolationEvidence 1))
        "a nonzero installed-CLI isolation probe cannot enter Darwin evidence"
    ("darwin", Left reason) ->
      fail ("Darwin validation authority unexpectedly refused the Darwin lane: " <> reason)
    (_, Left reason) ->
      assert
        ("available only on Darwin" `isInfixOf` reason)
        "Darwin validation authority explicitly refuses every non-Darwin lane"
    (_, Right _) ->
      fail "Darwin validation authority was minted on a non-Darwin lane"
  writeFile projectPath correctProject

  runDarwinHeapCapOverallocationAssertions
  assert
    ( classifyDarwinBuildMemorySamplingObservation True (Right 4096)
        == DarwinBuildMemorySamplingObserved 4096
    )
    "Darwin sampling continues after relay closure while the footprint observer still sees the live group"
  assert
    ( classifyDarwinBuildMemorySamplingObservation
        False
        (Left "injected footprint observation failure")
        == DarwinBuildMemorySamplingNeedsTerminalSettlement
          False
          "injected footprint observation failure"
    )
    "Darwin sampling enters bounded terminal settlement only after the footprint observer loses the group"
  assert
    ( classifyDarwinBuildMemoryTerminalSettlement True (Right True)
        == Right DarwinBuildMemoryTerminalSettled
    )
    "Darwin terminal settlement requires closed relays and no live group member"
  let terminalSettlementPreservedRelayLag =
        case classifyDarwinBuildMemoryTerminalSettlement False (Right True) of
          Right (DarwinBuildMemoryTerminalPending 1 _) -> True
          _ -> False
  assert
    terminalSettlementPreservedRelayLag
    "Darwin terminal settlement tolerates relay scheduling lag after group disappearance"
  assert
    ( classifyDarwinBuildMemoryTerminalSettlement True (Right False)
        == Right DarwinBuildMemoryTerminalLiveGroup
    )
    "Darwin terminal settlement refuses a footprint failure while the group is still live instead of waiting out an unsampled tail"
  assert
    ( classifyDarwinBuildMemoryTerminalSettlement
        True
        (Left "injected group observation failure")
        == Left "injected group observation failure"
    )
    "Darwin terminal settlement preserves fixed-observer loss as a refusal"
  runDarwinBuildMemoryTerminalSettlementFixtureForTest
  when (System.Info.os == "darwin") $ do
    runDarwinBuildMemoryProcessGroupFixtureForTest
      DarwinBuildMemoryNormalCleanupFixture
    runDarwinBuildMemoryProcessGroupFixtureForTest
      DarwinBuildMemoryExceptionalCleanupFixture

  resolved <- resolveBuildMemoryMechanism
  case resolved of
    Left reason ->
      fail ("the fixture lane resolves no build-memory mechanism: " <> reason)
    Right (UnenforcedLane _) ->
      runHeapCapOnlyBoundFixture scratchDirectory plan widerPlan
    Right (EnforcedLane _) ->
      runEnforcedAddressSpaceBoundFixture scratchDirectory plan widerPlan

runDarwinHeapCapOverallocationAssertions :: IO ()
runDarwinHeapCapOverallocationAssertions =
  when (System.Info.os == "darwin") $ do
    executable <- getExecutablePath
    completed <-
      timeout
        (30 * 1000000)
        ( readCreateProcessWithExitCode
            ( proc
                executable
                [ "+RTS",
                  "-M" <> show darwinHeapCapFixtureMib <> "M",
                  "-xr256M",
                  "-RTS",
                  "__infernix_unit_darwin_heap_cap_overallocation_fixture"
                ]
            )
            ""
        )
    case completed of
      Nothing ->
        fail "the bounded Darwin RTS heap-cap adversary exceeded its 30-second deadline"
      Just (overExit, activeHeapOutput, _) -> do
        let activeMaxHeapBlocks =
              readMaybe (takeWhile (not . isSpace) activeHeapOutput) :: Maybe Integer
        assert
          (activeMaxHeapBlocks == Just darwinHeapCapFixtureExpectedBlocks)
          "the Darwin adversary observes the exact active RTS maxHeapSize before allocation"
        assert
          (isCleanFailureExit overExit)
          "allocating twice a 64 MiB Darwin RTS heap cap exits ordinary nonzero without host pressure"

-- | Whether an enforced-lane mint returned the plan's derived ceiling. An
-- unenforced result is a failure here: on this lane the ceiling is installed,
-- so anything else means the mint took the wrong arm.
enforcedCeilingMatchesPlan ::
  BuildMemoryPlan ->
  Either (BuildMemoryBound 'AddressSpaceUnavailable) (BuildMemoryBound 'AddressSpaceEnforced) ->
  Bool
enforcedCeilingMatchesPlan plan outcome =
  case outcome of
    Right bound -> enforcedAddressCeilingMib bound == planProcessAddressMib plan
    Left _ -> False

-- | Whether an unenforced-lane mint returned the plan's derived ceiling. The
-- number is derived rather than guaranteed here, which is why it is read with
-- 'buildMemoryBoundCeilingMib' and not 'enforcedAddressCeilingMib' — the latter
-- does not typecheck against this arm, which is the whole point of the index.
heapCapCeilingMatchesPlan ::
  BuildMemoryPlan ->
  Either (BuildMemoryBound 'AddressSpaceUnavailable) (BuildMemoryBound 'AddressSpaceEnforced) ->
  Bool
heapCapCeilingMatchesPlan plan outcome =
  case outcome of
    Left bound -> buildMemoryBoundCeilingMib bound == planProcessAddressMib plan
    Right _ -> False

-- | The lane that installs no address-space ceiling. The bound here is the
-- committed runtime heap cap, so the cases that carry content are the two
-- refusals — an absent cap and a stale one — and the real compile beneath it.
runHeapCapOnlyBoundFixture ::
  FilePath -> BuildMemoryPlan -> BuildMemoryPlan -> IO ()
runHeapCapOnlyBoundFixture scratchDirectory plan widerPlan = do
  let projectPath = scratchDirectory </> "cabal.project.local"
  removeTestPathIfPresent projectPath

  absent <-
    try @IOException
      (requireBoundedBuildMemory scratchDirectory "unit heap-cap absent case" plan)
  assert
    (isLeft absent)
    "a lane with no address-space enforcement refuses when no runtime heap cap is committed at all"

  writeFile projectPath (renderCabalProjectLocal widerPlan)
  stale <-
    try @IOException
      (requireBoundedBuildMemory scratchDirectory "unit heap-cap stale case" plan)
  assert
    (planRtsHeapMib widerPlan /= planRtsHeapMib plan)
    "the wider fixture plan really commits a different heap cap, so the stale case is not vacuous"
  assert
    (isLeft stale)
    "a committed runtime heap cap that disagrees with the derived plan is refused, not accepted"

  writeFile projectPath (renderCabalProjectLocal plan)
  observed <-
    requireBoundedBuildMemory scratchDirectory "unit heap-cap agreeing case" plan
  assert
    (heapCapCeilingMatchesPlan plan observed)
    "an unenforced lane mints a bound only from a committed heap cap that matches the plan"

  runBoundedCompilerChainAssertions scratchDirectory
  exitSuccess

runEnforcedAddressSpaceBoundFixture ::
  FilePath -> BuildMemoryPlan -> BuildMemoryPlan -> IO ()
runEnforcedAddressSpaceBoundFixture scratchDirectory _callerPlan widerPlan = do
  -- Phase 1 Sprint 1.37: this fixture does not run in a pristine process image.
  --
  -- On the enforced lane the governed toolchain invocation installs its ceiling
  -- and every descendant inherits it: @infernix test unit@ spawns Cabal inside
  -- 'withBoundedToolchainChild', so the container lane's committed @-xr14187M@
  -- reaches this child through two execs, and a soft limit of 14187 MiB is what
  -- it measurably observes. Stating the negative case against an /unbounded/
  -- address space therefore asserted a state the lane guarantees it will not be
  -- in; it could only hold under a bare @cabal test@, which this repository does
  -- not use for validation. Inheriting the bound is the intended behaviour
  -- rather than the defect — the caller's own assertion names inheritance as one
  -- of the things this child proves.
  --
  -- So the fixture derives its own floor plan: the tightest ceiling a plan can
  -- carry, the per-process heap floor times the address-space multiplier. Any
  -- lane able to host this toolchain installs a limit above that, so the
  -- refusal, the install, the observation, and the lower-only preservation are
  -- each exercised against a real inherited bound instead of against its
  -- absence.
  plan <-
    buildMemoryFixturePlan
      (minimumProcessHeapMib + 2 * toolchainControlHeapMib)
      1
  observedLimitMib <- softAddressLimitMib
  assert
    (maybe True (> toInteger (planProcessAddressMib plan)) observedLimitMib)
    ( "the inherited address-space limit leaves room for the floor plan: "
        <> "observed a soft limit of "
        <> maybe "unbounded" (\mib -> show mib <> " MiB") observedLimitMib
        <> " against the floor ceiling of "
        <> show (planProcessAddressMib plan)
        <> " MiB, so the refusal case is not representable on this lane"
    )
  refused <-
    try @IOException
      ( requireBoundedBuildMemory
          scratchDirectory
          "unit build-memory negative case"
          plan
      )
  assert
    (buildMemoryRefusalNamesSurface refused)
    ( "requireBoundedBuildMemory refuses an address space wider than the "
        <> "derived ceiling and names the spawning surface; the fixture "
        <> "observed a soft address limit of "
        <> maybe "unbounded" (\mib -> show mib <> " MiB") observedLimitMib
        <> " against a derived per-process ceiling of "
        <> show (planProcessAddressMib plan)
        <> " MiB"
    )

  established <- establishBoundedBuildMemory scratchDirectory plan
  assert
    (enforcedCeilingMatchesPlan plan established)
    "establishBoundedBuildMemory installs the derived per-process address-space ceiling"

  observed <-
    requireBoundedBuildMemory
      scratchDirectory
      "unit build-memory positive case"
      plan
  assert
    (enforcedCeilingMatchesPlan plan observed)
    "requireBoundedBuildMemory observes the installed ceiling"

  -- A wider derived plan must not widen an installed ceiling: the bound is
  -- lower-only, exactly as the descriptor-space kernel is.
  preserved <- establishBoundedBuildMemory scratchDirectory widerPlan
  assert
    (planProcessAddressMib widerPlan > planProcessAddressMib plan)
    "the wider fixture plan really is wider, so the preservation case is not vacuous"
  assert
    (enforcedCeilingMatchesPlan plan preserved)
    "establishBoundedBuildMemory never raises a tighter address-space limit"

  executable <- getExecutablePath

  -- Inherited across fork/exec without the child doing anything itself. The
  -- child carries the default 1024.65 GiB reservation request, so its runtime
  -- has to clamp to the inherited limit to start at all; that it reports the
  -- limit at all is the clamping half of the proof.
  (reportExit, reportedLimit, _) <-
    readCreateProcessWithExitCode
      (proc executable ["__infernix_unit_build_memory_report_fixture"])
      ""
  assert
    (reportExit == ExitSuccess)
    "a child started under the installed ceiling runs rather than failing to reserve"
  assert
    (filter (not . isSpace) reportedLimit == show (planProcessAddressMib plan))
    "the per-process ceiling is inherited across fork and exec unchanged"

  runBoundedCompilerChainAssertions scratchDirectory

  -- Adversarial over-allocation under the ceiling: a clean non-zero exit, no
  -- global out-of-memory condition. The explicit reservation request is larger
  -- than the ceiling on purpose, so the runtime has to clamp it; the 24 GiB
  -- request is then refused rather than committed.
  (overExit, _, _) <-
    readCreateProcessWithExitCode
      ( proc
          executable
          [ "+RTS",
            "-xr16384M",
            "-RTS",
            "__infernix_unit_build_memory_overallocation_fixture"
          ]
      )
      ""
  assert
    (isCleanFailureExit overExit)
    "an over-allocation under the installed ceiling exits non-zero and cleanly"

  exitSuccess

-- | The real compiler, under whatever bound this lane installed. This is the
-- chain the doctrine claims and it is checked rather than asserted: a compile
-- needing more than the bound allows fails here. It carries content on both
-- lanes, which is why it is shared rather than living in the enforced arm.
runBoundedCompilerChainAssertions :: FilePath -> IO ()
runBoundedCompilerChainAssertions scratchDirectory = do
  compilerPath <- firstExistingHostToolCandidate HostTools.HostGhc
  case compilerPath of
    Nothing ->
      putStrLn
        "build-memory: no ghc on this image; the compiler-chain case is skipped loudly"
    Just ghcPath -> do
      let sourcePath = scratchDirectory </> "BoundedBuildMemoryProbe.hs"
          outputPath = scratchDirectory </> "BoundedBuildMemoryProbe"
      createDirectoryIfMissing True scratchDirectory
      writeFile sourcePath "module Main (main) where\nmain :: IO ()\nmain = pure ()\n"
      (compileExit, _, compileErrors) <-
        readCreateProcessWithExitCode
          (proc ghcPath ["-v0", "-o", outputPath, sourcePath])
          ""
      assert
        (compileExit == ExitSuccess)
        ( "the compiler runs under the bound this lane installed: "
            <> compileErrors
        )

firstExistingHostToolCandidate :: HostTools.HostTool -> IO (Maybe FilePath)
firstExistingHostToolCandidate tool = go (HostTools.hostToolFallbackCandidates tool)
  where
    go [] = pure Nothing
    go (candidate : remaining) = do
      present <- doesFileExist candidate
      if present then pure (Just candidate) else go remaining

-- | The pure half: the arithmetic, the committed floor, and the generated
-- project file. None of it installs anything.
runBuildMemoryAssertions :: FilePath -> IO ()
runBuildMemoryAssertions unitTestRoot = do
  assert
    toolchainReservationFitsEveryPlan
    "the executable's baked address-space reservation fits under every ceiling the mint can produce"
  assert
    (toolchainAddressSpaceReservationMib < minimumProcessAddressMib)
    "the reservation invariant is stated in the same units the plan is"
  assert
    (minimumProcessAddressMib == minimumProcessHeapMib * heapToAddressSpaceMultiplier)
    "the address-space floor is derived from the heap floor rather than declared separately"
  assert
    ( isLeft
        ( mkDarwinBuildMemoryInvocationEvidence
            DarwinBuildAllWithTests
            0
            1
            emptyDarwinBuildMemorySamples
        )
    )
    "the measurement-bearing Darwin build refuses terminal evidence without a physical-footprint sample"
  assert
    ( isRight
        ( mkDarwinBuildMemoryInvocationEvidence
            DarwinInstallAllExecutables
            0
            1
            emptyDarwinBuildMemorySamples
        )
    )
    "a reused Darwin install may record explicit terminal-before-first-probe evidence without fabricating a sample"

  let committedAccountMib =
        committedBuildJobs * minimumProcessHeapMib
          + (committedBuildJobs + 1) * toolchainControlHeapMib
  plan <- buildMemoryFixturePlan committedAccountMib committedBuildJobs
  assert
    (planRtsHeapMib plan == minimumProcessHeapMib)
    "the per-process heap cap is the budget divided by the job count"
  assert
    ( planProcessAddressMib plan
        == planRtsHeapMib plan * heapToAddressSpaceMultiplier
    )
    "the per-process address-space ceiling is derived from the heap cap"
  assert
    (planToolchainAccountMib plan <= planBudgetMib plan)
    "the plan's complete compiler and control/helper account never exceeds its budget"
  assert
    ( checkedToolchainAccountMib
        (planJobs plan)
        (planRtsHeapMib plan)
        (planControlHeapMib plan)
        (planBudgetMib plan)
        == Right (planToolchainAccountMib plan)
    )
    "Darwin validation checks the complete compiler and control/helper account before spawn"
  assert
    (isLeft (checkedToolchainAccountMib maxBound 2 1 maxBound))
    "Darwin validation refuses complete-claimant integer overflow before spawn"
  assert
    ( isLeft
        ( checkedToolchainAccountMib
            1
            minimumProcessHeapMib
            toolchainControlHeapMib
            (minimumProcessHeapMib + 2 * toolchainControlHeapMib - 1)
        )
    )
    "Darwin validation refuses a complete claimant sum above the account budget"

  -- The failure this module exists for: a per-process ceiling that was never
  -- divided by its concurrency. A budget that cannot fund its job count at the
  -- calibrated floor is refused by name, with both operands in the message.
  let starved = mkBuildMemoryBudget (minimumProcessHeapMib * 4)
  case starved of
    Left reason -> assert False ("the fixture budget must be constructible: " <> reason)
    Right budget ->
      case mkBuildConcurrency 8 of
        Left reason -> assert False ("8 jobs must be constructible: " <> reason)
        Right concurrency ->
          case deriveBuildMemoryPlan budget concurrency of
            Right _ ->
              assert
                False
                "deriveBuildMemoryPlan must refuse a budget that starves its job count"
            Left reason -> do
              assert
                (show (minimumProcessHeapMib :: Int) `isInfixOf` reason)
                "the starved-derivation refusal names the calibrated floor"
              assert
                ("8 jobs" `isInfixOf` reason)
                "the starved-derivation refusal names the job count it divided by"

  assert
    (isLeft (mkBuildConcurrency (maximumBuildJobs + 1)))
    "a job count above the account's cap is refused rather than silently clamped"
  assert
    (isLeft (mkBuildConcurrency 0))
    "a zero job count is refused"
  assert
    ( isLeft
        ( mkBuildMemoryBudget
            (minimumProcessHeapMib + 2 * toolchainControlHeapMib - 1)
        )
    )
    "a budget that cannot fund one compiler and both required control slots is refused"

  -- The committed floor in `cabal.project` and the compile-fixture project is
  -- the same pair this module mints, so the two cannot drift apart.
  assert
    (committedRtsHeapMib == minimumProcessHeapMib)
    "the committed cabal.project heap cap is the calibrated floor"
  assert
    ( committedProcessAddressMib
        == committedRtsHeapMib * heapToAddressSpaceMultiplier
    )
    "the committed cabal.project address-space reservation is derived from its heap cap"
  assert
    (committedBuildJobs <= maximumBuildJobs)
    "the committed job count is inside the account's cap"
  assert
    (planCompilerHeapAccountMib plan + planControlAccountMib plan == committedAccountMib)
    "the committed account includes both compiler and control/helper claimants"

  let rendered = renderCabalProjectLocal plan
  assert
    (("jobs: " <> show (planJobs plan)) `isInfixOf` rendered)
    "the generated cabal.project.local states its job count"
  assert
    (("-M" <> show (planRtsHeapMib plan) <> "M") `isInfixOf` rendered)
    "the generated cabal.project.local states its per-process heap cap"
  assert
    (("-xr" <> show (planProcessAddressMib plan) <> "M") `isInfixOf` rendered)
    "the generated cabal.project.local bounds the compiler's own address-space reservation"
  assert
    ( "compiler subtotal" `isInfixOf` rendered
        && "control/helper subtotal" `isInfixOf` rendered
        && (show (planToolchainAccountMib plan) <> " MiB total") `isInfixOf` rendered
    )
    "the generated cabal.project.local states every subtotal, because a per-process cap is not a host bound"

  -- The measured Linux fact the ceiling is derived from.
  assert
    (parseMemTotalMib "MemTotal:       131004488 kB\nMemFree: 1 kB\n" == Just 127934)
    "MemTotal is parsed from /proc/meminfo in MiB"
  assert
    (isNothing (parseMemTotalMib "MemFree:        131004488 kB\n"))
    "a /proc/meminfo payload without MemTotal is not defaulted"
  assert
    (isNothing (parseMemTotalMib "MemTotal:       131004488 MB\n"))
    "a MemTotal line in an unexpected unit is refused rather than reinterpreted"
  assert
    (isNothing (parseMemTotalMib "MemTotal:       0 kB\n"))
    "a zero MemTotal is refused rather than funding a ceiling"

  -- The behavioural half, in a child that can install the ceiling.
  executable <- getExecutablePath
  let scratchDirectory = unitTestRoot </> "build-memory"
  createDirectoryIfMissing True scratchDirectory
  (boundExit, boundOut, boundErrors) <-
    readCreateProcessWithExitCode
      ( proc
          executable
          [ "+RTS",
            "-xr1024M",
            "-RTS",
            "__infernix_unit_build_memory_bound_fixture",
            scratchDirectory
          ]
      )
      ""
  unless (null boundOut) (putStr boundOut)
  assert
    (boundExit == ExitSuccess)
    ( "the bounded build-memory child proves install, refusal, inheritance, the "
        <> "compiler chain, and a clean over-allocation failure: "
        <> boundErrors
    )

-- | Phase 6 Sprint 6.44 follow-on — the bounded descriptor space.
--
-- The behavioural half of the correction for the pre-@exec@ descriptor walk
-- that @close_fds = True@ performs. A containerd pod's soft @RLIMIT_NOFILE@ is
-- @1073741816@, and a spawn at that limit was measured at 313 s inside a
-- container started with exactly that @--ulimit@, against a 5 s observer
-- deadline. These assertions pin the three properties the correction rests on:
-- the bound holds in this process image, a spawn kernel refuses to spawn
-- without it, and establishing it never /raises/ a limit a host already set
-- tighter.
--
-- Every case that mutates the limit restores it, because leaving it raised
-- would make every later spawn in this suite fail closed.
-- | The refusal has to name the spawning kernel, so an unbounded process image
-- is attributable from one line of output rather than from a stalled deadline.
descriptorRefusalNamesKernel :: Either IOException value -> Bool
descriptorRefusalNamesKernel outcome =
  case outcome of
    Left failure ->
      "unit descriptor-space negative case" `isInfixOf` displayException failure
    Right _ -> False

-- | Phase 1 Sprint 1.33: the native artifact marker is a line of the runner's
-- output, not the whole stream. The measured Core ML basic-pitch shape below is
-- the one that regressed: real diagnostics ahead of a real marker.
runNativeArtifactMarkerAssertions :: IO ()
runNativeArtifactMarkerAssertions = do
  let marker path = "infernix-native-artifact-file:" <> path
  assert
    (nativeArtifactMarkerPathsForTest (marker "/tmp/out.mid") == ["/tmp/out.mid"])
    "a stream whose only line is the marker names one artifact"
  assert
    ( nativeArtifactMarkerPathsForTest
        ( Text.unlines
            [ "Predicting MIDI for /models/basic-pitch/input.wav",
              "isfinite: True",
              "shape: (1, 43844, 1)",
              marker "/tmp/basic-pitch/out.mid"
            ]
        )
        == ["/tmp/basic-pitch/out.mid"]
    )
    "runner diagnostics ahead of the marker do not hide it"
  assert
    (null (nativeArtifactMarkerPathsForTest "isfinite: True\nshape: (1, 43844, 1)\n"))
    "a stream with no marker stays inline output"
  assert
    ( length
        ( nativeArtifactMarkerPathsForTest
            (Text.unlines [marker "/tmp/one.mid", marker "/tmp/two.mid"])
        )
        == 2
    )
    "two marker lines are both seen, so the caller can refuse rather than pick"
  assert
    (nativeArtifactMarkerPathsForTest ("  " <> marker "/tmp/out.mid" <> "  ") == ["/tmp/out.mid"])
    "surrounding whitespace on the marker line is stripped before matching"

-- | Phase 1 Sprint 1.34: a sealed engine artifact is not a cache directory. The
-- two lists must agree — a rendered name the filter does not know is a name the
-- ambient environment can still supply.
runAppleRuntimeEnvironmentAssertions :: IO ()
runAppleRuntimeEnvironmentAssertions = do
  let installRoot = "/opt/infernix/engines/apple/basic-pitch"
      scratchRoot = "/var/folders/scratch"
      rendered = CappedEngineInternal.appleRuntimeEnvironmentForTest installRoot scratchRoot
      lookupName name = lookup name rendered
  assert
    (all ((`elem` CappedEngineInternal.appleRuntimeEnvironmentNamesForTest) . fst) rendered)
    "every name the Apple runtime environment renders is one the inherited filter drops"
  assert
    (lookupName "NUMBA_CACHE_DIR" == Just (scratchRoot </> "infernix-numba-cache"))
    "the Numba cache resolves under the supplied scratch root"
  assert
    ( maybe
        False
        (not . isPrefixOf installRoot)
        (lookupName "NUMBA_CACHE_DIR")
    )
    "the Numba cache is not written inside the sealed install root"
  assert
    (lookupName "PYTHONDONTWRITEBYTECODE" == Just "1" && lookupName "PYTHONNOUSERSITE" == Just "1")
    "the sealed artifact still refuses bytecode writes and user site packages"

runDescriptorSpaceAssertions :: IO ()
runDescriptorSpaceAssertions = do
  established <- requireBoundedDescriptorSpace "unit descriptor-space assertion"
  assert
    (descriptorSpaceBoundLimit established <= spawnDescriptorLimitCeiling)
    "the unit process image runs inside the established descriptor bound"

  original <- getResourceLimit ResourceOpenFiles
  let restore = setResourceLimit ResourceOpenFiles original
  flip finally restore $ do
    -- An unbounded descriptor space is a named refusal, not a stall. The raised
    -- value stays modest: if this assertion ever leaks it, later spawns fail
    -- closed rather than taking five minutes each.
    setResourceLimit
      ResourceOpenFiles
      original {softLimit = ResourceLimit (spawnDescriptorLimitCeiling * 2)}
    refused <-
      try @IOException
        (requireBoundedDescriptorSpace "unit descriptor-space negative case")
    assert
      (descriptorRefusalNamesKernel refused)
      "requireBoundedDescriptorSpace refuses an unbounded descriptor space and names the spawning kernel"

    -- Re-establishing from an unbounded space brings it back under the ceiling.
    reestablished <- establishBoundedDescriptorSpace
    assert
      (descriptorSpaceBoundLimit reestablished == spawnDescriptorLimitCeiling)
      "establishBoundedDescriptorSpace lowers an unbounded soft limit to the ceiling"

    -- A host that already imposes a tighter limit keeps it: the bound is only
    -- ever lowered, so establishing it cannot widen a descriptor space.
    let tighter = 512
    setResourceLimit
      ResourceOpenFiles
      original {softLimit = ResourceLimit tighter}
    preserved <- establishBoundedDescriptorSpace
    assert
      (descriptorSpaceBoundLimit preserved == tighter)
      "establishBoundedDescriptorSpace preserves a tighter host-imposed soft limit"

-- | Phase 4 Sprint 4.39 — the artifact-derived memory requirement.
--
-- Every fixture builds its artifact in the test rather than checking in a binary
-- blob, then mutates one property at a time. Each mutation carries the positive
-- control that the unmutated artifact derives cleanly, because a negative
-- fixture that would fail for an unrelated reason proves nothing.
runArtifactRequirementAssertions :: FilePath -> IO ()
runArtifactRequirementAssertions unitTestRoot = do
  let artifactRoot = unitTestRoot </> "artifact-requirements"
  createDirectoryIfMissing True artifactRoot

  -- The closed cache function, pinned against SmolLM2-135M-Instruct's declared
  -- geometry: thirty layers, three key/value heads, sixty-four wide heads, two
  -- bytes per element, keys and values counted separately.
  let smolGeometry = ModelGeometry 30 3 64 576
  assert
    (keyValueCacheBytes smolGeometry 2048 2 == 47185920)
    "Sprint 4.39: the cache term is exactly 45.0 MiB at a 2048-token context"
  assert
    ( keyValueCacheBytes smolGeometry 4096 2
        == 2 * keyValueCacheBytes smolGeometry 2048 2
    )
    "Sprint 4.39: the cache term is exactly linear in context length"
  assert
    (modelRequirementBytesToMib 47185920 == 45)
    "Sprint 4.39: byte quantities round up to whole MiB"
  assert
    (modelRequirementBytesToMib (47185920 + 1) == 46)
    "Sprint 4.39: a rounded requirement never understates what was measured"

  -- The positive control: a well-formed safetensors artifact derives cleanly and
  -- its weight term is the exact sum over its own tensor table.
  let cleanPath = artifactRoot </> "clean.safetensors"
      -- The largest tensor is deliberately neither the first nor the last entry,
      -- so a reader that reported the head or the tail of its own table rather
      -- than the maximum over it would fail this fixture instead of passing it.
      cleanTensors =
        [ ("model.embed_tokens.weight", "F16", [576, 128] :: [Int]),
          ("model.layers.0.self_attn.k_proj.weight", "F16", [192, 576]),
          ("model.layers.0.mlp.down_proj.weight", "F16", [576, 64])
        ]
      cleanTensorBytes = [product dims * 2 | (_, _, dims) <- cleanTensors]
      cleanWeightBytes = sum cleanTensorBytes
      cleanLargestBytes = maximum cleanTensorBytes
  BS.writeFile cleanPath (safetensorsArtifactBytes cleanTensors)
  cleanHeader <- readArtifactHeader cleanPath
  assert
    (fmap artifactHeaderWeightBytes cleanHeader == Right (toInteger cleanWeightBytes))
    "Sprint 4.39: the weight term is the exact sum over the artifact's own tensor table"
  assert
    (fmap artifactHeaderLargestTensorBytes cleanHeader == Right (toInteger cleanLargestBytes))
    "Sprint 4.39: the largest single tensor is reported beside the total"
  assert
    (either (const False) ((< 4096) . artifactHeaderPrefixBytes) cleanHeader)
    "Sprint 4.39: the derivation reads only the header prefix, not the payload"

  -- Each mutation yields no requirement rather than a small one.
  mapM_
    (assertArtifactRefusal artifactRoot)
    [ ( "declared-header-past-file",
        \bytes -> BS.pack [255, 255, 255, 255, 255, 255, 0, 0] <> BS.drop 8 bytes
      ),
      ( "tensor-extent-disagrees-with-shape",
        mutateSafetensorsTable "[576,128]" "[576,129]"
      ),
      ( "offsets-overlap",
        mutateSafetensorsTable "\"data_offsets\":[147456," "\"data_offsets\":[147455,"
      ),
      ( "offsets-leave-a-gap",
        mutateSafetensorsTable "\"data_offsets\":[147456," "\"data_offsets\":[147457,"
      )
    ]

  -- The prefix budget bounds the read even when the artifact adversarially
  -- declares a header far larger than the budget.
  let adversarialPath = artifactRoot </> "adversarial-header-length.safetensors"
  BS.writeFile
    adversarialPath
    (BS.pack [0, 0, 0, 0, 0, 0, 0, 255] <> BS.drop 8 (safetensorsArtifactBytes cleanTensors))
  adversarialHeader <- readArtifactHeader adversarialPath
  assert
    (either (const True) (const False) adversarialHeader)
    "Sprint 4.39: a header length past the prefix budget is refused, never read"

  -- The second reader: a GGUF artifact whose tensors are individually aligned.
  -- An alignment-blind tiling check would reject every real GGUF file whose
  -- tensor sizes are not multiples of its alignment, which is most of them, so
  -- this fixture deliberately uses a size that is not.
  let ggufPath = artifactRoot </> "clean.gguf"
      ggufTensors = [("token_embd.weight", 0 :: Int, [100, 4] :: [Int])]
      ggufWeightBytes = 100 * 4 * 4 :: Int
  BS.writeFile ggufPath (ggufArtifactBytes ggufTensors)
  ggufHeader <- readArtifactHeader ggufPath
  assert
    (fmap artifactHeaderWeightBytes ggufHeader == Right (toInteger ggufWeightBytes))
    "Sprint 4.39: the GGUF reader sums its own tensor-info block"
  assert
    (either (const False) ((< 4096) . artifactHeaderPrefixBytes) ggufHeader)
    "Sprint 4.39: the GGUF derivation reads only the header prefix"

  -- The recorded digest is a statement about one exact header: changing a single
  -- header byte moves it, so a requirement cannot be reattributed to a different
  -- header at the same path.
  let renamedPath = artifactRoot </> "renamed-tensor.safetensors"
      -- Derived from the clean fixture so exactly one thing differs: the first
      -- tensor's name. A second literal list could drift from it silently and
      -- turn this into an assertion about two unrelated artifacts.
      renamedTensors = case cleanTensors of
        ((name, dtype, dims) : rest) -> (name <> "X", dtype, dims) : rest
        [] -> []
  BS.writeFile renamedPath (safetensorsArtifactBytes renamedTensors)
  renamedHeader <- readArtifactHeader renamedPath
  assert
    ( fmap artifactHeaderPrefixDigest cleanHeader
        /= fmap artifactHeaderPrefixDigest renamedHeader
    )
    "Sprint 4.39: the recorded prefix digest changes when the header does"

-- | Assert one mutated artifact is refused, with the unmutated artifact as its
-- positive control.
assertArtifactRefusal :: FilePath -> (String, BS.ByteString -> BS.ByteString) -> IO ()
assertArtifactRefusal artifactRoot (label, mutate) = do
  let controlTensors =
        [ ("model.embed_tokens.weight", "F16", [576, 128] :: [Int]),
          ("model.layers.0.self_attn.k_proj.weight", "F16", [192, 576])
        ]
      controlBytes = safetensorsArtifactBytes controlTensors
      controlPath = artifactRoot </> (label <> "-control.safetensors")
      mutatedPath = artifactRoot </> (label <> ".safetensors")
  BS.writeFile controlPath controlBytes
  BS.writeFile mutatedPath (mutate controlBytes)
  controlHeader <- readArtifactHeader controlPath
  mutatedHeader <- readArtifactHeader mutatedPath
  assert
    (either (const False) (const True) controlHeader)
    ("Sprint 4.39: the unmutated control for " <> label <> " derives cleanly")
  assert
    (either (const True) (const False) mutatedHeader)
    ("Sprint 4.39: the " <> label <> " mutation yields no requirement")

-- | Build a safetensors artifact: eight little-endian bytes of header length,
-- that many bytes of JSON tensor table, then a densely tiled payload.
safetensorsArtifactBytes :: [(String, String, [Int])] -> BS.ByteString
safetensorsArtifactBytes tensors =
  BS.pack (littleEndianEightBytes (length tableJson))
    <> ByteString8.pack tableJson
    <> BS.replicate payloadBytes 0
  where
    entries = safetensorsEntriesJson tensors
    tableJson = "{" <> intercalate "," entries <> "}"
    payloadBytes = sum [product dims * 2 | (_, _, dims) <- tensors]

safetensorsEntriesJson :: [(String, String, [Int])] -> [String]
safetensorsEntriesJson = go 0
  where
    go _ [] = []
    go offset ((name, dtype, dims) : rest) =
      let extent = product dims * 2
          entry =
            "\""
              <> name
              <> "\":{\"dtype\":\""
              <> dtype
              <> "\",\"shape\":["
              <> intercalate "," (map show dims)
              <> "],\"data_offsets\":["
              <> show offset
              <> ","
              <> show (offset + extent)
              <> "]}"
       in entry : go (offset + extent) rest

-- | Build a GGUF artifact: magic, version, tensor count, metadata count, an
-- empty metadata block, then one tensor-info entry per tensor, then the payload
-- aligned to the format's own default.
ggufArtifactBytes :: [(String, Int, [Int])] -> BS.ByteString
ggufArtifactBytes tensors =
  BS.concat
    [ ByteString8.pack "GGUF",
      BS.pack (littleEndianBytes 4 3),
      BS.pack (littleEndianEightBytes (length tensors)),
      BS.pack (littleEndianEightBytes 0),
      BS.concat (ggufTensorInfoBytes tensors),
      BS.replicate padding 0,
      BS.replicate payloadBytes 0
    ]
  where
    infoBytes = sum (map BS.length (ggufTensorInfoBytes tensors))
    headerBytes = 4 + 4 + 8 + 8 + infoBytes
    padding = (32 - (headerBytes `mod` 32)) `mod` 32
    payloadBytes = sum [ggufAlignedSize (product dims * 4) | (_, _, dims) <- tensors]

ggufAlignedSize :: Int -> Int
ggufAlignedSize value = ((value + 31) `div` 32) * 32

ggufTensorInfoBytes :: [(String, Int, [Int])] -> [BS.ByteString]
ggufTensorInfoBytes = go 0
  where
    go _ [] = []
    go offset ((name, ggmlType, dims) : rest) =
      BS.concat
        [ BS.pack (littleEndianEightBytes (length name)),
          ByteString8.pack name,
          BS.pack (littleEndianBytes 4 (length dims)),
          BS.concat [BS.pack (littleEndianEightBytes dimension) | dimension <- dims],
          BS.pack (littleEndianBytes 4 ggmlType),
          BS.pack (littleEndianEightBytes offset)
        ]
        : go (offset + ggufAlignedSize (product dims * 4)) rest

littleEndianBytes :: Int -> Int -> [Word8]
littleEndianBytes width value =
  [fromIntegral ((value `div` (256 ^ index)) `mod` 256) | index <- [0 .. width - 1]]

littleEndianEightBytes :: Int -> [Word8]
littleEndianEightBytes value =
  [fromIntegral ((value `div` (256 ^ index)) `mod` 256) | index <- [0 .. 7 :: Int]]

mutateSafetensorsTable :: String -> String -> BS.ByteString -> BS.ByteString
mutateSafetensorsTable needle replacement bytes =
  BS.pack (littleEndianEightBytes (length mutatedTable))
    <> ByteString8.pack mutatedTable
    <> BS.drop (8 + originalLength) bytes
  where
    originalLength =
      sum
        [ fromIntegral byte * (256 ^ index)
        | (index, byte) <- zip [0 :: Int ..] (BS.unpack (BS.take 8 bytes))
        ]
    originalTable = ByteString8.unpack (BS.take originalLength (BS.drop 8 bytes))
    mutatedTable = replaceFirstSubstring needle replacement originalTable

-- | Phase 6 Sprint 6.50: a measured ceiling breach names the ceiling it
-- breached __and__ the footprint it observed, and a real breach is strictly
-- above its ceiling. Written as a named helper because the readability gate
-- rejects a hanging @case@ inside an assertion.
--
-- Phase 4 Sprint 4.37: the reported resource is pinned here too, and the three
-- facts are pinned together deliberately. Comparing the reported ceiling
-- against the expected ceiling alone is satisfied by an implementation that
-- reports its own ceiling back, which is what the retired path did, so in the
-- failing case that assertion was vacuous. The resource is the only assertion
-- that distinguishes the two writers of one shared termination reference.
breachOutcomeExceeds ::
  Types.Resource ->
  Int ->
  Maybe CappedEngineInternal.EngineOutcome ->
  Bool
breachOutcomeExceeds expectedResource expectedCeilingMib outcome =
  case outcome of
    Just (CappedEngineInternal.EngineExceededCeiling resource ceilingMib observedMib) ->
      resource == expectedResource
        && ceilingMib == expectedCeilingMib
        && observedMib > expectedCeilingMib
    _ -> False

reapCappedEngineFixture :: String -> CPid -> IO ProcessStatus
reapCappedEngineFixture fixtureLabel processId = poll 80
  where
    poll :: Int -> IO ProcessStatus
    poll retriesRemaining = do
      maybeStatus <- getProcessStatus False False processId
      case maybeStatus of
        Just processStatus -> pure processStatus
        Nothing
          | retriesRemaining <= 0 ->
              fail (fixtureLabel <> " was not reapable within four seconds")
          | otherwise -> do
              threadDelay 50000
              poll (retriesRemaining - 1)

startGroupedCappedEngineFixture :: String -> IO () -> IO CPid
startGroupedCappedEngineFixture fixtureLabel fixtureAction = do
  (readyReader, readyWriter) <- PosixIO.createPipe
  childPid <-
    forkProcess $ do
      PosixIO.closeFd readyReader
      processId <- getProcessID
      _ <- createProcessGroupFor processId
      _ <- PosixByteString.fdWrite readyWriter "ready"
      PosixIO.closeFd readyWriter
      fixtureAction
  PosixIO.closeFd readyWriter
  ready <- PosixByteString.fdRead readyReader 5
  PosixIO.closeFd readyReader
  if ready == "ready"
    then pure childPid
    else do
      _ <- getProcessStatus True False childPid
      fail (fixtureLabel <> " did not establish its process group")

runLinuxWatchdogBreachAssertions :: IO ()
runLinuxWatchdogBreachAssertions =
  unless (System.Info.os == "darwin") $ do
    breachPid <-
      startGroupedCappedEngineFixture
        "memory-breach fixture"
        runLinuxMemoryBreachFixture
    breachOutcome <-
      CappedEngineInternal.linuxWatchdogOutcomeForTest
        16
        breachPid
    breachExit <- reapCappedEngineFixture "memory-breach fixture" breachPid
    assert
      ( breachOutcomeExceeds PodRam 16 breachOutcome
          && breachExit /= Exited ExitSuccess
      )
      "Sprint 4.32: Linux live RSS breach returns the typed ceiling outcome, names the observed footprint, and reaps the grouped engine"

    smallPid <-
      startGroupedCappedEngineFixture
        "small-memory fixture"
        runSmallMemoryFixture
    smallOutcome <-
      CappedEngineInternal.linuxWatchdogOutcomeForTest
        512
        smallPid
    smallExit <- reapCappedEngineFixture "small-memory fixture" smallPid
    assert
      (isNothing smallOutcome && smallExit == Exited ExitSuccess)
      "Sprint 4.32: a smaller execution succeeds after a live Linux ceiling breach"

-- | Phase 4 Sprint 4.35 — a native runner never reaches its engine with an
-- unhydrated cache.
--
-- The precondition is the native lane's only cache-miss reporter: unlike the
-- Python adapters it has no exit-75 protocol, so an absent payload reaches the
-- runner as an ordinary open failure that classifies as `worker_failed` and is
-- therefore never retried. These cases pin the three outcomes that matter — a
-- populated cache proceeds, an absent one reports the classified miss that
-- drives bootstrap-and-retry, and a zero-byte entry counts as absent rather
-- than as a cache hit — plus the package-backed model that legitimately
-- requires no payload at all.
runNativeModelCacheHydrationAssertions :: FilePath -> ModelDescriptor -> IO ()
runNativeModelCacheHydrationAssertions unitTestRoot packageBackedModel = do
  let cacheRoot = unitTestRoot </> "native-model-cache"
      cacheConfig = nativeModelCacheFixtureConfig cacheRoot
  removeTestPathIfPresent cacheRoot

  whisperModel <-
    maybe (fail "expected apple-silicon whisper row") pure (findModel AppleSilicon "speech-whisper-small")

  absent <- requireHydratedNativeModelCache whisperModel cacheConfig
  assert
    ( either
        ( \failure ->
            errorCode failure == "model_cache_not_populated"
              && "speech-whisper-small" `Text.isInfixOf` message failure
              && "payload" `Text.isInfixOf` message failure
        )
        (const False)
        absent
    )
    "an absent native model payload is the classified cache miss that drives bootstrap-and-retry, naming the model and the file"

  let payloadPath = cacheRoot </> "speech-whisper-small" </> "payload"
  createDirectoryIfMissing True (takeDirectory payloadPath)
  writeFile payloadPath ""
  empty <- requireHydratedNativeModelCache whisperModel cacheConfig
  assert
    (isLeft empty)
    "a zero-byte native model payload counts as absent rather than as a populated cache"

  writeFile payloadPath "ggml"
  populated <- requireHydratedNativeModelCache whisperModel cacheConfig
  assert
    (isRight populated)
    "a populated native model payload satisfies the precondition"

  packageBacked <- requireHydratedNativeModelCache packageBackedModel cacheConfig
  assert
    (isRight packageBacked)
    "a package-backed native tool requires no payload and is never blocked by the precondition"

nativeModelCacheFixtureConfig :: FilePath -> WorkerModelCacheConfig
nativeModelCacheFixtureConfig cacheRoot =
  WorkerModelCacheConfig
    { workerModelCacheRoot = Text.pack cacheRoot,
      workerModelCacheQuotaBytes = 1024 * 1024 * 1024,
      workerMinioEndpoint = "http://127.0.0.1:9000",
      workerMinioModelsBucket = "infernix-models",
      workerMinioDemoArtifactsBucket = "infernix-demo-objects",
      workerMinioRegion = "us-east-1",
      workerMinioAccessKey = "fixture-access-key",
      workerMinioSecretKey = "fixture-secret-key"
    }

-- | Phase 4 Sprint 4.32 — the adversarial Apple ceiling-breach survival test.
--
-- The Apple twin of 'runLinuxWatchdogBreachAssertions', and it needs no special
-- hardware: the fixed public-tool observer over @\/usr\/bin\/top@ plus
-- @\/usr\/bin\/footprint@ is available on any supported Apple host, so this is a
-- machine-independent regression on that lane rather than cohort-only evidence.
--
-- Three cases in order, because the first is what keeps the second from being
-- vacuous. A child that allocates nothing must /not/ breach the ceiling — which
-- proves this image's own resident baseline sits below it, so the breach that
-- follows is attributable to the allocation rather than to the runtime that
-- carries it. Then the breach itself returns the typed ceiling outcome and the
-- group is reaped non-successfully. Then a second small execution succeeds,
-- establishing that the host, this process, and subsequent smaller work all
-- survive the breach.
--
-- The child is re-exec'd rather than forked because the Apple watchdog consumes
-- a 'ProcessHandle'; the breach path signals the group without reaping, so
-- 'waitForProcess' here is the process's only waiter.
runAppleWatchdogBreachAssertions :: IO ()
runAppleWatchdogBreachAssertions =
  when (System.Info.os == "darwin") $ do
    baselineOutcome <-
      runAppleCappedEngineFixture
        "apple baseline fixture"
        "__infernix_unit_apple_memory_small_fixture"
        appleBreachCeilingMib
    assert
      (isNothing (fst baselineOutcome) && snd baselineOutcome == ExitSuccess)
      ( "Sprint 4.32: an Apple execution that allocates nothing stays under the "
          <> show appleBreachCeilingMib
          <> " MiB ceiling, so the breach case below is not vacuous"
      )

    breachOutcome <-
      runAppleCappedEngineFixture
        "apple memory-breach fixture"
        "__infernix_unit_apple_memory_breach_fixture"
        appleBreachCeilingMib
    assert
      ( breachOutcomeExceeds HostRam appleBreachCeilingMib (fst breachOutcome)
          && snd breachOutcome /= ExitSuccess
      )
      "Sprint 4.32: Apple live footprint breach returns the typed ceiling outcome, names the observed footprint, and reaps the grouped engine"

    survivorOutcome <-
      runAppleCappedEngineFixture
        "apple post-breach fixture"
        "__infernix_unit_apple_memory_small_fixture"
        appleBreachCeilingMib
    assert
      (isNothing (fst survivorOutcome) && snd survivorOutcome == ExitSuccess)
      "Sprint 4.32: a smaller Apple execution succeeds after a live ceiling breach"

-- | 256 MiB: above this image's own resident baseline (proved by the first
-- case) and well below the 512 MiB the breach child dirties.
appleBreachCeilingMib :: Int
appleBreachCeilingMib = 256

-- | Start one grouped re-exec of this image, drive the production Apple
-- watchdog against it, and reap it exactly once.
runAppleCappedEngineFixture ::
  String ->
  String ->
  Int ->
  IO (Maybe CappedEngineInternal.EngineOutcome, ExitCode)
runAppleCappedEngineFixture fixtureLabel fixtureArgument ceilingMib = do
  selfPath <- getExecutablePath
  (_, _, _, processHandle) <-
    createProcess (proc selfPath [fixtureArgument]) {create_group = True}
  maybeChildPid <- getPid processHandle
  childPid <-
    maybe
      (fail (fixtureLabel <> " did not report a process id"))
      pure
      maybeChildPid
  outcome <-
    CappedEngineInternal.appleWatchdogOutcomeForTest
      ceilingMib
      processHandle
      childPid
  childExit <- waitForProcess processHandle
  pure (outcome, childExit)

runMissingProcessGroupSettlementAssertions :: IO ()
runMissingProcessGroupSettlementAssertions = do
  resumed <-
    CappedEngineInternal.missingProcessGroupSettlementForTest
      [Right False, Right True]
      [Right False]
  assert
    (resumed == Right True)
    "Sprint 4.32: a process group that reappears during bounded settlement resumes full measurement"

  exited <-
    CappedEngineInternal.missingProcessGroupSettlementForTest
      (replicate 4 (Right False))
      [Right True]
  assert
    (exited == Right False)
    "Sprint 4.32: a process exit published during bounded settlement completes without enforcement failure"

  let persistentReason =
        "process group remained absent while the engine handle remained live"
  unavailable <-
    CappedEngineInternal.missingProcessGroupSettlementForTest
      (replicate 4 (Right False))
      [Right False]
  assert
    (unavailable == Left persistentReason)
    "Sprint 4.32: persistent process-group absence for a live engine remains a typed enforcement failure"

  let observationFailure = "synthetic /proc observation failure"
  failedObservation <-
    CappedEngineInternal.missingProcessGroupSettlementForTest
      [Left observationFailure]
      []
  assert
    (failedObservation == Left observationFailure)
    "Sprint 4.32: a settlement recheck observation failure remains terminal and exact"

  let terminalObservationFailure = "synthetic leader observation failure"
  failedTerminalObservation <-
    CappedEngineInternal.missingProcessGroupSettlementForTest
      (replicate 4 (Right False))
      [Left terminalObservationFailure]
  assert
    (failedTerminalObservation == Left terminalObservationFailure)
    "Sprint 4.32: a terminal-state observation failure remains terminal and exact"

-- | Phase 6 Sprint 6.44 — the NVIDIA VRAM watchdog against a real device. A
-- grouped child that holds no CUDA context must sample cleanly to zero
-- attributed bytes and complete without a fabricated breach and without an
-- enforcement-unavailable failure: that exercises the fixed @nvidia-smi@ spawn,
-- the @\/proc@ group enumeration, the attribution join, and the loop's exit
-- path end to end on real hardware.
--
-- The adversarial breach — a real CUDA allocation past a declared ceiling —
-- needs a device-allocating child and is therefore owned by the @linux-gpu@
-- behavioral cohort, not by this machine-independent suite. On a host without
-- the fixed tool the assertion is skipped loudly rather than passing vacuously.
runNvidiaWatchdogAssertions :: IO ()
runNvidiaWatchdogAssertions =
  unless (System.Info.os == "darwin") $ do
    nvidiaSmiPresent <- doesFileExist "/usr/bin/nvidia-smi"
    if not nvidiaSmiPresent
      then
        putStrLn
          "skipping the live NVIDIA VRAM watchdog assertions: /usr/bin/nvidia-smi is absent on this host"
      else do
        childPid <-
          startGroupedCappedEngineFixture
            "NVIDIA no-context fixture"
            runSmallMemoryFixture
        outcome <-
          CappedEngineInternal.nvidiaWatchdogOutcomeForTest
            512
            childPid
        childExit <- reapCappedEngineFixture "NVIDIA no-context fixture" childPid
        assert
          (isNothing outcome && childExit == Exited ExitSuccess)
          ( "Sprint 6.44: a live NVIDIA VRAM sample of a group holding no CUDA context "
              <> "completes without a breach or an enforcement failure; observed "
              <> show outcome
          )
        deviceVram <- CappedEngineInternal.observeNvidiaDeviceVramMib
        assert
          (maybe False (> 0) deviceVram)
          ( "Sprint 6.44: the fixed NVIDIA device-memory observer reports a positive envelope; observed "
              <> show deviceVram
          )
        samplerAvailable <- CappedEngineInternal.verifyNvidiaVramSampler
        assert
          samplerAvailable
          "Sprint 6.44: the NVIDIA VRAM startup probe reports the sampler available on a CUDA host"

-- | The interpreter that holds the device allocation.
--
-- Pinned as a literal absolute path for the same reason @\/usr\/bin\/nvidia-smi@
-- is: an enforcement fixture that follows a configurable path proves whatever
-- that path points at. The launcher image installs @python3@ unconditionally
-- for every runtime mode, so this is the interpreter the cohort actually has.
cudaFixtureInterpreter :: FilePath
cudaFixtureInterpreter = "/usr/bin/python3"

-- | A real CUDA device allocation, held open for the watchdog to observe.
--
-- Sprint 6.44's remaining work called for a fixture that allocates device
-- memory past a declared ceiling. Driver-API calls through @ctypes@ need no
-- compiler and add no repo-owned native source, which is what makes this
-- expressible at all under the no-repo-owned-native-source doctrine.
--
-- The first stdout line is the gate. @allocated@ means the device memory is
-- held and attributable; @unavailable \<reason\>@ means this host cannot make
-- the observation, and the caller skips loudly rather than vacuously passing.
-- Every driver call is checked, so a partial failure cannot masquerade as a
-- held allocation.
cudaAllocationFixtureProgram :: String
cudaAllocationFixtureProgram =
  intercalate
    "\n"
    [ "import ctypes, sys, time",
      "requested = int(sys.argv[1])",
      "hold = float(sys.argv[2])",
      "def unavailable(reason):",
      "    sys.stdout.write('unavailable ' + reason + '\\n')",
      "    sys.stdout.flush()",
      "    raise SystemExit(0)",
      "try:",
      "    driver = ctypes.CDLL('libcuda.so.1')",
      "except OSError as failure:",
      "    unavailable('libcuda.so.1 ' + str(failure))",
      "if driver.cuInit(0) != 0:",
      "    unavailable('cuInit')",
      "device = ctypes.c_int(0)",
      "if driver.cuDeviceGet(ctypes.byref(device), 0) != 0:",
      "    unavailable('cuDeviceGet')",
      "context = ctypes.c_void_p()",
      "if driver.cuCtxCreate_v2(ctypes.byref(context), 0, device) != 0:",
      "    unavailable('cuCtxCreate_v2')",
      "pointer = ctypes.c_void_p()",
      "size = ctypes.c_size_t(requested * 1024 * 1024)",
      "if driver.cuMemAlloc_v2(ctypes.byref(pointer), size) != 0:",
      "    unavailable('cuMemAlloc_v2 ' + str(requested))",
      "sys.stdout.write('allocated\\n')",
      "sys.stdout.flush()",
      "time.sleep(hold)"
    ]

-- | CUDA-host calibration for the resident-memory mechanism. The CUDA context
-- is established before the host allocation, so the refusal case demonstrates
-- the Linux GPU lane rather than a Python process which never reached its
-- device runtime. A caught 'MemoryError' exits non-zero; no successful result
-- is fabricated from the refusal.
cudaHostCeilingCalibrationProgram :: String
cudaHostCeilingCalibrationProgram =
  intercalate
    "\n"
    [ "import ctypes, sys, time",
      "host_requested = int(sys.argv[1])",
      "hold = float(sys.argv[2])",
      "try:",
      "    driver = ctypes.CDLL('libcuda.so.1')",
      "except OSError as failure:",
      "    sys.stdout.write('unavailable libcuda.so.1 ' + str(failure) + '\\n')",
      "    sys.stdout.flush()",
      "    raise SystemExit(73)",
      "if driver.cuInit(0) != 0:",
      "    sys.stdout.write('unavailable cuInit\\n')",
      "    sys.stdout.flush()",
      "    raise SystemExit(73)",
      "device = ctypes.c_int(0)",
      "if driver.cuDeviceGet(ctypes.byref(device), 0) != 0:",
      "    sys.stdout.write('unavailable cuDeviceGet\\n')",
      "    sys.stdout.flush()",
      "    raise SystemExit(73)",
      "context = ctypes.c_void_p()",
      "if driver.cuCtxCreate_v2(ctypes.byref(context), 0, device) != 0:",
      "    sys.stdout.write('unavailable cuCtxCreate_v2\\n')",
      "    sys.stdout.flush()",
      "    raise SystemExit(73)",
      "try:",
      "    resident = bytearray(host_requested * 1024 * 1024)",
      "except MemoryError:",
      "    sys.stdout.write('host-refused\\n')",
      "    sys.stdout.flush()",
      "    raise SystemExit(42)",
      "sys.stdout.write('allocated\\n')",
      "sys.stdout.flush()",
      "time.sleep(hold)"
    ]

-- | Launch a device-allocating child and wait for its gate line.
--
-- Returns the process handle, its process-group pid, and the gate line. The
-- caller decides whether the gate permits an assertion or a loud skip.
startCudaAllocationFixture :: Int -> Double -> IO (Maybe (ProcessHandle, CPid, String))
startCudaAllocationFixture requestedMib holdSeconds = do
  (_, maybeOut, _, handle) <-
    createProcess
      ( proc
          cudaFixtureInterpreter
          [ "-c",
            cudaAllocationFixtureProgram,
            show requestedMib,
            show holdSeconds
          ]
      )
        { create_group = True,
          std_out = CreatePipe
        }
  outHandle <-
    maybe (fail "CUDA allocation fixture exposed no stdout pipe") pure maybeOut
  childPid <-
    getPid handle >>= maybe (fail "CUDA allocation fixture exposed no pid") pure
  -- The gate is bounded: a driver that never returns must not hang the suite.
  gate <- timeout cudaFixtureGateTimeoutMicros (System.IO.hGetLine outHandle)
  pure ((,,) handle childPid <$> gate)

-- | Start the CUDA-initialized host allocation fixture behind the same pinned
-- data-segment installer and exact soft/hard value used by production.
startCudaHostCeilingCalibrationFixture ::
  Int ->
  Int ->
  Double ->
  IO (Maybe (ProcessHandle, String))
startCudaHostCeilingCalibrationFixture ceilingMib requestedMib holdSeconds = do
  let ceilingBytes = ceilingMib * 1024 * 1024
  (_, maybeOut, _, handle) <-
    createProcess
      ( proc
          Ceiling.ceilingEnforcementTool
          [ "--data=" <> show ceilingBytes <> ":" <> show ceilingBytes,
            "--",
            cudaFixtureInterpreter,
            "-c",
            cudaHostCeilingCalibrationProgram,
            show requestedMib,
            show holdSeconds
          ]
      )
        { create_group = True,
          std_out = CreatePipe
        }
  outHandle <-
    maybe (fail "CUDA host-ceiling calibration fixture exposed no stdout pipe") pure maybeOut
  gate <- timeout cudaFixtureGateTimeoutMicros (System.IO.hGetLine outHandle)
  pure ((,) handle <$> gate)

-- | Driver initialisation plus a multi-gibibyte allocation measured at under a
-- second on the development host; a minute is loose enough for a loaded cohort
-- and still bounded.
cudaFixtureGateTimeoutMicros :: Int
cudaFixtureGateTimeoutMicros = 60 * 1000000

-- | Phase 6 Sprint 6.44 — the adversarial CUDA ceiling breach.
--
-- The deliverable Sprint 6.44 could not close: no suite allocated device memory
-- past a ceiling, so nothing observed a /runtime/ breach of an /admitted/ GPU
-- grant. The integration suite cannot cover it — 'validateCatalogModelInference'
-- classifies every catalogue row as either a pre-admission typed rejection or a
-- completion, and a runtime breach is neither.
--
-- Mirrors 'runLinuxWatchdogBreachAssertions' exactly: a breach returns the typed
-- 'EngineExceededCeiling', the group is reaped non-successfully, and a
-- subsequent smaller allocation completes cleanly under the same enforcer.
--
-- The ceilings sit clear of the CUDA context floor, which is a real allocation
-- the driver makes before any @cuMemAlloc@: 496 MiB measured on this host. The
-- breach case allocates 3072 MiB against a 1024 MiB ceiling (observed 3568 MiB),
-- and the clean case allocates 64 MiB against a 3072 MiB ceiling (observed
-- ~560 MiB), so neither outcome can be produced by context overhead alone.
--
-- Skips loudly and never vacuously: outer-container device access depends on the
-- host daemon's default runtime rather than on @compose.yaml@, so a skip must
-- say which precondition was missing.
runNvidiaVramBreachAssertions :: IO ()
runNvidiaVramBreachAssertions =
  unless (System.Info.os == "darwin") $ do
    nvidiaSmiPresent <- doesFileExist "/usr/bin/nvidia-smi"
    interpreterPresent <- doesFileExist cudaFixtureInterpreter
    if not nvidiaSmiPresent
      then
        putStrLn
          "skipping the live CUDA ceiling-breach assertions: /usr/bin/nvidia-smi is absent on this host"
      else
        if not interpreterPresent
          then
            putStrLn
              ( "skipping the live CUDA ceiling-breach assertions: "
                  <> cudaFixtureInterpreter
                  <> " is absent on this host"
              )
          else runLiveNvidiaVramBreachAssertions

runLiveNvidiaVramBreachAssertions :: IO ()
runLiveNvidiaVramBreachAssertions = do
  started <- startCudaAllocationFixture cudaBreachAllocationMib 120
  case started of
    Nothing ->
      putStrLn
        ( "skipping the live CUDA ceiling-breach assertions: the device "
            <> "allocation fixture produced no gate line within its bound"
        )
    Just (_, breachPid, "allocated") -> do
      breachOutcome <-
        CappedEngineInternal.nvidiaWatchdogOutcomeForTest
          cudaBreachCeilingMib
          breachPid
      breachExit <- reapCappedEngineFixture "CUDA breach fixture" breachPid
      assert
        ( breachOutcomeExceeds NvidiaVram cudaBreachCeilingMib breachOutcome
            && breachExit /= Exited ExitSuccess
        )
        ( "Sprint 6.44: a live CUDA allocation past the declared ceiling returns the "
            <> "typed ceiling outcome and reaps the grouped engine non-successfully; observed "
            <> show breachOutcome
            <> " and "
            <> show breachExit
        )
      runNvidiaVramCleanAllocationAssertion
    Just (_, breachPid, gate) -> do
      void (reapCappedEngineFixture "unavailable CUDA fixture" breachPid)
      putStrLn
        ( "skipping the live CUDA ceiling-breach assertions: the device "
            <> "allocation fixture reported "
            <> gate
        )

-- | The GPU worker stays healthy after a breach: a smaller allocation under the
-- same enforcer completes without a breach and exits successfully.
runNvidiaVramCleanAllocationAssertion :: IO ()
runNvidiaVramCleanAllocationAssertion = do
  started <- startCudaAllocationFixture cudaCleanAllocationMib 1
  case started of
    Just (_, cleanPid, "allocated") -> do
      cleanOutcome <-
        CappedEngineInternal.nvidiaWatchdogOutcomeForTest
          cudaCleanCeilingMib
          cleanPid
      cleanExit <- reapCappedEngineFixture "CUDA clean fixture" cleanPid
      assert
        (isNothing cleanOutcome && cleanExit == Exited ExitSuccess)
        ( "Sprint 6.44: a smaller live CUDA allocation after a breach completes under the "
            <> "same enforcer without a breach or an enforcement failure; observed "
            <> show cleanOutcome
            <> " and "
            <> show cleanExit
        )
    _ ->
      fail
        ( "Sprint 6.44: the post-breach CUDA allocation fixture did not reach its "
            <> "gate, so the GPU worker was not proven healthy after the breach"
        )

-- | Phase 6 Sprint 6.51 — availability is a live pre-launch observation, not
-- an alias for the device's total capacity. Record the free quantity, hold a
-- real CUDA allocation in a different process group, and then ask for an arena
-- which was available before that claimant arrived. The production check must
-- refuse it with both observed quantities and attribution to the claimant this
-- machine did not start.
runCompetingNvidiaTenantAssertion :: IO ()
runCompetingNvidiaTenantAssertion =
  unless (System.Info.os == "darwin") $ do
    nvidiaSmiPresent <- doesFileExist "/usr/bin/nvidia-smi"
    if not nvidiaSmiPresent
      then
        putStrLn
          "skipping the live competing NVIDIA tenant assertion: /usr/bin/nvidia-smi is absent on this host"
      else do
        freeBefore <- CappedEngineInternal.observeNvidiaDeviceFreeMibForTest
        case freeBefore of
          Left reason ->
            fail
              ( "Sprint 6.51: the CUDA host could not establish its initial free-device reading: "
                  <> Text.unpack reason
              )
          Right admittedArenaMib -> do
            started <- startCudaAllocationFixture cudaCompetingTenantAllocationMib 120
            case started of
              Just (tenantHandle, _, "allocated") -> do
                (availability, freeDuring) <-
                  ( (,)
                      <$> CappedEngineInternal.observeDeviceArenaAvailability admittedArenaMib
                      <*> CappedEngineInternal.observeNvidiaDeviceFreeMibForTest
                  )
                    `finally` ( do
                                  terminateProcess tenantHandle
                                  tenantExit <- timeout (4 * 1000000) (waitForProcess tenantHandle)
                                  assert
                                    (isJust tenantExit)
                                    "Sprint 6.51: the competing CUDA tenant was not reaped within four seconds"
                              )
                case (availability, freeDuring) of
                  (Left refusal, Right observedFreeMib) ->
                    assert
                      ( observedFreeMib < admittedArenaMib
                          && show observedFreeMib `isInfixOf` Text.unpack refusal
                          && show admittedArenaMib `isInfixOf` Text.unpack refusal
                          && "claimant this machine did not start" `isInfixOf` Text.unpack refusal
                      )
                      ( "Sprint 6.51: the competing CUDA tenant changed free VRAM but did not produce "
                          <> "the exact named pre-launch refusal; initial free "
                          <> show admittedArenaMib
                          <> " MiB, current free "
                          <> show observedFreeMib
                          <> " MiB, refusal "
                          <> Text.unpack refusal
                      )
                  (Right (), observed) ->
                    fail
                      ( "Sprint 6.51: an arena equal to the pre-tenant free quantity was accepted "
                          <> "while the competing CUDA allocation was held; observed "
                          <> show observed
                      )
                  (Left refusal, Left reason) ->
                    fail
                      ( "Sprint 6.51: the refusal was produced but the confirming free-device "
                          <> "observation failed: "
                          <> Text.unpack refusal
                          <> "; "
                          <> Text.unpack reason
                      )
              Just (tenantHandle, _, gate) -> do
                _ <- waitForProcess tenantHandle
                putStrLn
                  ( "skipping the live competing NVIDIA tenant assertion: the CUDA allocation "
                      <> "fixture reported "
                      <> gate
                  )
              Nothing ->
                putStrLn
                  "skipping the live competing NVIDIA tenant assertion: the CUDA allocation fixture produced no bounded gate line"

-- Large enough to move the free-device reading decisively while leaving ample
-- room for the test image and the selected cohort's card.
cudaCompetingTenantAllocationMib :: Int
cudaCompetingTenantAllocationMib = 2048

-- | Phase 6 Sprint 6.51 — calibrate the Linux GPU host column independently
-- from the permanently detection-only device column. The first process proves
-- a CUDA-initialized allocation can complete beneath a generous installed
-- ceiling. The second initializes the same device runtime, then receives a
-- clean non-zero host allocation refusal beyond its installed ceiling.
runLinuxGpuHostCeilingCalibrationAssertion :: IO ()
runLinuxGpuHostCeilingCalibrationAssertion =
  unless (System.Info.os == "darwin") $ do
    nvidiaSmiPresent <- doesFileExist "/usr/bin/nvidia-smi"
    if not nvidiaSmiPresent
      then
        putStrLn
          "skipping the live Linux GPU host-ceiling calibration: /usr/bin/nvidia-smi is absent on this host"
      else do
        generous <- startCudaHostCeilingCalibrationFixture 4096 256 1
        case generous of
          Just (handle, "allocated") -> do
            exitCode <- waitForProcess handle
            assert
              (exitCode == ExitSuccess)
              "Sprint 6.51: the CUDA-initialized host allocation did not complete beneath the generous installed ceiling"
          Just (handle, gate) -> do
            exitCode <- waitForProcess handle
            fail
              ( "Sprint 6.51: the generous CUDA host-ceiling calibration did not allocate: "
                  <> gate
                  <> "; exit "
                  <> show exitCode
              )
          Nothing ->
            fail "Sprint 6.51: the generous CUDA host-ceiling calibration produced no bounded gate line"

        refusal <- startCudaHostCeilingCalibrationFixture 1024 2048 1
        case refusal of
          Just (handle, "host-refused") -> do
            exitCode <- waitForProcess handle
            assert
              (exitCode == ExitFailure 42)
              ( "Sprint 6.51: the CUDA-initialized over-budget host allocation did not retain "
                  <> "its clean refusal exit; observed "
                  <> show exitCode
              )
          Just (handle, gate) -> do
            terminateProcess handle
            _ <- waitForProcess handle
            fail
              ( "Sprint 6.51: the CUDA-initialized over-budget host allocation was not refused; "
                  <> "observed gate "
                  <> gate
              )
          Nothing ->
            fail "Sprint 6.51: the refusing CUDA host-ceiling calibration produced no bounded gate line"

-- | 3072 MiB over a 1024 MiB ceiling, against a 496 MiB context floor.
cudaBreachAllocationMib :: Int
cudaBreachAllocationMib = 3072

cudaBreachCeilingMib :: Int
cudaBreachCeilingMib = 1024

-- | 64 MiB under a 3072 MiB ceiling, again clear of the context floor.
cudaCleanAllocationMib :: Int
cudaCleanAllocationMib = 64

cudaCleanCeilingMib :: Int
cudaCleanCeilingMib = 3072

main :: IO ()
main = do
  -- Test images spawn self-exec children through the same close_fds
  -- kernels the production binary uses, so they bound their descriptor
  -- space first. See "Infernix.DescriptorSpace".
  _ <- establishBoundedDescriptorSpace
  dispatchBuildMemoryFixture
  dispatchCappedEngineMemoryFixture
  Subprocess.dispatchInternalSubprocessMode
  unitTestRoot <- testRootPath "unit"
  ProcessIdentitySpec.runProcessIdentityTests
    (unitTestRoot </> "process-identity")
  runDescriptorSpaceAssertions
  runNativeArtifactMarkerAssertions
  runAppleRuntimeEnvironmentAssertions
  runBuildMemoryAssertions unitTestRoot
  runArtifactRequirementAssertions unitTestRoot
  runMissingProcessGroupSettlementAssertions
  runLinuxWatchdogBreachAssertions
  runAppleWatchdogBreachAssertions
  runNvidiaWatchdogAssertions
  runNvidiaVramBreachAssertions
  runCompetingNvidiaTenantAssertion
  runLinuxGpuHostCeilingCalibrationAssertion
  assert (length (catalogForMode AppleSilicon) == 16) "apple-silicon runnable catalog count matches the revised matrix"
  assert (length (catalogForMode LinuxCpu) == 12) "linux-cpu runnable catalog count matches the revised matrix"
  assert (length (catalogForMode LinuxGpu) == 16) "linux-gpu runnable catalog count matches the revised matrix"
  assert
    (expectedDaemonLocationForRuntime AppleSilicon == "cluster-pod")
    "apple-silicon publication reports the cluster service daemon location"
  assert
    (expectedInferenceExecutorLocationForRuntime AppleSilicon == "control-plane-host")
    "apple-silicon publication reports the host-native inference executor location"
  assert
    (expectedDaemonLocationForRuntime LinuxCpu == "cluster-pod")
    "linux-cpu publication reports the cluster-resident service daemon location"
  assert
    (expectedDaemonLocationForRuntime LinuxGpu == "cluster-pod")
    "linux-gpu publication reports the cluster-resident service daemon location"
  assert
    (expectedInferenceDispatchModeForRuntime AppleSilicon == "pulsar-bridge-to-host-daemon")
    "apple-silicon publication reports the host-daemon dispatch mode"
  assert
    (expectedInferenceDispatchModeForRuntime LinuxCpu == "pulsar-bridge-to-cluster-daemon")
    "linux-cpu publication reports the cluster-daemon dispatch mode"
  assert
    (expectedInferenceDispatchModeForRuntime LinuxGpu == "pulsar-bridge-to-cluster-daemon")
    "linux-gpu publication reports the cluster-daemon dispatch mode"
  assert
    -- Phase 7 Sprint 7.7: the supported split topology has no daemon
    -- PVCs (coordinator + engine + demo all run PVC-free).
    (null (platformClaimsForRuntime AppleSilicon))
    "apple-silicon split topology has no daemon PVCs"
  assert
    (null (platformClaimsForRuntime LinuxCpu) && null (platformClaimsForRuntime LinuxGpu))
    "linux split topologies have no daemon PVCs"
  assert
    ( not
        ( pulsarBootstrapLogIndicatesDirtyState
            "INFO The current epoch is 1\nINFO Got zxid 0x1 while starting ZooKeeper\n"
        )
    )
    "Pulsar dirty-state detection ignores standalone ZooKeeper epoch/zxid startup fragments"
  assert
    ( pulsarBootstrapLogIndicatesDirtyState
        "ERROR The current epoch 1 is older than the last zxid 0x200000001\n"
    )
    "Pulsar dirty-state detection catches ZooKeeper epoch regression"
  assert
    ( pulsarBootstrapLogIndicatesDirtyState
        "org.apache.bookkeeper.bookie.BookieException$InvalidCookieException: Cookie instanceId is not matching with metadata"
    )
    "Pulsar dirty-state detection catches BookKeeper cookie mismatch"
  assert
    (isRetryablePulsarWebSocketClientFailure (toException WebSockets.ConnectionClosed))
    "Pulsar WebSocket client retries an early connection close during startup"
  assert
    (isRetryablePulsarWebSocketClientFailure (toException WebSockets.ConnectionTimeout))
    "Pulsar WebSocket client retries a handshake timeout during startup"
  let missingHandshakeResponse =
        WebSockets.OtherHandshakeException
          "Network.WebSockets.Client.newClientConnection: no handshake response from server"
  assert
    (isRetryablePulsarWebSocketClientFailure (toException missingHandshakeResponse))
    "Pulsar WebSocket client retries a missing handshake response during startup"
  let transientProxyServerError =
        WebSockets.OtherHandshakeException
          "Network.WebSockets.Http.HandshakeException: MalformedResponse (ResponseHead {responseCode = 500, responseMessage = \"Server Error\", responseHeaders = [(\"Server\",\"Jetty(9.4.58.v20250814)\")]}) \"Wrong response status or message.\""
  assert
    (isRetryablePulsarWebSocketClientFailure (toException transientProxyServerError))
    "Pulsar WebSocket client retries a transient Pulsar proxy 5xx handshake response during startup"
  let invalidHandshakePath =
        WebSockets.OtherHandshakeException
          "Network.WebSockets.Http.HandshakeException: MalformedResponse (ResponseHead {responseCode = 404, responseMessage = \"Not Found\", responseHeaders = [(\"Server\",\"Jetty(9.4.58.v20250814)\")]}) \"Wrong response status or message.\""
  assert
    (not (isRetryablePulsarWebSocketClientFailure (toException invalidHandshakePath)))
    "Pulsar WebSocket client does not retry non-transient handshake status responses"
  assert (isJust (findModel LinuxGpu "llm-qwen25-awq")) "linux-gpu includes the AWQ row"
  assert (isNothing (findModel AppleSilicon "llm-qwen25-awq")) "apple-silicon omits unsupported AWQ rows"
  assert
    (parseCommand ["cluster", "status"] == Right ClusterStatusCommand)
    "the structured command registry parses cluster commands without a runtime-mode prefix"
  assert
    ( parseCommand ["cluster", "reclaim-slot"]
        == Right (ClusterReclaimSlotCommand Nothing)
        && parseCommand ["cluster", "reclaim-slot", "--force-owner-pid", "17"]
          == Right (ClusterReclaimSlotCommand (Just 17))
        && isLeft (parseCommand ["cluster", "reclaim-slot", "--force-owner-pid", "0"])
        && isLeft (parseCommand ["cluster", "reclaim-slot", "--force-owner-pid", "not-a-pid"])
    )
    "the cluster-slot recovery command accepts only an optional positive bounded PID premise"
  assert
    (parseCommand ["internal", "discover", "images", "rendered-chart.yaml"] == Right (InternalDiscoverImagesCommand "rendered-chart.yaml"))
    "the structured command registry parses internal discovery commands from the same definition used by the docs"
  assert
    ( parseCommand ["internal", "validate-darwin-build-memory"]
        == Right InternalValidateDarwinBuildMemoryCommand
    )
    "the registry exposes the Darwin build-memory evidence run only through its closed opt-in command"
  assert
    ( not (commandRequiresConfiguredStartup (InitCommand (Just AppleSilicon) (Just True) Nothing True False))
        && not (commandRequiresConfiguredStartup (TestInitCommand (Just AppleSilicon) (Just True) Nothing))
        && not (commandRequiresConfiguredStartup ShowRootHelp)
        && commandRequiresConfiguredStartup TestUnitCommand
    )
    "init, test init, and help remain reachable across a stale host-manifest schema while operational commands require configured startup"
  assert
    ( parseCommand ["internal", "validate-darwin-audiveris-cancellation"]
        == Right InternalValidateDarwinAudiverisCancellationCommand
        && parseCommand ["internal", "validate-darwin-installed-python-source-isolation"]
          == Right InternalValidateDarwinInstalledPythonSourceIsolationCommand
    )
    "the registry exposes both Darwin-only Apple materializer cohort modes through fixed internal commands"
  assert
    ( parseCommand ["internal", "materialize-substrate", "linux-cpu", "--demo-ui", "false"]
        == Right (InternalMaterializeSubstrateCommand LinuxCpu Nothing False False)
    )
    "the structured command registry parses explicit substrate materialization commands"
  assert
    ( parseCommand ["internal", "materialize-substrate", "linux-cpu", "--empty-models"]
        == Right (InternalMaterializeSubstrateCommand LinuxCpu Nothing True True)
        && parseCommand ["internal", "materialize-substrate", "linux-gpu", "--demo-ui", "false", "--empty-models"]
          == Right (InternalMaterializeSubstrateCommand LinuxGpu Nothing False True)
    )
    "Sprint 8.5: the registry parses the image-baked --empty-models substrate materialization"
  assert
    ( parseCommand ["internal", "materialize-substrate", "linux-cpu", "--demo-ui", "true", "--engine-machines", "2"]
        == Right (InternalMaterializeSubstrateCommand LinuxCpu (Just 2) True False)
        && isLeft (parseCommand ["internal", "materialize-substrate", "linux-cpu", "--engine-machines", "0"])
    )
    "Sprint 8.12: the lane-facing generator takes the fleet size, and a fleet of zero is not a parse"
  assert
    (parseCommand ["internal", "materialize-linux-native-engines"] == Right InternalMaterializeLinuxNativeEnginesCommand)
    "the structured command registry parses Linux native engine materialization"
  assert
    ( parseCommand ["internal", "playwright", "prepare-engine", "llm-qwen25"]
        == Right (InternalPlaywrightPrepareEngineCommand "llm-qwen25")
        -- Phase 6 Sprint 6.47 retired `internal playwright replace-demo-pods`
        -- with the frontend pod-replacement browser section that was its only
        -- caller, so the closed harness vocabulary is one action.
        && isLeft (parseCommand ["internal", "playwright", "replace-demo-pods"])
    )
    "the structured command registry parses only the closed Playwright harness actions"
  mapM_
    ( \schema ->
        assert
          (parseCommand ["internal", "dhall-schema", Text.unpack (dhallSchemaName schema)] == Right (InternalDhallSchemaCommand schema))
          "the structured command registry parses reflected Dhall schema commands"
    )
    allDhallSchemas
  assertDhallSchemaReflection
  assert
    ("### `cluster`" `isInfixOf` renderCliReferenceCommandsSection)
    "the generated CLI reference includes the cluster family heading"
  assert
    ("- `test` - runs the aggregate validation entrypoints" `isInfixOf` renderCliSurfaceFamiliesSection)
