        "kind registry-host generation leaves the retired helper-registry namespace untouched"
      assert
        (legacyRegistryHostsContents == "legacy helper registry\n")
        "kind registry-host generation does not rewrite the retired helper-registry namespace"
      -- Phase 2 Sprint 2.13: the previous test injected
      -- INFERNIX_HOST_REPO_ROOT=/host/infernix via env so the
      -- generated Kind config rendered host-side paths under
      -- @/host/infernix/...@. After the env-var retirement, the
      -- supported flow takes that override through
      -- @HostConfig.hostFilesystem.hostRepoRoot@ on the staged host
      -- manifest. The test now constructs a fixture whose typed
      -- @hostRepoRoot@ is @/host/infernix@ directly; the test still
      -- writes to real disk under @realRepoRoot@ by using a separate
      -- @diskTestRoot@ for @ensureRepoLayout@ + @writeGeneratedKindConfig@.
      let outerFixture = linuxOuterContainerUnitTestFixture realRepoRoot unitTestRoot (unitTestRoot </> "outer-container" </> "build")
      outerPaths <- discoverPathsWithHostManifest (Just outerFixture)
      ensureRepoLayout outerPaths
      generatedLinuxGpuKindConfigPath <- writeGeneratedKindConfig outerPaths LinuxGpu singleEngineMachine 30090 30002 30080
      generatedLinuxGpuKindConfig <- readFile generatedLinuxGpuKindConfigPath
      let expectedHostKindMount = "hostPath: " <> realRepoRoot </> ".build/test-unit/.data/kind/linux-gpu"
          expectedHostRegistryMount = "hostPath: " <> realRepoRoot </> ".build/kind/linux-gpu/registry"
          expectedLinuxGpuRegistryHostsFile =
            realRepoRoot
              </> ".build"
              </> "kind"
              </> "linux-gpu"
              </> "registry"
              </> "localhost:30002"
              </> "hosts.toml"
      assert
        (expectedHostKindMount `isInfixOf` generatedLinuxGpuKindConfig)
        "linux-gpu outer-container Kind config mounts host-resolved retained cluster data"
      assert
        ("containerPath: /var/infernix-data" `isInfixOf` generatedLinuxGpuKindConfig)
        "linux-gpu outer-container Kind config exposes retained data at the node PV root"
      assert
        (expectedHostRegistryMount `isInfixOf` generatedLinuxGpuKindConfig)
        "linux-gpu outer-container Kind config mounts runtime-scoped host-resolved registry hosts"
      linuxGpuRegistryHostsContents <- readFile expectedLinuxGpuRegistryHostsFile
      assert
        ( "server = \"http://infernix-linux-gpu-" `isInfixOf` linuxGpuRegistryHostsContents
            && "-control-plane:30002\"" `isInfixOf` linuxGpuRegistryHostsContents
        )
        "linux-gpu registry hosts file targets the active linux-gpu control-plane mirror"
      assert
        ("containerPath: /var/run/nvidia-container-devices/all" `isInfixOf` generatedLinuxGpuKindConfig)
        "linux-gpu outer-container Kind config keeps the NVIDIA worker device mount"
      -- Phase 9 Sprint 9.4: the data-plane loopback invariant. The generated
      -- Kind config must bind every host port mapping to 127.0.0.1 so the MinIO
      -- S3 (30011) and Pulsar proxy (30080) data-plane NodePorts the Apple host
      -- worker reaches, and the admin-gated Envoy edge (30090), are reachable
      -- only on loopback. `infernix lint chart` pins the committed reference
      -- configs; this pins the binary-owned generator (`renderKindConfig`).
      let generatedListenAddressLines =
            filter ("listenAddress:" `isInfixOf`) (lines generatedLinuxGpuKindConfig)
      assert
        ( not (null generatedListenAddressLines)
            && all ("127.0.0.1" `isInfixOf`) generatedListenAddressLines
        )
        "Phase 9 Sprint 9.4: generated Kind config binds every host port mapping to the 127.0.0.1 loopback address"
      assert
        ("containerPort: 30011" `isInfixOf` generatedLinuxGpuKindConfig)
        "Phase 9 Sprint 9.4: generated Kind config exposes the MinIO S3 data-plane NodePort mapping (30011)"
      assert
        ("containerPort: 30080" `isInfixOf` generatedLinuxGpuKindConfig)
        "Phase 9 Sprint 9.4: generated Kind config exposes the Pulsar proxy data-plane NodePort mapping (30080)"
      -- Phase 3 Sprint 3.16 regression guard, stated against the generator
      -- rather than the tracked reference file. `kind/cluster-linux-cpu.yaml`
      -- was edited down to one worker by the sprint, but a Kind cluster is
      -- created from `renderKindConfig`, where `kindWorkerCount LinuxCpu`
      -- still returned 2 — so the lane ran a two-worker cluster and the
      -- tracked file was a reference document that deployed nothing. This is
      -- the same shape as the generated Helm overlay's replica counts, and it
      -- is pinned the same way: over every supported mode, against the text
      -- that deploys.
      linuxCpuGeneratedKindConfig <-
        readFile =<< writeGeneratedKindConfig outerPaths LinuxCpu singleEngineMachine 30090 30002 30080
      appleGeneratedKindConfig <-
        readFile =<< writeGeneratedKindConfig outerPaths AppleSilicon singleEngineMachine 30090 30002 30080
      let generatedWorkerCount configText =
            length (filter (("- role: worker" ==) . dropWhile (== ' ')) (lines configText))
      mapM_
        ( \(modeLabel, configText) ->
            assert
              (generatedWorkerCount configText == 1)
              ( "Sprint 3.16: the generated "
                  <> modeLabel
                  <> " Kind config declares exactly one worker node, one machine per lane; declared: "
                  <> show (generatedWorkerCount configText)
              )
        )
        [ ("linux-cpu", linuxCpuGeneratedKindConfig),
          ("linux-gpu", generatedLinuxGpuKindConfig),
          ("apple-silicon", appleGeneratedKindConfig)
        ]
      let demoConfigPath = buildRoot paths </> "demo-config-test.dhall"
      createDirectoryIfMissing True (buildRoot paths)
      BS.writeFile
        demoConfigPath
        (renderGeneratedDemoConfigPayload paths LinuxCpu singleEngineMachine True linuxCpuUnitInferenceMemoryBudget)
      generatedDemoPlan <-
        decodeCompiledRuntimePlanFile demoConfigPath
          >>= expectDecodedCompiledPlan "rendered linux demo config"
      let generatedDemoConfig =
            unitGeneratedDemoConfig
              paths
              LinuxCpu
              True
              linuxCpuUnitInferenceMemoryBudget
          demoConfig = generatedDemoConfig
      Lazy.writeFile demoConfigPath (encodeDemoConfig demoConfig)
      demoConfigContents <- readFile demoConfigPath
      -- Phase 8 Sprint 8.9: every enum-like choice is a Dhall union value, so
      -- the wire spelling is an alternative label rather than a quoted string.
      assert
        ("runtimeMode = < AppleSilicon | LinuxCpu | LinuxGpu >.LinuxCpu" `isInfixOf` demoConfigContents)
        "generated substrate materialization writes Dhall union alternatives, not text tags"
      assert
        ( not ("runtimeMode = \"" `isInfixOf` demoConfigContents)
            && not ("daemonRole = \"" `isInfixOf` demoConfigContents)
            && not ("adapterType = \"" `isInfixOf` demoConfigContents)
            && not ("fieldType = \"" `isInfixOf` demoConfigContents)
            && not ("runtimeLane = \"" `isInfixOf` demoConfigContents)
            && not ("pulsarConnectionMode = \"" `isInfixOf` demoConfigContents)
            && not ("subscription = \"" `isInfixOf` demoConfigContents)
            && not ("source = \"" `isInfixOf` demoConfigContents)
            && not ("resource = \"" `isInfixOf` demoConfigContents)
        )
        "no generated enum-like field is written as a quoted text tag"
      assert
        (not ("edgePort" `isInfixOf` demoConfigContents))
        "the generated execution plan no longer carries the never-read edgePort placeholder"
      assert
        (not (" = +" `isInfixOf` demoConfigContents))
        "generated quantities are Natural literals, so no Integer sign prefix is written"
      assert
        (not ("\"runtimeMode\":" `isInfixOf` demoConfigContents))
        "generated substrate materialization no longer writes banner-prefixed JSON"
      -- Phase 8 Sprint 8.10: the engine daemons, the topics, the engine list,
      -- the per-entity runtime mode and location, the pool in-flight knob, the
      -- model runtime lane, and the substrate limit's resource/source are all
      -- derived by the binary, so none of them is written at all.
      assert
        ( not ("engineDaemons" `isInfixOf` demoConfigContents)
            && not ("request_topics" `isInfixOf` demoConfigContents)
            && not ("result_topic" `isInfixOf` demoConfigContents)
            && not ("engines =" `isInfixOf` demoConfigContents)
            && not (", runtimeMode =" `isInfixOf` demoConfigContents)
            && not ("runtimeLane" `isInfixOf` demoConfigContents)
            && not ("location =" `isInfixOf` demoConfigContents)
            && not ("maxInflightPerMember" `isInfixOf` demoConfigContents)
            && not ("headroomMib" `isInfixOf` demoConfigContents)
            && not ("resource =" `isInfixOf` demoConfigContents)
            && not ("source =" `isInfixOf` demoConfigContents)
            && not ("host_batch_topic" `isInfixOf` demoConfigContents)
        )
        "generated substrate materialization omits every field the binary derives"
      decodedJsonConfig <-
        maybe (fail "public JSON demo config decode failed") pure (Aeson.decode (Aeson.encode demoConfig))
      assert
        (not (null (engineDaemons decodedJsonConfig)))
        "public JSON demo-config decode preserves engine daemon metadata"
      -- Phase 8 Sprint 8.9: the JSON projection of the budget names its
      -- alternative with a key, not with a string under a shared `kind` key.
      -- `/api/demo-config` is the only surface that carries it and the
      -- Playwright reader is its only consumer, so pin the shape here.
      let renderedBudgetJson =
            LazyChar8.unpack
              (Aeson.encode (inferenceMemoryBudget demoConfig))
      assert
        ( "substrateEnforced" `isInfixOf` renderedBudgetJson
            && not ("\"kind\"" `isInfixOf` renderedBudgetJson)
        )
        "the budget JSON names its alternative with an object key, not a kind text tag"
      assert
        ( ( Aeson.decode (Aeson.encode (inferenceMemoryBudget demoConfig)) ::
              Maybe InferenceMemoryBudget
          )
            == Just (inferenceMemoryBudget demoConfig)
        )
        "the budget JSON round-trips through the key-named alternative encoding"
      assert
        ( retiredBudgetJsonDiagnosticNamesRetirement
            "{\"kind\":\"substrate-enforced\",\"podLimit\":{\"resource\":\"pod-ram\",\"source\":\"cluster-engine-pod-memory-limit\",\"limitMib\":4096}}"
        )
        "a retired kind-tagged budget JSON payload is named as retired, not surfaced as a bare missing-alternative error"
      let decodedConfig = demoConfig
      assert (configRuntimeMode decodedConfig == LinuxCpu) "demo-config decode preserves runtime mode"
      assert (demoUiEnabled decodedConfig) "demo-config decode preserves the demo UI flag"
      assert (daemonConfigLocation (coordinatorDaemon decodedConfig) == "cluster-pod") "demo-config decode preserves cluster daemon metadata"
      assert (daemonConfigRole (webappDaemon decodedConfig) == Webapp) "demo-config decode preserves webapp daemon metadata"
      assert (not (null (engineDaemons decodedConfig))) "linux demo-config decode preserves engine daemon metadata"
      let emptyModelsConfig = demoConfig {models = []}
          emptyModelsConfigPath = buildRoot paths </> "demo-config-empty-models-test.dhall"
      Lazy.writeFile emptyModelsConfigPath (encodeDemoConfig emptyModelsConfig)
      strictEmptyModelsDecode <- try (validateDemoConfigFile emptyModelsConfigPath) :: IO (Either IOError ())
      assert
        (either (isInfixOf "EmptyModelCatalog" . show) (const False) strictEmptyModelsDecode)
        "compiled runtime-config validation rejects image-baked empty-model configs"
      assert
        (daemonConfigConsumerSubscriptionType (coordinatorDaemon decodedConfig) == Just ConsumerShared)
        "linux coordinator metadata uses Shared service subscription ownership"
      assert
        (all ((== Just ConsumerShared) . daemonConfigConsumerSubscriptionType) (engineDaemons decodedConfig))
        "linux engine metadata uses Shared service subscription ownership"
      assert (enginePools decodedConfig == enginePoolsForMode LinuxCpu) "demo-config decode preserves engine pools"
      assert (engineMembers decodedConfig == engineMembersForMode LinuxCpu) "demo-config decode preserves engine members"
      assert (requestTopics decodedConfig == requestTopicsForMode LinuxCpu) "demo-config decode preserves request topics"
      assert (resultTopic decodedConfig == resultTopicForMode LinuxCpu) "demo-config decode preserves the result topic"
      compiledDemoPlan <- decodeCompiledRuntimePlanFile demoConfigPath >>= expectDecodedCompiledPlan "generated linux demo config"
      assert
        (ExecutionPlan.compiledPlanRuntimeMode generatedDemoPlan == LinuxCpu)
        "the rendered Linux config compiles with its generated runtime identity"
      let startupTopics = startupTopicsForPlan compiledDemoPlan
      assert
        (all (`elem` startupTopics) (requestTopics decodedConfig))
        "startup topic reconciliation includes coordinator request topics"
      assert
        (all (all (`elem` startupTopics) . daemonConfigRequestTopics) (engineDaemons decodedConfig))
        "startup topic reconciliation includes derived engine pool request topics"
      assert
        (resultTopic decodedConfig `elem` startupTopics)
        "startup topic reconciliation includes the result topic"
      assert
        (modelBootstrapTopic decodedConfig `elem` startupTopics)
        "startup topic reconciliation includes the model-bootstrap request topic"
      case listToMaybe (models decodedConfig) of
        Just firstModel ->
          assert
            ( ConversationTopic.modelBootstrapReadyTopicName ConversationTopic.systemTopicNamespace (modelId firstModel)
                `elem` startupTopics
            )
            "startup topic reconciliation includes per-model bootstrap ready topics"
        Nothing ->
          fail "expected decoded linux-cpu demo config to include models"
      assert
        (length startupTopics == length (nub startupTopics))
        "startup topic reconciliation produces a deduplicated topic set"
      assert (engines decodedConfig == engineBindingsForMode LinuxCpu) "demo-config decode preserves engine bindings"
      assert (length (models decodedConfig) == length (catalogForMode LinuxCpu)) "demo-config decode preserves the model list"
      case (enginePools decodedConfig, engineMembers decodedConfig) of
        (firstPool : secondPool : remainingPools, firstMember : remainingMembers) -> do
          firstModelId <-
            maybe
              (fail "expected linux-cpu demo config to include at least one model")
              (pure . modelId)
              (listToMaybe (models decodedConfig))
          assertDemoConfigDecodeFails
            unitTestRoot
            "duplicate-pool-id"
            "DuplicatePoolId"
            decodedConfig {enginePools = firstPool : firstPool : secondPool : remainingPools}
          assertDemoConfigDecodeFails
            unitTestRoot
            "invalid-pool-id"
            "InvalidPoolId"
            decodedConfig {enginePools = firstPool {enginePoolId = "persistent://bad/topic"} : secondPool : remainingPools}
          assertDemoConfigDecodeFails
            unitTestRoot
            "failover-pool"
            "InvalidPoolSubscription"
            decodedConfig {enginePools = firstPool {enginePoolSubscriptionType = ConsumerFailover} : secondPool : remainingPools}
          -- Phase 8 Sprint 8.11: five disagreement classes that used to have
          -- their own rejection are now unrepresentable on the wire, so the
          -- assertion is that the round trip /succeeds/ and produces the
          -- agreeing shape. A pool carries its own model descriptors, so a
          -- model id no catalog defines has nowhere to be written; members are
          -- inverted out of the pool graph, so a dangling member, a one-sided
          -- link in either direction, and a member serving no pool cannot be
          -- written either.
          assertDemoConfigWireCannotExpress
            unitTestRoot
            "dangling-pool-model"
            decodedConfig {enginePools = firstPool {enginePoolModelIds = "missing-model" : enginePoolModelIds firstPool} : secondPool : remainingPools}
            ( \roundTripped ->
                all
                  (all (`elem` map modelId (models roundTripped)) . enginePoolModelIds)
                  (enginePools roundTripped)
            )
            "every pool model id names a model the round-tripped catalog defines"
          assertDemoConfigWireCannotExpress
            unitTestRoot
            "dangling-pool-member"
            decodedConfig {enginePools = firstPool {enginePoolMemberIds = ["missing-member"]} : secondPool : remainingPools}
            ( \roundTripped ->
                all
                  (all (`elem` map engineMemberId (engineMembers roundTripped)) . enginePoolMemberIds)
                  (enginePools roundTripped)
            )
            "every pool member id names a member the round-tripped graph defines"
          assertDemoConfigWireCannotExpress
            unitTestRoot
            "one-sided-member-link"
            decodedConfig {engineMembers = firstMember {engineMemberPoolIds = []} : remainingMembers}
            ( \roundTripped ->
                and
                  [ enginePoolId pool `elem` engineMemberPoolIds member
                  | pool <- enginePools roundTripped,
                    member <- engineMembers roundTripped,
                    engineMemberId member `elem` enginePoolMemberIds pool
                  ]
                  && and
                    [ engineMemberId member `elem` enginePoolMemberIds pool
                    | member <- engineMembers roundTripped,
                      pool <- enginePools roundTripped,
                      enginePoolId pool `elem` engineMemberPoolIds member
                    ]
            )
            "the pool/member link round-trips bidirectionally in both directions"
          assertDemoConfigWireCannotExpress
            unitTestRoot
            "duplicate-member-id"
            decodedConfig {engineMembers = firstMember : firstMember : remainingMembers}
            ( \roundTripped ->
                let memberIds = map engineMemberId (engineMembers roundTripped)
                 in memberIds == nub memberIds
            )
            "the round-tripped member set has no duplicate identity"
          assertDemoConfigDecodeFails
            unitTestRoot
            "ambiguous-model-pool"
            "MultiplyPlacedModel"
            decodedConfig {enginePools = firstPool : secondPool {enginePoolModelIds = firstModelId : enginePoolModelIds secondPool} : remainingPools}
          -- The catalog is the pool graph, so an unplaced model has no wire
          -- representation at all: a model exists because a pool declares it.
          assert
            ( all
                (\model -> any ((modelId model `elem`) . enginePoolModelIds) (enginePools decodedConfig))
                (models decodedConfig)
            )
            "every model in the decoded catalog is owned by the pool that declared it"
        _ ->
          fail "expected linux-cpu demo config to include at least two pools and one member"
      assertClusterConfig unitTestRoot demoConfigPath
      let appleConfigPath = buildRoot paths </> "apple-host-demo-config-test.dhall"
      BS.writeFile
        appleConfigPath
        (renderGeneratedDemoConfigPayload paths AppleSilicon singleEngineMachine True appleUnitInferenceMemoryBudget)
      generatedApplePlan <-
        decodeCompiledRuntimePlanFile appleConfigPath
          >>= expectDecodedCompiledPlan "rendered apple demo config"
      let generatedAppleConfig =
            unitGeneratedDemoConfig
              paths
              AppleSilicon
              True
              appleUnitInferenceMemoryBudget
          decodedAppleConfig = generatedAppleConfig
      Lazy.writeFile appleConfigPath (encodeDemoConfig decodedAppleConfig)
      compiledApplePlan <-
        decodeCompiledRuntimePlanFile appleConfigPath
          >>= expectDecodedCompiledPlan "generated apple demo config"
      let appleHostConfig = decodedAppleConfig
          expectedAppleMemberTopics =
            maybe
              []
              ExecutionPlan.compiledDaemonRequestTopics
              (ExecutionPlan.lookupCompiledEngineDaemon "apple-host-default" compiledApplePlan)
      assert (enginePools decodedAppleConfig == enginePoolsForMode AppleSilicon) "apple host demo-config preserves engine pools"
      -- Phase 8 Sprint 8.11: the catalog is the pool graph, so the compiled
      -- model order is pool order rather than catalog order. Compare the sets.
      assert
        ( sortOn modelId (ExecutionPlan.compiledPlanConfiguredModels generatedApplePlan)
            == sortOn modelId (catalogForMode AppleSilicon)
        )
        "the rendered Apple config compiles with every generated catalog model"
      assertExecutionPlanWireAndQuantityProperties unitTestRoot demoConfig appleHostConfig
      DemoConfigProperties.runDemoConfigParserProperties paths
      DemoConfigProperties.runColimaPledgeParserProperties
      EnforcerProperties.runFiniteCgroupLimitParserProperties
      assertExecutionPlanCompilerCoverage paths unitTestRoot demoConfig appleHostConfig
      -- Phase 4 Sprint 4.27 — the typed inference-memory budget
      -- round-trips through the substrate config. Config validation accepts
      -- mixed catalogs even when one model is too large; runtime admission
      -- rejects only the selected oversized request.
      assert
        (inferenceMemoryBudget decodedAppleConfig == appleUnitInferenceMemoryBudget)
        "apple host demo-config preserves the typed inference memory budget"
      assert
        ( all
            ((> 0) . executionContextLength . modelExecutionShape)
            (models decodedAppleConfig)
        )
        "every apple catalog model declares a positive execution context length"
      -- Phase 4 Sprint 4.31 — the checked partition rejects oversubscription and
      -- an undersized headroom; the required footprint rejects a non-positive value.
      assert
        (isRight (mkHostMemoryPartition 65536 49152 minHostHeadroomMib))
        "mkHostMemoryPartition accepts a fitting physical/vmReserve/headroom split"
      assert
        (isLeft (mkHostMemoryPartition 8192 8192 minHostHeadroomMib))
        "mkHostMemoryPartition rejects a vmReserve + headroom split that oversubscribes physical RAM"
      assert
        (isLeft (mkHostMemoryPartition 65536 0 (minHostHeadroomMib - 1)))
        "mkHostMemoryPartition rejects a headroom below the co-tenant floor"
      -- Phase 4 Sprint 4.34: the exact case accepted before the sprint. The
      -- reservations meet physical exactly, so the split is arithmetically valid
      -- and its inference capacity is zero. A zero-capacity partition compiled a
      -- plan, started a daemon, and left every model unavailable, because every
      -- declared footprint is positive.
      assert
        (isLeft (mkHostMemoryPartition (49152 + minHostHeadroomMib) 49152 minHostHeadroomMib))
        "mkHostMemoryPartition rejects a split whose reservations exactly exhaust physical RAM"
      assert
        ( either
            (isInfixOf "leaves no inference capacity")
            (const False)
            (mkHostMemoryPartition (49152 + minHostHeadroomMib) 49152 minHostHeadroomMib)
        )
        "the zero-capacity refusal names what it refused rather than reporting oversubscription"
      assert
        (isLeft (hostPartitionForCapacity 0))
        "hostPartitionForCapacity refuses a zero capacity rather than normalizing it"
      assert
        (isLeft (hostPartitionForCapacity (-1)))
        "hostPartitionForCapacity refuses a negative capacity rather than clamping it to zero"
      assert
        (either (const False) ((== 65536 - 49152 - minHostHeadroomMib) . hostPartitionInferenceCapacityMib) (mkHostMemoryPartition 65536 49152 minHostHeadroomMib))
        "mkHostMemoryPartition derives inference capacity as physical - vmReserve - headroom"
      -- Phase 4 Sprint 4.31 — one claimable pool, two occupants. The pool is
      -- minted once and both occupants are derived from it, so neither is
      -- computed from a figure that is blind to the other, and the resolved
      -- inference capacity on the supported development host is unchanged.
      assert
        (isLeft (mkHostClaimablePool 0 0))
        "mkHostClaimablePool refuses an unmeasured host rather than deriving a pool from zero"
      assert
        (isLeft (mkHostClaimablePool 65536 (-1)))
        "mkHostClaimablePool refuses a negative reserve"
      assert
        (isLeft (mkHostClaimablePool 65536 65536))
        "mkHostClaimablePool refuses a reserve that leaves no pool for either occupant"
      assert
        (either (const False) ((== 16384) . hostClaimablePoolMib) (mkHostClaimablePool 65536 49152))
        "the claimable pool is physical RAM less the virtual-machine reserve"
      assert
        ( either
            (const False)
            ((== 8192) . hostClaimablePoolToolchainAccountMib)
            (mkHostClaimablePool 65536 49152)
        )
        "the toolchain account is the declared share of that same pool"
      assert
        ( either
            (const False)
            ( \partition ->
                hostPartitionClaimablePoolMib partition == 16384
                  && hostPartitionToolchainAccountMib partition == 8192
                  && hostPartitionInferenceCapacityMib partition == 10240
            )
            (mkHostMemoryPartition 65536 49152 minHostHeadroomMib)
        )
        "the partition carries the pool and the toolchain occupant beside an unchanged 10240 MiB capacity"
      assert
        ( either
            (const False)
            (isLeft . mkConcurrentHostPoolClaim)
            (mkHostMemoryPartition 65536 49152 minHostHeadroomMib)
        )
        "a concurrent claim over both occupants of one fully-assigned pool is not constructible"
      assert
        ( either
            (const False)
            ( either
                (isInfixOf "overcommit it by 8192 MiB")
                (const False)
                . mkConcurrentHostPoolClaim
            )
            (mkHostMemoryPartition 65536 49152 minHostHeadroomMib)
        )
        "the concurrent-claim refusal names the overcommitment rather than reporting a bare failure"
      assert
        (isLeft (mkHostResidentRequirement 0) && isLeft (mkHostResidentRequirement (-1)))
        "mkHostResidentRequirement rejects a non-positive host-residency quantity"
      assert
        (isRight (mkHostResidentRequirement 4096))
        "mkHostResidentRequirement accepts a positive host-residency quantity"
      -- Phase 4 Sprint 4.38: a device-using requirement checks /both/ terms, so
      -- a model that uses the device while stating nothing about the device is
      -- not a term rather than a review obligation.
      assert
        ( isLeft (mkHostAndDeviceRequirement 4096 0)
            && isLeft (mkHostAndDeviceRequirement 0 4096)
        )
        "mkHostAndDeviceRequirement rejects a non-positive quantity in either term"
      assert
        (isRight (mkHostAndDeviceRequirement 4096 2048))
        "mkHostAndDeviceRequirement accepts two positive quantities"
      assert
        ( fmap (isJust . modelDeviceRequirement) (mkHostAndDeviceRequirement 4096 2048)
            == Right True
        )
        "a device-using requirement carries its device term by construction"
      assert
        ( fmap (isJust . modelDeviceRequirement) (mkHostResidentRequirement 4096)
            == Right False
        )
        "a host-only requirement carries no device term at all"
      -- Phase 4 Sprint 4.38: one enumeration names the three physical
      -- resources, and its codec keeps the wire spellings the retired
      -- value-level enumeration used. A Haskell-side rename that moved a wire
      -- spelling would be a contract change with its own regeneration; bundling
      -- one into the other is how a type cleanup becomes a compatibility break.
      assert
        ( map resourceText [HostRam, PodRam, NvidiaVram]
            == ["unified-host-ram", "pod-ram", "gpu-vram"]
        )
        "the merged resource codec renders the unchanged wire spellings"
      assert
        ( all
            (\resource -> parseResource (resourceText resource) == Just resource)
            [HostRam, PodRam, NvidiaVram]
        )
        "every resource round-trips through the merged codec"
      assert
        (isNothing (parseResource "unified-host-vram"))
        "the merged resource codec rejects an unknown resource string"
      assert
        ( all
            (\resource -> Aeson.decode (Aeson.encode resource) == Just resource)
            [HostRam, PodRam, NvidiaVram]
        )
        "every resource round-trips through its JSON codec"
      -- Phase 6 Sprint 6.42 — the engine-spawn capability-gating lint fires on a
      -- raw engine spawn in a guarded production file, exempts the capped-engine
      -- kernel (the sole legitimate engine-spawn surface), and passes a clean line.
      assert
        (not (null (unboundedEngineSpawnViolations "src/Infernix/Runtime/Daemon.hs" [(1, "  (_, _, _, ph) <- createProcess spec")])))
        "unboundedEngineSpawnViolations fires on an injected raw createProcess in a guarded file"
      assert
        (null (unboundedEngineSpawnViolations "src/Infernix/Runtime/CappedEngine/Internal.hs" [(1, "  (_, _, _, ph) <- createProcess spec")]))
        "unboundedEngineSpawnViolations exempts the capped-engine kernel module"
      assert
        (null (unboundedEngineSpawnViolations "src/Infernix/Runtime/CappedEngine/FixedObserver.hs" [(1, "  created <- createProcess fixedObserverSpec")]))
        "unboundedEngineSpawnViolations narrowly exempts the fixed public-tool observer kernel"
      assert
        ( not
            ( any
                null
                [ unboundedEngineSpawnViolations
                    "src/Infernix/Runtime/CappedEngine.hs"
                    [(1, "  created <- createProcess callerObserverSpec")],
                  unboundedEngineSpawnViolations
                    "src/Infernix/Runtime/Daemon.hs"
                    [(1, "  created <- createProcess callerObserverSpec")]
                ]
            )
        )
        "unboundedEngineSpawnViolations rejects raw observer spawns in callers and unrelated runtime modules"
      assert
        (null (unboundedEngineSpawnViolations "src/Infernix/Runtime/Daemon.hs" [(1, "  result <- awaitEngineOutcome handle")]))
        "unboundedEngineSpawnViolations passes a line without a raw engine spawn"
      -- Phase 6 Sprint 6.44 follow-on — the descriptor-bound gate fires on a
      -- `close_fds` spawn surface that never observes the bound, and clears the
      -- same file once the observation is present. This is the structural half
      -- of the correction for the 313 s pre-exec descriptor walk a containerd
      -- pod's soft RLIMIT_NOFILE of 1073741816 produces.
      assert
        ( not
            ( null
                ( unboundedDescriptorSpawnViolations
                    "src/Infernix/Runtime/Daemon.hs"
                    [ (1, "  created <- createProcess spec {close_fds = True}")
                    ]
                )
            )
        )
        "unboundedDescriptorSpawnViolations fires on a close_fds spawn that never observes the descriptor bound"
      assert
        ( null
            ( unboundedDescriptorSpawnViolations
                "src/Infernix/Runtime/Daemon.hs"
                [ (1, "  _ <- requireBoundedDescriptorSpace \"daemon spawn\""),
                  (2, "  created <- createProcess spec {close_fds = True}")
                ]
            )
        )
        "unboundedDescriptorSpawnViolations clears a close_fds spawn that observes the descriptor bound"
      assert
        ( null
            ( unboundedDescriptorSpawnViolations
                "src/Infernix/Runtime/Daemon.hs"
                [(1, "  -- close_fds = True is discussed in this comment only")]
            )
        )
        "unboundedDescriptorSpawnViolations ignores close_fds inside a comment"
      assert
        ( null
            ( unboundedDescriptorSpawnViolations
                "src/Infernix/DescriptorSpace.hs"
                [(1, "  spawnDescriptorLimitCeiling = 16384 -- close_fds")]
            )
        )
        "unboundedDescriptorSpawnViolations exempts the module that owns the bound"
      -- Phase 6 Sprint 6.46: the toolchain rule's structural half. The
      -- behavioural half — that a reintroduced uncapped spawn in the real
      -- `src/Infernix/CLI.hs` is rejected — is the same rule applied to the same
      -- file path, so it is asserted here rather than by mutating tracked source.
      assert
        ( not
            ( null
                ( unboundedToolchainSpawnViolations
                    "src/Infernix/CLI.hs"
                    [ (1, "  resolved <- resolveCliHostTool paths HostCabal"),
                      (2, "  created <- createProcess (proc resolved arguments)")
                    ]
                )
            )
        )
        "unboundedToolchainSpawnViolations fires on a toolchain spawn that never observes the build-memory ceiling"
      assert
        ( not
            ( null
                ( unboundedToolchainSpawnViolations
                    "src/Infernix/CLI.hs"
                    [ (1, "  resolved <- resolveCliHostTool paths HostCabal"),
                      (2, "  _ <- requireBoundedDescriptorSpace label"),
                      (3, "  created <- withBoundedToolchainChild authority (createProcess (proc resolved arguments) {close_fds = True, create_group = True})"),
                      (4, "  cleanupToolchainProcessGroupParts label handle group [] []"),
                      (5, "  outcome <- awaitProcessExitReadiness deadline handle")
                    ]
                )
            )
        )
        "unboundedToolchainSpawnViolations rejects an otherwise bounded Cabal spawn that skips the invocation project-state check"
      assert
        ( null
            ( unboundedToolchainSpawnViolations
                "src/Infernix/CLI.hs"
                [ (1, "  resolved <- resolveCliHostTool paths HostCabal"),
                  (2, "  requireToolchainInvocationProjectState authority invocation"),
                  (3, "  _ <- requireBoundedDescriptorSpace label"),
                  (4, "  created <- withBoundedToolchainChild authority (createProcess (proc resolved arguments) {close_fds = True, create_group = True})"),
                  (5, "  cleanupToolchainProcessGroupParts label handle group [] []"),
                  (6, "  outcome <- awaitProcessExitReadiness deadline handle")
                ]
            )
        )
        "unboundedToolchainSpawnViolations clears a toolchain spawn only for the complete owned lifecycle"
      assert
        ( null
            ( unboundedToolchainSpawnViolations
                "src/Infernix/CLI.hs"
                [(1, "  parentDirectories = map takeDirectory [HostCabal, HostGhc]")]
            )
        )
        "unboundedToolchainSpawnViolations ignores a HostCabal mention in a file that spawns nothing"
      assert
        ( null
            ( unboundedToolchainSpawnViolations
                "src/Infernix/CLI.hs"
                [(1, "  -- HostCabal is discussed in this comment only"), (2, "  x = createProcess y")]
            )
        )
        "unboundedToolchainSpawnViolations ignores HostCabal inside a comment"
      assert
        ( null
            ( unboundedToolchainSpawnViolations
                "src/Infernix/BuildMemory.hs"
                [(1, "  toolchain = HostCabal"), (2, "  spawn = createProcess spec")]
            )
        )
        "unboundedToolchainSpawnViolations exempts the module that owns the boundary"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/Subprocess.hs"
                    [(1, "{-# LANGUAGE ForeignFunctionInterface #-}")]
                )
            )
        )
        "native-boundary lint rejects ForeignFunctionInterface in the subprocess kernel"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/Subprocess/Protocol.hs"
                    [(1, "foreign import ccall unsafe \"spawn\" c_spawn :: IO Int")]
                )
            )
        )
        "native-boundary lint rejects a direct foreign import in subprocess evidence"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [ (1, "foreign"),
                      (2, "  import ccall unsafe \"spawn\" c_spawn :: IO Int")
                    ]
                )
            )
        )
        "native-boundary lint rejects a direct foreign import split across lines"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [ (1, "foreign"),
                      (2, "  export ccall infernix_spawn :: IO Int")
                    ]
                )
            )
        )
        "native-boundary lint rejects a direct foreign export split across lines"
      assert
        ( not
            ( any
                null
                [ unsafeNativeBoundaryViolations
                    "app/RelocatedShim.hs"
                    [(1, "foreign import ccall unsafe \"spawn\" c_spawn :: IO Int")],
                  unsafeNativeBoundaryViolations
                    "src/RelocatedShim.hs"
                    [(1, "import Language.C.Inline qualified as C")]
                ]
            )
        )
        "native-boundary lint covers every production Haskell source root"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [ (1, "quote = '\"'"),
                      (2, "foreign import ccall unsafe \"spawn\" c_spawn :: IO Int")
                    ]
                )
            )
        )
        "native-boundary lint cannot be desynchronized by a character literal"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [ (1, "#define FOREIGN foreign"),
                      (2, "FOREIGN import ccall unsafe \"spawn\" c_spawn :: IO Int")
                    ]
                )
            )
        )
        "native-boundary lint rejects CPP macro definitions that could hide boundary tokens"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Runtime/Daemon.hs"
                    [(1, "import Infernix.Cluster.Subprocess.Protocol")]
                )
            )
        )
        "native-boundary lint confines subprocess protocol capabilities to their kernel owner"
      assert
        ( all
            null
            [ unsafeNativeBoundaryViolations
                "src/Infernix/Cluster/Subprocess/Activity.hs"
                [(1, "module Infernix.Cluster.Subprocess.Activity where")],
              unsafeNativeBoundaryViolations
                "src/Infernix/Cluster/Subprocess/Protocol.hs"
                [(1, "module Infernix.Cluster.Subprocess.Protocol where")]
            ]
        )
        "native-boundary lint distinguishes internal module declarations from forbidden imports"
      assert
        ( not
            ( null
                ( unsafeNativeBoundaryViolations
                    "src/Infernix/Runtime/Daemon.hs"
                    [ (1, "import"),
                      (2, "  Infernix.Cluster.Subprocess.Protocol")
                    ]
                )
            )
        )
        "native-boundary lint rejects a multiline subprocess protocol import"
      assert
        ( not
            ( any
                null
                [ unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [(1, "import System.Process.Internal")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [(1, "import System.Process.Internals")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/Cluster/RelocatedShim.hs"
                    [(1, "import Language.C.Inline qualified as C")]
                ]
            )
        )
        "native-boundary lint rejects process internals and inline-C after cosmetic relocation"
      assert
        ( not
            ( any
                null
                [ unsafeNativeBoundaryViolations
                    "src/Infernix/Runtime/Daemon.hs"
                    [(1, "child <- forkProcess action")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/CLI.hs"
                    [(1, "executeFile executable False arguments environment")]
                ]
            )
        )
        "native-boundary lint permits raw POSIX fork/exec only inside the bounded-command kernel"
      assert
        ( null
            ( unsafeNativeBoundaryViolations
                "src/Infernix/Lint/HaskellStyle.hs"
                [ (1, "-- System.Process.Internal ForeignFunctionInterface"),
                  (2, "{- Language.C.Inline"),
                  (3, "foreign import ccall unsafe \"spawn\" -}"),
                  (4, "example = \"System.Process.Internals foreign import\"")
                ]
            )
        )
        "native-boundary lint ignores policy tokens in comments and string literals"
      assert
        ( not
            ( any
                null
                [ unsafeNativeBoundaryViolations
                    "src/Infernix/ProcessIdentity.hs"
                    [(1, "foreign import ccall unsafe \"proc_pid_rusage\" c_proc_pid_rusage :: CInt -> CInt -> Ptr () -> IO CInt")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/Runtime/CappedEngine/Internal.hs"
                    [(1, "foreign import ccall unsafe \"proc_pid_rusage\" c_proc_pid_rusage :: CInt -> CInt -> Ptr () -> IO CInt")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/Runtime/CappedEngine/FixedObserver.hs"
                    [(1, "foreign import ccall unsafe \"sysctlbyname\" c_sysctlbyname :: CString -> IO CInt")],
                  unsafeNativeBoundaryViolations
                    "app/Main.hs"
                    [(1, "foreign import ccall unsafe \"posix_spawn\" c_spawn :: IO Int")],
                  unsafeNativeBoundaryViolations
