                    [(1, "> foreign import ccall unsafe \"getpid\" c_getpid :: IO Int")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/Signature.hsig"
                    [(1, "foreign import ccall unsafe \"getpid\" c_getpid :: IO Int")],
                  unsafeNativeBoundaryViolations
                    "src/Infernix/LiterateSignature.lhsig"
                    [(1, "> foreign import ccall unsafe \"getpid\" c_getpid :: IO Int")]
                ]
            )
