              routes = [RouteInfo "/" "demo web UI"],
              storageClass = "standard",
              claims = [],
              clusterRuntimeMode = LinuxCpu,
              clusterEngineMemberIds = [],
              kubeconfigPath = Config.generatedKubeconfigPath linuxCpuOuterPaths,
              generatedDemoConfigPath = Config.generatedDemoConfigPath linuxCpuOuterPaths,
              publishedDemoConfigPath = Config.publishedConfigMapCatalogPath linuxCpuOuterPaths,
              publishedConfigMapManifestPath = Config.publishedConfigMapManifestPath linuxCpuOuterPaths,
              mountedDemoConfigPath = "/var/infernix/demo/infernix-substrate.dhall",
              updatedAt = linuxCpuFinalNow
            }
        linuxCpuFinalValues = renderHelmValues linuxCpuOuterPaths OuterContainer linuxCpuFinalState "{}" [] FinalPhase
        linuxCpuPulsarReadyValues = renderHelmValues linuxCpuOuterPaths OuterContainer linuxCpuFinalState "{}" [] PulsarReadyPhase
        expectedKeycloakExternalBaseUrl =
          "  externalBaseUrl: http://"
            <> kindControlPlaneNodeName linuxCpuOuterPaths LinuxCpu
            <> ":30090/auth"
        expectedPulsarReadyKeycloakBlock =
          unlines
            [ "keycloak:",
              expectedKeycloakExternalBaseUrl,
              "  enabled: true"
            ]
    assert
      (length (filter (== expectedKeycloakExternalBaseUrl) (lines linuxCpuFinalValues)) == 2)
      "linux-cpu final Helm values preserve Keycloak externalBaseUrl across the local resource override"
    assert
      (expectedPulsarReadyKeycloakBlock `isInfixOf` linuxCpuPulsarReadyValues)
      "linux-cpu Pulsar-ready Helm values start Keycloak before final app workloads"
    -- Phase 8 Sprint 8.4 regression guard: the operator-routes SecurityPolicy
    -- builds its JWT `issuer` from `clusterConfig.keycloak.baseUrl`, which must
    -- be the routed edge URL (matching the `iss` Keycloak stamps into tokens),
    -- not the chart's `http://127.0.0.1/auth` default. Emitting it under the same
    -- `clusterConfig:` block as `body` keeps the SecurityPolicy and the mounted
    -- cluster config consistent; dropping it 401s every valid operator token.
    assert
      ( ("    baseUrl: http://" <> kindControlPlaneNodeName linuxCpuOuterPaths LinuxCpu <> ":30090/auth")
          `elem` lines linuxCpuFinalValues
      )
      "Sprint 8.4: final Helm values set clusterConfig.keycloak.baseUrl to the routed edge URL so the operator-route SecurityPolicy issuer matches Keycloak token iss"
    assert
      ("      memory: 5120Mi" `isInfixOf` linuxCpuFinalValues)
      "linux-cpu final Helm values keep a 1 GiB daemon/watchdog envelope above the 4 GiB child-execution budget"
    -- Phase 6 Sprint 6.44 regression guard. Runtime refinement compares the
    -- observed pod cgroup limit with `childBudget + linuxOuterEnvelopeHeadroomMib`
    -- for **exact** equality, so the generated engine memory limit and the
    -- generated child budget are two halves of one contract. The `linux-cpu`
    -- half was asserted above; the `linux-gpu` half was not, and reusing the CPU
    -- lane's 4 GiB budget against the GPU lane's 16 GiB engine pod produced
    -- `OuterEnvelopeTooLarge 5120 16384` on every GPU placement — no engine ever
    -- became ready, and no machine-independent gate could see it because
    -- `linux-gpu` compiled no plan at all before this sprint. Pin both halves.
    assert
      ( linuxGpuEngineInferenceRamBudgetMib + ExecutionPlan.linuxOuterEnvelopeHeadroomMib
          == linuxGpuEnginePodMemoryLimitMib
      )
      "linux-gpu child-execution budget plus the daemon/watchdog headroom equals the engine pod memory limit exactly, as runtime refinement requires"
    assert
      ( linuxEngineInferenceRamBudgetMib + ExecutionPlan.linuxOuterEnvelopeHeadroomMib
          == 5120
      )
      "linux-cpu child-execution budget plus the daemon/watchdog headroom equals its 5 GiB engine pod memory limit exactly"
    assert
      ("      PULSAR_GC: \"-XX:+UseSerialGC -XX:+ExitOnOutOfMemoryError -XX:+DisableExplicitGC -XX:+PerfDisableSharedMem\"" `isInfixOf` linuxCpuFinalValues)
      "linux-cpu final Helm values override local Pulsar JVM GC away from the default pre-touch profile"
    assert
      ("      PULSAR_MEM: \"-Xms64m -Xmx128m -XX:MaxDirectMemorySize=64m\"" `isInfixOf` linuxCpuFinalValues)
      "linux-cpu final Helm values cap local Pulsar proxy heap and direct memory"
    assert
      ("      httpNumThreads: \"8\"" `isInfixOf` linuxCpuFinalValues)
      "linux-cpu final Helm values keep enough local Pulsar proxy HTTP threads for Jetty startup"
    assert
      ("      httpServerIdleTimeout: \"7200000\"" `isInfixOf` linuxCpuFinalValues)
      "linux-cpu final Helm values keep a Pulsar WebSocket consumer alive through bounded real inference"
    -- Phase 8 Sprint 8.4: the binary renders the cluster-config ConfigMap
    -- body and the cluster-secrets manifest as strings; the Helm values
    -- carry them under `clusterConfig.body` / `clusterSecrets.manifest`, and
    -- the chart template only `nindent`s the string.
    assert
      ("clusterConfig:" `isInfixOf` linuxCpuFinalValues && "  body: |" `isInfixOf` linuxCpuFinalValues)
      "Sprint 8.4: final Helm values carry the binary-rendered clusterConfig.body"
    assert
      ("    { pulsar = { httpBaseUrl = \"http://infernix-infernix-pulsar-proxy.platform.svc.cluster.local\"" `isInfixOf` linuxCpuFinalValues)
      "Sprint 8.4: the rendered clusterConfig.body embeds the default Pulsar wiring"
    assert
