    let registryFailureMeasured =
          case classifyRegistryApiStatus 503 of
            Left progress ->
              Readiness.progressObserved progress == 0
                && Readiness.progressExpected progress == 1
                && "503"
                  `Text.isInfixOf` Readiness.progressDetail progress
            Right () -> False
    assert
