    assert
      (dockerHubMirrorRef "docker.io/percona/percona-pgbackrest:2.58.0-1" == Just "mirror.gcr.io/percona/percona-pgbackrest:2.58.0-1")
      "docker hub fallback maps explicit docker.io refs to mirror.gcr.io"
