    -- nvkind configmap-persistence bug detector: matches only the upstream
    -- failure signature (the @%!w(<nil>)@ wrapped-nil marker together with
    -- the config/configmap write phrase), and ignores unrelated failures so
    -- the repo-owned GPU node recovery path is not taken for the wrong error.
    assert
      ( linuxGpuNvkindConfigMapBug
          "failed adding config to cluster \"infernix-linux-gpu\": %!w(<nil>)"
      )
      "nvkind detector matches the 'adding config to cluster' + %!w(<nil>) signature"
    assert
      ( linuxGpuNvkindConfigMapBug
          "error writing configmap: %!w(<nil>)"
      )
      "nvkind detector matches the 'writing configmap' + %!w(<nil>) signature"
    assert
      (not (linuxGpuNvkindConfigMapBug "address already in use"))
      "nvkind detector ignores the port-rebind retry signature"
    assert
      (not (linuxGpuNvkindConfigMapBug "writing configmap: connection refused"))
      "nvkind detector ignores a configmap-write error without the %!w(<nil>) marker"
    assert
      (not (linuxGpuNvkindConfigMapBug "boom %!w(<nil>) during node image pull"))
      "nvkind detector ignores the %!w(<nil>) marker without a config/configmap write phrase"
    assert
      (not (linuxGpuNvkindConfigMapBug ""))
      "nvkind detector ignores an empty error"
  -- Phase 1 Sprint 1.16: managed-state-transition evidence + command kernels.
  readinessStepRef <- IORef.newIORef (0 :: Int)
  let scriptedReadinessStep target = do
        observed <- IORef.readIORef readinessStepRef
        IORef.writeIORef readinessStepRef (observed + 1)
        pure
          ( if observed >= target
              then Right observed
              else Left (Readiness.Progress observed target "staging")
          )
  readyOutcome <-
    Readiness.awaitReadiness (Readiness.Deadline 0 30 30) (scriptedReadinessStep 3)
  assert
    (Readiness.foldReadiness (const True) (const False) (const False) readyOutcome)
    "awaitReadiness yields Ready once the step reports evidence"
  (_, _, _, closedProcessHandle) <-
    createProcess (proc "/usr/bin/true" [])
  closedProcessExit <- waitForProcess closedProcessHandle
  maskedCutoffTransition <-
    Readiness.awaitProcessExitReadiness
      (Readiness.pollLimitedDeadline 0 0 0 1)
      closedProcessHandle
  assert
    ( closedProcessExit == ExitSuccess
        && Readiness.foldReadiness
          (== ExitSuccess)
          (const False)
          (const False)
          maskedCutoffTransition
    )
    "a masked nonblocking positive transition survives the post-probe cutoff instead of rearming destructive cleanup after reap"
  stalledOutcome <-
    Readiness.awaitReadiness
      (Readiness.Deadline 0 1 100)
      (pure (Left (Readiness.Progress 1 3 "stuck")) :: IO (Either Readiness.Progress Int))
  assert
    (Readiness.foldReadiness (const False) (const False) (const True) stalledOutcome)
    "awaitReadiness with no new progress resolves as Expired past the stall window"
  -- Managed-state-transition hardening (warm-model-cache "11/16" stall): an
  -- Unobservable poll (a transient MinIO HEAD fault) must not be mistaken for a
  -- not-ready measurement. It is retried within budget, so a present-but-
  -- momentarily-faulting cache still resolves Ready rather than plateauing at a
  -- fabricated count until the give-up deadline.
  observableStepRef <- IORef.newIORef (0 :: Int)
  let scriptedObservableStep faults = do
        n <- IORef.readIORef observableStepRef
        IORef.writeIORef observableStepRef (n + 1)
        pure
          ( if n < faults
              then Readiness.Unobservable (Text.pack "transient MinIO HEAD fault")
              else Readiness.Measured (Right n)
          )
  transientFaultOutcome <-
    Readiness.awaitReadinessObservable (Readiness.Deadline 0 30 30) (scriptedObservableStep 5)
  assert
    (Readiness.foldReadiness (const True) (const False) (const False) transientFaultOutcome)
    "awaitReadinessObservable retries Unobservable polls and still yields Ready once the cache is observed present (warm-cache 11/16 stall regression)"
  persistentUnobservableOutcome <-
    Readiness.awaitReadinessObservable
      (Readiness.Deadline 0 3 100)
      (pure (Readiness.Unobservable (Text.pack "MinIO unreachable")) :: IO (Readiness.PollOutcome Int))
  assert
    (Readiness.foldReadiness (const False) (const False) (const True) persistentUnobservableOutcome)
    "awaitReadinessObservable gives up bounded (Expired) when every poll is Unobservable past the stall window"
  let exactPollAttempts = 4
      exactPollCapDeadline =
        Readiness.pollLimitedDeadline 0 30 30 exactPollAttempts
  measuredPollCountRef <- IORef.newIORef (0 :: Int)
  measuredBudgetOutcome <-
    Readiness.awaitReadiness
      exactPollCapDeadline
      ( do
          measuredPoll <-
            IORef.atomicModifyIORef'
              measuredPollCountRef
              (\count -> let next = count + 1 in (next, next))
          pure
            ( Left
                (Readiness.Progress measuredPoll (exactPollAttempts + 1) "advancing")
            ) ::
            IO (Either Readiness.Progress ())
      )
  measuredPollCount <- IORef.readIORef measuredPollCountRef
  assert
    ( measuredPollCount == exactPollAttempts
        && Readiness.foldReadiness (const False) (const True) (const False) measuredBudgetOutcome
    )
    "pollLimitedDeadline enforces the exact maximum Measured poll count and classifies advancing cap exhaustion as NotReady"
  stalledMeasuredPollCountRef <- IORef.newIORef (0 :: Int)
  stalledMeasuredBudgetOutcome <-
    Readiness.awaitReadiness
      exactPollCapDeadline
      ( do
          IORef.modifyIORef' stalledMeasuredPollCountRef (+ 1)
          pure (Left (Readiness.Progress 0 1 "not advancing")) ::
            IO (Either Readiness.Progress ())
      )
  stalledMeasuredPollCount <- IORef.readIORef stalledMeasuredPollCountRef
  assert
    ( stalledMeasuredPollCount == exactPollAttempts
        && Readiness.foldReadiness (const False) (const False) (const True) stalledMeasuredBudgetOutcome
    )
    "pollLimitedDeadline classifies an exact-cap constant Measured stream as Expired"
  unobservablePollCountRef <- IORef.newIORef (0 :: Int)
  unobservableBudgetOutcome <-
    Readiness.awaitReadinessObservable
      exactPollCapDeadline
      ( do
          IORef.modifyIORef' unobservablePollCountRef (+ 1)
          pure (Readiness.Unobservable "readiness transport unavailable") ::
            IO (Readiness.PollOutcome ())
      )
  unobservablePollCount <- IORef.readIORef unobservablePollCountRef
  assert
    ( unobservablePollCount == exactPollAttempts
        && Readiness.foldReadiness (const False) (const False) (const True) unobservableBudgetOutcome
    )
    "pollLimitedDeadline enforces the exact maximum Unobservable poll count and classifies wholly unobservable cap exhaustion as Expired"
  wallLimitedPollCountRef <- IORef.newIORef (0 :: Int)
  wallLimitedBudgetOutcome <-
    Readiness.awaitReadiness
      (Readiness.budgetDeadline exactPollAttempts 250000)
      ( ( do
            poll <-
              IORef.atomicModifyIORef'
                wallLimitedPollCountRef
                (\count -> let next = count + 1 in (next, next))
            if poll == 1
              then
                pure
                  ( Left
                      (Readiness.Progress poll (exactPollAttempts + 1) "advancing")
                  )
              else do
                threadDelay 5000000
                pure
                  ( Left
                      (Readiness.Progress poll (exactPollAttempts + 1) "advancing")
                  )
        ) ::
          IO (Either Readiness.Progress ())
      )
  wallLimitedPollCount <- IORef.readIORef wallLimitedPollCountRef
  assert
