  concurrentQuickResult <-
    runTestCommand (Subprocess.TestEcho "concurrent-quick")
  concurrentLongResult <-
    timeout 30000000 (MVar.takeMVar concurrentLongOutcome)
  assert
    ( concurrentQuickResult
