        && anchorReapEvidence == expectedAnchorReaps
        && supervisorReapEvidence == expectedSupervisorReaps
        && designatedAnchorAbsent
        && designatedSupervisorAbsent
        && designatedPinAbsent
        && designatedTargetAbsent
        && designatedQuiescent
