      80
      synchronousTargetIdentity
  synchronousDescendantAbsent <-
    waitForRecordedIdentityAbsent
      80
      synchronousDescendantIdentity
  synchronousQuiescent <-
    waitForBoundedCommandActivitiesQuiescent
