                              { HostConfig.dhallRetry =
                                  HostConfig.Bounded
                                    HostConfig.DhallBoundedRetry
                                      { HostConfig.dhallAttempts = 3,
                                        HostConfig.dhallBackoffMicros = 5000000
                                      }
                              }
