        && cancelledAnchorAbsent
        && cancelledSupervisorAbsent
        && cancelledPinAbsent
        && cancelledGroupAbsent
        && Subprocess.boundedCommandActivitiesOwnerProcessGroup
          cancelledActivitiesQuiescent
          == cancelledOwnerProcessGroup
