  let stoppedSupervisorChildPidPath =
        subprocessRoot </> "bounded-stopped-supervisor-child.pid"
  removeTestPathIfPresent stoppedSupervisorChildPidPath
  stoppedSupervisorResult <- MVar.newEmptyMVar
  _ <-
    forkIO
      ( try @SomeException
