  retryWorkersThawed <- workersAreThawed
  retryKindLog <- System.IO.readFile' snapshotKindLog
  retryDockerLog <- System.IO.readFile' snapshotDockerLog
  retryDeleteAttempted <- doesFileExist snapshotDeleteMarker
  retryObservedCleanIncoming <- doesFileExist snapshotRetryCleanMarker
  retryObservedStaleIncoming <- doesFileExist snapshotRetryFoundStaleMarker
  stalePartialStillPresent <- doesFileExist firstPartialPath
  retryPartialPresent <- doesFileExist retryPartialPath
  retryMarkerPresent <- doesFileExist snapshotCompletionMarker
  retryPreviousPresent <- doesDirectoryExist previousSnapshotRoot
  retryReservationRetained <- doesFileExist snapshotReservationPath
  committedSnapshotAfterRetryFailure <-
    snapshotDirectoryTree committedSnapshotRoot
  assert
    ( isLeft retryCopyFailureResult
        && retryWorkersThawed
        && loggedThaw snapshotWorkerA retryDockerLog
        && loggedThaw snapshotWorkerB retryDockerLog
        && any ("cp " `isPrefixOf`) (lines retryDockerLog)
        && noKindDelete retryKindLog
        && not retryDeleteAttempted
        && retryObservedCleanIncoming
        && not retryObservedStaleIncoming
        && not stalePartialStillPresent
        && retryPartialPresent
        && not retryMarkerPresent
        && not retryPreviousPresent
        && retryReservationRetained
        && committedSnapshotAfterRetryFailure == committedSnapshotBeforeFaults
    )
    "a retry discards the prior incomplete incoming tree before copying, never promotes it, preserves committed bytes, and still blocks Kind deletion"

  removeFile snapshotLiveMarker
  snapshotFaultCleanup <-
    try @IOException
      (releaseHarnessClusterSlotAt snapshotFaultPaths (Just AppleSilicon))
  snapshotReservationAfterCleanup <-
    doesFileExist snapshotReservationPath
  assert
    (isRight snapshotFaultCleanup && not snapshotReservationAfterCleanup)
    "the retained-snapshot rollback fixture releases its harness reservation after the synthetic cluster becomes absent"
  removeTestPathIfPresent snapshotFaultRoot
  -- Sprint 2.15: ownership authorization combines actual Kind presence with
  -- persisted ownership. An absent slot remains available to the first creator,
  -- while every live cluster requires a matching present owner record.
  let mstRuntimeMode = clusterRuntimeMode mstState
      -- Sprint 6.45: authorization now also consumes the checkout identity the
      -- live cluster carries. The pre-existing assertions below are about the
      -- owner record, so they run against a slot this checkout created; the
      -- cross-checkout assertions that follow them vary the two identities
      -- independently.
      mstCheckout = clusterCheckoutIdentityFromHostRoot "/home/operator/infernix"
      authorizeOwnSlot ::
        ClusterOwner ->
        RuntimeMode ->
        [RuntimeMode] ->
        Maybe ClusterState ->
        Either ClusterOwnershipRefusal ClusterSlotAdmission
      authorizeOwnSlot owner runtimeMode presentRuntimeModes maybeState =
        authorizeClusterOwnership
          owner
          runtimeMode
          presentRuntimeModes
          maybeState
          mstCheckout
          (ClusterSlotIdentifiedAs mstCheckout)
      replayPhase =
        LifecyclePhase
          { lifecyclePhaseTransition = LifecycleBringUp,
            lifecyclePhaseName = "replay-retained-state-into-kind",
            lifecyclePhaseDetail = "replaying retained state before workloads start",
            lifecyclePhaseHeartbeatAt = mstNow
          }
      replayProvisioningState =
        mstState {clusterLifecycle = ClusterProvisioning replayPhase}
      replayActivatingState =
        mstState {clusterLifecycle = ClusterActivating replayPhase}
      legacyProvisioningState =
        mstState
          { clusterLifecycle =
              ClusterProvisioning
                replayPhase
                  { lifecyclePhaseName = "prepare-kind-cluster"
                  }
          }
      invalidReplayTransitionState =
        mstState
          { clusterLifecycle =
              ClusterActivating
                replayPhase
                  { lifecyclePhaseTransition = LifecycleMutate
                  }
          }
  assert
    ( retainedReplayPlan False False OperatorOwned mstRuntimeMode Nothing
        == StartRetainedReplay
        && retainedReplayPlan True True OperatorOwned mstRuntimeMode Nothing
          == RetainedReplayNotRequired
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode (Just replayProvisioningState)
          == ResumeRetainedReplay
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode (Just replayActivatingState)
          == ResumeRetainedReplay
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode (Just (mstState {clusterLifecycle = ClusterReady}))
          == RetainedReplayNotRequired
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode Nothing
          == RefuseAmbiguousRetainedReplay
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode (Just legacyProvisioningState)
          == RefuseAmbiguousRetainedReplay
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode (Just invalidReplayTransitionState)
          == RefuseAmbiguousRetainedReplay
        && retainedReplayPlan False True HarnessOwned mstRuntimeMode (Just replayProvisioningState)
          == RefuseAmbiguousRetainedReplay
        && retainedReplayPlan False True OperatorOwned AppleSilicon (Just replayProvisioningState)
          == RefuseAmbiguousRetainedReplay
        && retainedReplayPlan False True OperatorOwned mstRuntimeMode (Just (mstState {clusterLifecycle = ClusterAbsent}))
          == RefuseAmbiguousRetainedReplay
    )
    "detached retained replay starts only for absence, resumes only from the exact durable intent, and refuses ambiguous live clusters"
  assert
    ( retainedReplayPending replayProvisioningState
        && retainedReplayPending replayActivatingState
        && not (retainedReplayPending legacyProvisioningState)
        && not (retainedReplayPending invalidReplayTransitionState)
    )
    "retained replay intent requires the reserved phase name and bring-up transition in a pre-workload lifecycle position"
  assert
    ( kindKubeconfigRecoveryPlan StartRetainedReplay
        == RecreatePreWorkloadKind
        && kindKubeconfigRecoveryPlan ResumeRetainedReplay
          == RecreatePreWorkloadKind
        && kindKubeconfigRecoveryPlan RetainedReplayNotRequired
          == LeaveUnreadableKindUntouched
        && kindKubeconfigRecoveryPlan RefuseAmbiguousRetainedReplay
          == LeaveUnreadableKindUntouched
    )
    "an unreadable kubeconfig authorizes delete-and-recreate only while exact pre-workload replay intent is required"
  assert
    (isRight (authorizeOwnSlot HarnessOwned mstRuntimeMode [] Nothing))
    "an actually absent unrecorded slot authorizes the harness as first creator"
  assert
    (isRight (authorizeOwnSlot HarnessOwned mstRuntimeMode [] (Just mstState)))
    "an actually absent slot ignores a stale other-owner record for first-creator behavior"
  assert
    (isRight (authorizeOwnSlot HarnessOwned mstRuntimeMode [mstRuntimeMode] (Just (mstState {clusterOwner = HarnessOwned}))))
    "a live HarnessOwned cluster authorizes the harness"
  assert
    (isRight (authorizeOwnSlot OperatorOwned mstRuntimeMode [mstRuntimeMode] (Just mstState)))
    "a live OperatorOwned cluster authorizes the operator"
  assert
    (isLeft (authorizeOwnSlot HarnessOwned mstRuntimeMode [mstRuntimeMode] (Just mstState)))
    "a live OperatorOwned cluster refuses harness takeover and teardown"
  assert
    (isLeft (authorizeOwnSlot OperatorOwned mstRuntimeMode [mstRuntimeMode] (Just (mstState {clusterOwner = HarnessOwned}))))
    "a live HarnessOwned cluster refuses operator takeover, teardown, and kubectl passthrough"
  assert
    (isLeft (authorizeOwnSlot OperatorOwned mstRuntimeMode [mstRuntimeMode] Nothing))
    "a live cluster without matching persisted state fails closed for the operator"
  assert
    (isRight (authorizeOwnSlot OperatorOwned mstRuntimeMode [mstRuntimeMode] (Just (mstState {clusterLifecycle = ClusterAbsent}))))
    "a live cluster preserves its recorded owner through an interrupted lifecycle transition"
  assert
    (isLeft (authorizeOwnSlot HarnessOwned mstRuntimeMode [mstRuntimeMode] (Just (mstState {clusterLifecycle = ClusterAbsent}))))
    "a live cluster with an absent lifecycle still refuses the other owner"
  assert
    ( isRight (authorizeOwnSlot HarnessOwned mstRuntimeMode [] Nothing)
        && isLeft (authorizeOwnSlot HarnessOwned mstRuntimeMode [mstRuntimeMode] (Just mstState))
    )
    "a harness cleanup recheck refuses an operator that wins the slot after initial seizure"
  assert
    (isLeft (authorizeOwnSlot HarnessOwned mstRuntimeMode [AppleSilicon] (Just (mstState {clusterOwner = HarnessOwned, clusterRuntimeMode = AppleSilicon}))))
    "a live cluster in another runtime cannot be ignored by a harness operation"
  assert
    (isLeft (authorizeOwnSlot OperatorOwned mstRuntimeMode [mstRuntimeMode, AppleSilicon] (Just mstState)))
    "two live Infernix runtimes are an invariant breach that fails closed"
  -- Sprint 6.45: the cross-checkout guard. The lifecycle lock, the harness
  -- reservation, and the persisted state are all repo-local, while the Kind
  -- cluster they protect is machine-global, so the ownership record alone
  -- cannot tell "my cluster" from "the other checkout's cluster". These
  -- fixtures are the two distinct checkouts that difference requires.
  let secondCheckout = clusterCheckoutIdentityFromHostRoot "/home/operator/infernix-second"
      harnessState = mstState {clusterOwner = HarnessOwned}
      authorizeFrom checkoutIdentity slotIdentity owner state =
        authorizeClusterOwnership
          owner
          mstRuntimeMode
          [mstRuntimeMode]
          (Just state)
          checkoutIdentity
          slotIdentity
      refusalReasonOf outcome =
        case outcome of
          Left refusal -> Just (ownershipRefusalReason refusal)
          Right _ -> Nothing
  assert
    ( refusalReasonOf
        (authorizeFrom secondCheckout (ClusterSlotIdentifiedAs mstCheckout) HarnessOwned harnessState)
        == Just (ForeignCheckoutSlot mstCheckout)
        && refusalReasonOf
          (authorizeFrom secondCheckout (ClusterSlotIdentifiedAs mstCheckout) OperatorOwned mstState)
          == Just (ForeignCheckoutSlot mstCheckout)
    )
    "a second checkout cannot authorize a cluster it did not create, even holding a leftover matching owner record"
  assert
    ( authorizeFrom mstCheckout (ClusterSlotIdentifiedAs mstCheckout) HarnessOwned harnessState
        == Right ClusterSlotOwned
        && authorizeFrom mstCheckout (ClusterSlotIdentifiedAs mstCheckout) OperatorOwned mstState
          == Right ClusterSlotOwned
    )
    "the creating checkout still authorizes its own cluster for either owner"
  assert
    ( refusalReasonOf (authorizeFrom mstCheckout ClusterSlotUnidentified HarnessOwned harnessState)
        == Just UnidentifiedClusterSlot
        && authorizeFrom mstCheckout ClusterSlotUnidentified OperatorOwned mstState
          == Right ClusterSlotAdoptable
        && authorizeFrom mstCheckout ClusterSlotUnidentified OperatorOwned harnessState
          == Right ClusterSlotAdoptable
    )
    "an unidentified cluster is adoptable by the explicit operator even after interrupted harness ownership, and is always refused to the harness"
  assert
    ( authorizeClusterOwnership HarnessOwned mstRuntimeMode [] (Just harnessState) secondCheckout ClusterSlotUnidentified
        == Right ClusterSlotAbsent
        && authorizeClusterOwnership HarnessOwned mstRuntimeMode [] Nothing secondCheckout (ClusterSlotIdentifiedAs mstCheckout)
          == Right ClusterSlotAbsent
    )
    "an absent inventory has no resource to identify and stays available to the first creator"
  assert
    ( clusterCheckoutIdentityFromHostRoot "/home/operator/infernix/"
        == clusterCheckoutIdentityFromHostRoot "/home/operator/infernix"
        && clusterCheckoutIdentityFromHostRoot "/home/operator//infernix"
          == clusterCheckoutIdentityFromHostRoot "/home/operator/infernix"
        && clusterCheckoutIdentityFromHostRoot "/home/operator/infernix"
          /= clusterCheckoutIdentityFromHostRoot "/home/operator/infernix-second"
    )
    "checkout identity compares host roots after normalization, so a trailing or doubled separator is not a different checkout"
  assert
    ( isRight
        (authorizeHarnessReservationAccess OperatorOwned 100 True Nothing Nothing)
        && isLeft
          (authorizeHarnessReservationAccess OperatorOwned 100 True (Just 100) Nothing)
        && isLeft
          (authorizeHarnessReservationAccess HarnessOwned 100 False (Just 100) Nothing)
        && isLeft
          (authorizeHarnessReservationAccess HarnessOwned 100 True (Just 101) Nothing)
        && isRight
          (authorizeHarnessReservationAccess HarnessOwned 100 True (Just 100) Nothing)
    )
    "harness mutation authority requires a live reservation in the caller's exact process group and fences operators"
  assert
    ( isRight (authorizeRuntimeConfigWriteAccess 100 False Nothing Nothing)
        && isRight (authorizeRuntimeConfigWriteAccess 100 True (Just 100) Nothing)
        && isLeft (authorizeRuntimeConfigWriteAccess 100 True (Just 101) Nothing)
        && isLeft (authorizeRuntimeConfigWriteAccess 100 False (Just 100) Nothing)
    )
    "runtime-config writers are fenced while another live harness process group owns the config transaction"
  -- Phase 1 Sprint 1.21 — the cluster-owned suites run inside a bounded
  -- toolchain child that is deliberately placed in a fresh process group, so
  -- process-group equality alone stopped recognising the harness's own work and
  -- refused the suites' `internal materialize-substrate` writes and cluster
  -- mutations. A delegated child group restores that authority for exactly one
  -- child; the owner-alive requirement still gates both arms, so a delegation
  -- outliving a crashed harness authorizes nothing.
  assert
    ( isRight (authorizeRuntimeConfigWriteAccess 101 True (Just 100) (Just 101))
        && isRight
          (authorizeHarnessReservationAccess HarnessOwned 101 True (Just 100) (Just 101))
        && isLeft (authorizeRuntimeConfigWriteAccess 102 True (Just 100) (Just 101))
        && isLeft
          (authorizeHarnessReservationAccess HarnessOwned 102 True (Just 100) (Just 101))
        && isLeft (authorizeRuntimeConfigWriteAccess 101 False (Just 100) (Just 101))
        && isLeft
          (authorizeHarnessReservationAccess HarnessOwned 101 False (Just 100) (Just 101))
        && isRight (authorizeRuntimeConfigWriteAccess 100 True (Just 100) (Just 101))
    )
    "Sprint 1.21: a delegated toolchain child group carries harness authority only while the owner is verified alive, and only for that exact group"
  -- Sprint 6.43: a leftover .harness-backup (from a prior killed run) is
  -- reconciled on entry — the operator config is restored and the backup consumed.
  let legacyRecoveryPaths =
        clusterStatePaths
          { repoRoot = clusterStateRoot
          }
      reconcileRuntimeConfig = clusterStateRoot </> "infernix.dhall"
      reconcileBackupConfig = reconcileRuntimeConfig <> ".harness-backup"
  writeFile reconcileBackupConfig "OPERATOR ORIGINAL CONFIG"
  writeFile reconcileRuntimeConfig "HARNESS LEFTOVER CONFIG"
  reconcileInterruptedHarnessStateAt legacyRecoveryPaths
  restoredContents <- readFile reconcileRuntimeConfig
  backupStillPresent <- doesFileExist reconcileBackupConfig
  assert
    (restoredContents == "OPERATOR ORIGINAL CONFIG")
    "locked legacy recovery restores the operator config from a leftover .harness-backup"
  assert
    (not backupStillPresent)
    "locked legacy recovery consumes the leftover .harness-backup on restore"
  -- Sprint 5.12: the client model-bootstrap deadline is single-sourced from the
  -- server ceiling and can never be shorter than it (a negative margin clamps).
  assert
    (Contracts.clientModelBootstrapDeadlineSeconds 0 == Contracts.modelBootstrapReadyServerCeilingSeconds)
    "clientModelBootstrapDeadlineSeconds with no margin equals the server ceiling"
  assert
    (Contracts.clientModelBootstrapDeadlineSeconds (-1000) >= Contracts.modelBootstrapReadyServerCeilingSeconds)
    "a negative margin cannot make the client model-bootstrap deadline shorter than the server ceiling"
  assert
    ( Contracts.clientModelBootstrapDeadlineSeconds Contracts.clientModelBootstrapDeadlineMarginSeconds
        > Contracts.modelBootstrapReadyServerCeilingSeconds
    )
    "the client model-bootstrap deadline includes a positive margin over the server ceiling"
  -- Sprint 8.7: the config-side port state files read fail-closed — absent is
  -- Nothing, valid decodes, and a present-but-undecodable file is a loud error.
  let edgePortFile = edgePortPath clusterStatePaths
  removePathForcibly edgePortFile
  absentPort <- readEdgePortMaybe clusterStatePaths
  assert (isNothing absentPort) "readEdgePortMaybe treats an absent port file as Nothing"
  writeFile edgePortFile "9137"
  validPort <- readEdgePortMaybe clusterStatePaths
  assert (validPort == Just 9137) "readEdgePortMaybe decodes a valid recorded port"
  writeFile edgePortFile "not-a-port"
  corruptPort <- try @SomeException (readEdgePortMaybe clusterStatePaths)
  assert
    (case corruptPort of Left _ -> True; Right _ -> False)
    "readEdgePortMaybe fails closed on a present but undecodable port file"
  putStrLn "unit tests passed"

-- | Phase 1 Sprint 1.23: pin the closed host/runtime derivation and the
-- fail-closed consumer contract without invoking Poetry or mutating a real
-- engine environment. The fixture also proves that a lock file created by an
-- install changes the marker digest, so publishing a pre-install digest could
-- never satisfy readiness.
runPreparedPythonEnvironmentAssertions :: FilePath -> FilePath -> IO ()
runPreparedPythonEnvironmentAssertions repoRootPath unitTestRoot = do
  applePlan <-
    expectRight
      "derive Darwin prepared-Python plan"
      (Python.preparedPythonEnvironmentPlanForTest "darwin" AppleSilicon)
  linuxCpuPlan <-
    expectRight
      "derive Linux CPU prepared-Python plan"
      (Python.preparedPythonEnvironmentPlanForTest "linux" LinuxCpu)
  linuxGpuPlan <-
    expectRight
      "derive Linux GPU base prepared-Python plan"
      (Python.preparedPythonEnvironmentPlanForTest "linux" LinuxGpu)
  mismatchedHostPlan <-
    expectRight
      "derive mismatched-host prepared-Python plan"
      (Python.preparedPythonEnvironmentPlanForTest "darwin" LinuxCpu)
  assert
    ( sort applePlan
        == sort
          [ ("transformers-python", ["apple-silicon"]),
            ("pytorch-python", ["apple-silicon"]),
            ("diffusers-python", ["apple-silicon"])
          ]
    )
    "prepared Darwin framework plan is derived from the three active Python-native Apple bindings"
  assert
    ( sort linuxCpuPlan
        == sort
          [ ("transformers-python", ["linux-cpu"]),
            ("pytorch-python", ["linux-cpu"])
          ]
    )
    "prepared Linux CPU framework plan is derived from the two active Python-native CPU bindings"
  assert
    (null linuxGpuPlan && null mismatchedHostPlan)
    "Linux GPU base materialization and mismatched host/runtime pairs have no shared framework plan"

  transformersBinding <-
    maybe
      (fail "Apple catalog omitted transformers-python")
      pure
      ( find
          ((== "transformers-python") . engineBindingAdapterId)
          (engineBindingsForMode AppleSilicon)
      )
  let invalidBinding =
        transformersBinding
          { engineBindingAdapterId = "transformers"
          }
      fixtureRoot = unitTestRoot </> "prepared-python-repo"
      fixtureHostConfig = hostNativeUnitTestFixture fixtureRoot unitTestRoot
      pyprojectBytes = ByteString8.pack "[tool.poetry]\nname = \"fixture\"\n"
      lockBytes = ByteString8.pack "package = []\n"
  fixturePaths <- discoverPathsWithHostManifest (Just fixtureHostConfig)
  interpreterPath <-
    expectRight
      "derive exact prepared interpreter path"
      (Python.preparedPythonEngineInterpreterPathForTest fixturePaths transformersBinding)
  assert
    ( isLeft
        (Python.preparedPythonEngineInterpreterPathForTest fixturePaths invalidBinding)
    )
    "prepared interpreter derivation rejects an adapter id without the exact -python suffix"
  markerWithoutLock <-
    expectRight
      "render pre-lock prepared marker"
      ( Python.preparedPythonFrameworkMarkerForTest
          "darwin"
          AppleSilicon
          transformersBinding
          pyprojectBytes
          Nothing
      )
      >>= maybe (fail "Darwin marker plan omitted transformers-python") pure
  markerWithLock <-
    expectRight
      "render post-lock prepared marker"
      ( Python.preparedPythonFrameworkMarkerForTest
          "darwin"
          AppleSilicon
          transformersBinding
          pyprojectBytes
          (Just lockBytes)
      )
      >>= maybe (fail "Darwin marker plan omitted transformers-python") pure
  assert
    (markerWithoutLock /= markerWithLock)
    "a poetry.lock created by install changes the prepared marker digest"

  let projectDirectory =
        takeDirectory (takeDirectory (takeDirectory interpreterPath))
      pyprojectPath = projectDirectory </> "pyproject.toml"
      lockPath = projectDirectory </> "poetry.lock"
      markerPath =
        projectDirectory
          </> ".venv"
          </> fst markerWithLock
  createDirectoryIfMissing True (takeDirectory interpreterPath)
  writeFile pyprojectPath (ByteString8.unpack pyprojectBytes)
  writeFile lockPath (ByteString8.unpack lockBytes)
  writeFile interpreterPath "#!/bin/sh\nexit 0\n"
  interpreterPermissions <- getPermissions interpreterPath
  setPermissions
    interpreterPath
    interpreterPermissions {executable = True}
  writeFile markerPath (snd markerWithLock)
  matchingReadiness <-
    Python.preparedPythonEngineEnvironmentReadyForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
  assert
    (matchingReadiness == Right interpreterPath)
    "matching executable, project digest, and marker satisfy prepared environment readiness"

  -- The runtime holds a shared lease on the exact writer lock from readiness
  -- through capped-process completion. A second reader must enter concurrently,
  -- while the existing non-blocking writer must fail before it can tombstone or
  -- mutate the environment.
  secondReaderEntered <- MVar.newEmptyMVar
  releaseSecondReader <- MVar.newEmptyMVar
  secondReaderResult <- MVar.newEmptyMVar
  (readerOverlap, writerWhileReadLocked, completedSecondReader) <-
    Python.withPreparedPythonEngineEnvironmentReadAuthorityForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
      ( \_ -> do
          _ <-
            forkIO
              ( try @SomeException
                  ( Python.withPreparedPythonEngineEnvironmentReadAuthorityForTest
                      "darwin"
                      fixturePaths
                      AppleSilicon
                      transformersBinding
                      ( \_ -> do
                          MVar.putMVar secondReaderEntered ()
                          MVar.takeMVar releaseSecondReader
                      )
                  )
                  >>= MVar.putMVar secondReaderResult
              )
          flip finally (void (MVar.tryPutMVar releaseSecondReader ())) $ do
            overlap <- timeout 2000000 (MVar.takeMVar secondReaderEntered)
            writerAttempt <-
              try @SomeException
                ( Python.interruptPreparedPythonEnvironmentAfterInvalidationForTest
                    "darwin"
                    fixturePaths
                    AppleSilicon
                    transformersBinding
                )
            _ <- MVar.tryPutMVar releaseSecondReader ()
            readerResult <- timeout 2000000 (MVar.takeMVar secondReaderResult)
            pure (overlap, writerAttempt, readerResult)
      )
  assert
    (readerOverlap == Just ())
    "two prepared-environment readers can hold the shared project lease concurrently"
  assert
    ( exceptionMessageContains
        "Poetry project mutation lock is already held"
        writerWhileReadLocked
    )
    "a prepared-environment read lease excludes the Poetry project writer"
  assert
    (maybe False isRight completedSecondReader)
    "the concurrent prepared-environment reader releases its shared lease cleanly"
  markerWhileReadLocked <- readFile markerPath
  assert
    (markerWhileReadLocked == snd markerWithLock)
    "an excluded writer cannot invalidate readiness while a reader owns launch custody"
  writerAfterReaders <-
    try @SomeException
      ( Python.interruptPreparedPythonEnvironmentAfterInvalidationForTest
          "darwin"
          fixturePaths
          AppleSilicon
          transformersBinding
      )
  assert
    (isRight writerAfterReaders)
    "the Poetry project writer enters after every shared read lease is released and takes the idempotent ready fast path"
  markerAfterReaders <- readFile markerPath
  assert
    (markerAfterReaders == snd markerWithLock)
    "the post-reader no-op writer preserves current readiness"

  pythonReadAuthoritySource <-
    readFile (repoRootPath </> "src/Infernix/Python.hs")
  cappedEngineFacadeSource <-
    readFile (repoRootPath </> "src/Infernix/Runtime/CappedEngine.hs")
  cappedEngineKernelSource <-
    readFile (repoRootPath </> "src/Infernix/Runtime/CappedEngine/Internal.hs")
  assert
    ( "type role PreparedPythonEnvironmentReadAuthority nominal"
        `isInfixOf` pythonReadAuthoritySource
        && "(forall s. PreparedPythonEnvironmentReadAuthority s -> IO result)"
          `isInfixOf` pythonReadAuthoritySource
        && not
          ( "PreparedPythonEnvironmentReadAuthority (..)"
              `isInfixOf` pythonReadAuthoritySource
          )
    )
    "prepared-environment read authority is opaque, nominal, and confined to a rank-2 region"
  assert
    ( "runExecutablePythonWorker"
        `isInfixOf` cappedEngineFacadeSource
        && "PreparedPythonEnvironmentReadAuthority s"
          `isInfixOf` cappedEngineKernelSource
        && not
          ( "preparedPythonEngineInterpreterPath paths engineBinding"
              `isInfixOf` cappedEngineKernelSource
          )
    )
    "only the hidden capped-engine kernel consumes locked prepared-environment authority and it does not re-derive the interpreter"

  writeFile markerPath "malformed\n"
  malformedReadiness <-
    Python.preparedPythonEngineEnvironmentReadyForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
  assert
    (isLeft malformedReadiness)
    "a malformed prepared environment marker fails closed"
  interruptedProducer <-
    try @SomeException
      ( Python.interruptPreparedPythonEnvironmentAfterInvalidationForTest
          "darwin"
          fixturePaths
          AppleSilicon
          transformersBinding
      )
  assert
    ( exceptionMessageContains
        "injected interruption after prepared-environment marker invalidation"
        interruptedProducer
    )
    "the deterministic producer interruption fires only after durable invalidation"
  interruptedMarker <- readFile markerPath
  assert
    (interruptedMarker == "infernix-framework-environment-incomplete\n")
    "an interrupted producer leaves the exact durable in-progress marker"
  interruptedInstallReadiness <-
    Python.preparedPythonEngineEnvironmentReadyForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
  assert
    (isLeft interruptedInstallReadiness)
    "the durable in-progress marker left by an interrupted install fails closed"
  repeatedInterruptedProducer <-
    try @SomeException
      ( Python.interruptPreparedPythonEnvironmentAfterInvalidationForTest
          "darwin"
          fixturePaths
          AppleSilicon
          transformersBinding
      )
  assert
    ( exceptionMessageContains
        "injected interruption after prepared-environment marker invalidation"
        repeatedInterruptedProducer
    )
    "a retry treats the tombstone as unready and re-enters the repair branch"
  repeatedInterruptedMarker <- readFile markerPath
  assert
    (repeatedInterruptedMarker == "infernix-framework-environment-incomplete\n")
    "a repeated interrupted repair preserves fail-closed tombstone evidence"
  removeFile markerPath
  missingMarkerReadiness <-
    Python.preparedPythonEngineEnvironmentReadyForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
  assert
    (isLeft missingMarkerReadiness)
    "a missing prepared environment marker fails closed"

  writeFile markerPath (snd markerWithLock)
  writeFile lockPath "package = [\"drift\"]\n"
  staleProjectReadiness <-
    Python.preparedPythonEngineEnvironmentReadyForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
  assert
    (isLeft staleProjectReadiness)
    "poetry.lock drift makes an otherwise well-formed marker stale"
  removeFile interpreterPath
  missingInterpreterReadiness <-
    Python.preparedPythonEngineEnvironmentReadyForTest
      "darwin"
      fixturePaths
      AppleSilicon
      transformersBinding
  assert
    (isLeft missingInterpreterReadiness)
    "a missing prepared interpreter fails closed without request-time repair"

  removePathForcibly (takeDirectory markerPath)
  freshInterruptedProducer <-
    try @SomeException
      ( Python.interruptPreparedPythonEnvironmentAfterInvalidationForTest
          "darwin"
          fixturePaths
          AppleSilicon
          transformersBinding
      )
  assert
    ( exceptionMessageContains
        "injected interruption after prepared-environment marker invalidation"
        freshInterruptedProducer
    )
    "a first install with no .venv reaches the mutation checkpoint without requiring a tombstone parent"
  freshMarkerPresent <- doesFileExist markerPath
  assert
    (not freshMarkerPresent)
    "a first-install interruption leaves stable marker absence as fail-closed readiness evidence"

countNonOverlappingOccurrences :: String -> String -> Int
countNonOverlappingOccurrences needle = go
  where
    go remaining
      | null needle = 0
      | null remaining = 0
      | needle `isPrefixOf` remaining =
          1 + go (drop (length needle) remaining)
      | otherwise = go (drop 1 remaining)

-- | Phase 1 Sprint 1.11 — set up a unit-test sandbox at @root@. The
-- supported pattern is: tests inside @withTestRoot@ obtain 'Paths' via
-- 'discoverPathsWithHostManifest' with an explicit typed fixture
-- ('hostNativeUnitTestFixture' or 'linuxOuterContainerUnitTestFixture')
-- so the operator's @INFERNIX_*@ env vars and the host-staged
-- @./.build/infernix-host.dhall@ are bypassed.
withTestRoot :: FilePath -> IO a -> IO a
withTestRoot root action = do
  catchIOError (removePathForcibly root) ignoreMissing
  createDirectoryIfMissing True root
  withCurrentDirectory root action
  where
    ignoreMissing err
      | isDoesNotExistError err = pure ()
      | otherwise = ioError err

-- | Phase 1 Sprint 1.11 — host-native HostConfig fixture. The first
-- argument is the operator's real repo root (so source-tree paths like
-- @repoRoot \</\> "python"@ still resolve to the real @python\/@
-- directory). The second is the unit-test sandbox root, used to
-- redirect every data / runtime / kind / cache path away from the
-- operator's real @./.data/@ tree. The build root deliberately matches
-- @realRepoRoot \</\> ".build"@ so 'controlPlaneContext' returns
-- 'HostNative'.
hostNativeUnitTestFixture :: FilePath -> FilePath -> HostConfig.HostConfig
hostNativeUnitTestFixture repoRootPath testRoot =
  let base = HostConfig.defaultAppleHostNativeHostConfig (Text.pack repoRootPath) (Text.pack "/tmp")
   in base
        { HostConfig.hostToolPaths =
            (HostConfig.hostToolPaths base)
              { HostConfig.hostPoetry = "/tmp/infernix-unit-missing-poetry"
              },
          HostConfig.hostFilesystem =
            (HostConfig.hostFilesystem base)
              { HostConfig.hostRepoRoot = Text.pack repoRootPath,
                HostConfig.hostBuildRoot = Text.pack (repoRootPath </> ".build"),
                HostConfig.hostDataRoot = Text.pack (testRoot </> ".data"),
                HostConfig.hostRuntimeRoot = Text.pack (testRoot </> ".data" </> "runtime"),
                HostConfig.hostKindRoot = Text.pack (testRoot </> ".data" </> "kind"),
                HostConfig.hostKubeconfigPath = Text.pack (repoRootPath </> ".build" </> "infernix.kubeconfig"),
                HostConfig.hostSecretsRoot = Text.pack (testRoot </> ".data" </> "runtime" </> "secrets"),
                HostConfig.hostHomeDirectory = Text.pack "/tmp"
              }
        }

-- | Phase 1 Sprint 1.11 — outer-container HostConfig fixture for tests
-- that exercise the Linux launcher path. The first argument is the
-- repo root the fixture should report (use the operator's real repo
