-- | The command shim root: the leading component of a rendered subprocess
-- @PATH@. 'Subprocess.clusterSubprocessEnv' prepends it, and subprocess
-- environment construction rejects any component containing @':'@, so
-- splitting on the first colon recovers it exactly.
leadingSearchPathComponent :: Subprocess.SubprocessEnv -> FilePath
leadingSearchPathComponent environment =
  takeWhile
    (/= ':')
    (fromMaybe "" (lookup "PATH" (Subprocess.renderSubprocessEnv environment)))

testRootPath :: FilePath -> IO FilePath
testRootPath suiteName = do
  paths <- discoverPaths
  pure (repoRoot paths </> ".build" </> ("test-" <> suiteName))

-- | Redirect every configured host tool onto a stub this suite creates.
--
-- The manifest defaults name Homebrew and macOS system paths, and command
-- compilation refuses a configured tool that is not an executable file. A
-- fixture that keeps those defaults is therefore asserting about whatever the
-- host happens to have installed: the same case compiles on a Homebrew host
-- and fails everywhere else for a reason that has nothing to do with what it
-- tests. This suite is in the machine-independent gate set, so its tool
-- availability has to come from the fixture rather than from the machine.
--
-- A tool the defaults leave empty stays empty. "Configured but unavailable" is
-- a distinct state several assertions depend on, and a stub would erase it.
hermeticHostToolPaths ::
  FilePath ->
  HostConfig.HostToolPaths ->
  IO HostConfig.HostToolPaths
hermeticHostToolPaths stubRoot configured = do
  createDirectoryIfMissing True stubRoot
  docker <- stub "docker" HostConfig.hostDocker
  kubectl <- stub "kubectl" HostConfig.hostKubectl
  helm <- stub "helm" HostConfig.hostHelm
  kind <- stub "kind" HostConfig.hostKind
  cabalTool <- stub "cabal" HostConfig.hostCabal
  ghc <- stub "ghc" HostConfig.hostGhc
  ghcup <- stub "ghcup" HostConfig.hostGhcup
  npm <- stub "npm" HostConfig.hostNpm
  node <- stub "node" HostConfig.hostNode
  python3 <- stub "python3.12" HostConfig.hostPython3
  python311 <- stub "python3.11" HostConfig.hostPython311
  llamaCompletion <- stub "llama-completion" HostConfig.hostLlamaCompletion
  whisperCli <- stub "whisper-cli" HostConfig.hostWhisperCli
  poetry <- stub "poetry" HostConfig.hostPoetry
  git <- stub "git" HostConfig.hostGit
  tar <- stub "tar" HostConfig.hostTar
  curl <- stub "curl" HostConfig.hostCurl
  aptGet <- stub "apt-get" HostConfig.hostAptGet
  brew <- stub "brew" HostConfig.hostBrew
  sudo <- stub "sudo" HostConfig.hostSudo
  systemctl <- stub "systemctl" HostConfig.hostSystemctl
  mkdirTool <- stub "mkdir" HostConfig.hostMkdir
  chmodTool <- stub "chmod" HostConfig.hostChmod
  lnTool <- stub "ln" HostConfig.hostLn
  installTool <- stub "install" HostConfig.hostInstall
  idTool <- stub "id" HostConfig.hostId
  getent <- stub "getent" HostConfig.hostGetent
  cutTool <- stub "cut" HostConfig.hostCut
  dirnameTool <- stub "dirname" HostConfig.hostDirname
  bash <- stub "bash" HostConfig.hostBash
  crictl <- stub "crictl" HostConfig.hostCrictl
  chownTool <- stub "chown" HostConfig.hostChown
  nvidiaSmi <- stub "nvidia-smi" HostConfig.hostNvidiaSmi
  nvkind <- stub "nvkind" HostConfig.hostNvkind
  skopeo <- stub "skopeo" HostConfig.hostSkopeo
  hostnameTool <- stub "hostname" HostConfig.hostHostname
  sysctl <- stub "sysctl" HostConfig.hostSysctl
  pure
    configured
      { HostConfig.hostDocker = docker,
        HostConfig.hostKubectl = kubectl,
        HostConfig.hostHelm = helm,
        HostConfig.hostKind = kind,
        HostConfig.hostCabal = cabalTool,
        HostConfig.hostGhc = ghc,
        HostConfig.hostGhcup = ghcup,
        HostConfig.hostNpm = npm,
        HostConfig.hostNode = node,
        HostConfig.hostPython3 = python3,
        HostConfig.hostPython311 = python311,
        HostConfig.hostLlamaCompletion = llamaCompletion,
        HostConfig.hostWhisperCli = whisperCli,
        HostConfig.hostPoetry = poetry,
        HostConfig.hostGit = git,
        HostConfig.hostTar = tar,
        HostConfig.hostCurl = curl,
        HostConfig.hostAptGet = aptGet,
        HostConfig.hostBrew = brew,
        HostConfig.hostSudo = sudo,
        HostConfig.hostSystemctl = systemctl,
        HostConfig.hostMkdir = mkdirTool,
        HostConfig.hostChmod = chmodTool,
        HostConfig.hostLn = lnTool,
        HostConfig.hostInstall = installTool,
        HostConfig.hostId = idTool,
        HostConfig.hostGetent = getent,
        HostConfig.hostCut = cutTool,
        HostConfig.hostDirname = dirnameTool,
        HostConfig.hostBash = bash,
        HostConfig.hostCrictl = crictl,
        HostConfig.hostChown = chownTool,
        HostConfig.hostNvidiaSmi = nvidiaSmi,
        HostConfig.hostNvkind = nvkind,
        HostConfig.hostSkopeo = skopeo,
        HostConfig.hostHostname = hostnameTool,
        HostConfig.hostSysctl = sysctl
      }
  where
    stub leafName readConfigured
      | Text.null (readConfigured configured) = pure ""
      | otherwise = do
          let stubPath = stubRoot </> leafName
          writeFile stubPath "#!/bin/sh\nexit 0\n"
          stubPermissions <- getPermissions stubPath
          setPermissions stubPath stubPermissions {executable = True}
          pure (Text.pack stubPath)

extractDockerfileHostManifest :: String -> Either String String
extractDockerfileHostManifest dockerfileContents =
  case dropWhile (/= hostManifestPrintfStart) (lines dockerfileContents) of
    [] -> Left "docker/Dockerfile is missing the host-manifest printf block"
    _printfStart : remainingLines -> do
      let (argumentLines, terminatorLines) =
            break
              (isInfixOf "> /opt/infernix/dhall/InfernixHost.dhall")
              remainingLines
      case terminatorLines of
        [] ->
          Left "docker/Dockerfile host-manifest printf block is unterminated"
        _ -> unlines <$> traverse decodeArgumentLine argumentLines
  where
    hostManifestPrintfStart = "RUN printf '%s\\n' \\"

    decodeArgumentLine rawLine
      | "hostArchitecture =" `isInfixOf` rawLine =
          Right ", hostArchitecture = \"arm64\""
      | otherwise = do
          quotedArgument <-
            case reverse (dropWhile (== ' ') rawLine) of
              '\\' : reversedArgument ->
                Right (trimArgumentWhitespace (reverse reversedArgument))
              _ ->
                Left
                  ( "Dockerfile host-manifest argument is missing its line continuation: "
                      <> rawLine
                  )
          case quotedArgument of
            '\'' : quotedBody
              | not (null quotedBody),
                last quotedBody == '\'' ->
                  Right (init quotedBody)
            _ ->
              Left
                ( "Dockerfile host-manifest argument is not a single-quoted literal: "
                    <> rawLine
                )

    trimArgumentWhitespace =
      reverse
        . dropWhile (== ' ')
        . reverse
        . dropWhile (== ' ')

removeTestPathIfPresent :: FilePath -> IO ()
removeTestPathIfPresent path =
  catchIOError (removePathForcibly path) $ \err ->
    if isDoesNotExistError err
      then pure ()
      else ioError err

writeNamedPipePayloadNonblocking :: FilePath -> BS.ByteString -> IO ()
writeNamedPipePayloadNonblocking path payload = do
  startedAt <- getMonotonicTimeNSec
  bracketPreservingPrimary
    (openBefore (startedAt + 1000000000))
    PosixIO.closeFd
    ( \descriptor -> do
        written <- PosixByteString.fdWrite descriptor payload
        unless (fromIntegral written == BS.length payload) $
          fail "the nonblocking FIFO release write was incomplete"
    )
  where
    openBefore deadline = do
      opened <-
        try @IOException
          ( PosixIO.openFd
              path
              PosixIO.WriteOnly
              PosixIO.defaultFileFlags
                { PosixIO.nonBlock = True
                }
          )
      case opened of
        Right descriptor -> pure descriptor
        Left failure
          | isDoesNotExistError failure -> do
              now <- getMonotonicTimeNSec
              if now >= deadline
                then ioError failure
                else yield >> openBefore deadline
          | otherwise -> ioError failure

snapshotDirectoryTree :: FilePath -> IO [(FilePath, Maybe BS.ByteString)]
snapshotDirectoryTree root = walk ""
  where
    walk relativeDirectory = do
      entries <- sort <$> listDirectory (root </> relativeDirectory)
      concat <$> mapM (snapshotEntry relativeDirectory) entries

    snapshotEntry relativeDirectory entry = do
      let relativePath =
            if null relativeDirectory
              then entry
              else relativeDirectory </> entry
          absolutePath = root </> relativePath
      isDirectory <- doesDirectoryExist absolutePath
      if isDirectory
        then do
          descendants <- walk relativePath
          pure ((relativePath, Nothing) : descendants)
        else do
          contents <- BS.readFile absolutePath
          pure [(relativePath, Just contents)]

parseExactIdentityPairs ::
  Int ->
  String ->
  Either String [(Integer, ProcessBirthIdentity)]
parseExactIdentityPairs expectedPairCount contents =
  case parsePairs (lines contents) of
    Right pairs
      | length pairs == expectedPairCount -> Right pairs
      | otherwise ->
          Left
            ( "expected "
                <> show expectedPairCount
                <> " exact identities, observed "
                <> show (length pairs)
            )
    Left failure -> Left failure
  where
    parsePairs [] = Right []
    parsePairs (processIdText : birthIdentityText : remaining) = do
      processId <-
        maybe
          (Left ("invalid process id: " <> processIdText))
          Right
          (readMaybe processIdText)
      birthIdentity <-
        maybe
          (Left ("invalid process birth identity: " <> birthIdentityText))
          Right
          (parseProcessBirthIdentity birthIdentityText)
      ((processId, birthIdentity) :) <$> parsePairs remaining
    parsePairs _ =
      Left "exact identity evidence had an unmatched pid/birth line"

parseRegisteredTargetAndLeader ::
  String ->
  Either String (RecordedProcessIdentity, RecordedProcessIdentity)
parseRegisteredTargetAndLeader contents =
  case lines contents of
    [ targetProcessIdText,
      targetProcessGroupText,
      targetBirthIdentityText,
      leaderProcessIdText,
      leaderBirthIdentityText
      ] -> do
        targetProcessId <-
          maybe
            (Left ("invalid registered target process id: " <> targetProcessIdText))
            Right
            (readMaybe targetProcessIdText)
        targetProcessGroup <-
          maybe
            (Left ("invalid registered target process group: " <> targetProcessGroupText))
            Right
            (readMaybe targetProcessGroupText)
        targetBirthIdentity <-
          maybe
            (Left ("invalid registered target birth identity: " <> targetBirthIdentityText))
            Right
            (parseProcessBirthIdentity targetBirthIdentityText)
        leaderProcessId <-
          maybe
            (Left ("invalid registered leader process id: " <> leaderProcessIdText))
            Right
            (readMaybe leaderProcessIdText)
        leaderBirthIdentity <-
          maybe
            (Left ("invalid registered leader birth identity: " <> leaderBirthIdentityText))
            Right
            (parseProcessBirthIdentity leaderBirthIdentityText)
        unlessEither
          ( targetProcessId > 0
              && targetProcessGroup > 0
              && leaderProcessId > 0
              && targetProcessId /= leaderProcessId
              && targetProcessGroup == leaderProcessId
          )
          "registered target and leader topology is invalid"
        pure
          ( RecordedProcessIdentity
              targetProcessId
              targetProcessGroup
              targetBirthIdentity,
            RecordedProcessIdentity
              leaderProcessId
              leaderProcessId
              leaderBirthIdentity
          )
    _ ->
      Left
        "registered target authority must contain target pid/group/birth and leader pid/birth"

data RecordedProcessIdentity = RecordedProcessIdentity
  { recordedProcessId :: !Integer,
    recordedProcessGroup :: !Integer,
    recordedProcessBirth :: !ProcessBirthIdentity
  }
  deriving (Eq, Show)

newtype ReapedChildIdentity
  = ReapedRegisteredIdentity RecordedProcessIdentity
  deriving (Eq, Show)

data ReapEvidence = ReapEvidence
  { reapEvidenceOwner :: !RecordedProcessIdentity,
    reapEvidenceChildren :: ![(String, ReapedChildIdentity)]
  }
  deriving (Eq, Show)

decodeReapEvidence :: String -> Either String ReapEvidence
decodeReapEvidence contents = do
  value <-
    Aeson.eitherDecodeStrict'
      (ByteString8.pack contents)
  case value of
    Aeson.Object evidenceObject -> do
      version <-
        requireMaybe
          "reap evidence has no numeric version"
          (activityIntegerField "version" evidenceObject)
      unlessEither
        (version == 2)
        "unsupported designated-owner reap evidence version"
      ownerValue <-
        requireMaybe
          "reap evidence has no owner"
          (KeyMap.lookup (Key.fromString "owner") evidenceObject)
      owner <- decodeRecordedIdentityValue ownerValue
      childrenValue <-
        requireMaybe
          "reap evidence has no reapedChildren"
          (KeyMap.lookup (Key.fromString "reapedChildren") evidenceObject)
      childValues <-
        case Aeson.fromJSON childrenValue of
          Aeson.Success values -> Right values
          Aeson.Error failure -> Left failure
      children <- mapM decodeReapedChild childValues
      pure
        ReapEvidence
          { reapEvidenceOwner = owner,
            reapEvidenceChildren = children
          }
    _ -> Left "reap evidence is not a JSON object"
  where
    decodeReapedChild childValue =
      case childValue of
        Aeson.Object childObject -> do
          label <-
            requireMaybe
              "reaped child has no label"
              (jsonStringField "label" childObject)
          identityKind <-
            requireMaybe
              "reaped child has no identityKind"
              (jsonStringField "identityKind" childObject)
          identityValue <-
            requireMaybe
              "reaped child has no identity"
              (KeyMap.lookup (Key.fromString "identity") childObject)
          identity <-
            case identityKind of
              "registered" ->
                ReapedRegisteredIdentity
                  <$> decodeRecordedIdentityValue identityValue
              _ -> Left "reaped child has an unsupported identityKind"
          status <-
            requireMaybe
              "reaped child has no status"
              (jsonStringField "status" childObject)
          unlessEither
            (not (null status))
            "reaped child status is empty"
          pure (label, identity)
        _ -> Left "reaped child is not a JSON object"

decodeRecordedIdentityValue ::
  Aeson.Value ->
  Either String RecordedProcessIdentity
decodeRecordedIdentityValue value =
  case value of
    Aeson.Object identityObject ->
      RecordedProcessIdentity
        <$> requireMaybe
          "recorded identity has no processId"
          (activityIntegerField "processId" identityObject)
        <*> requireMaybe
          "recorded identity has no processGroup"
          (activityIntegerField "processGroup" identityObject)
        <*> requireMaybe
          "recorded identity has no birthIdentity"
          (activityBirthIdentityField "birthIdentity" identityObject)
    _ -> Left "recorded identity is not a JSON object"

decodePrefixedRecordedIdentity ::
  String ->
  KeyMap.KeyMap Aeson.Value ->
  Either String RecordedProcessIdentity
decodePrefixedRecordedIdentity prefix identityObject =
  RecordedProcessIdentity
    <$> requireMaybe
      ("missing " <> prefix <> "ProcessId")
      (activityIntegerField (prefix <> "ProcessId") identityObject)
    <*> requireMaybe
      ("missing " <> prefix <> "ProcessGroup")
      (activityIntegerField (prefix <> "ProcessGroup") identityObject)
    <*> requireMaybe
      ("missing " <> prefix <> "BirthIdentity")
      (activityBirthIdentityField (prefix <> "BirthIdentity") identityObject)

decodeSynchronousTreeEvidence ::
  Lazy.ByteString ->
  Either
    String
    ( RecordedProcessIdentity,
      RecordedProcessIdentity,
      RecordedProcessIdentity
    )
decodeSynchronousTreeEvidence contents = do
  value <- Aeson.eitherDecode contents
  case value of
    Aeson.Object evidenceObject -> do
      version <-
        requireMaybe
          "synchronous tree evidence has no version"
          (activityIntegerField "version" evidenceObject)
      unlessEither
        (version == 3)
        "unsupported synchronous tree evidence version"
      (,,)
        <$> decodePrefixedRecordedIdentity "target" evidenceObject
        <*> decodePrefixedRecordedIdentity "descendant" evidenceObject
        <*> decodePrefixedRecordedIdentity "groupLeader" evidenceObject
    _ -> Left "synchronous tree evidence is not a JSON object"

waitForSynchronousTreeEvidence ::
  Int ->
  FilePath ->
  IO
    ( Maybe
        ( RecordedProcessIdentity,
          RecordedProcessIdentity,
          RecordedProcessIdentity
        )
    )
waitForSynchronousTreeEvidence attemptsRemaining evidencePath = do
  exists <- doesFileExist evidencePath
  decoded <-
    if exists
      then do
        contents <- Lazy.readFile evidencePath
        pure (either (const Nothing) Just (decodeSynchronousTreeEvidence contents))
      else pure Nothing
  case decoded of
    Just evidence -> pure (Just evidence)
    Nothing
      | attemptsRemaining <= 0 -> pure Nothing
      | otherwise -> do
          threadDelay 50000
          waitForSynchronousTreeEvidence
            (attemptsRemaining - 1)
            evidencePath

waitForRecordedIdentityAbsent ::
  Int ->
  RecordedProcessIdentity ->
  IO Bool
waitForRecordedIdentityAbsent attemptsRemaining identity =
  waitForExactProcessIdentityAbsent
    attemptsRemaining
    (recordedProcessId identity)
    (recordedProcessBirth identity)

jsonStringField ::
  String ->
  KeyMap.KeyMap Aeson.Value ->
  Maybe String
jsonStringField fieldName objectValue = do
  fieldValue <- KeyMap.lookup (Key.fromString fieldName) objectValue
  case Aeson.fromJSON fieldValue of
    Aeson.Success stringValue -> Just stringValue
    Aeson.Error _ -> Nothing

requireMaybe :: String -> Maybe value -> Either String value
requireMaybe failure =
  maybe (Left failure) Right

unlessEither :: Bool -> String -> Either String ()
unlessEither condition failure =
  if condition then Right () else Left failure

waitForPidExit :: Int -> String -> IO Bool
waitForPidExit attemptsRemaining processId = do
  (exitCode, _, _) <-
    readCreateProcessWithExitCode
      (proc "/bin/kill" ["-0", processId])
      ""
  case exitCode of
    ExitFailure _ -> pure True
    ExitSuccess
      | attemptsRemaining <= 0 -> pure False
      | otherwise -> do
          threadDelay 50000
          waitForPidExit (attemptsRemaining - 1) processId

-- | Poll until a process group holds no signalable member.
--
-- Darwin answers @kill(-pgid, 0)@ with @EPERM@, not @ESRCH@, while the only
-- remaining member is an unreaped zombie -- the ordinary transient state after
-- a group's owner is killed and its children are reparented. @EPERM@ is
-- therefore neither absence evidence nor a defect: the probe keeps waiting for
-- the group to disappear outright, and exhausting the budget reports @False@ so
-- the caller's assertion names the real invariant instead of dying inside the
-- probe.
waitForProcessGroupAbsent :: Int -> Integer -> IO Bool
waitForProcessGroupAbsent attemptsRemaining processGroup = do
  groupProbe <-
    try @IOException
      (signalProcessGroup nullSignal (fromIntegral processGroup))
  case groupProbe of
    Left failure
      | isDoesNotExistError failure -> pure True
      | not (isPermissionError failure) -> ioError failure
    _
      | attemptsRemaining <= 0 -> pure False
      | otherwise -> do
          threadDelay 50000
          waitForProcessGroupAbsent
            (attemptsRemaining - 1)
            processGroup

waitForExactProcessIdentityAbsent ::
  Int ->
  Integer ->
  ProcessBirthIdentity ->
  IO Bool
waitForExactProcessIdentityAbsent attemptsRemaining processId expectedIdentity = do
  observedIdentity <- readProcessBirthIdentity processId
  if observedIdentity /= Just expectedIdentity
    then pure True
    else
      if attemptsRemaining <= 0
        then pure False
        else do
          threadDelay 50000
          waitForExactProcessIdentityAbsent
            (attemptsRemaining - 1)
            processId
            expectedIdentity

waitForExternalPidStopped :: Int -> String -> IO Bool
waitForExternalPidStopped attemptsRemaining processId = do
  (exitCode, processState, _) <-
    readCreateProcessWithExitCode
      (proc "/bin/ps" ["-o", "state=", "-p", processId])
      ""
  if exitCode == ExitSuccess && 'T' `elem` processState
    then pure True
    else
      if attemptsRemaining <= 0
        then pure False
        else do
          threadDelay 50000
          waitForExternalPidStopped (attemptsRemaining - 1) processId

data CurrentCommandActivity = CurrentCommandActivity
  { currentOwnerProcessId :: !Integer,
    currentOwnerProcessGroup :: !Integer,
    currentOwnerBirthIdentity :: !ProcessBirthIdentity,
    currentCommandProcessId :: !Integer,
    currentCommandProcessGroup :: !Integer,
    currentCommandBirthIdentity :: !ProcessBirthIdentity,
    currentSupervisorProcessId :: !Integer,
    currentSupervisorProcessGroup :: !Integer,
    currentSupervisorBirthIdentity :: !ProcessBirthIdentity,
    currentTargetGroupLeaderProcessId :: !Integer,
    currentTargetGroup :: !Integer,
    currentTargetGroupLeaderBirthIdentity :: !ProcessBirthIdentity
  }
  deriving (Show)

currentOwnerIdentity :: CurrentCommandActivity -> RecordedProcessIdentity
currentOwnerIdentity activity =
  RecordedProcessIdentity
    (currentOwnerProcessId activity)
    (currentOwnerProcessGroup activity)
    (currentOwnerBirthIdentity activity)

currentAnchorIdentity :: CurrentCommandActivity -> RecordedProcessIdentity
currentAnchorIdentity activity =
  RecordedProcessIdentity
    (currentCommandProcessId activity)
    (currentCommandProcessGroup activity)
    (currentCommandBirthIdentity activity)

currentSupervisorIdentity :: CurrentCommandActivity -> RecordedProcessIdentity
currentSupervisorIdentity activity =
  RecordedProcessIdentity
    (currentSupervisorProcessId activity)
    (currentSupervisorProcessGroup activity)
    (currentSupervisorBirthIdentity activity)

currentPinIdentity :: CurrentCommandActivity -> RecordedProcessIdentity
currentPinIdentity activity =
  RecordedProcessIdentity
    (currentTargetGroupLeaderProcessId activity)
    (currentTargetGroup activity)
    (currentTargetGroupLeaderBirthIdentity activity)

waitForCurrentCommandActivity ::
  Int ->
  Paths ->
  Integer ->
  IO CurrentCommandActivity
waitForCurrentCommandActivity attemptsRemaining paths ownerProcessGroup = do
  maybeActivity <-
    readCurrentCommandActivity paths ownerProcessGroup
  case maybeActivity of
    Just activity -> pure activity
    Nothing
      | attemptsRemaining <= 0 ->
          fail "bounded-command current activity lease was not published"
      | otherwise -> do
          threadDelay 50000
          waitForCurrentCommandActivity
            (attemptsRemaining - 1)
            paths
            ownerProcessGroup

waitForCurrentCommandActivityByPin ::
  Int ->
  Paths ->
  Integer ->
  Integer ->
  ProcessBirthIdentity ->
  IO CurrentCommandActivity
waitForCurrentCommandActivityByPin
  attemptsRemaining
  paths
  ownerProcessGroup
  pinProcessId
  pinBirthIdentity = do
    activities <-
      readCurrentCommandActivities paths ownerProcessGroup
    case [ activity
         | activity <- activities,
           let pinIdentity = currentPinIdentity activity,
           recordedProcessId pinIdentity == pinProcessId,
           recordedProcessBirth pinIdentity == pinBirthIdentity
         ] of
      [activity] -> pure activity
      []
        | attemptsRemaining > 0 -> do
            threadDelay 50000
            waitForCurrentCommandActivityByPin
              (attemptsRemaining - 1)
              paths
              ownerProcessGroup
              pinProcessId
              pinBirthIdentity
      [] ->
        fail "bounded-command activity with the expected exact pin identity was not published"
      activitiesWithMatchingPin ->
        fail
          ( "multiple bounded-command activities carried the same exact pin identity: "
              <> show activitiesWithMatchingPin
          )

readCurrentCommandActivity ::
  Paths ->
  Integer ->
  IO (Maybe CurrentCommandActivity)
readCurrentCommandActivity paths ownerProcessGroup = do
  activities <-
    readCurrentCommandActivities paths ownerProcessGroup
  case activities of
    [] -> pure Nothing
    [activity] -> pure (Just activity)
    _ ->
      fail
        ( "multiple current bounded-command activities were live for owner group "
            <> show ownerProcessGroup
            <> ": "
            <> show activities
        )

readCurrentCommandActivities ::
  Paths ->
  Integer ->
  IO [CurrentCommandActivity]
readCurrentCommandActivities paths ownerProcessGroup = do
  let activityRoot =
        runtimeRoot paths </> "bounded-command-activity"
  activityRootExists <- doesDirectoryExist activityRoot
  if not activityRootExists
    then pure []
    else do
      entries <- listDirectory activityRoot
      documents <-
        mapM
          (Lazy.readFile . (activityRoot </>))
          (filter (".lease.json" `isSuffixOf`) entries)
      pure
        [ activity
        | document <- documents,
          Just activity <-
            [decodeCurrentCommandActivity ownerProcessGroup document]
        ]

decodeCurrentCommandActivity ::
  Integer ->
  Lazy.ByteString ->
  Maybe CurrentCommandActivity
decodeCurrentCommandActivity ownerProcessGroup document = do
  Aeson.Object activityObject <- Aeson.decode document
  version <- activityIntegerField "version" activityObject
  recordedOwner <- activityIntegerField "ownerProcessGroup" activityObject
  ownerProcessId <-
    activityIntegerField "ownerProcessId" activityObject
  ownerBirthIdentity <-
    activityBirthIdentityField "ownerBirthIdentity" activityObject
  commandProcessId <-
    activityIntegerField "commandProcessId" activityObject
  commandProcessGroup <-
    activityIntegerField "commandProcessGroup" activityObject
  commandBirthIdentity <-
    activityBirthIdentityField "commandBirthIdentity" activityObject
  supervisorProcessId <-
    activityIntegerField "watchdogProcessId" activityObject
  supervisorProcessGroup <-
    activityIntegerField "watchdogProcessGroup" activityObject
  supervisorBirthIdentity <-
    activityBirthIdentityField "watchdogBirthIdentity" activityObject
  targetGroupLeaderProcessId <-
    activityIntegerField "targetGroupLeaderProcessId" activityObject
  targetGroup <-
    activityIntegerField "targetGroup" activityObject
  targetGroupLeaderBirthIdentity <-
    activityBirthIdentityField
      "targetGroupLeaderBirthIdentity"
      activityObject
  if version `elem` [3, 4] && recordedOwner == ownerProcessGroup
    then
      Just
        CurrentCommandActivity
          { currentOwnerProcessId = ownerProcessId,
            currentOwnerProcessGroup = recordedOwner,
            currentOwnerBirthIdentity = ownerBirthIdentity,
            currentCommandProcessId = commandProcessId,
            currentCommandProcessGroup = commandProcessGroup,
            currentCommandBirthIdentity = commandBirthIdentity,
            currentSupervisorProcessId = supervisorProcessId,
            currentSupervisorProcessGroup = supervisorProcessGroup,
            currentSupervisorBirthIdentity = supervisorBirthIdentity,
            currentTargetGroupLeaderProcessId = targetGroupLeaderProcessId,
            currentTargetGroup = targetGroup,
            currentTargetGroupLeaderBirthIdentity =
              targetGroupLeaderBirthIdentity
          }
    else Nothing

activityIntegerField ::
  String ->
  KeyMap.KeyMap Aeson.Value ->
  Maybe Integer
activityIntegerField fieldName activityObject = do
  fieldValue <-
    KeyMap.lookup (Key.fromString fieldName) activityObject
  case Aeson.fromJSON fieldValue of
    Aeson.Success integerValue -> Just integerValue
    Aeson.Error _ -> Nothing

activityBirthIdentityField ::
  String ->
  KeyMap.KeyMap Aeson.Value ->
  Maybe ProcessBirthIdentity
activityBirthIdentityField fieldName activityObject = do
  fieldValue <-
    KeyMap.lookup (Key.fromString fieldName) activityObject
  case Aeson.fromJSON fieldValue of
    Aeson.Success identityText ->
      parseProcessBirthIdentity identityText
    Aeson.Error _ -> Nothing

waitForBoundedCommandActivitiesQuiescent ::
  Int ->
  Paths ->
  Integer ->
  IO Bool
waitForBoundedCommandActivitiesQuiescent attemptsRemaining paths ownerProcessGroup = do
  result <-
    try @IOException
      ( Subprocess.proveBoundedCommandActivitiesQuiescent
          paths
          ownerProcessGroup
      )
  case result of
    Right _ -> pure True
    Left _
      | attemptsRemaining <= 0 -> pure False
      | otherwise -> do
          threadDelay 50000
          waitForBoundedCommandActivitiesQuiescent
            (attemptsRemaining - 1)
            paths
            ownerProcessGroup

-- | Wait for a fixture to publish a record, and treat an empty file as
-- not-yet-published rather than as the record.
--
-- Every publisher in the closed test-command language writes with
-- @printf ... > "$path"@, and the redirection creates and truncates the file
-- /before/ @printf@ runs. Observing the file between those two steps is
-- therefore a guaranteed window, not a scheduling artefact: the observer sees a
-- zero-length file and the caller's parse of it fails. That is the whole
-- mechanism behind the failure recorded as
-- @the cancelled protocol-isolation command published an invalid descendant pid@
-- — the "never published" branch did not fire, so the file existed, and the
-- only writer for it emits a valid integer.
--
-- Several call sites already assert @not (null contents)@ immediately after
-- this returns, which is this same race being reported as a failure instead of
-- being waited through. Waiting for a non-empty record makes the deadline the
-- only way to fail, which is what a fixture-publication wait should mean.
waitForFileContents :: Int -> FilePath -> IO (Maybe String)
waitForFileContents attemptsRemaining filePath = do
  fileExists <- doesFileExist filePath
  publishedContents <-
    if fileExists
      then System.IO.readFile' filePath
      else pure ""
  if not (null publishedContents)
    then pure (Just publishedContents)
    else
      if attemptsRemaining <= 0
        then pure (if fileExists then Just publishedContents else Nothing)
        else do
          threadDelay 50000
          waitForFileContents (attemptsRemaining - 1) filePath

assert :: Bool -> String -> IO ()
assert True _ = pure ()
assert False message = fail message

-- | Sprint 1.20 Apple-cohort regressions.
--
-- Every assertion below covers a defect that the first Apple cohort attempt
-- found on live hardware and that no machine-independent gate could reach. They
-- exist so a regression fails here rather than only during an Apple
-- materialization run.
-- | Phase 8 Sprint 8.11 — the checks that hold the system contract and the
-- machine contract together.
--
-- Three layers, and they buy different things. The pin and the served-pool
-- resolution are local: they prove this machine's manifest matches this
-- machine's copy of the contract, and neither can see another machine's copy.
-- The registered contract digest is the only one that could ever detect a fleet
-- disagreement, and at one engine machine it is proved the way a second machine
-- would prove it — by classifying a registered value that disagrees.
-- | Phase 8 Sprint 8.12 — the fleet contract: member identity, the workload
-- shape it implies, and the broker-side claim that bounds it.
--
-- What these assertions can and cannot decide is worth stating, because the
-- sprint's whole point is that a fleet property is not provable at one machine.
-- Everything here is about the /generated/ artefacts — the contract, the Kind
-- topology, the Helm overlay, the per-machine manifests, the claim topic, and
-- the refusal text — all of which are decidable from one process. That two
-- machines actually refuse each other at the broker is the cohort's to show.
runFleetMemberIdentityAssertions :: FilePath -> IO ()
runFleetMemberIdentityAssertions root = do
  paths <- discoverPaths
  twoMachines <-
    either (ioError . userError) pure (engineMachineCountForMode LinuxCpu 2)

  -- 1. The fleet dimension multiplies members and nothing else.
  let singlePools = enginePoolsForFleet LinuxCpu singleEngineMachine
      fleetPools = enginePoolsForFleet LinuxCpu twoMachines
      singleMembers = engineMembersForFleet LinuxCpu singleEngineMachine
      fleetMembers = engineMembersForFleet LinuxCpu twoMachines
  assert
    (singlePools == enginePoolsForMode LinuxCpu && singleMembers == engineMembersForMode LinuxCpu)
    "Sprint 8.12: a one-machine fleet generates exactly the single-machine pool graph"
  assert
    (length fleetMembers == 2 * length singleMembers)
    "Sprint 8.12: a two-machine fleet declares two members per single-machine member"
  assert
    (length (nub (map engineMemberId fleetMembers)) == length fleetMembers)
    "Sprint 8.12: fleet member identities are distinct"
  assert
    ( map enginePoolId fleetPools == map enginePoolId singlePools
        && map enginePoolModelIds fleetPools == map enginePoolModelIds singlePools
        && map enginePoolSubscriptionType fleetPools == map enginePoolSubscriptionType singlePools
    )
    "Sprint 8.12: the fleet dimension leaves pool identity, models, and subscription type alone"
  assert
    (all (\pool -> length (enginePoolMemberIds pool) == 2) fleetPools)
    "Sprint 8.12: every pool of a two-machine fleet names both machines, so both serve the same Shared topic"

  -- 2. The declared member ids are what a later reader recovers the fleet size
  --    from, because publication regenerates the payload rather than copying it.
  assert
    (engineMachineCountFromMemberIds (map engineMemberId fleetMembers) == twoMachines)
    "Sprint 8.12: the fleet size is recoverable from the declared member ids"
  assert
    (engineMachineCountFromMemberIds (map engineMemberId singleMembers) == singleEngineMachine)
    "Sprint 8.12: an unsuffixed member list reads as one machine"
  assert
    (engineMachineCountFromMemberIds [] == singleEngineMachine)
    "Sprint 8.12: an empty member list reads as one machine rather than as no machine"

  -- 3. The mode-scoped refusals.
  assert
    (isLeft (engineMachineCountForMode LinuxGpu 2))
    "Sprint 8.12: linux-gpu refuses a fleet above one machine rather than renaming its engine images"
  case engineMachineCountForMode LinuxGpu 2 of
    Left refusal ->
      assert
        (isInfixOf "--engine-machines 1" refusal && isInfixOf "framework engine image" refusal)
        "Sprint 8.12: the linux-gpu fleet refusal says what to do and why"
    Right _ -> assert False "Sprint 8.12: linux-gpu fleet refusal is reachable"
  assert
    (isLeft (engineMachineCountForMode LinuxCpu 0))
    "Sprint 8.12: a fleet of zero machines is refused at generation"

  -- 4. The claim topic is per identity, and it is not a pool topic.
  let claimTopicOne = engineMemberClaimTopicForMode LinuxCpu "linux-cpu-engine-m1"
      claimTopicTwo = engineMemberClaimTopicForMode LinuxCpu "linux-cpu-engine-m2"
      samplePoolTopic =
        enginePoolTopicForMode LinuxCpu (maybe "pool" enginePoolId (listToMaybe fleetPools)) "some-model"
  assert
    (claimTopicOne /= claimTopicTwo)
    "Sprint 8.12: each machine claims its own topic"
  assert
    (claimTopicOne /= samplePoolTopic && not (Text.isInfixOf "inference.batch." claimTopicOne))
    "Sprint 8.12: the claim topic is separate from the Shared pool topic it would otherwise exclude the fleet from"

  -- 5. The refusal a second machine gets.
  let claimRefusal =
        engineMemberClaimRefusal
          "linux-cpu-engine-m1"
          claimTopicOne
          (Just "linux-cpu-engine-m1@other-host:4242")
  assert
    ( isInfixOf "linux-cpu-engine-m1" claimRefusal
        && isInfixOf (Text.unpack claimTopicOne) claimRefusal
        && isInfixOf "other-host:4242" claimRefusal
    )
    "Sprint 8.12: the claim refusal names the identity, the claim topic, and the incumbent"
  assert
    ("the broker refused the claim but reported no consumer" `isInfixOf` engineMemberClaimRefusal "m" "t" Nothing)
    "Sprint 8.12: an incumbent that lapsed between the refusal and the lookup is reported as unknown, not as absent"

  -- 6. What counts as the broker refusing a second holder, and what does not.
  assert
    (isEngineMemberClaimConflict (toException (userError "handshake failed: 409 Conflict")))
    "Sprint 8.12: a 409 is read as a held claim"
  assert
    (isEngineMemberClaimConflict (toException (userError "Consumer Busy")))
    "Sprint 8.12: a consumer-busy response is read as a held claim"
  assert
    (not (isEngineMemberClaimConflict (toException (userError "Network.Socket.connect: connection refused"))))
    "Sprint 8.12: a transport failure is not read as a held claim"
  assert
    ( engineMemberClaimReacquisitionWindowSeconds >= 30
        && engineMemberClaimRetryDelayMicros > 0
    )
    "Sprint 8.12: the reacquisition window is wall-clock and covers the broker's keep-alive interval, so a restart is not an outage"

  -- 7. The Kind topology follows the contract's fleet.
  let kindConfigFor machineCount =
        renderKindConfig
          paths
          LinuxCpu
          machineCount
          30090
          30002
          30080
          (root </> "kind")
          (root </> "registry")
          False
      singleKind = kindConfigFor singleEngineMachine
      fleetKind = kindConfigFor twoMachines
      workerCountIn rendered = length (filter (isInfixOf "- role: worker") (lines rendered))
  assert
    (workerCountIn singleKind == 1)
    "Sprint 8.12: the single-machine Kind topology still has exactly one worker"
  assert
    (workerCountIn fleetKind == 2)
    "Sprint 8.12: a two-machine fleet gets one Kind worker per machine"
  assert
    ( isInfixOf (fleetSlotLabelKey <> "=1") fleetKind
        && isInfixOf (fleetSlotLabelKey <> "=2") fleetKind
    )
    "Sprint 8.12: each fleet worker carries its own slot label for its machine's nodeSelector"
  assert
    ((fleetSlotLabelKey <> "=1") `isInfixOf` singleKind)
    "Sprint 8.12: the single-worker topology carries the same slot label, so the two shapes differ only in size"

  -- 8. The per-machine contracts: one member each, one shared pin.
  let declaredFleetMemberIds = map engineMemberId fleetMembers
      fleetSystemContract =
        unitGeneratedDemoConfig paths LinuxCpu True linuxCpuUnitInferenceMemoryBudget
      fleetDigest = MachineContract.digestSystemContract fleetSystemContract
  machineContracts <- renderFleetMachineContracts paths fleetDigest declaredFleetMemberIds
  assert
    (map fst machineContracts == [1, 2])
    "Sprint 8.12: a two-machine fleet renders a machine contract per slot"
  assert
    ( and
        [ Text.unpack memberIdValue `isInfixOf` contractBody
        | ((_, contractBody), memberIdValue) <- zip machineContracts declaredFleetMemberIds
        ]
    )
    "Sprint 8.12: each machine contract names its own member identity"
  assert
    ( and
        [ not (Text.unpack otherMemberId `isInfixOf` contractBody)
        | ((slot, contractBody), _) <- zip machineContracts declaredFleetMemberIds,
          (otherSlot, otherMemberId) <- zip [1 ..] declaredFleetMemberIds,
          slot /= otherSlot
        ]
    )
    "Sprint 8.12: a machine contract names exactly one member, so a pod cannot adopt another machine's identity from its own manifest"
  assert
    ( all
        (isInfixOf (Text.unpack (MachineContract.systemContractDigestText fleetDigest)) . snd)
        machineContracts
    )
    "Sprint 8.12: every machine of a fleet is pinned to the same system contract"
  fleetContractsForOneMachine <-
    renderFleetMachineContracts paths fleetDigest (fleetMemberIdsForOneMachine paths)
  assert
    (null fleetContractsForOneMachine)
    "Sprint 8.12: a one-machine deployment renders no per-machine contract; its pod reads the baked manifest"

  -- 9. The generated Helm overlay.
  fleetNow <- getCurrentTime
  let fleetState =
        ClusterState
          { clusterLifecycle = ClusterReady,
            clusterOwner = OperatorOwned,
            edgePort = 30090,
            registryPort = 30002,
            routes = [RouteInfo "/" "demo web UI"],
            storageClass = "standard",
            claims = [],
            clusterRuntimeMode = LinuxCpu,
            clusterEngineMemberIds = declaredFleetMemberIds,
            kubeconfigPath = Config.generatedKubeconfigPath paths,
            generatedDemoConfigPath = Config.generatedDemoConfigPath paths,
            publishedDemoConfigPath = Config.publishedConfigMapCatalogPath paths,
            publishedConfigMapManifestPath = Config.publishedConfigMapManifestPath paths,
            mountedDemoConfigPath = "/opt/build/infernix.dhall",
            updatedAt = fleetNow
          }
      singleMachineState = fleetState {clusterEngineMemberIds = map engineMemberId singleMembers}
      fleetValues = renderHelmValues paths OuterContainer fleetState "{}" machineContracts FinalPhase
      singleValues = renderHelmValues paths OuterContainer singleMachineState "{}" [] FinalPhase
  assert
    ("  fleet:\n    enabled: true" `isInfixOf` fleetValues)
    "Sprint 8.12: the generated overlay turns the fleet lane on when the contract declares more than one machine"
  assert
    ( "    replicaCount: 1" `isInfixOf` fleetValues
        && "    replicaCount: 0"
          `isInfixOf` renderHelmValues paths OuterContainer fleetState "{}" machineContracts PulsarReadyPhase
    )
    "Sprint 8.12: a fleet machine's engine is phase-gated exactly as the shared engine is, so no engine is asked for before Pulsar is up"
  assert
    ("  fleet:\n    enabled: false" `isInfixOf` singleValues)
    "Sprint 8.12: the deployed single-machine topology keeps the fleet lane off"
  assert
    ( and
        [ ("name: " <> show (Text.unpack memberIdValue)) `isInfixOf` fleetValues
        | memberIdValue <- declaredFleetMemberIds
        ]
    )
    "Sprint 8.12: each fleet machine's declared identity reaches its Deployment as a compiled constant"
  assert
    ("engine:\n  replicaCount: 0" `isInfixOf` fleetValues)
    "Sprint 8.12: a fleet renders no shared engine workload, so the shared replica count names nothing"
  assert
    ("engine:\n  replicaCount: 1" `isInfixOf` singleValues)
    "Sprint 8.12: the single-machine overlay is unchanged"
  assert
    (isInfixOf "    m1.dhall: |" fleetValues && isInfixOf "    m2.dhall: |" fleetValues)
    "Sprint 8.12: each machine's contract is embedded in the overlay as a string the chart only nindents"

  -- 10. The rollout wait list and the scale targets name the machines.
  assert
    (clusterFleetEngineDeployments fleetState == ["deployment/infernix-engine-m1", "deployment/infernix-engine-m2"])
    "Sprint 8.12: a fleet deploys one engine workload per machine"
  assert
    (null (clusterFleetEngineDeployments singleMachineState))
    "Sprint 8.12: a single-machine deployment keeps the shared engine workload"
  assert
    ( notElem "deployment/infernix-engine" (finalPhaseDeployments fleetState)
        && all (`elem` finalPhaseDeployments fleetState) (clusterFleetEngineDeployments fleetState)
    )
    "Sprint 8.12: the rollout wait list names the machines that exist rather than a workload that does not"
  assert
    ("deployment/infernix-engine" `elem` finalPhaseDeployments singleMachineState)
    "Sprint 8.12: the single-machine rollout wait list is unchanged"
  putStrLn "Sprint 8.12 fleet member-identity assertions passed"
  where
    fleetMemberIdsForOneMachine _paths = []

runMachineContractAssertions :: FilePath -> IO ()
runMachineContractAssertions root = do
  paths <- discoverPaths
  let appleSystemContract =
        unitGeneratedDemoConfig paths AppleSilicon True appleUnitInferenceMemoryBudget
      linuxSystemContract =
        unitGeneratedDemoConfig paths LinuxCpu True linuxCpuUnitInferenceMemoryBudget
      contractRoot = root </> "machine-contract"
      systemContractPath = contractRoot </> "infernix.dhall"
      foreignContractPath = contractRoot </> "foreign-infernix.dhall"
      pinnedDigest = MachineContract.digestSystemContract appleSystemContract
      foreignDigest = MachineContract.digestSystemContract linuxSystemContract
      declaredNode =
        HostConfig.MachineNode
          { HostConfig.machineRole = Enums.daemonRoleToDhall Engine,
            HostConfig.machineMembers = ["apple-host-default"],
            HostConfig.machineModelCacheQuotaBytes = fromInteger defaultModelCacheQuotaBytes,
            HostConfig.machineSystemContractDigest =
              MachineContract.systemContractDigestText pinnedDigest
          }
      appleManifest =
        HostConfig.defaultAppleHostNativeHostConfig
          (Text.pack contractRoot)
          (Text.pack contractRoot)
      pinnedManifest = appleManifest {HostConfig.hostMachine = HostConfig.DeclaredMachine declaredNode}
      imageManifest = appleManifest {HostConfig.hostMachine = HostConfig.ImageDefaultMachine}
  createDirectoryIfMissing True contractRoot
  Lazy.writeFile systemContractPath (encodeDemoConfig appleSystemContract)
  Lazy.writeFile foreignContractPath (encodeDemoConfig linuxSystemContract)
  -- The digest follows the contract a payload describes, not the payload's
  -- bytes: a written file and the value it was rendered from digest alike.
  observedDigest <- MachineContract.digestSystemContractFile systemContractPath
  assert
    (observedDigest == pinnedDigest)
    "the system-contract digest of a written file equals the digest of the value it renders"
  -- The live cohort's defect, pinned: one deployment holds the same contract as
  -- more than one payload — the operator's file names its own absolute
  -- `generatedPath`, the published cluster mirror is rendered for the pods that
  -- mount it — and those payloads must digest alike or the machines refuse each
  -- other over a disagreement that does not exist.
  let publishedMirror =
        appleSystemContract
          { generatedPath = "/opt/build/published-mirror.dhall",
            mountedPath = "/opt/build/infernix.dhall",
            configMapName = "infernix-demo-config-mirror",
            demoUiEnabled = not (demoUiEnabled appleSystemContract)
          }
  assert
    (MachineContract.digestSystemContract publishedMirror == pinnedDigest)
    "two payloads of one contract that differ only in machine-local fields digest alike"
  assert
    ( MachineContract.digestSystemContract
        appleSystemContract
          { enginePools =
              case enginePools appleSystemContract of
                pool : remaining -> pool {enginePoolMemberIds = ["someone-else"]} : remaining
                [] -> []
          }
        /= pinnedDigest
    )
    "a changed pool member moves the contract digest"
  assert
    ( "sha256:"
        `Text.isPrefixOf` MachineContract.systemContractDigestText pinnedDigest
    )
    "the system-contract digest is a prefixed sha256 hex value"
  assert
    (MachineContract.classifyMachinePin pinnedManifest pinnedDigest == MachineContract.MachinePinAgrees)
    "a machine contract paired with the system contract it was generated against agrees"
  assert
    ( MachineContract.classifyMachinePin pinnedManifest foreignDigest
        == MachineContract.MachinePinDisagrees
          (MachineContract.systemContractDigestText pinnedDigest)
          (MachineContract.systemContractDigestText foreignDigest)
    )
    "a machine contract paired with a foreign system contract fails the pin and names both digests"
  assert
    (MachineContract.classifyMachinePin imageManifest pinnedDigest == MachineContract.MachinePinUndeclared)
    "the image-default manifest pins nothing, which is absence rather than disagreement"
  foreignPairResult <-
    try (MachineContract.requireMachineContractPair pinnedManifest foreignContractPath) ::
      IO (Either IOError ())
  assert
    (either (isInfixOf "pinned to a different system contract" . show) (const False) foreignPairResult)
    "pairing a machine contract with a foreign system contract on disk is refused by name"
  matchingPairResult <-
    try (MachineContract.requireMachineContractPair pinnedManifest systemContractPath) ::
      IO (Either IOError ())
  assert
    (either (const False) (const True) matchingPairResult)
    "pairing a machine contract with its own system contract is accepted"
  imageDaemonResult <-
    try (void (MachineContract.requireDeclaredMachine imageManifest)) ::
      IO (Either IOError ())
  assert
    (either (isInfixOf "declares no machine contract" . show) (const False) imageDaemonResult)
    "a daemon started against the image-default manifest is refused by name"
  -- Identity is declared, not discovered.
  assert
    (MachineContract.resolveMachineMemberId declaredNode Nothing == Right "apple-host-default")
    "one declared member identity needs no selection"
  assert
    ( either
        (isInfixOf "is not declared by this machine contract")
        (const False)
        (MachineContract.resolveMachineMemberId declaredNode (Just "someone-elses-member"))
    )
    "an engine name outside the declared identities is refused rather than adopted"
  let multiMemberNode = declaredNode {HostConfig.machineMembers = ["native", "transformers"]}
  assert
    ( either
        (isInfixOf "pass `--engine-name`")
        (const False)
        (MachineContract.resolveMachineMemberId multiMemberNode Nothing)
    )
    "more than one declared identity and no engine name is a refusal, not a default"
  assert
    (MachineContract.resolveMachineMemberId multiMemberNode (Just "transformers") == Right "transformers")
    "an engine name naming one of the declared identities resolves to it"
  assert
    ( either
        (isInfixOf "declares no engine member identity")
        (const False)
        (MachineContract.resolveMachineMemberId declaredNode {HostConfig.machineMembers = []} Nothing)
    )
    "a machine contract declaring no identity is refused rather than defaulted"
  -- The broker-registered digest: three states, and absence is not
  -- disagreement.
  let registeredBody digestValue =
        LazyChar8.pack ("{\"contractDigest\":\"" <> Text.unpack digestValue <> "\"}")
      unpinnedBody = LazyChar8.pack "{\"someOtherProperty\":\"value\"}"
  assert
    ( Pulsar.classifyRegisteredContractDigest
        pinnedDigest
        (registeredBody (MachineContract.systemContractDigestText pinnedDigest))
        == Pulsar.RegisteredDigestAgrees
    )
    "a registered digest equal to this daemon's contract digest agrees"
  assert
    ( Pulsar.classifyRegisteredContractDigest pinnedDigest unpinnedBody
        == Pulsar.RegisteredDigestAbsent
    )
    "a topic carrying no contract digest reports absence, not disagreement"
  assert
    ( Pulsar.classifyRegisteredContractDigest
        pinnedDigest
        (registeredBody (MachineContract.systemContractDigestText foreignDigest))
        == Pulsar.RegisteredDigestDisagrees (MachineContract.systemContractDigestText foreignDigest)
    )
    "a registered digest that disagrees is classified as a disagreement and carries the incumbent value"
  -- The registrar/verifier split: a deliberate contract change must not be an
  -- outage. The registered digest is durable broker state that outlives a
  -- cluster, so a check that only ever refuses would freeze the fleet's contract
  -- at whatever was registered first.
  assert
    ( Pulsar.contractDigestAuthorityForRole Coordinator == Pulsar.RegistersContractDigest
        && Pulsar.contractDigestAuthorityForRole Engine == Pulsar.VerifiesContractDigest
        && Pulsar.contractDigestAuthorityForRole Webapp == Pulsar.VerifiesContractDigest
    )
    "the coordinator registers the fleet's contract digest and every other role verifies it"
  let refusal =
        Pulsar.registeredContractDigestRefusal
          "persistent://infernix/demo/inference.request.apple-silicon"
          (MachineContract.systemContractDigestText foreignDigest)
          (MachineContract.systemContractDigestText pinnedDigest)
  assert
    ( isInfixOf "refuses to start" refusal
        && isInfixOf (Text.unpack (MachineContract.systemContractDigestText foreignDigest)) refusal
        && isInfixOf (Text.unpack (MachineContract.systemContractDigestText pinnedDigest)) refusal
    )
    "the disagreement refusal names the registered incumbent and this daemon's digest"
  -- The generated pair round-trips: render, decode, re-render, byte-compare.
  -- This is what makes the pin meaningful — a renderer and a decoder that
  -- disagree would give one contract two digests depending on which side
  -- computed it.
  let roundTripPath = contractRoot </> "round-trip.dhall"
  mapM_
    ( \(runtimeModeValue, budget) -> do
        let firstRender = renderGeneratedDemoConfigPayload paths runtimeModeValue singleEngineMachine True budget
        BS.writeFile roundTripPath firstRender
        decodedConfig <- decodeDemoConfigFile roundTripPath
        let secondRender = Lazy.toStrict (encodeDemoConfig decodedConfig)
        assert
          (firstRender == secondRender)
          ( "the generated system contract for "
              <> Text.unpack (runtimeModeId runtimeModeValue)
              <> " re-renders byte-identically after a decode"
          )
        roundTrippedDigest <- MachineContract.digestSystemContractFile roundTripPath
        assert
          ( roundTrippedDigest
              == MachineContract.digestSystemContract
                (unitGeneratedDemoConfig paths runtimeModeValue True budget)
          )
          ( "the content pin is stable across the decode/re-render round trip for "
              <> Text.unpack (runtimeModeId runtimeModeValue)
          )
    )
    [ (AppleSilicon, appleUnitInferenceMemoryBudget),
      (LinuxCpu, linuxCpuUnitInferenceMemoryBudget)
    ]
  putStrLn "Sprint 8.11 machine-contract assertions passed"

runAppleCohortRegressionAssertions :: FilePath -> IO ()
runAppleCohortRegressionAssertions repoRootPath = do
  runDyldAuditRegressionAssertions
  runSealedArtifactEnvironmentRegressionAssertions repoRootPath
  putStrLn "Sprint 1.20 Apple-cohort regressions passed"

-- | macOS 26 emits more than load records under the @dyld[<pid>]:@ prefix.
runDyldAuditRegressionAssertions :: IO ()
runDyldAuditRegressionAssertions = do
  assert
    ( Subprocess.parseDyldAuditLineForTest
        "dyld[4321]: <E730B179-D826-315A-A49B-FAF364854DB7> /opt/x/lib/libz.dylib"
        == Right (Subprocess.DyldLoadedPath "/opt/x/lib/libz.dylib")
    )
    "a uuid-prefixed dyld frame is exact loader provenance"
  -- dyld emits a great deal of commentary under the same prefix. None of it
  -- carries a path, and enumerating the message shapes proved brittle: two
  -- separate rounds of this smoke were broken by a form not yet listed. Any
  -- frame that does not announce itself as a load record is commentary.
  mapM_
    ( \frame ->
        assert
          ( Subprocess.parseDyldAuditLineForTest frame
              == Right Subprocess.DyldSchedulingFrame
          )
          ("a dyld commentary frame is not loader provenance: " <> frame)
    )
    [ "dyld[4321]: move loaded to delayed: Accounts",
      "dyld[4321]: move delayed to loaded: Accounts",
      "dyld[4321]: libgcc_s.1.1.dylib has weak-def (or flat lookup) symbol used by libgfortran.5.dylib, so cannot be delayed",
      "dyld[4321]: something this kernel has never seen /opt/x/lib/libz.dylib"
    ]
  assert
    ( Subprocess.parseDyldAuditLineForTest "version: 9870 (2d973636e)"
        == Right Subprocess.NotDyldAuditLine
    )
    "a runner's own diagnostic line is not a dyld frame"
  -- A frame that claims to be a load record but violates the shape still fails
  -- closed, so commentary can never be laundered into a loaded path.
  mapM_
    ( \frame ->
        assert
          (isLeft (Subprocess.parseDyldAuditLineForTest frame))
          ("a malformed dyld load record fails closed: " <> frame)
    )
    [ "dyld[4321]: <not-a-uuid> /opt/x/lib/libz.dylib",
      "dyld[4321]: <E730B179-D826-315A-A49B-FAF364854DB7> relative/libz.dylib",
      "dyld[4321]: <E730B179-D826-315A-A49B-FAF364854DB7> /opt/../etc/libz.dylib",
      "dyld[4321]: loaded: relative/libz.dylib"
    ]

-- | The sealed artifact runtime environment must survive every validator, and
-- loader frames must never be mistaken for the runner's own output.
runSealedArtifactEnvironmentRegressionAssertions :: FilePath -> IO ()
runSealedArtifactEnvironmentRegressionAssertions repoRootPath = do
  let artifactRoot = "/data/engines/llama-cpp-cli.tmp"
      nativeEnvironment =
        Subprocess.sealedArtifactRuntimeEnvironmentForTest
          artifactRoot
          "native/bin/llama-completion"
      audiverisEnvironment =
        Subprocess.sealedArtifactRuntimeEnvironmentForTest
          artifactRoot
          ( ProvisioningInternal.installedSmokeExecutableRelativePath
              ProvisioningInternal.JvmAdapter
          )
      retiredAudiverisLauncherEnvironment =
        Subprocess.sealedArtifactRuntimeEnvironmentForTest
          artifactRoot
          "Audiveris.app/Contents/MacOS/Audiveris"
      installedPythonSmokeArguments =
        ProvisioningInternal.installedSmokeArguments
          ProvisioningInternal.OnnxRuntimeAdapter
          artifactRoot
  -- Without DYLD_PRINT_LIBRARIES the smoke cannot emit the provenance its own
  -- validator demands.
  assert
    ( lookup "DYLD_PRINT_LIBRARIES" nativeEnvironment == Just "1"
        && lookup "GGML_BACKEND_PATH" nativeEnvironment
          == Just (artifactRoot </> "native" </> "libexec")
        && lookup "DYLD_PRINT_LIBRARIES" audiverisEnvironment == Just "1"
    )
    "a sealed artifact target carries its loader-provenance runtime environment"
  assert
    (isNothing (lookup "DYLD_PRINT_LIBRARIES" retiredAudiverisLauncherEnvironment))
    "the retired Audiveris launcher cannot authorize loader provenance"
  -- The Audiveris invocation has drifted between its producer and its consumer
  -- twice. The invariant that stops a third is not that the paths match but
  -- that the whole invocation does: the smoke exists to prove that the thing
  -- inference runs works, so running the same binary without the classpath that
  -- reaches `Audiveris` would report on the bare JVM instead. `java -version`
  -- is exactly that mistake, and it answers on standard error in three lines
  -- rather than the seven-field banner the pinned receipt is bound to.
  assert
    ( ProvisioningInternal.installedSmokeExecutableRelativePath
        ProvisioningInternal.JvmAdapter
        == ArtifactTarget.audiverisAppleJvmRelativePath
        && ProvisioningInternal.installedSmokeArguments
          ProvisioningInternal.JvmAdapter
          artifactRoot
          == ArtifactTarget.audiverisAppleLeadingArguments artifactRoot
            <> ["-version"]
        && ProvisioningInternal.installedSmokeArguments
          ProvisioningInternal.JvmAdapter
          artifactRoot
          /= ["-version"]
    )
    "the Audiveris installed smoke runs the inference target's own executable and classpath, not the bare JVM"
  assert
    ( installedPythonSmokeArguments
        == [ "lib" </> "apple_native_runner.py",
             "--adapter-id",
             "onnx-runtime-native",
             "--engine-name",
             "onnx-runtime-native",
             "--expected-python-prefix",
             artifactRoot </> "venv",
             "--smoke"
           ]
    )
    "the installed Python smoke carries the artifact-local interpreter prefix required by its runner"
  -- These entries name artifact-root-relative paths, so the rendered-command
  -- contract must admit them structurally, not by literal enumeration.
  assert
    ( isRight
        ( Subprocess.renderedEnvironmentContractForTest
            (("PYTHONDONTWRITEBYTECODE", "1") : nativeEnvironment)
        )
    )
    "the rendered-environment contract admits a sealed artifact runtime environment"
  assert
    ( isRight
        ( Subprocess.renderedEnvironmentContractForTest
            (("PYTHONDONTWRITEBYTECODE", "1") : audiverisEnvironment)
        )
    )
    "the rendered-environment contract admits the current Audiveris installed smoke"
  assert
    ( isLeft
        ( Subprocess.renderedEnvironmentContractForTest
            ( ("PYTHONDONTWRITEBYTECODE", "1")
                : ("DYLD_PRINT_LIBRARIES", "0")
                : filter ((/= "DYLD_PRINT_LIBRARIES") . fst) nativeEnvironment
            )
        )
    )
    "the rendered-environment contract still rejects an unfixed guard value"
  assert
    ( isLeft
        ( Subprocess.renderedEnvironmentContractForTest
            [("DYLD_PRINT_LIBRARIES", "1"), ("UNEXPECTED", "value")]
        )
    )
    "the rendered-environment contract still rejects an unknown name set"
  -- The Linux sealed run is the case the Apple-shaped assertions above never
  -- reached. Its contracts named LD_DEBUG alone while every rendered command
  -- also carries the renderer's fixed guard, so the Linux native artifact
  -- smoke was refused as an unsupported command environment on every input.
  -- Both assertions therefore drive the shape the renderer produces, not a
  -- restatement of it, and both fail against the pre-correction source.
  let linuxSealedRunEnvironment =
        Subprocess.linuxSealedRunRenderedEnvironmentForTest
  assert
    ( isRight
        (Subprocess.renderedEnvironmentContractForTest linuxSealedRunEnvironment)
    )
    "the rendered-environment contract admits the Linux sealed-run environment"
  let baseEnvironment =
        [ ("PATH", "/usr/bin"),
          ("HOME", "/tmp/home"),
          ("TMPDIR", "/tmp/tmp"),
          ("LANG", "C"),
          ("LC_ALL", "C"),
          ("HELM_CONFIG_HOME", "/tmp/helm/config"),
          ("HELM_CACHE_HOME", "/tmp/helm/cache"),
          ("HELM_DATA_HOME", "/tmp/helm/data")
        ]
      darwinPythonSnapshotParent =
        "/data/runtime/command-executable-snapshots"
      darwinPythonSnapshotRoot =
        darwinPythonSnapshotParent </> "anchor-generation"
      darwinPythonHome = darwinPythonSnapshotRoot </> "python-home"
      darwinPythonPaths = [darwinPythonSnapshotRoot </> "python-path"]
      darwinProjectSources = [darwinPythonSnapshotRoot </> "project-source"]
      darwinPythonSnapshotTargetEnvironment =
        Subprocess.darwinPythonSnapshotTargetEnvironmentForTest
          darwinPythonSnapshotRoot
          baseEnvironment
      targetEnvironment =
        baseEnvironment
          <> (("PYTHONDONTWRITEBYTECODE", "1") : nativeEnvironment)
  assert
    ( lookup "PYTHONHOME" darwinPythonSnapshotTargetEnvironment
        == Just (darwinPythonSnapshotRoot </> "python-home")
        && lookup "DYLD_FRAMEWORK_PATH" darwinPythonSnapshotTargetEnvironment
          == Just (darwinPythonSnapshotRoot </> "python-framework")
        && lookup "DYLD_LIBRARY_PATH" darwinPythonSnapshotTargetEnvironment
          == Just (darwinPythonSnapshotRoot </> "dyld-libraries")
        && isNothing
          (lookup "PYTHONNOUSERSITE" darwinPythonSnapshotTargetEnvironment)
        && lookup "PYTHONDONTWRITEBYTECODE" darwinPythonSnapshotTargetEnvironment
          == Just "1"
    )
    "the Darwin Python snapshot target uses the renderer-owned environment vocabulary"
  assert
    ( isRight
        ( Subprocess.supervisorTargetEnvironmentContractForTest
            darwinPythonSnapshotRoot
            []
            baseEnvironment
            darwinPythonSnapshotTargetEnvironment
        )
    )
    "a supervised Darwin Python snapshot admits the environment its renderer produces"
  assert
    ( isRight
        ( Subprocess.darwinPythonSnapshotClosureEnvironmentContractForTest
            darwinPythonSnapshotRoot
            darwinPythonHome
            darwinPythonPaths
            darwinProjectSources
            darwinPythonSnapshotTargetEnvironment
        )
    )
    "the Darwin closure audit agrees with the exact per-anchor snapshot root"
  assert
    ( either
        ("DYLD_FRAMEWORK_PATH" `isInfixOf`)
        (const False)
        ( Subprocess.darwinPythonSnapshotClosureEnvironmentContractForTest
            darwinPythonSnapshotParent
            darwinPythonHome
            darwinPythonPaths
            darwinProjectSources
            darwinPythonSnapshotTargetEnvironment
        )
    )
    "the Darwin closure audit rejects a shared parent in place of its per-anchor snapshot root"
  subprocessSource <-
    readFile (repoRootPath </> "src/Infernix/Cluster/Subprocess.hs")
  assert
    ( "supervisorPlanExecutableSnapshotRoot = snapshotRoot,"
        `isInfixOf` unwords (words subprocessSource)
    )
    "the exact-snapshot plan rewrite carries the per-anchor root used by its Darwin loader renderer"
  assert
    ( all
        (isLeft . Subprocess.renderedEnvironmentContractForTest)
        [ [ ("PYTHONNOUSERSITE", "1"),
            ("PYTHONDONTWRITEBYTECODE", "1")
          ],
          [ ("PYTHONDONTWRITEBYTECODE", "1"),
            ("PYTHONNOUSERSITE", "1")
          ]
        ]
        && isLeft
          ( Subprocess.supervisorTargetEnvironmentContractForTest
              darwinPythonSnapshotRoot
              []
              baseEnvironment
              ( baseEnvironment
                  <> [ ("PYTHONDONTWRITEBYTECODE", "1"),
                       ("PYTHONNOUSERSITE", "1")
                     ]
              )
          )
    )
    "standalone no-user-site rows remain unrenderable in either ordering"
  -- The installed smoke runs from the sealed artifact root, and pre-activation
  -- that root is the candidate sibling the lease does not name.
  assert
    ( isRight
        ( Subprocess.supervisorTargetEnvironmentContractForTest
            "/data/runtime/command-executable-snapshots"
            [artifactRoot]
            baseEnvironment
            targetEnvironment
        )
    )
    "a supervised target may resolve its closure inside an owned artifact root"
  assert
    ( isLeft
        ( Subprocess.supervisorTargetEnvironmentContractForTest
            "/data/runtime/command-executable-snapshots"
            []
            baseEnvironment
            targetEnvironment
        )
    )
    "a supervised target with no owned artifact root is still confined to its snapshot"
  assert
    ( isRight
        ( Subprocess.supervisorTargetEnvironmentContractForTest
            "/data/runtime/command-executable-snapshots"
            [artifactRoot]
            baseEnvironment
            (baseEnvironment <> linuxSealedRunEnvironment)
        )
    )
    "a supervised Linux sealed run matches a closed rendered environment"
  -- A runner that reports through stderr leaves stdout empty; loader frames of
  -- either kind must be excluded from the diagnostics used as its output.
  let loaderStderr =
        ByteString8.pack
          ( unlines
              [ "dyld[4321]: <E730B179-D826-315A-A49B-FAF364854DB7> " <> artifactRoot <> "/native/lib/libllama.dylib",
                "dyld[4321]: <CACC182C-0F51-3D79-890C-D32EC0F5802E> /usr/lib/libSystem.B.dylib",
                "dyld[4321]: move loaded to delayed: Accounts",
                "dyld[4321]: move delayed to loaded: Accounts",
                "version: 9870 (2d973636e)",
                "built with AppleClang 21.0.0 for Darwin arm64"
              ]
          )
  assert
    ( Subprocess.installedRunnerApplicationOutputForTest [artifactRoot] loaderStderr
        == Right
          ( ByteString8.pack
              ( unlines
                  [ "version: 9870 (2d973636e)",
                    "built with AppleClang 21.0.0 for Darwin arm64"
                  ]
              )
          )
    )
    "installed runner diagnostics exclude every dyld frame kind"
  assert
    ( isLeft
        ( Subprocess.installedRunnerApplicationOutputForTest
            [artifactRoot]
            ( ByteString8.pack
                "dyld[4321]: <E730B179-D826-315A-A49B-FAF364854DB7> /opt/elsewhere/lib/libz.dylib\n"
            )
        )
    )
    "an unsealed non-system library still fails the installed runner smoke"

assertJsonRoundtrip :: (Eq a, Show a, Aeson.ToJSON a, Aeson.FromJSON a) => String -> a -> IO ()
assertJsonRoundtrip label value =
  case Aeson.eitherDecode (Aeson.encode value) of
    Left err ->
      fail (label <> ": JSON decode failed: " <> err)
    Right decoded ->
      assert
        (decoded == value)
        (label <> ": encode/decode roundtrip diverged. Original=" <> show value <> " Decoded=" <> show decoded)

assertJsonEncodingContains :: (Aeson.ToJSON a) => String -> a -> Text.Text -> IO ()
assertJsonEncodingContains label value needle = do
  let encoded = TextEncoding.decodeUtf8 (Lazy.toStrict (Aeson.encode value))
  assert
    (needle `Text.isInfixOf` encoded)
    (label <> ": expected encoded JSON to contain " <> Text.unpack needle <> ", encoded=" <> Text.unpack encoded)

-- | Phase 8 Sprint 8.11 — assert that a disagreement has no wire
-- representation.
--
-- The mutated config is rendered and decoded like any generated payload. The
-- round trip must /succeed/, and the decoded result must satisfy the invariant
-- the mutation tried to break: the wire could not carry the disagreement, so
-- there is nothing left to reject.
-- | Phase 8 Sprint 8.11 — the two in-cluster daemon records are derived, so a
-- generated payload always describes them the one way the runtime mode implies.
assertDerivedClusterDaemonMetadata :: FilePath -> DemoConfig -> IO ()
assertDerivedClusterDaemonMetadata root demoConfig = do
  let configPath = root </> "derived-cluster-daemon-metadata.dhall"
  Lazy.writeFile
    configPath
    ( encodeDemoConfig
        demoConfig
          { coordinatorDaemon =
              (coordinatorDaemon demoConfig)
                { daemonConfigRole = Webapp,
                  daemonConfigMemberId = Just "not-a-member",
                  daemonConfigPulsarConnectionMode = PublicationEdgeAutoDiscovery
                }
          }
    )
  roundTripped <- decodeDemoConfigFile configPath
  assert
    ( daemonConfigRole (coordinatorDaemon roundTripped) == Coordinator
        && isNothing (daemonConfigMemberId (coordinatorDaemon roundTripped))
        && daemonConfigPulsarConnectionMode (coordinatorDaemon roundTripped) == ConfiguredTransport
        && daemonConfigLocation (coordinatorDaemon roundTripped) == "cluster-pod"
    )
    "the coordinator daemon round-trips as the derived record, whatever the in-memory config said"
  assert
    (daemonConfigRole (webappDaemon roundTripped) == Webapp)
    "the webapp daemon round-trips as the derived record"

assertDemoConfigWireCannotExpress ::
  FilePath ->
  FilePath ->
  DemoConfig ->
  (DemoConfig -> Bool) ->
  String ->
  IO ()
assertDemoConfigWireCannotExpress root label demoConfig invariant description = do
  let configPath = root </> ("wire-cannot-express-" <> label <> ".dhall")
  Lazy.writeFile configPath (encodeDemoConfig demoConfig)
  roundTripped <- decodeDemoConfigFile configPath
  assert (invariant roundTripped) description

assertDemoConfigDecodeFails :: FilePath -> FilePath -> String -> DemoConfig -> IO ()
assertDemoConfigDecodeFails root label expectedMessageFragment demoConfig = do
  let configPath = root </> ("invalid-demo-config-" <> label <> ".dhall")
  Lazy.writeFile configPath (encodeDemoConfig demoConfig)
  decoded <- try (validateDemoConfigFile configPath) :: IO (Either IOError ())
  assert
    (either (isInfixOf expectedMessageFragment . show) (const False) decoded)
    ("invalid demo config is rejected for " <> label)

assertExecutionPlanWireAndQuantityProperties :: FilePath -> DemoConfig -> DemoConfig -> IO ()
assertExecutionPlanWireAndQuantityProperties root substrateConfig hostConfig = do
  let hostBudgetConfigPath = root </> "execution-plan-host-budget-roundtrip.dhall"
      substrateConfigPath = root </> "execution-plan-substrate-budget-roundtrip.dhall"
      legacyBudgetPath = root </> "execution-plan-legacy-flat-budget.dhall"
      zeroBudget =
        SubstrateEnforcedBudget
          ( PodMemoryLimit
              { podMemoryLimitResource = PodRam,
                podMemoryLimitSource = ClusterEnginePodMemoryLimit,
                podMemoryLimitMib = 0
              }
          )
      negativeBudget =
        SubstrateEnforcedBudget
          ( PodMemoryLimit
              { podMemoryLimitResource = PodRam,
                podMemoryLimitSource = ClusterEnginePodMemoryLimit,
                podMemoryLimitMib = -1
              }
          )
  Lazy.writeFile hostBudgetConfigPath (encodeDemoConfig hostConfig)
  _ <-
    decodeCompiledRuntimePlanFile hostBudgetConfigPath
      >>= expectDecodedCompiledPlan "HostEnforced budget union arm"
  Lazy.writeFile substrateConfigPath (encodeDemoConfig substrateConfig)
  _ <-
    decodeCompiledRuntimePlanFile substrateConfigPath
      >>= expectDecodedCompiledPlan "SubstrateEnforced budget union arm"
  renderedSubstrateConfig <- System.IO.readFile' substrateConfigPath
  legacyBudgetConfig <-
    replaceExecutionPlanBudgetLine
      "{ kind = \"substrate-enforced\", resource = \"pod-ram\", source = \"legacy-flat-budget\", limitMib = +65536 }"
      renderedSubstrateConfig
  writeFile legacyBudgetPath legacyBudgetConfig
  assertCompiledRuntimePlanDecodeFails
    legacyBudgetPath
    "execution-plan decoder rejects the retired flat/tagged memory-budget shape"
  assertRetiredSubstrateShapeDiagnostic
    legacyBudgetPath
    "text-discriminated `kind =` inference-memory-budget record"
  -- Phase 8 Sprint 8.9: the same targeted diagnostic now covers the retired
  -- text-tagged enums. A stale payload from a pre-union binary must name its
  -- retired shape and the regenerating command rather than surfacing a bare
  -- structural Dhall type error. `daemonRole` is the sharpest case: its three
  -- retired aliases (`frontend`, `cluster`, `host`) are values a union cannot
  -- express at all, so a stale file carrying one has no other diagnosis.
  let retiredEnumCases =
        [ ( "legacy-text-runtime-mode",
            "runtimeMode = < AppleSilicon | LinuxCpu | LinuxGpu >.LinuxCpu",
            "runtimeMode = \"linux-cpu\"",
            "text-tagged `runtimeMode` field"
          )
        ]
  mapM_
    ( \(caseLabel, currentSpelling, retiredSpelling, expectedShape) -> do
        let retiredPath = root </> ("execution-plan-" <> caseLabel <> ".dhall")
        assert
          (currentSpelling `isInfixOf` renderedSubstrateConfig)
          ( "the generated payload no longer writes the current union spelling for "
              <> caseLabel
              <> "; the retired-shape fixture below would be vacuous"
          )
        writeFile
          retiredPath
          (replaceFirstSubstring currentSpelling retiredSpelling renderedSubstrateConfig)
        assertRetiredSubstrateShapeDiagnostic retiredPath expectedShape
    )
    retiredEnumCases
  -- Phase 8 Sprint 8.10: a stale payload still carrying a field the binary now
  -- derives must name that exact field and the regenerating command rather than
  -- reporting a bare structural type error at whichever record the decoder
  -- happened to reach first. Each case injects one retired field into a payload
  -- that is otherwise exactly what the binary writes.
  let retiredFieldAnchor = ", models_bucket = "
      retiredFieldCases =
        [ ( "retired-request-topics",
            ", request_topics = [ \"persistent://infernix/demo/inference.request.linux-cpu\" ]\n",
            "generated `request_topics` field, now derived from the runtime mode"
          ),
          ( "retired-result-topic",
            ", result_topic = \"persistent://infernix/demo/inference.result.linux-cpu\"\n",
            "generated `result_topic` field, now derived from the runtime mode"
          ),
          ( "retired-engine-daemons",
            ", engineDaemons = ([] : List Text)\n",
            "generated `engineDaemons` list, now derived from the engine members and the pool graph"
          ),
          ( "retired-engines",
            ", engines = ([] : List Text)\n",
            "generated `engines` list, now derived from the models' selected engines"
          ),
          ( "retired-per-entity-runtime-mode",
            ", runtimeMode = < AppleSilicon | LinuxCpu | LinuxGpu >.LinuxCpu\n",
            "per-entity `runtimeMode` field, now derived from the top-level runtime mode"
          ),
          ( "retired-runtime-lane",
            ", runtimeLane = < AppleSiliconHost | KindLinuxCpu >.KindLinuxCpu\n",
            "per-model `runtimeLane` field, now derived from the runtime mode and `requiresGpu`"
          ),
          ( "retired-location",
            ", location = \"cluster-pod\"\n",
            "per-daemon or per-member `location` field, now derived from the role and the runtime mode"
          ),
          ( "retired-max-inflight",
            ", maxInflightPerMember = 1\n",
            "per-pool `maxInflightPerMember` knob, which only ever held one supported value"
          ),
          ( "retired-limit-resource",
            ", resource = < HostRam | PodRam | NvidiaVram >.PodRam\n",
            "substrate-limit `resource` field, now derived from the runtime mode and which half of the budget the limit occupies"
          ),
          ( "retired-limit-source",
            ", source = < ClusterEnginePodMemoryLimit | LinuxGpuVramBudget >.ClusterEnginePodMemoryLimit\n",
            "substrate-limit `source` field, now derived alongside its resource"
          ),
          ( "retired-partition-headroom",
            ", headroomMib = 6144\n",
            "host-partition `headroomMib` term, which only ever held the binary's own minimum"
          ),
          -- Phase 8 Sprint 8.11: the fields that moved to the machine contract
          -- or became derivable when the catalog moved inside its pool.
          ( "retired-daemon-role",
            ", daemonRole = < Coordinator | Engine | Webapp >.Coordinator\n",
            "generated `daemonRole` field, which now lives in the machine contract's `machine` block"
          ),
          ( "retired-coordinator-record",
            ", coordinator = { role = < Coordinator | Engine | Webapp >.Coordinator }\n",
            "generated `coordinator` record, now derived from the runtime mode"
          ),
          ( "retired-webapp-record",
            ", webapp = { role = < Coordinator | Engine | Webapp >.Webapp }\n",
            "generated `webapp` record, now derived from the runtime mode"
          ),
          ( "retired-engine-members",
            ", engineMembers = ([] : List Text)\n",
            "generated `engineMembers` list, now inverted out of the pool graph"
          ),
          -- Phase 4 Sprint 4.38: the per-model device flag and the single
          -- footprint were replaced by one closed requirement union, so a stale
          -- payload carrying either names the field it still holds.
          ( "retired-requires-gpu",
            ", requiresGpu = False\n",
            "per-model `requiresGpu` field, now derived from the requirement's own arm"
          ),
          ( "retired-model-ram-footprint",
            ", modelRamFootprintMib = 4096\n",
            "per-model `modelRamFootprintMib` field, replaced by the derived requirement and the declared execution shape"
          )
        ]
  assert
    (retiredFieldAnchor `isInfixOf` renderedSubstrateConfig)
    "the generated payload no longer carries the retired-field injection anchor; the fixtures below would be vacuous"
  mapM_
    ( \(caseLabel, retiredField, expectedShape) -> do
        let retiredPath = root </> ("execution-plan-" <> caseLabel <> ".dhall")
        writeFile
          retiredPath
          ( replaceFirstSubstring
              retiredFieldAnchor
              (retiredField <> retiredFieldAnchor)
              renderedSubstrateConfig
          )
        assertCompiledRuntimePlanDecodeFails
          retiredPath
          ("execution-plan decoder rejects a payload still carrying " <> caseLabel)
        assertRetiredSubstrateShapeDiagnostic retiredPath expectedShape
    )
    retiredFieldCases
  assertCompiledRuntimePlanDecodeFailsForConfig
    root
    "zero-substrate-budget"
    substrateConfig {inferenceMemoryBudget = zeroBudget}
  assertCompiledRuntimePlanDecodeFailsForConfig
    root
    "negative-substrate-budget"
    substrateConfig {inferenceMemoryBudget = negativeBudget}
  runProperty
    "positive model-memory quantities roundtrip through the smart constructor"
    ( forAll (choose (1, 1048576)) $ \mib ->
        either
          (const False)
          ((== mib) . modelResourceRequirementHostMib)
          (mkHostResidentRequirement mib)
    )
  runProperty
    "zero and negative model-memory quantities are rejected"
    ( forAll (choose (-1048576, 0)) $ \mib ->
        isLeft (mkHostResidentRequirement mib)
    )
  runProperty
    "fitting host-memory partitions preserve their exact inference capacity"
    ( forAll (choose (0, 65536)) $ \vmReserveMib ->
        forAll (choose (minHostHeadroomMib, minHostHeadroomMib + 8192)) $ \headroomMib ->
          forAll (choose (1, 65536)) $ \capacityMib ->
            let physicalMib = vmReserveMib + headroomMib + capacityMib
             in either
                  (const False)
                  ((== capacityMib) . hostPartitionInferenceCapacityMib)
                  (mkHostMemoryPartition physicalMib vmReserveMib headroomMib)
    )
  runProperty
    "oversubscribed host-memory partitions are rejected"
    ( forAll (choose (1, 65536)) $ \vmReserveMib ->
        forAll (choose (minHostHeadroomMib, minHostHeadroomMib + 8192)) $ \headroomMib ->
          forAll (choose (1, vmReserveMib)) $ \oversubscriptionMib ->
            let physicalMib = vmReserveMib + headroomMib - oversubscriptionMib
             in isLeft (mkHostMemoryPartition physicalMib vmReserveMib headroomMib)
    )
  runProperty
    "host-memory partitions below the co-tenant headroom floor are rejected"
    ( forAll (choose (0, minHostHeadroomMib - 1)) $ \headroomMib ->
        isLeft (mkHostMemoryPartition 131072 0 headroomMib)
    )
  assert
    (isLeft (mkHostMemoryPartition 1 maxBound minHostHeadroomMib))
    "host-memory partition arithmetic rejects an overflow-boundary VM reserve"
  assert
    (isLeft (mkHostMemoryPartition maxBound maxBound minHostHeadroomMib))
    "host-memory partition arithmetic rejects near-boundary oversubscription without Int wraparound"
  assert
    (isLeft (hostPartitionForCapacity maxBound))
    "host-memory capacity synthesis rejects a capacity whose required headroom would overflow Int"

replaceExecutionPlanBudgetLine :: String -> String -> IO String
replaceExecutionPlanBudgetLine replacement renderedConfig =
  case filter (isPrefixOf budgetPrefix) (lines renderedConfig) of
    [_] ->
      pure
        ( unlines
            [ if budgetPrefix `isPrefixOf` line
                then budgetPrefix <> replacement
                else line
            | line <- lines renderedConfig
            ]
        )
    matches ->
      fail
        ( "expected exactly one generated inferenceMemoryBudget line, found "
            <> show (length matches)
        )
  where
    budgetPrefix = ", inferenceMemoryBudget = "

assertCompiledRuntimePlanDecodeFailsForConfig :: FilePath -> FilePath -> DemoConfig -> IO ()
assertCompiledRuntimePlanDecodeFailsForConfig root label demoConfig = do
  let configPath = root </> ("invalid-execution-plan-" <> label <> ".dhall")
  Lazy.writeFile configPath (encodeDemoConfig demoConfig)
  assertCompiledRuntimePlanDecodeFails
    configPath
    ("execution-plan decoder rejects " <> label)

-- | Phase 8 Sprint 8.9 — a retired @kind@-tagged budget JSON payload must be
-- named as retired rather than surfaced as a bare missing-alternative error.
retiredBudgetJsonDiagnosticNamesRetirement :: String -> Bool
retiredBudgetJsonDiagnosticNamesRetirement payload =
  case Aeson.eitherDecode (LazyChar8.pack payload) :: Either String InferenceMemoryBudget of
    Left decodeError -> "retired flat kind=" `isInfixOf` decodeError
    Right _ -> False

-- | Replace the first occurrence of a substring. Used to age a freshly
-- generated payload back to a retired spelling, so the migration diagnostic is
-- tested against a file that is otherwise exactly what the binary writes.
replaceFirstSubstring :: String -> String -> String -> String
replaceFirstSubstring needle replacement haystack =
  case breakOnSubstring needle haystack of
    Nothing -> haystack
    Just (before, after) -> before <> replacement <> after

breakOnSubstring :: String -> String -> Maybe (String, String)
breakOnSubstring needle = go []
  where
    go _ [] = Nothing
    go seen rest@(nextChar : laterChars)
      | needle `isPrefixOf` rest = Just (reverse seen, drop (length needle) rest)
      | otherwise = go (nextChar : seen) laterChars

assertCompiledRuntimePlanDecodeFails :: FilePath -> String -> IO ()
assertCompiledRuntimePlanDecodeFails configPath message = do
  decoded <- tryDecodeCompiledRuntimePlanFile configPath
  assert (isLeft decoded) message

-- | Phase 8 Sprint 8.9 — a retired flat payload must fail with a diagnostic
-- that names the retired shape and the command that regenerates it, not with a
-- bare structural Dhall type error.
assertRetiredSubstrateShapeDiagnostic :: FilePath -> String -> IO ()
assertRetiredSubstrateShapeDiagnostic configPath retiredShapeFragment = do
  decoded <- tryDecodeCompiledRuntimePlanFile configPath
  case decoded of
    Right _ ->
      fail "retired flat/tagged execution-plan payload unexpectedly decoded"
    Left failure -> do
      let rendered = show failure
      assert
        (retiredShapeFragment `isInfixOf` rendered)
        ( "retired execution-plan payload diagnostic does not name the retired shape ("
            <> retiredShapeFragment
            <> "): "
            <> rendered
        )
      assert
        ("infernix init" `isInfixOf` rendered)
        ( "retired execution-plan payload diagnostic does not name the regenerating command: "
            <> rendered
        )

tryDecodeCompiledRuntimePlanFile ::
  FilePath ->
  IO (Either IOError (Either ExecutionPlan.ConfigErrors ExecutionPlan.CompiledRuntimePlan))
tryDecodeCompiledRuntimePlanFile configPath =
  try (decodeCompiledRuntimePlanFile configPath)

assertExecutionPlanCompilerCoverage :: Paths -> FilePath -> DemoConfig -> DemoConfig -> IO ()
assertExecutionPlanCompilerCoverage paths root linuxConfig appleConfig = do
  mapM_ assertCatalogEngineResolution allRuntimeModes
  applePlan <- expectCompiledExecutionPlan root "valid-apple-plan" appleConfig
  assertCompiledExecutionPlanAccounting appleConfig applePlan
  assertCompiledExecutionPlanRoutes appleConfig applePlan
  assertCatalogPlanCoverage AppleSilicon appleConfig applePlan
  let barkModelIdValue = "audio-bark-small"
      barkRequiredMib = 8192
      barkSupportedBudget = hostEnforcedUnitBudget 10240
      barkSupportedConfig =
        appleConfig
          { inferenceMemoryBudget = barkSupportedBudget
          }
      barkConstrainedBudget = hostEnforcedUnitBudget 5120
      barkConstrainedConfig =
        appleConfig
          { inferenceMemoryBudget = barkConstrainedBudget
          }
  -- The row must still be in the catalog for the plan fixtures below to place
  -- it; only the memory constant it used to carry is gone.
  _barkAppleDescriptor <-
    maybe
      (fail "Apple catalog omitted the Bark model")
      pure
      (findModel AppleSilicon barkModelIdValue)
  -- Phase 4 Sprint 4.39: the catalog carries no memory constant any more, so
  -- what these fixtures pin is the admission arithmetic against a supplied
  -- requirement rather than the value of a table this repository deleted.
  barkRequirement <-
    expectRight
      "construct the Bark host-residency requirement fixture"
      (mkHostResidentRequirement barkRequiredMib)
  barkSupportedPlan <-
    expectCompiledExecutionPlan
      root
      "bark-supported-apple-plan"
      barkSupportedConfig
  assert
    ( isNothing
        ( ExecutionPlan.predictedAdmissionRejection
            barkSupportedPlan
            barkModelIdValue
            barkRequirement
        )
    )
    "an 8 GiB requirement is admitted by the real 10 GiB Apple inference partition"
  barkConstrainedPlan <-
    expectCompiledExecutionPlan
      root
      "bark-constrained-apple-plan"
      barkConstrainedConfig
  barkConstrainedRejection <-
    maybe
      (fail "Bark remained admitted by a 5 GiB Apple inference budget")
      pure
      ( ExecutionPlan.predictedAdmissionRejection
          barkConstrainedPlan
          barkModelIdValue
          barkRequirement
      )
  assert
    ( barkConstrainedRejection
        == ModelMemoryLimitExceeded
          { inferenceErrorModelId = barkModelIdValue,
            inferenceErrorRequiredMib = barkRequiredMib,
            inferenceErrorAvailableMib = 5120,
            inferenceErrorResource = HostRam,
            inferenceErrorSource = inferenceMemoryBudgetSource barkConstrainedBudget
          }
    )
    "an 8 GiB requirement is refused before execution by a 5 GiB Apple budget"
  singleAppleConfig <-
    expectRight
      "derive a single-model execution-plan fixture"
      (singleModelExecutionPlanConfig applePlan appleConfig)
  model <- expectSingleton "single-model execution-plan model" (models singleAppleConfig)
  binding <- expectSingleton "single-model execution-plan engine" (engines singleAppleConfig)
  pool <- expectSingleton "single-model execution-plan pool" (enginePools singleAppleConfig)
  member <- expectSingleton "single-model execution-plan member" (engineMembers singleAppleConfig)
  daemon <- expectSingleton "single-model execution-plan daemon" (engineDaemons singleAppleConfig)
  requestField <-
    maybe
      (fail "single-model execution-plan model has no request field")
      pure
      (listToMaybe (requestShape model))
  engineRouteTopicValue <-
    expectSingleton
      "single-model execution-plan engine route topic"
      (daemonConfigRequestTopics daemon)
  let canonicalBootstrapRequest =
        BootstrapModels.ModelBootstrapRequest
          { BootstrapModels.bootstrapRequestModelId = modelId model,
            BootstrapModels.bootstrapRequestDownloadUrl = downloadUrl model,
            BootstrapModels.bootstrapRequestRequestedAtIso8601 = "2026-07-25T12:00:00Z"
          }
  assert
    (isRight (validateModelBootstrapRequest applePlan canonicalBootstrapRequest))
    "model-bootstrap authorization accepts the exact compiled descriptor URL and a canonical timestamp"
  assert
    ( isLeft
        ( validateModelBootstrapRequest
            applePlan
            canonicalBootstrapRequest
              { BootstrapModels.bootstrapRequestDownloadUrl = "https://attacker.invalid/model"
              }
        )
    )
    "model-bootstrap authorization rejects an attacker-controlled URL for a compiled model id"
  assert
    ( isLeft
        ( validateModelBootstrapRequest
            applePlan
            canonicalBootstrapRequest
              { BootstrapModels.bootstrapRequestModelId = "unknown-model"
              }
        )
    )
    "model-bootstrap authorization rejects an unknown model id"
  assert
    ( isLeft
        ( validateModelBootstrapRequest
            applePlan
            canonicalBootstrapRequest
              { BootstrapModels.bootstrapRequestRequestedAtIso8601 = "not-a-timestamp"
              }
        )
    )
    "model-bootstrap authorization rejects a malformed requestedAt timestamp"
  let unenforceableFootprintMib =
        fromInteger (toInteger (maxBound :: Word64) `div` 1048576 + 1)
      -- Phase 4 Sprint 4.39: the compiler no longer reads an authored footprint,
      -- so what it can still refuse on every role is the declared execution
      -- shape the cache term is evaluated against.
      unenforceableShapeModel =
        model
          { modelExecutionShape =
              (modelExecutionShape model)
                { executionContextLength = unenforceableFootprintMib
                }
          }
  let modelIdValue = modelId model
      poolIdValue = enginePoolId pool
      memberIdValue = engineMemberId member
      missingEngineId = "unit-missing-engine"
      duplicateModel =
        model
          { matrixRowId = matrixRowId model <> "-duplicate"
          }
      duplicateMatrixModel =
        model
          { modelId = modelIdValue <> "-duplicate"
          }
      duplicateMatrixPool =
        pool
          { enginePoolModelIds =
              [modelIdValue, modelId duplicateMatrixModel]
          }
      secondPoolId = poolIdValue <> "-second"
      secondMemberId = memberIdValue <> "-second"
      secondPool =
        pool
          { enginePoolId = secondPoolId,
            enginePoolMemberIds = [secondMemberId]
          }
      secondMember =
        member
          { engineMemberId = secondMemberId,
            engineMemberPoolIds = [secondPoolId]
          }
      multiplyPlacedConfig =
        singleAppleConfig
          { enginePools = [pool, secondPool],
            engineMembers = [member, secondMember]
          }
      podLimitFor resource source limitMib =
        PodMemoryLimit
          { podMemoryLimitResource = resource,
            podMemoryLimitSource = source,
            podMemoryLimitMib = limitMib
          }
      podBudget resource source limitMib =
        SubstrateEnforcedBudget (podLimitFor resource source limitMib)
      linuxCpuConfig =
        executionPlanConfigForRuntime
          LinuxCpu
          (podBudget PodRam ClusterEnginePodMemoryLimit 65536)
          singleAppleConfig
      -- Phase 4 Sprint 4.39: device usage is where the weights live, so a
      -- device-lane fixture declares a streamed load rather than setting a flag
      -- beside a host quantity.
      deviceExecutionShape =
        (modelExecutionShape model) {executionLoadStrategy = StreamWeightsToDevice}
      linuxCpuGpuModel =
        model
          { runtimeMode = LinuxCpu,
            runtimeLane = KindLinuxCpu,
            modelExecutionShape = deviceExecutionShape
          }
      linuxCpuGpuConfig =
        executionPlanConfigForRuntime
          LinuxCpu
          (podBudget PodRam ClusterEnginePodMemoryLimit 65536)
          (withCatalog singleAppleConfig [linuxCpuGpuModel])
      linuxGpuModel =
        model
          { runtimeMode = LinuxGpu,
            runtimeLane = KindLinuxGpuGpu,
            modelExecutionShape = deviceExecutionShape
          }
      linuxGpuWithPodBudget =
        executionPlanConfigForRuntime
          LinuxGpu
          (podBudget PodRam ClusterEnginePodMemoryLimit 65536)
          (withCatalog singleAppleConfig [linuxGpuModel])
      linuxGpuWithVramBudget =
        executionPlanConfigForRuntime
          LinuxGpu
          (podBudget NvidiaVram LinuxGpuVramBudget 65536)
          (withCatalog singleAppleConfig [linuxGpuModel])
      invalidIdentifiers =
        [ ("path", "path/segment"),
          ("whitespace", "has whitespace"),
          ("backslash", "back\\slash"),
          ("uppercase", "Uppercase"),
          ("unicode", "unicodé"),
          ("leading-separator", "-leading"),
          ("trailing-separator", "trailing-"),
          ("repeated-separator", "repeated--separator")
        ]
      bootstrapReadyTopicValue =
        ConversationTopic.modelBootstrapReadyTopicName
          ConversationTopic.systemTopicNamespace
          modelIdValue
      -- Phase 8 Sprint 8.10: the coordinator request topic and the shared result
      -- topic are derived from the runtime mode, so neither can be pointed at
      -- another family's topic any more — those two collision classes are
      -- unrepresentable rather than merely unreached. The model-bootstrap topic
      -- is still declared, so it is the collision axis that survives.
      withModelBootstrapTopic topicValue =
        singleAppleConfig {modelBootstrapTopic = topicValue}
  assertExecutionPlanIdentifierCoverage
    root
    singleAppleConfig
    model
    binding
    pool
    member
    invalidIdentifiers
  -- Phase 8 Sprint 8.10: the engine list is derived from the models' selected
  -- engines, so a drifted, arbitrary, lookalike, or cross-runtime binding is no
  -- longer expressible. What survives is the one fact a generated engine list
  -- could ever have added: a model naming an engine this runtime has no
  -- canonical binding for.
  assertExecutionPlanError
    root
    "unknown-selected-engine"
    (ExecutionPlan.UnknownSelectedEngine modelIdValue "arbitrary-engine")
    (withCatalog singleAppleConfig [model {selectedEngine = "arbitrary-engine"}])
  assertExecutionPlanError
    root
    "cross-runtime-selected-engine"
    (ExecutionPlan.UnknownSelectedEngine modelIdValue "vLLM")
    (withCatalog singleAppleConfig [model {selectedEngine = "vLLM"}])
  assertExecutionPlanError root "empty-model-catalog" ExecutionPlan.EmptyModelCatalog (withCatalog singleAppleConfig [])
  assertExecutionPlanError root "empty-pool-catalog" ExecutionPlan.EmptyPoolCatalog (singleAppleConfig {enginePools = []})
  -- Phase 8 Sprint 8.11: an empty member catalog is expressible only by
  -- emptying every pool's member list, which the pool-side check reports first.
  assertExecutionPlanError
    root
    "empty-member-catalog"
    ExecutionPlan.EmptyMemberCatalog
    ( singleAppleConfig
        { enginePools = map (\poolValue -> poolValue {enginePoolMemberIds = []}) (enginePools singleAppleConfig),
          engineMembers = []
        }
    )
  assertExecutionPlanError root "blank-models-bucket" ExecutionPlan.BlankModelsBucket (singleAppleConfig {modelsBucket = " "})
  assertExecutionPlanError
    root
    "blank-model-bootstrap-topic"
    ExecutionPlan.BlankModelBootstrapTopic
    (singleAppleConfig {modelBootstrapTopic = " "})
  assertExecutionPlanError
    root
    "models-bucket-drift"
    (ExecutionPlan.ModelsBucketMismatch defaultModelsBucket "unit-models-bucket")
    (singleAppleConfig {modelsBucket = "unit-models-bucket"})
  assertExecutionPlanError
    root
    "model-bootstrap-topic-drift"
    (ExecutionPlan.ModelBootstrapTopicMismatch defaultModelBootstrapTopic "persistent://infernix/unit/bootstrap")
    (singleAppleConfig {modelBootstrapTopic = "persistent://infernix/unit/bootstrap"})
  assertExecutionPlanError
    root
    "blank-config-map-name"
    ExecutionPlan.BlankConfigMapName
    (singleAppleConfig {configMapName = " "})
  assertExecutionPlanError
    root
    "blank-generated-path"
    ExecutionPlan.BlankGeneratedPath
    (singleAppleConfig {generatedPath = " "})
  assertExecutionPlanError
    root
    "blank-mounted-path"
    ExecutionPlan.BlankMountedPath
    (singleAppleConfig {mountedPath = " "})
  -- Phase 8 Sprint 8.11: the two in-cluster daemon records left the wire —
  -- both run in a pod, both use the configured transport, and neither carries a
  -- member id — so a declared daemon that disagrees with the derivation has no
  -- wire representation at all. The plan compiler keeps the three mismatch
  -- checks for the in-memory configs it also validates.
  assertDerivedClusterDaemonMetadata root singleAppleConfig
  assertExecutionPlanError
    root
    "invalid-model-descriptor"
    (ExecutionPlan.InvalidModelDescriptor modelIdValue)
    (singleAppleConfig {models = [model {requestShape = []}]})
  assertExecutionPlanError
    root
    "unenforceable-model-execution-shape"
    (ExecutionPlan.UnenforceableModelExecutionShape modelIdValue (toInteger unenforceableFootprintMib))
    (withCatalog singleAppleConfig [unenforceableShapeModel])
  assertExecutionPlanError
    root
    "duplicate-model-id"
    (ExecutionPlan.DuplicateModelId modelIdValue)
    (withCatalog singleAppleConfig [model, duplicateModel])
  assertExecutionPlanError
    root
    "duplicate-matrix-row-id"
    (ExecutionPlan.DuplicateMatrixRowId (matrixRowId model))
    ( singleAppleConfig
        { models = [model, duplicateMatrixModel],
          enginePools = [duplicateMatrixPool]
        }
    )
  assertExecutionPlanError
    root
    "duplicate-pool-id"
    (ExecutionPlan.DuplicatePoolId poolIdValue)
    (singleAppleConfig {enginePools = [pool, pool]})
  -- Phase 8 Sprint 8.11: a duplicate member identity has no wire
  -- representation — members are inverted out of the pool graph, so the same id
  -- named twice is one member. The plan compiler keeps the check for the
  -- in-memory configs it also validates; the wire half is asserted positively in
  -- the generated-config round trip above.
  assertExecutionPlanError
    root
    "bootstrap-engine-route-topic-family-collision"
    (ExecutionPlan.TopicFamilyCollision engineRouteTopicValue ["engine-route", "model-bootstrap-request"])
    (withModelBootstrapTopic engineRouteTopicValue)
  assertExecutionPlanError
    root
    "bootstrap-result-topic-family-collision"
    (ExecutionPlan.TopicFamilyCollision (resultTopic singleAppleConfig) ["model-bootstrap-request", "result"])
    (withModelBootstrapTopic (resultTopic singleAppleConfig))
  assertExecutionPlanError
    root
    "bootstrap-ready-topic-family-collision"
    (ExecutionPlan.TopicFamilyCollision bootstrapReadyTopicValue ["model-bootstrap-ready", "model-bootstrap-request"])
    (withModelBootstrapTopic bootstrapReadyTopicValue)
  assertDerivedRouteTopicCollision
    root
    singleAppleConfig
    model
    pool
    member
    daemon
  assertExecutionPlanError
    root
    "duplicate-pool-model-reference"
    (ExecutionPlan.DuplicatePoolModelReference poolIdValue modelIdValue)
    -- Phase 8 Sprint 8.11: a pool holds descriptors, so a repeated reference is
    -- the same descriptor written twice under one pool.
    (withCatalog singleAppleConfig [model, model])
  assertExecutionPlanError
    root
    "duplicate-pool-member-reference"
    (ExecutionPlan.DuplicatePoolMemberReference poolIdValue memberIdValue)
    (singleAppleConfig {enginePools = [pool {enginePoolMemberIds = [memberIdValue, memberIdValue]}]})
  assertExecutionPlanError
    root
    "duplicate-member-pool-reference"
    (ExecutionPlan.DuplicateMemberPoolReference memberIdValue poolIdValue)
    -- Phase 8 Sprint 8.11: a member's pools are the pools that name it, so a
    -- repeated pool reference is one pool id written twice in the pool list.
    (singleAppleConfig {enginePools = [pool, pool]})
  assertExecutionPlanError
    root
    "duplicate-request-field"
    (ExecutionPlan.DuplicateRequestField modelIdValue (name requestField))
    (singleAppleConfig {models = [model {requestShape = [requestField, requestField]}]})
  assertExecutionPlanError
    root
    "invalid-pool-id"
    (ExecutionPlan.InvalidPoolId "unit/bad-pool")
    (singleAppleConfig {enginePools = [pool {enginePoolId = "unit/bad-pool"}]})
  assertExecutionPlanError
    root
    "invalid-member-id"
    (ExecutionPlan.InvalidMemberId "unit/bad-member")
    ( singleAppleConfig
        { enginePools = [pool {enginePoolMemberIds = ["unit/bad-member"]}],
          engineMembers = [member {engineMemberId = "unit/bad-member"}]
        }
    )
  assertExecutionPlanError
    root
    "empty-pool-models"
    (ExecutionPlan.EmptyPoolModels poolIdValue)
    (singleAppleConfig {enginePools = [pool {enginePoolModelIds = []}]})
  assertExecutionPlanError
    root
    "empty-pool-members"
    (ExecutionPlan.EmptyPoolMembers poolIdValue)
    (singleAppleConfig {enginePools = [pool {enginePoolMemberIds = []}]})
  assertExecutionPlanError
    root
    "unknown-selected-engine"
    (ExecutionPlan.UnknownSelectedEngine modelIdValue missingEngineId)
    (withCatalog singleAppleConfig [model {selectedEngine = missingEngineId}])
  assertExecutionPlanError
    root
    "unsupported-linux-cpu-gpu-requirement"
    (ExecutionPlan.UnsupportedGpuRequirement modelIdValue LinuxCpu)
    linuxCpuGpuConfig
  -- Phase 8 Sprint 8.11: eight graph-disagreement fixtures were retired here
  -- rather than re-pointed, because the generated wire can no longer express
  -- what they asserted — a dangling pool model, a dangling pool member, a
  -- dangling member pool, a one-sided link in either direction, a member that
  -- serves no pool, a model no pool places, and a model whose pool names no
  -- eligible member. A pool carries its own model
  -- descriptors and members are inverted out of the pool graph, so each of those
  -- states has no representation to write. The plan compiler keeps every check
  -- (it validates any 'DemoConfig', and the wire is one of its inputs); the wire
  -- half is asserted positively against the generated round trip instead.
  assertExecutionPlanError
    root
    "multiply-placed-model"
    (ExecutionPlan.MultiplyPlacedModel modelIdValue [poolIdValue, secondPoolId])
    multiplyPlacedConfig
  assertExecutionPlanError
    root
    "invalid-pool-subscription"
    (ExecutionPlan.InvalidPoolSubscription poolIdValue)
    (singleAppleConfig {enginePools = [pool {enginePoolSubscriptionType = ConsumerFailover}]})
  assertExecutionPlanError
    root
    "invalid-exclusive-pool-subscription"
    (ExecutionPlan.InvalidPoolSubscription poolIdValue)
    (singleAppleConfig {enginePools = [pool {enginePoolSubscriptionType = ConsumerExclusive}]})
  -- Phase 8 Sprint 8.10 retired this assertion with the field it was about: the
  -- per-pool in-flight knob is no longer on the wire, so "a negative value is
  -- unrepresentable" would be a claim about something that is not there. It is
  -- not re-pointed at another quantity, because after the deletion every
  -- remaining generated quantity is behind a checked constructor on the domain
  -- side (`mkModelMemoryFootprint`, `mkHostMemoryPartition`, the positive
  -- substrate limit), so a negative one cannot be built to render in the first
  -- place. The surviving wire-level property — that quantities render as
  -- `Natural` literals with no `+` sign prefix — is asserted at the
  -- materialization boundary.
  assertExecutionPlanError
    root
    "apple-pod-budget-mismatch"
    (ExecutionPlan.RuntimeBudgetMismatch AppleSilicon PodRam)
    (singleAppleConfig {inferenceMemoryBudget = podBudget PodRam ClusterEnginePodMemoryLimit 65536})
  assertExecutionPlanError
    root
    "linux-host-budget-mismatch"
    (ExecutionPlan.RuntimeBudgetMismatch LinuxCpu HostRam)
    (linuxCpuConfig {inferenceMemoryBudget = inferenceMemoryBudget singleAppleConfig})
  -- Phase 8 Sprint 8.10: which physical resource a substrate limit bounds, and
  -- which policy set it, are derived from the runtime mode and from which half
  -- of the budget the limit occupies. A limit claiming the wrong resource — a
  -- VRAM limit on `linux-cpu`, a swapped dual pair, a substrate limit claiming
  -- unified host RAM — is no longer a constructible term, so those four fixtures
  -- are retired with the fields rather than left asserting a property of
  -- something the wire cannot express. What survives is the arm choice, which is
  -- still declared: a budget whose union arm does not match the runtime mode.
  assertExecutionPlanError
    root
    "gpu-dual-resource-budget-required"
    ExecutionPlan.GpuDualResourceBudgetRequired
    linuxGpuWithVramBudget
  assertExecutionPlanError
    root
    "gpu-model-without-vram-enforcer"
    (ExecutionPlan.GpuModelWithoutVramEnforcer modelIdValue)
    linuxGpuWithPodBudget
  let availableMib = inferenceMemoryBudgetCapacityMib (inferenceMemoryBudget singleAppleConfig)
      requiredMib = availableMib + 1
  oversizedRequirement <-
    expectRight
      "construct an oversized execution-plan model requirement"
      (mkHostResidentRequirement requiredMib)
  fundableRequirement <-
    expectRight
      "construct a fundable execution-plan model requirement"
      (mkHostResidentRequirement availableMib)
  -- Phase 4 Sprint 4.34: an all-over-capacity catalog still compiles, because
  -- placement is graph validation and this process is not the machine that will
  -- execute. The refusal it used to raise here now belongs to the engine's
  -- refinement (`NoAdmissiblePlacement`), which is pinned in the
  -- execution-plan-internal suite; what this fixture pins is that the compiler
  -- places the model and predicts its rejection.
  let allOversizedConfig = withCatalog singleAppleConfig [model]
  allOversizedPlan <-
    expectCompiledExecutionPlan root "no-admissible-placement" allOversizedConfig
  assert
    ( map
        (modelId . ExecutionPlan.compiledPlacementDescriptor)
        (ExecutionPlan.compiledRuntimePlanPlacements allOversizedPlan)
        == [modelIdValue]
    )
    "an over-capacity catalog is still placed by the compiler"
  assert
    ( isJust
        ( ExecutionPlan.predictedAdmissionRejection
            allOversizedPlan
            modelIdValue
            oversizedRequirement
        )
    )
    ( "an over-capacity requirement is predicted to be rejected by the machine "
        <> "that would execute it"
    )
  -- Phase 4 Sprint 4.39: the prediction takes the requirement, so the same plan
  -- admits a requirement the machine can fund. A prediction that could not say
  -- "yes" would be satisfied by an implementation that always refuses.
  assert
    ( isNothing
        ( ExecutionPlan.predictedAdmissionRejection
            allOversizedPlan
            modelIdValue
            fundableRequirement
        )
    )
    "the same plan admits a requirement inside the machine's declared capacity"
  -- The unavailable-model accounting still has to work when *some* model is
  -- admissible, so the fixture pairs the over-capacity model with the original.
  let oversizedModelIdValue = modelIdValue <> "-oversized"
      oversizedModel =
        model
          { modelId = oversizedModelIdValue,
            matrixRowId = matrixRowId model <> "-oversized"
          }
      oversizedConfig =
        singleAppleConfig
          { models = [model, oversizedModel],
            enginePools =
              [pool {enginePoolModelIds = enginePoolModelIds pool <> [oversizedModelIdValue]}],
            -- The derived per-model request topic is the pool topic suffixed with
            -- the model id, so the engine daemon's declared topics have to grow
            -- with the pool or the compiled graph disagrees with the daemon.
            engineDaemons =
              [ daemon
                  { daemonConfigRequestTopics =
                      daemonConfigRequestTopics daemon
                        <> map (<> "-oversized") (daemonConfigRequestTopics daemon)
                  }
              ]
          }
  oversizedPlan <- expectCompiledExecutionPlan root "one-unavailable-model" oversizedConfig
  assert
    ( sort (map (modelId . ExecutionPlan.compiledPlacementDescriptor) (ExecutionPlan.compiledRuntimePlanPlacements oversizedPlan))
        == sort [modelIdValue, oversizedModelIdValue]
    )
    "both the fitting and the over-capacity model are placed, because placement is graph validation"
  assert
    ( isNothing
        ( ExecutionPlan.predictedAdmissionRejection
            oversizedPlan
            modelIdValue
            fundableRequirement
        )
    )
    "a fitting requirement is predicted to be admitted"
  oversizedRejection <-
    maybe
      (fail "over-capacity execution-plan model is missing from the predicted admission rejection")
      pure
      ( ExecutionPlan.predictedAdmissionRejection
          oversizedPlan
          oversizedModelIdValue
          oversizedRequirement
      )
  assert
    ( oversizedRejection
        == ModelMemoryLimitExceeded
          { inferenceErrorModelId = oversizedModelIdValue,
            inferenceErrorRequiredMib = requiredMib,
            inferenceErrorAvailableMib = availableMib,
            inferenceErrorResource = HostRam,
            inferenceErrorSource = inferenceMemoryBudgetSource (inferenceMemoryBudget singleAppleConfig)
          }
    )
    "the predicted rejection carries the exact typed admission failure"
  assertCompiledExecutionPlanAccounting oversizedConfig oversizedPlan
  -- Keep the Linux fixture tied to the same public compiler boundary.
  linuxPlan <- expectCompiledExecutionPlan root "valid-linux-plan" linuxConfig
  assertCompiledExecutionPlanAccounting linuxConfig linuxPlan
  assertCompiledExecutionPlanRoutes linuxConfig linuxPlan
  assertCatalogPlanCoverage LinuxCpu linuxConfig linuxPlan
  _barkLinuxDescriptor <-
    maybe
      (fail "Linux CPU catalog omitted the Bark model")
      pure
      (findModel LinuxCpu barkModelIdValue)
  barkLinuxRequirement <-
    expectRight
      "construct the Linux Bark host-residency requirement fixture"
      (mkHostResidentRequirement barkRequiredMib)
  barkLinuxRejection <-
    maybe
      (fail "Linux CPU admitted an 8 GiB requirement despite its 4 GiB inference budget")
      pure
      ( ExecutionPlan.predictedAdmissionRejection
          linuxPlan
          barkModelIdValue
          barkLinuxRequirement
      )
  assert
    ( barkLinuxRejection
        == ModelMemoryLimitExceeded
          { inferenceErrorModelId = barkModelIdValue,
            inferenceErrorRequiredMib = barkRequiredMib,
            inferenceErrorAvailableMib = 4096,
            inferenceErrorResource = PodRam,
            inferenceErrorSource = inferenceMemoryBudgetSource (inferenceMemoryBudget linuxConfig)
          }
    )
    "Linux CPU rejects Bark before execution with the exact 8 GiB required and 4 GiB available budget"
  -- A single-resource `linux-gpu` budget still cannot enforce both axes, so it
  -- remains a hard config error rather than silently admitting device work
  -- against one limit.
  let linuxGpuSingleResourcePath = root </> "execution-plan-linux-gpu-single-resource.dhall"
      linuxGpuSingleResourceBudget = podBudget NvidiaVram LinuxGpuVramBudget 65536
  BS.writeFile
    linuxGpuSingleResourcePath
    (renderGeneratedDemoConfigPayload paths LinuxGpu singleEngineMachine False linuxGpuSingleResourceBudget)
  linuxGpuSingleResourceResult <- decodeCompiledRuntimePlanFile linuxGpuSingleResourcePath
  case linuxGpuSingleResourceResult of
    Right _ ->
      fail "Linux GPU catalog compiled against a single-resource budget"
    Left errors -> do
      let errorList = NonEmpty.toList errors
      assert
        (ExecutionPlan.GpuDualResourceBudgetRequired `elem` errorList)
        "single-resource Linux GPU budget reaches the explicit dual-resource budget blocker"
      assert
        (not (any engineBindingSelectionError errorList))
        "every Linux GPU catalog engine resolves canonically before the dual-resource budget blocker"

  -- Phase 6 Sprint 6.44 — the production dual budget compiles the whole
  -- `linux-gpu` catalog, and every device-using model that fits is placed with
  -- both an independently admitted pod-RAM and NVIDIA VRAM grant.
  let linuxGpuConfigPath = root </> "execution-plan-linux-gpu-catalog.dhall"
      linuxGpuDualCatalogBudget =
        DualEnforcedBudget
          (podLimitFor PodRam ClusterEnginePodMemoryLimit 4096)
          (podLimitFor NvidiaVram LinuxGpuVramBudget 4096)
  BS.writeFile
    linuxGpuConfigPath
    (renderGeneratedDemoConfigPayload paths LinuxGpu singleEngineMachine False linuxGpuDualCatalogBudget)
  linuxGpuPlan <-
    either
      (\errors -> fail ("Linux GPU catalog failed to compile under the dual budget: " <> show (NonEmpty.toList errors)))
      pure
      =<< decodeCompiledRuntimePlanFile linuxGpuConfigPath
  -- Phase 4 Sprint 4.39: the prediction takes the requirement, so this fixture
  -- supplies one that exceeds both halves of the dual budget. What it pins is
  -- which resource a dual-resource refusal names, not a catalog constant.
  linuxGpuOverCapacityRequirement <-
    expectRight
      "construct a Linux GPU requirement past both declared limits"
      (mkHostAndDeviceRequirement 8192 8192)
  assert
    ( sort (map modelId (ExecutionPlan.compiledPlanConfiguredModels linuxGpuPlan))
        == sort (map modelId (catalogForMode LinuxGpu))
    )
    "Linux GPU compiled plan accounts for every generated catalog model"
  assert
    (not (null (ExecutionPlan.compiledRuntimePlanPlacements linuxGpuPlan)))
    "Linux GPU catalog places at least one model under the dual budget"
  -- The device-using models that exceed the VRAM half are rejected against the
  -- VRAM limit by name, not against the pod RAM limit that also applies.
  mapM_
    ( \placement ->
        let descriptor = ExecutionPlan.compiledPlacementDescriptor placement
         in mapM_
              ( \reason ->
                  assert
                    ( not (requiresGpu descriptor)
                        || inferenceErrorResource reason == NvidiaVram
                        || inferenceErrorResource reason == PodRam
                    )
                    "Linux GPU capacity rejection names one of the two enforced resources"
              )
              ( ExecutionPlan.predictedAdmissionRejection
                  linuxGpuPlan
                  (modelId descriptor)
                  linuxGpuOverCapacityRequirement
              )
    )
    (ExecutionPlan.compiledRuntimePlanPlacements linuxGpuPlan)

  -- A `linux-gpu` model that requires the device is bound to BOTH resources; a
  -- model on the shared lane stays on the resident-set lane alone, because a
  -- VRAM grant it would never consume is not evidence of anything.
  mapM_
    ( \placement ->
        let descriptor = ExecutionPlan.compiledPlacementDescriptor placement
            expectedResources =
              if requiresGpu descriptor then [PodRam, NvidiaVram] else [PodRam]
            enforcedResources =
              ExecutionPlan.compiledPlanPlacementEnforcedResources linuxGpuPlan placement
         in assert
              (enforcedResources == expectedResources)
              ( "Linux GPU placement "
                  <> Text.unpack (modelId descriptor)
                  <> " is bound to the wrong resource set: "
                  <> show enforcedResources
              )
    )
    (ExecutionPlan.compiledRuntimePlanPlacements linuxGpuPlan)
  assert
    ( any
        (requiresGpu . ExecutionPlan.compiledPlacementDescriptor)
        (ExecutionPlan.compiledRuntimePlanPlacements linuxGpuPlan)
    )
    "Linux GPU catalog places at least one device-using model, so the dual-resource arm is exercised"

assertCatalogEngineResolution :: RuntimeMode -> IO ()
assertCatalogEngineResolution mode =
  mapM_
    ( \descriptor ->
        case engineBindingForSelectedEngine mode (selectedEngine descriptor) of
          Nothing ->
            fail
              ( "catalog engine does not resolve canonically for "
                  <> show mode
                  <> ": "
                  <> Text.unpack (selectedEngine descriptor)
              )
          Just binding ->
            assert
              (binding `elem` engineBindingsForMode mode)
              ( "resolved catalog engine is absent from the generated binding set for "
                  <> show mode
                  <> ": "
                  <> Text.unpack (selectedEngine descriptor)
              )
    )
    (catalogForMode mode)

assertCatalogPlanCoverage ::
  RuntimeMode ->
  DemoConfig ->
  ExecutionPlan.CompiledRuntimePlan ->
  IO ()
assertCatalogPlanCoverage mode demoConfig compiledPlan =
  mapM_
    ( \descriptor -> do
        assert
          (descriptor `elem` models demoConfig)
          ( "generated config omitted a catalog descriptor for "
              <> show mode
              <> ": "
              <> Text.unpack (modelId descriptor)
          )
        binding <-
          maybe
            ( fail
                ( "catalog engine stopped resolving while checking the compiled plan for "
                    <> Text.unpack (modelId descriptor)
                )
            )
            pure
            (engineBindingForSelectedEngine mode (selectedEngine descriptor))
        assert
          (binding `elem` engines demoConfig)
          ( "generated config omitted the canonical binding for "
              <> Text.unpack (modelId descriptor)
          )
        assert
          (isJust (ExecutionPlan.lookupCompiledPlacement (modelId descriptor) compiledPlan))
          ( "compiled plan omitted catalog model "
              <> Text.unpack (modelId descriptor)
          )
    )
    (catalogForMode mode)

engineBindingSelectionError :: ExecutionPlan.ConfigError -> Bool
engineBindingSelectionError configError =
  case configError of
    ExecutionPlan.UnknownSelectedEngine _ _ -> True
    _ -> False

-- | Phase 8 Sprint 8.11: a pool owns its models on the wire, so a fixture that
-- changes the catalog has to move the pool with it. Assigning the whole catalog
-- to the first pool is what these single-pool fixtures always meant; before this
-- sprint the two lists were independent and a fixture could leave them
-- disagreeing without noticing.
withCatalog :: DemoConfig -> [ModelDescriptor] -> DemoConfig
withCatalog demoConfig catalog =
  case enginePools demoConfig of
    [] -> demoConfig {models = catalog}
    firstPool : remainingPools ->
      demoConfig
        { models = catalog,
          enginePools =
            firstPool {enginePoolModelIds = map modelId catalog} : remainingPools
        }

assertExecutionPlanIdentifierCoverage ::
  FilePath ->
  DemoConfig ->
  ModelDescriptor ->
  EngineBinding ->
  EnginePool ->
  EngineMember ->
  [(FilePath, Text.Text)] ->
  IO ()
assertExecutionPlanIdentifierCoverage root demoConfig model _binding pool member =
  mapM_
    ( \(label, invalidIdentifier) -> do
        assertExecutionPlanError
          root
          ("invalid-model-id-" <> label)
          (ExecutionPlan.InvalidModelId invalidIdentifier)
          (withCatalog demoConfig [model {modelId = invalidIdentifier}])
        assertExecutionPlanError
          root
          ("invalid-matrix-row-id-" <> label)
          (ExecutionPlan.InvalidMatrixRowId invalidIdentifier)
          (withCatalog demoConfig [model {matrixRowId = invalidIdentifier}])
        assertExecutionPlanError
          root
          ("invalid-pool-id-" <> label)
          (ExecutionPlan.InvalidPoolId invalidIdentifier)
          (demoConfig {enginePools = [pool {enginePoolId = invalidIdentifier}]})
        -- Phase 8 Sprint 8.11: a member exists because a pool names it, so an
        -- invalid member identity is written on the pool.
        assertExecutionPlanError
          root
          ("invalid-member-id-" <> label)
          (ExecutionPlan.InvalidMemberId invalidIdentifier)
          ( demoConfig
              { enginePools = [pool {enginePoolMemberIds = [invalidIdentifier]}],
                engineMembers = [member {engineMemberId = invalidIdentifier}]
              }
          )
    )

assertDerivedRouteTopicCollision ::
  FilePath ->
  DemoConfig ->
  ModelDescriptor ->
  EnginePool ->
  EngineMember ->
  DaemonConfig ->
  IO ()
assertDerivedRouteTopicCollision root demoConfig model pool member daemon = do
  let firstModelId = "b.model.c"
      secondModelId = "c"
      firstPoolId = "a"
      secondPoolId = "a.model.b"
      collisionTopic =
        "persistent://infernix/demo/inference.batch.apple-silicon.pool.a.model.b.model.c"
      firstModel =
        model
          { modelId = firstModelId
          }
      secondModel =
        model
          { matrixRowId = matrixRowId model <> "-collision",
            modelId = secondModelId
          }
      firstPool =
        pool
          { enginePoolId = firstPoolId,
            enginePoolModelIds = [firstModelId]
          }
      secondPool =
        pool
          { enginePoolId = secondPoolId,
            enginePoolModelIds = [secondModelId]
          }
      collisionConfig =
        demoConfig
          { engineDaemons =
              [daemon {daemonConfigRequestTopics = [collisionTopic, collisionTopic]}],
            enginePools = [firstPool, secondPool],
            engineMembers =
              [member {engineMemberPoolIds = [firstPoolId, secondPoolId]}],
            models = [firstModel, secondModel]
          }
      expectedSources =
        [(firstPoolId, firstModelId), (secondPoolId, secondModelId)]
  result <- compileExecutionPlanFixture root "derived-route-topic-collision" collisionConfig
  case result of
    Right _ -> fail "ambiguous derived route topics unexpectedly compiled"
    Left errors ->
      case [ sources
           | ExecutionPlan.DuplicateDerivedRouteTopic topic sources <- NonEmpty.toList errors,
             topic == collisionTopic
           ] of
        [sources] ->
          assert
            ( length sources == length expectedSources
                && all (`elem` sources) expectedSources
            )
            "derived route-topic collision reports both conflicting pool/model sources"
        collisions ->
          fail
            ( "derived route-topic collision emitted unexpected diagnostics: "
                <> show collisions
            )

expectCompiledExecutionPlan :: FilePath -> FilePath -> DemoConfig -> IO ExecutionPlan.CompiledRuntimePlan
expectCompiledExecutionPlan root label demoConfig = do
  result <- compileExecutionPlanFixture root label demoConfig
  case result of
    Left errors ->
      fail
        ( "expected execution-plan fixture to compile for "
            <> label
            <> ", errors="
            <> show (NonEmpty.toList errors)
        )
    Right plan -> pure plan

compileExecutionPlanFixture ::
  FilePath ->
  FilePath ->
  DemoConfig ->
  IO (Either ExecutionPlan.ConfigErrors ExecutionPlan.CompiledRuntimePlan)
compileExecutionPlanFixture root label demoConfig = do
  let configPath = root </> ("execution-plan-" <> label <> ".dhall")
  Lazy.writeFile configPath (encodeDemoConfig demoConfig)
  decodeCompiledRuntimePlanFile configPath

expectDecodedCompiledPlan ::
  String ->
  Either ExecutionPlan.ConfigErrors ExecutionPlan.CompiledRuntimePlan ->
  IO ExecutionPlan.CompiledRuntimePlan
expectDecodedCompiledPlan label decoded =
  case decoded of
    Left errors ->
      fail
        ( label
            <> " failed execution-plan compilation: "
            <> show (NonEmpty.toList errors)
        )
    Right plan -> pure plan

assertExecutionPlanError ::
  FilePath ->
  FilePath ->
  ExecutionPlan.ConfigError ->
  DemoConfig ->
  IO ()
assertExecutionPlanError root label expectedError demoConfig = do
  result <- compileExecutionPlanFixture root label demoConfig
  case result of
    Left errors ->
      assert
        (expectedError `elem` NonEmpty.toList errors)
        ( "execution-plan fixture "
            <> label
            <> " did not emit "
            <> executionPlanConfigErrorTag expectedError
            <> "; errors="
            <> show (NonEmpty.toList errors)
        )
    Right _ ->
      fail
        ( "execution-plan fixture unexpectedly compiled for "
            <> label
            <> "; expected "
            <> executionPlanConfigErrorTag expectedError
        )

executionPlanConfigErrorTag :: ExecutionPlan.ConfigError -> String
executionPlanConfigErrorTag configError =
  case configError of
    ExecutionPlan.EmptyModelCatalog -> "EmptyModelCatalog"
    ExecutionPlan.EmptyPoolCatalog -> "EmptyPoolCatalog"
    ExecutionPlan.EmptyMemberCatalog -> "EmptyMemberCatalog"
    ExecutionPlan.BlankModelsBucket -> "BlankModelsBucket"
    ExecutionPlan.BlankModelBootstrapTopic -> "BlankModelBootstrapTopic"
    ExecutionPlan.ModelsBucketMismatch _ _ -> "ModelsBucketMismatch"
    ExecutionPlan.ModelBootstrapTopicMismatch _ _ -> "ModelBootstrapTopicMismatch"
    ExecutionPlan.BlankConfigMapName -> "BlankConfigMapName"
    ExecutionPlan.BlankGeneratedPath -> "BlankGeneratedPath"
    ExecutionPlan.BlankMountedPath -> "BlankMountedPath"
    ExecutionPlan.DaemonRoleMismatch {} -> "DaemonRoleMismatch"
    ExecutionPlan.DaemonMemberMismatch {} -> "DaemonMemberMismatch"
    ExecutionPlan.DaemonConnectionModeMismatch {} -> "DaemonConnectionModeMismatch"
    ExecutionPlan.InvalidModelDescriptor _ -> "InvalidModelDescriptor"
    ExecutionPlan.InvalidModelId _ -> "InvalidModelId"
    ExecutionPlan.InvalidMatrixRowId _ -> "InvalidMatrixRowId"
    ExecutionPlan.UnenforceableModelExecutionShape _ _ -> "UnenforceableModelExecutionShape"
    ExecutionPlan.DuplicateModelId _ -> "DuplicateModelId"
    ExecutionPlan.DuplicateMatrixRowId _ -> "DuplicateMatrixRowId"
    ExecutionPlan.DuplicatePoolId _ -> "DuplicatePoolId"
    ExecutionPlan.DuplicateMemberId _ -> "DuplicateMemberId"
    ExecutionPlan.DuplicatePoolModelReference _ _ -> "DuplicatePoolModelReference"
    ExecutionPlan.DuplicatePoolMemberReference _ _ -> "DuplicatePoolMemberReference"
    ExecutionPlan.DuplicateMemberPoolReference _ _ -> "DuplicateMemberPoolReference"
    ExecutionPlan.DuplicateRequestField _ _ -> "DuplicateRequestField"
    ExecutionPlan.InvalidPoolId _ -> "InvalidPoolId"
    ExecutionPlan.InvalidMemberId _ -> "InvalidMemberId"
    ExecutionPlan.EmptyPoolModels _ -> "EmptyPoolModels"
    ExecutionPlan.EmptyPoolMembers _ -> "EmptyPoolMembers"
    ExecutionPlan.EmptyMemberPools _ -> "EmptyMemberPools"
    ExecutionPlan.UnknownSelectedEngine _ _ -> "UnknownSelectedEngine"
    ExecutionPlan.UnsupportedGpuRequirement _ _ -> "UnsupportedGpuRequirement"
    ExecutionPlan.DanglingPoolModel _ _ -> "DanglingPoolModel"
    ExecutionPlan.DanglingPoolMember _ _ -> "DanglingPoolMember"
    ExecutionPlan.DanglingMemberPool _ _ -> "DanglingMemberPool"
    ExecutionPlan.PoolMemberLinkMissing _ _ -> "PoolMemberLinkMissing"
    ExecutionPlan.MemberPoolLinkMissing _ _ -> "MemberPoolLinkMissing"
    ExecutionPlan.UnplacedModel _ -> "UnplacedModel"
    ExecutionPlan.MultiplyPlacedModel _ _ -> "MultiplyPlacedModel"
    ExecutionPlan.InvalidPoolSubscription _ -> "InvalidPoolSubscription"
    ExecutionPlan.ModelWithoutEligibleMember _ -> "ModelWithoutEligibleMember"
    ExecutionPlan.DuplicateDerivedRouteTopic _ _ -> "DuplicateDerivedRouteTopic"
    ExecutionPlan.TopicFamilyCollision _ _ -> "TopicFamilyCollision"
    ExecutionPlan.RuntimeBudgetMismatch _ _ -> "RuntimeBudgetMismatch"
    ExecutionPlan.GpuDualResourceBudgetRequired -> "GpuDualResourceBudgetRequired"
    ExecutionPlan.GpuModelWithoutVramEnforcer _ -> "GpuModelWithoutVramEnforcer"
    ExecutionPlan.InvalidMemoryEnforcer _ -> "InvalidMemoryEnforcer"

assertCompiledExecutionPlanAccounting :: DemoConfig -> ExecutionPlan.CompiledRuntimePlan -> IO ()
assertCompiledExecutionPlanAccounting demoConfig compiledPlan = do
  let configuredModels = ExecutionPlan.compiledPlanConfiguredModels compiledPlan
      placedModels = ExecutionPlan.compiledPlanAvailableModels compiledPlan
      configuredIds = map modelId configuredModels
      placedIds = map modelId placedModels
      configuredCounts = MapStrict.fromListWith (+) [(modelIdValue, 1 :: Int) | modelIdValue <- configuredIds]
      placedCounts = MapStrict.fromListWith (+) [(modelIdValue, 1 :: Int) | modelIdValue <- placedIds]
  -- Phase 8 Sprint 8.11: the catalog is the pool graph, so the compiled order
  -- is pool order rather than the order the in-memory config happened to list.
  -- What must not change is the set: every configured model is compiled, and
  -- nothing else is.
  assert
    (sortOn modelId configuredModels == sortOn modelId (models demoConfig))
    "compiled execution plan retains exactly the configured model set"
  -- Phase 4 Sprint 4.34: placement is exhaustive over the configured catalog,
  -- because admission — the only thing that used to remove a model here — has
  -- moved to the machine that will execute.
  assert
    (placedCounts == configuredCounts)
    "compiled placements account for every configured model exactly once"
  assert
    (ExecutionPlan.compiledPlanRuntimeMode compiledPlan == configRuntimeMode demoConfig)
    "compiled execution plan preserves runtime mode"
  assert
    ( compiledDaemonProjection (ExecutionPlan.compiledPlanCoordinatorDaemon compiledPlan)
        == daemonConfigProjection (coordinatorDaemon demoConfig)
    )
    "compiled execution plan preserves coordinator metadata"
  assert
    ( compiledDaemonProjection (ExecutionPlan.compiledPlanWebappDaemon compiledPlan)
        == daemonConfigProjection (webappDaemon demoConfig)
    )
    "compiled execution plan preserves webapp metadata"
  assert
    ( map compiledDaemonProjection (ExecutionPlan.compiledPlanEngineDaemons compiledPlan)
        == map daemonConfigProjection (engineDaemons demoConfig)
    )
    "compiled execution plan preserves engine daemon metadata"
  assert
    (ExecutionPlan.compiledPlanRequestTopics compiledPlan == requestTopics demoConfig)
    "compiled execution plan preserves request topics"
  assert
    (ExecutionPlan.compiledPlanResultTopic compiledPlan == resultTopic demoConfig)
    "compiled execution plan preserves the result topic"
  assert
    (ExecutionPlan.compiledPlanModelsBucket compiledPlan == modelsBucket demoConfig)
    "compiled execution plan preserves the models bucket"
  assert
    (ExecutionPlan.compiledPlanModelBootstrapTopic compiledPlan == modelBootstrapTopic demoConfig)
    "compiled execution plan preserves the model-bootstrap topic"

type DaemonProjection =
  ( DaemonRole,
    Text.Text,
    Maybe Text.Text,
    [Text.Text],
    Text.Text,
    PulsarConnectionMode,
    Maybe ConsumerSubscriptionType
  )

daemonConfigProjection :: DaemonConfig -> DaemonProjection
daemonConfigProjection daemon =
  ( daemonConfigRole daemon,
    daemonConfigLocation daemon,
    daemonConfigMemberId daemon,
    daemonConfigRequestTopics daemon,
    daemonConfigResultTopic daemon,
    daemonConfigPulsarConnectionMode daemon,
    daemonConfigConsumerSubscriptionType daemon
  )

compiledDaemonProjection :: ExecutionPlan.CompiledDaemon -> DaemonProjection
compiledDaemonProjection daemon =
  ( ExecutionPlan.compiledDaemonRole daemon,
    ExecutionPlan.compiledDaemonLocation daemon,
    ExecutionPlan.compiledDaemonMemberId daemon,
    ExecutionPlan.compiledDaemonRequestTopics daemon,
    ExecutionPlan.compiledDaemonResultTopic daemon,
    ExecutionPlan.compiledDaemonPulsarConnectionMode daemon,
    ExecutionPlan.compiledDaemonConsumerSubscriptionType daemon
  )

assertCompiledExecutionPlanRoutes :: DemoConfig -> ExecutionPlan.CompiledRuntimePlan -> IO ()
assertCompiledExecutionPlanRoutes demoConfig compiledPlan = do
  let placements = ExecutionPlan.compiledRuntimePlanPlacements compiledPlan
      routeKeys =
        [ ( ExecutionPlan.compiledPlacementId placement,
            ExecutionPlan.engineRoutePoolId route,
            ExecutionPlan.engineRouteMemberId route
          )
        | placement <- placements,
          route <- NonEmpty.toList (ExecutionPlan.compiledPlacementRoutes placement)
        ]
  assert
    (length routeKeys == length (nub routeKeys))
    "compiled execution-plan routes are unique by model, pool, and member"
  mapM_
    ( \placement -> do
        let descriptor = ExecutionPlan.compiledPlacementDescriptor placement
            actualRoutes =
              map
                executionPlanRouteMetadata
                (NonEmpty.toList (ExecutionPlan.compiledPlacementRoutes placement))
            expectedRoutes = expectedExecutionPlanRoutes demoConfig descriptor
            expectedEngine =
              find
                ((== selectedEngine descriptor) . engineBindingName)
                (engines demoConfig)
        assert
          (ExecutionPlan.lookupCompiledPlacement (modelId descriptor) compiledPlan == Just placement)
          "compiled execution-plan lookup returns the exact placement"
        assert
          (Just (ExecutionPlan.compiledPlacementEngine placement) == expectedEngine)
          "compiled placement retains the selected engine binding"
        assert
          (actualRoutes == expectedRoutes)
          ( "compiled placement routes preserve exact pool/member/subscription/inflight fields for "
              <> Text.unpack (modelId descriptor)
          )
        mapM_
          (assertCompiledRouteOwnedByDaemon compiledPlan)
          (NonEmpty.toList (ExecutionPlan.compiledPlacementRoutes placement))
    )
    placements

executionPlanRouteMetadata ::
  ExecutionPlan.EngineRoute ->
  (Text.Text, Text.Text, ConsumerSubscriptionType, Int)
executionPlanRouteMetadata route =
  ( ExecutionPlan.engineRoutePoolId route,
    ExecutionPlan.engineRouteMemberId route,
    ExecutionPlan.engineRouteSubscriptionType route,
    ExecutionPlan.engineRouteMaxInflightPerMember route
  )

assertCompiledRouteOwnedByDaemon ::
  ExecutionPlan.CompiledRuntimePlan ->
  ExecutionPlan.EngineRoute ->
  IO ()
assertCompiledRouteOwnedByDaemon compiledPlan route =
  case ExecutionPlan.lookupCompiledEngineDaemon (ExecutionPlan.engineRouteMemberId route) compiledPlan of
    Nothing ->
      fail
        ( "compiled route references a missing engine daemon: "
            <> Text.unpack (ExecutionPlan.engineRouteMemberId route)
        )
    Just daemon ->
      assert
        (ExecutionPlan.engineRouteTopic route `elem` ExecutionPlan.compiledDaemonRequestTopics daemon)
        "compiled route topic is authorized by its compiled engine daemon"

expectedExecutionPlanRoutes ::
  DemoConfig ->
  ModelDescriptor ->
  [(Text.Text, Text.Text, ConsumerSubscriptionType, Int)]
expectedExecutionPlanRoutes demoConfig descriptor =
  [ ( enginePoolId pool,
      memberIdValue,
      enginePoolSubscriptionType pool,
      enginePoolMaxInflightPerMember pool
    )
  | pool <- enginePools demoConfig,
    modelId descriptor `elem` enginePoolModelIds pool,
    memberIdValue <- enginePoolMemberIds pool,
    Just member <- [find ((== memberIdValue) . engineMemberId) (engineMembers demoConfig)],
    enginePoolId pool `elem` engineMemberPoolIds member
  ]

singleModelExecutionPlanConfig ::
  ExecutionPlan.CompiledRuntimePlan ->
  DemoConfig ->
  Either String DemoConfig
singleModelExecutionPlanConfig compiledPlan demoConfig = do
  model <- maybe (Left "model catalog is empty") Right (listToMaybe (models demoConfig))
  pool <-
    maybe
      (Left "first model has no engine pool")
      Right
      (find ((modelId model `elem`) . enginePoolModelIds) (enginePools demoConfig))
  memberIdValue <-
    maybe
      (Left "first model pool has no member")
      Right
      (listToMaybe (enginePoolMemberIds pool))
  member <-
    maybe
      (Left "first model pool member is missing")
      Right
      (find ((== memberIdValue) . engineMemberId) (engineMembers demoConfig))
  binding <-
    maybe
      (Left "first model selected engine is missing")
      Right
      (find ((== selectedEngine model) . engineBindingName) (engines demoConfig))
  daemon <-
    maybe
      (Left "engine daemon catalog is empty")
      Right
      (listToMaybe (engineDaemons demoConfig))
  placement <-
    maybe
      (Left "first model has no compiled placement")
      Right
      (ExecutionPlan.lookupCompiledPlacement (modelId model) compiledPlan)
  route <-
    maybe
      (Left "first model has no compiled route for its selected pool member")
      Right
      ( find
          ( \candidate ->
              ExecutionPlan.engineRoutePoolId candidate == enginePoolId pool
                && ExecutionPlan.engineRouteMemberId candidate == memberIdValue
          )
          (NonEmpty.toList (ExecutionPlan.compiledPlacementRoutes placement))
      )
  let poolIdValue = enginePoolId pool
      routeTopic = ExecutionPlan.engineRouteTopic route
  pure
    demoConfig
      { engineDaemons =
          [ daemon
              { daemonConfigRole = Engine,
                daemonConfigMemberId = Just memberIdValue,
                daemonConfigRequestTopics = [routeTopic]
              }
          ],
        enginePools =
          [ pool
              { enginePoolModelIds = [modelId model],
                enginePoolMemberIds = [memberIdValue]
              }
          ],
        engineMembers =
          [ member
              { engineMemberPoolIds = [poolIdValue]
              }
          ],
        engines = [binding],
        models = [model]
      }

executionPlanConfigForRuntime ::
  RuntimeMode ->
  InferenceMemoryBudget ->
  DemoConfig ->
  DemoConfig
executionPlanConfigForRuntime runtimeModeValue budget demoConfig =
  demoConfig
    { configRuntimeMode = runtimeModeValue,
      engineDaemons =
        [ daemon
            { daemonConfigLocation = memberLocation,
              daemonConfigPulsarConnectionMode = engineConnectionMode
            }
        | daemon <- engineDaemons demoConfig
        ],
      enginePools =
        [pool {enginePoolRuntimeMode = runtimeModeValue} | pool <- enginePools demoConfig],
      engineMembers =
        [ member
            { engineMemberRuntimeMode = runtimeModeValue,
              engineMemberLocation = memberLocation
            }
        | member <- engineMembers demoConfig
        ],
      models =
        [ configuredModel
            { runtimeMode = runtimeModeValue,
              runtimeLane = runtimeLaneForMode runtimeModeValue (requiresGpu configuredModel),
              -- Phase 8 Sprint 8.10: the engine list is derived from the models'
              -- selected engines, so retargeting a fixture at another runtime has
              -- to retarget the selected engine too. Otherwise the fixture reports
              -- `UnknownSelectedEngine` for an engine the new runtime does not
              -- have, instead of the property it exists to pin.
              selectedEngine =
                maybe
                  (selectedEngine configuredModel)
                  selectedEngine
                  (findModel runtimeModeValue (modelId configuredModel))
            }
        | configuredModel <- models demoConfig
        ],
      inferenceMemoryBudget = budget
    }
  where
    memberLocation =
      case runtimeModeValue of
        AppleSilicon -> "control-plane-host"
        LinuxCpu -> "cluster-pod"
        LinuxGpu -> "cluster-pod"
    engineConnectionMode =
      case runtimeModeValue of
        AppleSilicon -> PublicationEdgeAutoDiscovery
        LinuxCpu -> ConfiguredTransport
        LinuxGpu -> ConfiguredTransport

expectSingleton :: String -> [a] -> IO a
expectSingleton label values =
  case values of
    [value] -> pure value
    _ -> fail ("expected exactly one " <> label <> ", found " <> show (length values))

