mangleLastChar :: Text.Text -> Text.Text
mangleLastChar token =
  let lastDotIndex = Text.length token - Text.length (Text.takeWhileEnd (/= '.') token) - 1
      headerAndPayload = Text.take (lastDotIndex + 1) token
      signaturePart = Text.drop (lastDotIndex + 1) token
      mid = Text.length signaturePart `div` 2
      before = Text.take mid signaturePart
      midChar = Text.index signaturePart mid
      after = Text.drop (mid + 1) signaturePart
      replacement = if midChar == 'A' then 'B' else 'A'
   in headerAndPayload <> before <> Text.singleton replacement <> after

signJwt :: Crypto.PubKey.RSA.PrivateKey -> String -> Aeson.Value -> Text.Text
signJwt privateKey kid claimsValue =
  let headerJson = Aeson.encode (Aeson.object ["alg" Aeson..= ("RS256" :: String), "typ" Aeson..= ("JWT" :: String), "kid" Aeson..= kid])
      payloadJson = Aeson.encode claimsValue
      headerB64 = base64UrlText (Lazy.toStrict headerJson)
      payloadB64 = base64UrlText (Lazy.toStrict payloadJson)
      signingInput = TextEncoding.encodeUtf8 (headerB64 <> "." <> payloadB64)
      signatureResult =
        Crypto.PubKey.RSA.PKCS15.sign Nothing (Just Crypto.Hash.Algorithms.SHA256) privateKey signingInput
   in assembleSignedJwt headerB64 payloadB64 signatureResult

assembleSignedJwt :: Text.Text -> Text.Text -> Either Crypto.PubKey.RSA.Error BS.ByteString -> Text.Text
assembleSignedJwt _ _ (Left err) = error ("signJwt failed: " <> show err)
assembleSignedJwt headerB64 payloadB64 (Right signatureBytes) =
  headerB64 <> "." <> payloadB64 <> "." <> base64UrlText signatureBytes

base64UrlText :: BS.ByteString -> Text.Text
base64UrlText =
  Text.dropWhileEnd (== '=')
    . TextEncoding.decodeUtf8
    . Data.ByteString.Base64.URL.encode

integerToBytes :: Integer -> BS.ByteString
integerToBytes n
  | n == 0 = BS.singleton 0
  | otherwise = BS.pack (reverse (go n))
  where
    go 0 = []
    go x = fromIntegral (x `mod` 256) : go (x `div` 256)

expectRight :: String -> Either String a -> IO a
expectRight _ (Right value) = pure value
expectRight context (Left err) = fail (context <> ": " <> err)

assertDhallSchemaReflection :: IO ()
assertDhallSchemaReflection =
  mapM_ assertReflectedSchema allDhallSchemas
  where
    -- Zero-tracked-Dhall doctrine: no packaged `dhall/*.dhall` file to
    -- assert on disk; the schema is reflected from the decoder type and
    -- emitted by `infernix internal dhall-schema`. We assert the
    -- reflection renders a well-formed, field-complete schema.
    assertReflectedSchema schema = do
      rendered <-
        expectRight
          ("render reflected Dhall schema " <> Text.unpack (dhallSchemaName schema))
          (renderDhallSchema schema)
      assert
        (not (Text.null rendered))
        ("reflected Dhall schema is non-empty for " <> Text.unpack (dhallSchemaName schema))
      assert
        ("\n" `Text.isSuffixOf` rendered)
        ("reflected Dhall schema is newline-terminated for " <> Text.unpack (dhallSchemaName schema))
      mapM_
        ( \fieldName ->
            assert
              (fieldName `Text.isInfixOf` rendered)
              ("reflected Dhall schema includes " <> Text.unpack fieldName <> " for " <> Text.unpack (dhallSchemaName schema))
        )
        (dhallSchemaRequiredFields schema)
      case schema of
        HostSchema ->
          -- Phase 8 Sprint 8.11: the machine contract is a union, so a manifest
          -- that declares a machine always carries its pin. Assert the
          -- alternatives are reflected rather than merely rendered.
          mapM_
            ( \alternativeName ->
                assert
                  (alternativeName `Text.isInfixOf` rendered)
                  ( "host schema reflects the machine-contract alternative "
                      <> Text.unpack alternativeName
                  )
            )
            machineContractUnionAlternatives
        SubstrateSchema -> do
          assert
            ( "HostEnforced" `Text.isInfixOf` rendered
                && "SubstrateEnforced" `Text.isInfixOf` rendered
                && "DualEnforced" `Text.isInfixOf` rendered
            )
            "substrate schema reflects every inference-memory union alternative"
          assert
            (not ("podLimitMib" `Text.isInfixOf` rendered) && not ("kind" `Text.isInfixOf` rendered))
            "substrate schema excludes the retired text discriminator and zero-filled union fields"
          -- Phase 8 Sprint 8.9: every enum-like choice is a union in the
          -- reflected decoder too, not just in the renderer. A field that
          -- silently reverted to Text would still round-trip, so assert the
          -- alternatives are present and that the retired placeholder is gone.
          mapM_
            ( \alternativeName ->
                assert
                  (alternativeName `Text.isInfixOf` rendered)
                  ( "substrate schema reflects the union alternative "
                      <> Text.unpack alternativeName
                  )
            )
            generatedWireUnionAlternatives
          mapM_
            ( \retiredField ->
                assert
                  (not (retiredField `Text.isInfixOf` rendered))
                  ( "substrate schema still names the retired generated field "
                      <> Text.unpack retiredField
                  )
            )
            retiredGeneratedWireFields
          assert
            ( not ("edgePort" `Text.isInfixOf` rendered)
                && not ("Integer" `Text.isInfixOf` rendered)
            )
            "substrate schema drops the never-read edgePort placeholder and renders quantities as Natural"
          -- Phase 8 Sprint 8.9: the renderer writes the budget union's type
          -- annotation as text while the decoder derives it from the Haskell
          -- ADT. Nothing in the type system ties them together, so pin the
          -- agreement here: every alternative the renderer can emit must be an
          -- alternative the reflected decoder expects, and every alternative
          -- the decoder expects must be one the renderer can emit.
          schemaPaths <- discoverPaths
          mapM_
            ( \(budgetLabel, budgetMode, budget) -> do
                let renderedBudget =
                      TextEncoding.decodeUtf8
                        ( renderGeneratedDemoConfigPayload
                            schemaPaths
                            budgetMode
                            singleEngineMachine
                            False
                            budget
                        )
                mapM_
                  ( \alternative ->
                      assert
                        (alternative `Text.isInfixOf` renderedBudget)
                        ( "the rendered "
                            <> budgetLabel
                            <> " payload omits the union alternative "
                            <> Text.unpack alternative
                            <> " that the reflected decoder expects"
                        )
                  )
                  inferenceMemoryBudgetAlternatives
            )
            [ ("host-enforced", AppleSilicon, appleUnitInferenceMemoryBudget),
              ("substrate-enforced", LinuxCpu, linuxCpuUnitInferenceMemoryBudget),
              ("dual-enforced", LinuxGpu, linuxGpuUnitInferenceMemoryBudget)
            ]
        _ -> pure ()

dhallSchemaRequiredFields :: DhallSchema -> [Text.Text]
dhallSchemaRequiredFields schema =
  case schema of
    HostSchema ->
      [ "hostExecutionContext",
        "toolPaths",
        "filesystem",
        "machine",
        "modelCacheQuotaBytes",
        "systemContractDigest",
        "controlPlaneContext"
      ]
    ClusterSchema ->
      [ "pulsar",
        "minio",
        "keycloak",
        "coordinator"
      ]
    SecretsSchema ->
      [ "minio",
        "keycloakAdmin",
        "keycloakDb"
      ]
    SubstrateSchema ->
      [ "runtimeMode",
        "enginePools",
        "members",
        "subscription",
        "models",
        "inferenceMemoryBudget"
      ]

assertUniqueModelIds :: RuntimeMode -> IO ()
assertUniqueModelIds mode = do
  let modelsForMode = catalogForMode mode
      identifiers = map modelId modelsForMode
      matrixRows = map matrixRowId modelsForMode
  assert (length identifiers == length (nub identifiers)) ("catalog model ids are unique for " <> show mode)
  assert (length matrixRows == length (nub matrixRows)) ("catalog matrix rows are unique for " <> show mode)

