-- | Phase 7 Sprint 7.13 QuickCheck-style property generators for
-- arbitrary 'Contracts.ConversationEvent' sequences. The Reducer's
-- invariants must hold regardless of event ordering, idempotency key
-- collisions, or causal-ref shape; the generators below exercise the
-- shapes that matter end-to-end (prompt / cancel / inference-result /
-- user-upload) and the properties assert behaviour on every shrink.
assertConversationPropertyTests :: IO ()
assertConversationPropertyTests = do
  let ctx = Contracts.ContextId "ctx-property"
      seed =
        Contracts.ConversationState
          { Contracts.conversationStateContextId = ctx,
            Contracts.conversationStateMessages = [],
            Contracts.conversationStatePrefixHash =
              ConversationHash.unPrefixHash ConversationHash.emptyPrefixHash
          }
  runProperty
    "patch stream replay converges to snapshot reducer projection on every generated log"
    ( forAll
        genConversationLog
        ( \events ->
            let (_, patches) = ConversationReducer.foldEventsKeepingPatches ctx events
                snapshot = ConversationReducer.snapshotReducer ctx events
                replayed = foldl ConversationReducer.applyPatchToState seed patches
             in replayed == snapshot
        )
    )
  runProperty
    "prefixHash chain is monotonic in length and deterministic"
    ( forAll
        genConversationLog
        ( \events ->
            let chain = ConversationHash.prefixHashChainOver events
                chain2 = ConversationHash.prefixHashChainOver events
             in length chain == length events + 1 && chain == chain2
        )
    )
  runProperty
    "idempotency dedup drops every repeated (contextId, key) inside the same log"
    ( forAll
        genConversationLog
        ( \events ->
            let (_, patches) = ConversationReducer.foldEventsKeepingPatches ctx events
                snapshot = ConversationReducer.snapshotReducer ctx events
                stateMessageCount =
                  length
                    ( foldr
                        (:)
                        []
                        (Contracts.conversationStateMessages snapshot)
                    )
             in length patches == stateMessageCount
        )
    )

runProperty :: (Testable prop) => String -> prop -> IO ()
runProperty label property = do
  result <- quickCheckWithResult stdArgs {maxSize = 16, maxSuccess = 50} property
  case result of
    Success {} -> putStrLn ("property ok: " <> label)
    _ -> ioError (userError ("property failed: " <> label))

-- | Generate a conversation log of bounded length. Each message gets a
-- fresh monotonic-shaped MessageId so the reducer sees an ordering
-- consistent with a real Pulsar topic; cancel and inference-result
-- variants reference an earlier prompt's MessageId so the causal-ref
-- shape exercises the same dispatcher rule the production code path
-- runs.
genConversationLog :: Gen [Contracts.ConversationMessage]
genConversationLog = do
  count <- choose (0, 8)
  -- Each prompt is keyed by index so duplicates collide deterministically.
  let buildPrompt idx =
        Contracts.ConversationMessage
          { Contracts.conversationMessageId =
              Contracts.MessageId (Text.pack ("m-" ++ show idx)),
            Contracts.conversationMessageEvent =
              Contracts.ConversationUserPromptEvent
                Contracts.UserPromptPayload
                  { Contracts.promptText = Text.pack ("prompt-" ++ show idx),
                    Contracts.promptClientIdempotencyKey =
                      Contracts.ClientIdempotencyKey
                        (Text.pack ("idem-" ++ show idx)),
                    Contracts.promptUserUploads = []
                  }
          }
  let prompts = map buildPrompt ([1 .. count] :: [Int])
  -- Optionally interleave cancels / results / duplicates by appending
  -- causal-ref events keyed by prior prompts.
  extras <-
    if null prompts
      then pure []
      else listOf (genCausalEvent prompts)
  pure (prompts ++ extras)

genCausalEvent :: [Contracts.ConversationMessage] -> Gen Contracts.ConversationMessage
genCausalEvent prompts = do
  parent <- elements prompts
  let parentId = Contracts.conversationMessageId parent
  shape <- elements (["cancel", "result", "duplicate"] :: [String])
  case shape of
    "cancel" -> do
      tag <- choose (1, 1000 :: Int)
      pure
        Contracts.ConversationMessage
          { Contracts.conversationMessageId =
              Contracts.MessageId (Text.pack ("c-" ++ show tag)),
            Contracts.conversationMessageEvent =
              Contracts.ConversationCancelEvent
                (Contracts.ConversationCancelPayload parentId)
          }
    "result" -> do
      tag <- choose (1, 1000 :: Int)
      pure
        Contracts.ConversationMessage
          { Contracts.conversationMessageId =
              Contracts.MessageId (Text.pack ("r-" ++ show tag)),
            Contracts.conversationMessageEvent =
              Contracts.ConversationInferenceResultEvent
                Contracts.ConversationInferenceResultPayload
                  { Contracts.inferenceResultUserPromptMessageId = parentId,
                    Contracts.inferenceResultStatus = "Completed",
                    Contracts.inferenceResultInlineOutput = Just "ok",
                    Contracts.inferenceResultError = Nothing,
                    Contracts.inferenceResultArtifacts = []
                  }
          }
    _ -> pure parent

-- Phase 7 Sprint 7.12 — ContextId → modelId map invariants.
assertContextModelMap :: IO ()
assertContextModelMap = do
  contextModelMap <- ContextModelMap.newContextModelMap
  initialSize <- ContextModelMap.contextModelMapSize contextModelMap
  assert
    (initialSize == 0)
    "ContextModelMap starts empty"
  let contextA = Contracts.ContextId "c-a"
      contextB = Contracts.ContextId "c-b"

  ContextModelMap.recordContextModel contextModelMap contextA "llm-smollm2-safetensors"
  ContextModelMap.recordContextModel contextModelMap contextB "image-sdxl-turbo"
  afterDirectInsertSize <- ContextModelMap.contextModelMapSize contextModelMap
  assert
    (afterDirectInsertSize == 2)
    "ContextModelMap records direct (contextId, modelId) inserts"

  resolvedA <- ContextModelMap.lookupModelId contextModelMap contextA
  resolvedB <- ContextModelMap.lookupModelId contextModelMap contextB
  resolvedMissing <- ContextModelMap.lookupModelId contextModelMap (Contracts.ContextId "c-missing")
  assert
    (resolvedA == Just "llm-smollm2-safetensors")
    "ContextModelMap returns the model id for a known context"
  assert
    (resolvedB == Just "image-sdxl-turbo")
    "ContextModelMap returns the model id for the second known context"
  assert
    (isNothing resolvedMissing)
    "ContextModelMap returns Nothing for an unknown context"

  -- ContextCreated event populates the map; ContextRenamed and
  -- ContextSoftDeleted are no-ops for the (contextId, modelId)
  -- binding.
  let createdEvent =
        Contracts.ContextCreated
          { Contracts.contextCreatedContextId = Contracts.ContextId "c-c",
            Contracts.contextCreatedModelId = "llm-tinyllama-gguf",
            Contracts.contextCreatedTitle = "Tiny Chat"
          }
      renamedEvent =
        Contracts.ContextRenamed
          { Contracts.contextRenamedContextId = Contracts.ContextId "c-c",
            Contracts.contextRenamedTitle = "Renamed Tiny Chat"
          }
      softDeletedEvent =
        Contracts.ContextSoftDeleted
          { Contracts.contextSoftDeletedContextId = Contracts.ContextId "c-c"
          }
  ContextModelMap.recordContextMetadataEvent contextModelMap createdEvent
  resolvedAfterCreate <- ContextModelMap.lookupModelId contextModelMap (Contracts.ContextId "c-c")
  assert
    (resolvedAfterCreate == Just "llm-tinyllama-gguf")
    "ContextCreated event populates ContextModelMap"

  ContextModelMap.recordContextMetadataEvent contextModelMap renamedEvent
  resolvedAfterRename <- ContextModelMap.lookupModelId contextModelMap (Contracts.ContextId "c-c")
  assert
    (resolvedAfterRename == Just "llm-tinyllama-gguf")
    "ContextRenamed event does not alter the (contextId, modelId) binding"

  ContextModelMap.recordContextMetadataEvent contextModelMap softDeletedEvent
  resolvedAfterSoftDelete <- ContextModelMap.lookupModelId contextModelMap (Contracts.ContextId "c-c")
  assert
    (resolvedAfterSoftDelete == Just "llm-tinyllama-gguf")
    "ContextSoftDeleted event does not alter the (contextId, modelId) binding"

-- Phase 7 Sprint 7.11 — the server-side artifact download grant uses
-- the same MIME-to-render-disposition matrix as the SPA fallback.
assertArtifactDownloadDispositionMatrix :: IO ()
assertArtifactDownloadDispositionMatrix = do
  let assertDisposition mime expected =
        assert
          (DemoApi.renderDispositionForMime (Contracts.ArtifactMimeType mime) == expected)
          ("artifact download disposition for " <> Text.unpack mime)
  assertDisposition "image/png" Contracts.RenderInline
  assertDisposition "audio/wav" Contracts.RenderInline
  assertDisposition "video/mp4" Contracts.RenderInline
  assertDisposition "application/pdf" Contracts.BrowserNativePdf
  assertDisposition "application/json" Contracts.BoundedTextPreview
  assertDisposition "text/plain" Contracts.BoundedTextPreview
  assertDisposition "audio/midi" Contracts.RenderMidi
  assertDisposition "audio/x-midi" Contracts.RenderMidi
  assertDisposition "application/vnd.recordare.musicxml+xml" Contracts.RenderMusicXml
  assertDisposition "application/vnd.recordare.musicxml" Contracts.RenderMusicXml
  assertDisposition "application/zip" Contracts.RenderZipStems
  assertDisposition "application/octet-stream" Contracts.DownloadOnly

-- Phase 7 Sprint 7.14 — WebSocket client frames publish typed JSON
-- events onto the durable Pulsar topic families.
assertDemoWebSocketPublicationPlanning :: IO ()
assertDemoWebSocketPublicationPlanning = do
  let ns = ConversationTopic.defaultDemoTopicNamespace
      userIdValue = Contracts.UserId "user-a"
      contextIdValue = Contracts.ContextId "ctx-a"
      promptPayload =
        Contracts.UserPromptPayload
          { Contracts.promptText = "hello",
            Contracts.promptClientIdempotencyKey = Contracts.ClientIdempotencyKey "idem-1",
            Contracts.promptUserUploads = []
          }
      promptPublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientSubmitPrompt contextIdValue promptPayload)
      uploadRef =
        Contracts.ObjectRef
          { Contracts.objectBucket = "infernix-demo-objects",
            Contracts.objectKey = "users/user-a/contexts/ctx-a/uploads/browser.png"
          }
      uploadPayload =
        Contracts.ConversationUserUploadPayload
          { Contracts.uploadObjectRef = uploadRef,
            Contracts.uploadMimeType = Contracts.ArtifactMimeType "image/png",
            Contracts.uploadDisplayName = "browser.png"
          }

  case promptPublications of
    [publication] -> do
      assert
        (demoClientPublicationTopic publication == ConversationTopic.conversationTopicName ns userIdValue contextIdValue)
        "ClientSubmitPrompt publishes to the per-context conversation topic"
      assert
        ("frontend-conversation-user-a-ctx-a-" `Text.isPrefixOf` demoClientPublicationProducerName publication)
        "ClientSubmitPrompt scopes the frontend producer by context and mutation key"
      assert
        (demoClientPublicationSequenceKey publication == "idem-1")
        "ClientSubmitPrompt uses the client idempotency key as the dedup sequence key"
      assert
        (isNothing (demoClientPublicationMessageKey publication))
        "ClientSubmitPrompt does not set a compaction key on the append-only conversation topic"
      assert
        (decodeLazy (demoClientPublicationPayload publication) == Right (Contracts.ConversationUserPromptEvent promptPayload))
        "ClientSubmitPrompt payload is a ConversationUserPromptEvent"
    _ -> assert False "ClientSubmitPrompt creates exactly one publication"

  let uploadPublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientRecordUpload contextIdValue uploadPayload)
  case uploadPublications of
    [publication] -> do
      assert
        (demoClientPublicationTopic publication == ConversationTopic.conversationTopicName ns userIdValue contextIdValue)
        "ClientRecordUpload publishes to the per-context conversation topic"
      assert
        ("frontend-conversation-user-a-ctx-a-" `Text.isPrefixOf` demoClientPublicationProducerName publication)
        "ClientRecordUpload scopes the frontend producer by context and uploaded object key"
      assert
        (demoClientPublicationSequenceKey publication == "upload:infernix-demo-objects:users/user-a/contexts/ctx-a/uploads/browser.png")
        "ClientRecordUpload deduplicates by uploaded object ref"
      assert
        (decodeLazy (demoClientPublicationPayload publication) == Right (Contracts.ConversationUserUploadEvent uploadPayload))
        "ClientRecordUpload payload is a ConversationUserUploadEvent"
    _ -> assert False "ClientRecordUpload creates exactly one publication"

  let createPublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientCreateContext contextIdValue "llm-smollm2-safetensors" "Research")
  case createPublications of
    [publication] -> do
      assert
        (demoClientPublicationTopic publication == ConversationTopic.contextsMetadataTopicName ns userIdValue)
        "ClientCreateContext publishes to the per-user contexts metadata topic"
      assert
        ("frontend-contexts-user-a-" `Text.isPrefixOf` demoClientPublicationProducerName publication)
        "ClientCreateContext scopes the contexts producer by user and mutation key"
      assert
        (demoClientPublicationMessageKey publication == Just (Contracts.unContextId contextIdValue))
        "ClientCreateContext keys the compacted contexts topic by context id"
      assert
        (demoClientPublicationSequenceKey publication == "ctx-a:create:llm-smollm2-safetensors:Research")
        "ClientCreateContext uses an event-specific sequence key so later context updates are not deduplicated"
      assert
        ( decodeLazy (demoClientPublicationPayload publication)
            == Right
              ( Contracts.ContextCreated
                  { Contracts.contextCreatedContextId = contextIdValue,
                    Contracts.contextCreatedModelId = "llm-smollm2-safetensors",
                    Contracts.contextCreatedTitle = "Research"
                  }
              )
        )
        "ClientCreateContext payload is a ContextCreated event"
    _ -> assert False "ClientCreateContext creates exactly one publication"

  case catalogForMode LinuxGpu of
    knownModel : activeCatalogTail -> do
      let activeCatalog = knownModel : activeCatalogTail
          validCreate =
            Contracts.ClientCreateContext
              contextIdValue
              (modelId knownModel)
              "Known model"
          invalidModelId = "not-in-active-catalog"
          invalidCreate =
            Contracts.ClientCreateContext
              contextIdValue
              invalidModelId
              "Unknown model"
      assert
        (validateDemoClientMessageCatalog activeCatalog validCreate == Right ())
        "ClientCreateContext accepts model ids from the active catalog"
      case validateDemoClientMessageCatalog activeCatalog invalidCreate of
        Left DemoClientMessageError {demoClientMessageErrorCode = errorCode, demoClientMessageErrorMessage = errorMessage} -> do
          assert (errorCode == "unknown-model") "unknown ClientCreateContext model ids use the typed error code"
          assert (invalidModelId `Text.isInfixOf` errorMessage) "unknown ClientCreateContext model error names the rejected model id"
        Right () -> assert False "ClientCreateContext rejects model ids outside the active catalog"
    [] -> assert False "linux-gpu active catalog is non-empty"

  let renamePublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientRenameContext contextIdValue "Renamed")
  case renamePublications of
    [publication] -> do
      assert
        (demoClientPublicationTopic publication == ConversationTopic.contextsMetadataTopicName ns userIdValue)
        "ClientRenameContext publishes to the per-user contexts metadata topic"
      assert
        ("frontend-contexts-user-a-" `Text.isPrefixOf` demoClientPublicationProducerName publication)
        "ClientRenameContext scopes the contexts producer by user and mutation key"
      assert
        (demoClientPublicationMessageKey publication == Just (Contracts.unContextId contextIdValue))
        "ClientRenameContext keeps the context id as the compaction key"
      assert
        (demoClientPublicationSequenceKey publication == "ctx-a:rename:Renamed")
        "ClientRenameContext uses an event-specific sequence key distinct from create"
      assert
        ( decodeLazy (demoClientPublicationPayload publication)
            == Right (Contracts.ContextRenamed contextIdValue "Renamed")
        )
        "ClientRenameContext payload is a ContextRenamed event"
    _ -> assert False "ClientRenameContext creates exactly one publication"

  let draftPublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientUpdateDraft contextIdValue "draft text")
  case draftPublications of
    [publication] -> do
      assert
        (demoClientPublicationTopic publication == ConversationTopic.draftsMetadataTopicName ns userIdValue)
        "ClientUpdateDraft publishes to the per-user drafts metadata topic"
      assert
        ("frontend-drafts-user-a-" `Text.isPrefixOf` demoClientPublicationProducerName publication)
        "ClientUpdateDraft scopes the drafts producer by user and mutation key"
      assert
        (demoClientPublicationMessageKey publication == Just (Contracts.unContextId contextIdValue))
        "ClientUpdateDraft keys the compacted drafts topic by context id"
      assert
        ( decodeLazy (demoClientPublicationPayload publication)
            == Right (Contracts.DraftUpdated contextIdValue "draft text")
        )
        "ClientUpdateDraft payload is a DraftUpdated event"
    _ -> assert False "ClientUpdateDraft creates exactly one publication"

  let clearDraftPublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientUpdateDraft contextIdValue "")
  case clearDraftPublications of
    [publication] -> do
      assert
        (demoClientPublicationSequenceKey publication == "ctx-a:clear")
        "empty ClientUpdateDraft uses an explicit draft-clear sequence key"
      assert
        ( decodeLazy (demoClientPublicationPayload publication)
            == Right (Contracts.DraftCleared contextIdValue)
        )
        "empty ClientUpdateDraft payload is a DraftCleared event"
    _ -> assert False "empty ClientUpdateDraft creates exactly one publication"

  let cancelPublications =
        planDemoClientMessagePublications
          ns
          userIdValue
          (Contracts.ClientCancelPrompt contextIdValue (Contracts.MessageId "prompt-1"))
  case cancelPublications of
    [publication] ->
      assert
        ( decodeLazy (demoClientPublicationPayload publication)
            == Right (Contracts.ConversationCancelEvent (Contracts.ConversationCancelPayload (Contracts.MessageId "prompt-1")))
        )
        "ClientCancelPrompt payload is a ConversationCancelEvent"
    _ -> assert False "ClientCancelPrompt creates exactly one publication"

  assert
    (null (planDemoClientMessagePublications ns userIdValue (Contracts.ClientHello userIdValue)))
    "ClientHello does not publish a durable event"
  assert
    (null (planDemoClientMessagePublications ns userIdValue (Contracts.ClientSubscribeContext contextIdValue)))
    "ClientSubscribeContext does not publish a durable event"

decodeLazy :: (Aeson.FromJSON a) => Lazy.ByteString -> Either String a
decodeLazy = Aeson.eitherDecode

-- Phase 1 Sprint 1.11 — HostConfig roundtrip + HostTools resolution.
assertHostConfig :: FilePath -> FilePath -> IO ()
assertHostConfig repoRootPath testRoot = do
  let appleConfig = HostConfig.defaultAppleHostNativeHostConfig "/Users/operator/infernix" "/Users/operator"
      linuxConfig = HostConfig.defaultLinuxOuterContainerHostConfig "/root"
      linuxArmConfig = HostConfig.defaultLinuxOuterContainerHostConfigForArchitecture "/root" "aarch64"
      linuxMaterializationPaths =
        Paths
          { repoRoot = testRoot,
            buildRoot = testRoot </> ".build",
            dataRoot = testRoot </> ".data",
            runtimeRoot = testRoot </> ".data" </> "runtime",
            kindRoot = testRoot </> ".data" </> "kind",
            helmConfigRoot = testRoot </> ".data" </> "helm" </> "config",
            helmCacheRoot = testRoot </> ".data" </> "helm" </> "cache",
            helmDataRoot = testRoot </> ".data" </> "helm" </> "data",
            resultsRoot = testRoot </> ".data" </> "results",
            modelCacheRoot = testRoot </> ".data" </> "model-cache",
            pathsHostConfig = Just linuxConfig,
            pathsHostConfigPath = Nothing
          }
  assert
    (HostConfig.hostExecutionContext appleConfig == HostConfig.AppleHostNative)
    "default Apple host config reports the Apple host-native execution context"
  assert
    (HostConfig.hostArchitecture appleConfig == "arm64")
    "default Apple host config records the native arm64 architecture"
  assert
    (HostConfig.hostExecutionContext linuxConfig == HostConfig.LinuxOuterContainer)
    "default Linux host config reports the Linux outer-container execution context"
  assert
    (HostConfig.hostArchitecture linuxArmConfig == "arm64")
    "Linux host config normalizes aarch64 fixtures to the Docker arm64 architecture"
  assert
    (HostTools.hostToolPath linuxConfig HostTools.HostDocker == "/usr/bin/docker")
    "HostTools resolves docker by absolute path on Linux"
  assert
    (Text.unpack (HostTools.hostToolPath appleConfig HostTools.HostBrew) == "/opt/homebrew/bin/brew")
    "HostTools resolves brew by Homebrew absolute path on Apple"
  assert
    ( Text.unpack (HostTools.hostToolPath appleConfig HostTools.HostPoetry)
        == "/Users/operator/.local/share/pypoetry/venv/bin/poetry"
    )
    "HostTools resolves Poetry from the typed user-local bootstrap root on Apple"
  assert
    ( HostTools.hostToolPath appleConfig HostTools.HostPython3
        == "/opt/homebrew/bin/python3.12"
        && HostTools.hostToolPath appleConfig HostTools.HostPython311
          == "/opt/homebrew/bin/python3.11"
    )
    "HostTools keeps the general Python 3.12 and Core ML Python 3.11 paths distinct on Apple"
  assert
    (HostTools.hostToolPath linuxConfig HostTools.HostPython311 == "")
    "HostTools marks the Core ML Python 3.11 tool unavailable in the Linux outer-container"
  assert
    ( HostTools.hostToolPath appleConfig HostTools.HostLlamaCompletion
        == "/opt/homebrew/bin/llama-completion"
        && HostTools.hostToolPath appleConfig HostTools.HostWhisperCli
          == "/opt/homebrew/bin/whisper-cli"
    )
    "HostTools resolves both Apple native engine CLIs from explicit Homebrew paths"
  assert
    ( HostTools.hostToolPath linuxConfig HostTools.HostLlamaCompletion == ""
        && HostTools.hostToolPath linuxConfig HostTools.HostWhisperCli == ""
    )
    "HostTools marks Apple native engine CLIs unavailable in the Linux outer-container"
  assert
    (HostTools.hostToolPath appleConfig HostTools.HostAptGet == "")
    "HostTools returns empty path for tools unavailable in the active context"
  assert
    ( "/root/.ghcup/bin/cabal" `elem` HostTools.hostToolFallbackCandidates HostTools.HostCabal
        && "/root/.ghcup/bin/ghc" `elem` HostTools.hostToolFallbackCandidates HostTools.HostGhc
        && "/opt/homebrew/bin/python3.11" `elem` HostTools.hostToolFallbackCandidates HostTools.HostPython311
        && "/opt/homebrew/bin/llama-completion" `elem` HostTools.hostToolFallbackCandidates HostTools.HostLlamaCompletion
        && "/opt/homebrew/bin/whisper-cli" `elem` HostTools.hostToolFallbackCandidates HostTools.HostWhisperCli
        && "/opt/homebrew/bin/poetry" `elem` HostTools.hostToolFallbackCandidates HostTools.HostPoetry
    )
    "HostTools fallback candidates include the supported Linux ghcup and Apple Homebrew paths"
  let poetryBootstrapRequirements =
        Provisioning.pinnedPoetryBootstrapRequirementSpecs
      poetryBootstrapPackage =
        takeWhile (/= '=')
      validPoetryBootstrapRequirement requirement =
        case words requirement of
          [packageVersion, hashArgument] ->
            not (null (poetryBootstrapPackage packageVersion))
              && "==" `isInfixOf` packageVersion
              && length hashArgument == 78
              && "--hash=sha256:" `isPrefixOf` hashArgument
              && all
                (\character -> isHexDigit character && not (isUpper character))
                (drop 14 hashArgument)
          _ -> False
  assert
    ( Provisioning.pinnedPipRequirementSpec
        == ArtifactRecipe.pinnedPipRequirement
        && length poetryBootstrapRequirements == 45
        && all validPoetryBootstrapRequirement poetryBootstrapRequirements
        && length
          (nub (map poetryBootstrapPackage poetryBootstrapRequirements))
          == length poetryBootstrapRequirements
        && "pip==25.1.1 --hash=sha256:2913a38a2abf4ea6b64ab507bd9e967f3b53dc1ede74b01b0931e1ce548751af"
          `elem` poetryBootstrapRequirements
        && "poetry==2.4.1 --hash=sha256:a91f13279a3c9add0d12c5ca5c7cb173622930a5c8272fee68c751cb5c72f951"
          `elem` poetryBootstrapRequirements
        && and
          [ Provisioning.pinnedPythonRequirementSpecs provisioningAdapter
              == ArtifactRecipe.pinnedPythonRequirements recipe
          | (provisioningAdapter, recipe) <-
              [ ( Provisioning.ctranslate2PythonAdapter,
                  ArtifactRecipe.CTranslate2PythonRecipe
                ),
                ( Provisioning.onnxRuntimePythonAdapter,
                  ArtifactRecipe.OnnxRuntimePythonRecipe
                ),
                ( Provisioning.mlxPythonAdapter,
                  ArtifactRecipe.MlxPythonRecipe
                ),
                ( Provisioning.coreMlPythonAdapter,
                  ArtifactRecipe.CoreMlPythonRecipe
                )
              ]
          ]
        && Provisioning.audiverisPinnedVersion
          == ArtifactRecipe.audiverisVersion
        && Provisioning.audiverisPinnedDmgFileName
          == ArtifactRecipe.audiverisDmgFileName
        && Provisioning.audiverisPinnedDmgUrl
          == ArtifactRecipe.audiverisDmgUrl
    )
    "Sprint 1.20: provisioner commands and artifact fingerprints share one exact recipe catalog"
  -- Phase 1 Sprint 1.14 — the allowlisted Apple headless artifact
  -- plan uses runtime adapter ids and typed manifests, not a Tart VM.
  assert
    ( metalEngineArtifactAdapterIds
        == [ "llama-cpp-cli",
             "whisper-cpp-cli",
             "coreml-native",
             "ctranslate2-native",
             "mlx-native",
             "onnx-runtime-native",
             "jvm-native"
           ]
    )
    "Sprint 1.20: the Apple materialization plan uses runtime adapter ids without a repo-owned native bridge"
  assert
    (all (\artifact -> "tart" `notElem` Text.words (Text.toLower (metalEngineSourceRef artifact))) metalEngineBuildPlan)
    "Sprint 1.14: the Apple materialization plan carries no Tart source reference"
  case listToMaybe metalEngineBuildPlan of
    Nothing ->
      assert False "Sprint 1.14: the Apple materialization plan is non-empty"
    Just sampleArtifact -> do
      let sampleInstallRoot = testRoot </> ".data" </> "engines" </> Text.unpack (metalEngineAdapterId sampleArtifact)
          sampleDigest = "sha256:" <> Text.replicate 64 "a"
          sampleProvenance =
            [ EngineArtifact.ResolvedArtifactProvenance
                { EngineArtifact.resolvedProvenanceName = "sample-runtime",
                  EngineArtifact.resolvedProvenanceVersion = "1.2.3",
                  EngineArtifact.resolvedProvenanceSource = "upstream:test"
                }
            ]
      sampleManifest <-
        either
          (fail . ("Sprint 1.20: hydrated Apple manifest recipe resolution failed: " <>))
          pure
          ( AppleSiliconInternal.manifestForHydratedMetalEngineArtifact
              sampleInstallRoot
              sampleArtifact
              "1.2.3"
              (Just "Python 3.12.11")
              "runtime-1.2.3"
              sampleProvenance
              sampleDigest
          )
      let sampleManifestJson = renderEngineArtifactManifest sampleManifest
          sampleManifestText = TextEncoding.decodeUtf8 (Lazy.toStrict sampleManifestJson)
      assert
        (manifestAdapterId sampleManifest == metalEngineAdapterId sampleArtifact)
        "Sprint 1.20: hydrated manifest rendering preserves the adapter id"
      assert
        (manifestDigest sampleManifest == sampleDigest)
        "Sprint 1.20: hydrated manifest records the actual payload-tree digest"
      assert
        ("sha256:" `Text.isPrefixOf` manifestRecipeFingerprint sampleManifest)
        "Sprint 1.20: the public Apple manifest facade exposes its closed recipe fingerprint"
      assert
        ( "sha256:"
            `Text.isPrefixOf` manifestTargetContractFingerprint sampleManifest
            && isNothing (manifestImageTargetEvidence sampleManifest)
        )
        "architectural correction: Apple manifests bind an installed direct target, not image evidence"
      assert
        ("\"artifactKind\"" `isInfixOf` Text.unpack sampleManifestText)
        "Sprint 1.14: manifest JSON records artifactKind"
      assert
        ( "\"targetContractFingerprint\""
            `isInfixOf` Text.unpack sampleManifestText
            && "\"imageTargetEvidence\":null"
              `isInfixOf` Text.unpack sampleManifestText
            && not
              ("\"smokeCommand\"" `isInfixOf` Text.unpack sampleManifestText)
        )
        "architectural correction: manifest JSON records the closed direct target without a shell command"
      assert
        ("\"minioObjectKey\"" `isInfixOf` Text.unpack sampleManifestText)
        "Sprint 1.14: manifest JSON records the content-addressed MinIO key"
      assert
        ("\"resolvedProvenance\"" `isInfixOf` Text.unpack sampleManifestText)
        "Sprint 1.20: manifest JSON records exact resolved provenance"
      assert
        ("\"recipeFingerprint\"" `isInfixOf` Text.unpack sampleManifestText)
        "Sprint 1.20: manifest JSON records the recipe fingerprint"
      assert
        (either (const False) (const True) (decodeLazy sampleManifestJson :: Either String Aeson.Value))
        "Sprint 1.14: manifest JSON decodes as valid Aeson"
  assert
    ( linuxNativeEngineArtifactAdapterIds
        == [ "llama-cpp-cli",
             "whisper-cpp-cli",
             "onnx-runtime-native",
             "ctranslate2-native",
             "jvm-native"
           ]
    )
    "Sprint 4.18: the Linux native materialization plan covers the runnable Linux native adapter ids"
  let linuxArchitecture =
        case System.Info.arch of
          "x86_64" -> "amd64"
          "aarch64" -> "arm64"
          other -> Text.pack other
      catalogTarget adapterId = do
        identity <-
          maybe
            (fail ("closed native identity omitted " <> Text.unpack adapterId))
            pure
            (EngineArtifact.parseNativeArtifactIdentity adapterId)
        expectRight
          ("resolve Linux direct target for " <> Text.unpack adapterId)
          (ArtifactTarget.nativeArtifactTarget identity "linux-native" linuxArchitecture)
      catalogInstallRoot adapterId =
        testRoot </> "linux-native-engines" </> Text.unpack adapterId
  llamaTarget <- catalogTarget "llama-cpp-cli"
  whisperTarget <- catalogTarget "whisper-cpp-cli"
  onnxTarget <- catalogTarget "onnx-runtime-native"
  jvmTarget <- catalogTarget "jvm-native"
  appleJvmIdentity <-
    maybe
      (fail "closed native identity omitted jvm-native")
      pure
      (EngineArtifact.parseNativeArtifactIdentity "jvm-native")
  appleJvmTarget <-
    expectRight
      "resolve Apple Audiveris direct target"
      (ArtifactTarget.nativeArtifactTarget appleJvmIdentity "apple-silicon" "arm64")
  let llamaExecutable =
        ArtifactTarget.nativeArtifactTargetExecutable
          (catalogInstallRoot "llama-cpp-cli")
          llamaTarget
      whisperExecutable =
        ArtifactTarget.nativeArtifactTargetExecutable
          (catalogInstallRoot "whisper-cpp-cli")
          whisperTarget
      onnxExecutable =
        ArtifactTarget.nativeArtifactTargetExecutable
          (catalogInstallRoot "onnx-runtime-native")
          onnxTarget
      jvmExecutable =
        ArtifactTarget.nativeArtifactTargetExecutable
          (catalogInstallRoot "jvm-native")
          jvmTarget
      onnxPrefix =
        ArtifactTarget.nativeArtifactTargetLeadingArguments
          (catalogInstallRoot "onnx-runtime-native")
          "ONNX Runtime Linux runner"
          onnxTarget
      jvmPrefix =
        ArtifactTarget.nativeArtifactTargetLeadingArguments
          (catalogInstallRoot "jvm-native")
          "Audiveris JVM Linux runner"
          jvmTarget
      appleJvmRoot = testRoot </> "apple-engines" </> "jvm-native"
      appleJvmExecutable =
        ArtifactTarget.nativeArtifactTargetExecutable appleJvmRoot appleJvmTarget
      appleJvmPrefix =
        ArtifactTarget.nativeArtifactTargetLeadingArguments
          appleJvmRoot
          "Audiveris JVM Apple runner"
          appleJvmTarget
  assert
    ( llamaExecutable
        == "/opt/infernix/native-payloads/llama.cpp/llama-b9704/llama-completion"
        && null
          ( ArtifactTarget.nativeArtifactTargetLeadingArguments
              (catalogInstallRoot "llama-cpp-cli")
              "llama.cpp Linux runner"
              llamaTarget
          )
        && ArtifactTarget.nativeArtifactTargetImmutableClosureRoots
          (catalogInstallRoot "llama-cpp-cli")
          llamaTarget
          == ["/opt/infernix/native-payloads/llama.cpp/llama-b9704"]
    )
    "architectural correction: Linux llama execution is a fixed direct image target and closure"
  assert
    ( ( if linuxArchitecture == "amd64"
          then "whisper-bin-ubuntu-x64"
          else "whisper-bin-ubuntu-arm64"
      )
        `isInfixOf` whisperExecutable
    )
    "architectural correction: whisper selects exactly the host-architecture image target"
  assert
    ( onnxExecutable == "/opt/infernix/native-python/bin/python"
        && take 1 onnxPrefix
          == ["/workspace/python/native-runners/apple_native_runner.py"]
        && "--adapter-id" `elem` onnxPrefix
        && "onnx-runtime-native" `elem` onnxPrefix
    )
    "architectural correction: Linux Python adapters use the fixed interpreter and closed runner prefix"
  assert
    ( jvmExecutable == "/opt/infernix/audiveris-jre/bin/java"
        && jvmPrefix
          == [ "-Dorg.bytedeco.javacpp.cachedir=/opt/infernix/audiveris-javacpp-cache",
               "-Dorg.bytedeco.javacpp.canCreateSymbolicLink=false",
               "-cp",
               "/opt/audiveris/lib/app/*",
               "Audiveris"
             ]
    )
    "architectural correction: Audiveris uses the fixed image JRE and classpath"
  assert
    ( appleJvmExecutable
        == appleJvmRoot
          </> "Audiveris.app"
          </> "Contents"
          </> "runtime"
          </> "Contents"
          </> "Home"
          </> "bin"
          </> "java"
        && appleJvmPrefix
          == [ "-Dorg.bytedeco.javacpp.cachedir=" <> (appleJvmRoot </> "javacpp-cache"),
               "-Dorg.bytedeco.javacpp.canCreateSymbolicLink=false",
               "-cp",
               appleJvmRoot </> "Audiveris.app" </> "Contents" </> "app" </> "*",
               "Audiveris"
             ]
    )
    "Sprint 1.20: Apple Audiveris uses its bundled JVM and its own symlink-free JavaCPP cache"
  assert
    ( all
        (Text.isPrefixOf "sha256:" . ArtifactTarget.nativeArtifactTargetFingerprint)
        [llamaTarget, whisperTarget, onnxTarget, jvmTarget]
    )
    "architectural correction: every direct target has a stable closed-contract fingerprint"
  assert
    ( HostTools.hostToolName HostTools.HostKubectl == "kubectl"
        && HostTools.hostToolName HostTools.HostPython311 == "python3.11"
        && HostTools.hostToolName HostTools.HostLlamaCompletion == "llama-completion"
        && HostTools.hostToolName HostTools.HostWhisperCli == "whisper-cli"
    )
    "HostTools reports the supported short name for each tool, including the pinned Apple engine tools"
  -- Round-trip through the renderer + decoder so the materialization
  -- path stays mechanically self-consistent.
  let hostManifestRoot = testRoot </> "host-manifest"
      hostManifestPath = hostManifestRoot </> "infernix-host.dhall"
      generatedPolicyManifestPath =
        hostManifestRoot </> "infernix-host-generated-policies.dhall"
      boundedTransientPolicy =
        HostConfig.DhallCommandPolicy
          { HostConfig.dhallTimeoutMicros = 9000000,
            HostConfig.dhallRetry =
              HostConfig.Bounded
                HostConfig.DhallBoundedRetry
                  { HostConfig.dhallAttempts = 3,
                    HostConfig.dhallBackoffMicros = 5000
                  },
            HostConfig.dhallFailureClass = HostConfig.TransientThenFatal
          }
      generatedPolicies =
        HostConfig.defaultDhallCommandPolicies
          { HostConfig.dhallKindRead = boundedTransientPolicy
          }
      generatedPolicyConfig =
        linuxConfig
          { HostConfig.hostCommandPolicies = generatedPolicies
          }
      renderedPolicies =
        HostConfig.renderDhallCommandPolicies generatedPolicies
      renderedPolicyAlternatives =
        [ ">.Never",
          ">.Bounded { attempts = 3, backoffMicros = 5000 }",
          ">.Fatal",
          ">.TransientThenFatal",
          ">.IdempotentAbsence"
        ]
  createDirectoryIfMissing True hostManifestRoot
  writeFile hostManifestPath (HostConfig.renderHostConfig linuxConfig)
  decoded <- HostConfig.decodeHostConfigFile hostManifestPath
  assert
    (decoded == linuxConfig)
    "HostConfig round-trip through renderHostConfig + decodeHostConfigFile preserves every field"
  assert
    (all (`isInfixOf` renderedPolicies) renderedPolicyAlternatives)
    "generated command-policy rendering covers both retry arms and every failure-class alternative"
  writeFile
    generatedPolicyManifestPath
    (HostConfig.renderHostConfig generatedPolicyConfig)
  decodedGeneratedPolicyConfig <-
    HostConfig.decodeHostConfigFile generatedPolicyManifestPath
  assert
    (decodedGeneratedPolicyConfig == generatedPolicyConfig)
    "generated command policies round-trip through the HostConfig renderer and Dhall decoder"
  hostConfigSchema <-
    expectRight
      "reflect generated HostConfig schema"
      HostConfig.renderHostConfigSchema
  assert
    ( all
        (`Text.isInfixOf` hostConfigSchema)
        [ "commandPolicies",
          "retry",
          "Never",
          "Bounded",
          "attempts",
          "backoffMicros",
          "failureClass",
          "Fatal",
          "TransientThenFatal",
          "IdempotentAbsence"
        ]
    )
    "reflected HostConfig schema exposes the proper retry and failure-class unions"
  let appleRunnerLibraryPath =
        repoRootPath
          </> "python"
          </> "native-runners"
          </> "apple_native_runner.py"
  appleRunnerLibrary <- readFile appleRunnerLibraryPath
  case find ((== "coreml-native") . metalEngineAdapterId) metalEngineBuildPlan of
    Nothing ->
      assert False "Sprint 1.20: the Apple materialization plan includes coreml-native"
    Just coreMlArtifact -> do
      coreMlIdentity <-
        maybe
          (fail "closed native identity omitted coreml-native")
          pure
          (EngineArtifact.parseNativeArtifactIdentity "coreml-native")
      coreMlTarget <-
        expectRight
          "resolve Apple Core ML direct target"
          ( ArtifactTarget.nativeArtifactTarget
              coreMlIdentity
              "apple-silicon"
              "arm64"
          )
      let coreMlInstallRoot =
            testRoot </> "apple-engines" </> "coreml-native"
          coreMlExecutable =
            ArtifactTarget.nativeArtifactTargetExecutable
              coreMlInstallRoot
              coreMlTarget
          coreMlPrefix =
            ArtifactTarget.nativeArtifactTargetLeadingArguments
              coreMlInstallRoot
              "Core ML native runner"
              coreMlTarget
      assert
        ( coreMlExecutable
            == coreMlInstallRoot </> "venv" </> "bin" </> "infernix-python"
            && take 1 coreMlPrefix
              == [coreMlInstallRoot </> "lib" </> "apple_native_runner.py"]
            && "--adapter-id" `elem` coreMlPrefix
            && metalEngineAdapterId coreMlArtifact
              `elem` map Text.pack coreMlPrefix
            && not ("clang" `isInfixOf` appleRunnerLibrary)
        )
        "architectural correction: Core ML directly executes the artifact interpreter and fixed upstream-package runner"
      assert
        ( "MLModel.get_available_compute_devices" `isInfixOf` appleRunnerLibrary
            && "mx.set_default_device(mx.gpu)" `isInfixOf` appleRunnerLibrary
            && "mx.eval(observed)" `isInfixOf` appleRunnerLibrary
            && "mx.synchronize()" `isInfixOf` appleRunnerLibrary
        )
        "Sprint 1.20: public Core ML observation and synchronized MLX GPU execution replace the native bridge"
      assert
        ( "from python_coreml_stable_diffusion import pipeline"
            `isInfixOf` appleRunnerLibrary
            && "model_version=\"runwayml/stable-diffusion-v1-5\""
              `isInfixOf` appleRunnerLibrary
            && "compute_unit=\"CPU_AND_GPU\"" `isInfixOf` appleRunnerLibrary
            && "pipeline.main(pipeline_args)" `isInfixOf` appleRunnerLibrary
            && "\"Core ML Stable Diffusion\"" `isInfixOf` appleRunnerLibrary
        )
        "Sprint 1.20: Core ML Stable Diffusion runs the upstream pipeline in process and fails closed on empty output"
  case find ((== "llama-cpp-cli") . metalEngineAdapterId) metalEngineBuildPlan of
    Nothing ->
      assert False "Sprint 1.20: the Apple materialization plan includes llama-cpp-cli"
    Just _llamaArtifact -> do
      llamaIdentity <-
        maybe
          (fail "closed native identity omitted llama-cpp-cli")
          pure
          (EngineArtifact.parseNativeArtifactIdentity "llama-cpp-cli")
      appleLlamaTarget <-
        expectRight
          "resolve Apple llama direct target"
          ( ArtifactTarget.nativeArtifactTarget
              llamaIdentity
              "apple-silicon"
              "arm64"
          )
      let llamaInstallRoot =
            testRoot </> "apple-engines" </> "llama-cpp-cli"
      assert
        ( ArtifactTarget.nativeArtifactTargetExecutable
            llamaInstallRoot
            appleLlamaTarget
            == llamaInstallRoot </> "native" </> "bin" </> "llama-completion"
            && null
              ( ArtifactTarget.nativeArtifactTargetLeadingArguments
                  llamaInstallRoot
                  "llama.cpp Metal"
                  appleLlamaTarget
              )
            && ArtifactTarget.nativeArtifactTargetImmutableClosureRoots
              llamaInstallRoot
              appleLlamaTarget
              == [llamaInstallRoot </> "."]
        )
        "architectural correction: Apple llama directly executes the retained artifact binary"
      assert
        ( "inference must use Haskell direct-target supervision"
            `isInfixOf` appleRunnerLibrary
            && "smoke must use Haskell direct-target supervision"
              `isInfixOf` appleRunnerLibrary
            && not ("native-validation" `isInfixOf` appleRunnerLibrary)
            && not ("infernix_emit_validation_result" `isInfixOf` appleRunnerLibrary)
        )
        "architectural correction: the Python runner rejects CLI/JVM bypasses of direct Haskell supervision"
  case AppleSiliconInternal.parseResolvedPythonProvenance
    "coremltools==9.0\npython-coreml-stable-diffusion @ git+https://github.com/apple/ml-stable-diffusion.git@e12202c1f6405b83918b58a5d097cd61e3e1f702\n" of
    Left failure ->
      fail ("Sprint 1.20 provenance parser rejected exact pins: " <> failure)
    Right provenance ->
      assert
        (length provenance == 2)
        "Sprint 1.20: Python provenance parser records exact package and source versions"
  let relocationRoot =
        dataRoot linuxMaterializationPaths
          </> "engines"
          </> "apple-venv-relocation"
      relocationTempRoot = relocationRoot <> ".tmp"
      relocationBinRoot = relocationTempRoot </> "venv" </> "bin"
      relocationConfigPath = relocationTempRoot </> "venv" </> "pyvenv.cfg"
      relocationScriptPath = relocationBinRoot </> "engine-tool"
      residualPath = relocationTempRoot </> "venv" </> "lib" </> "residual.pth"
      relocationPythonHomeBin =
        relocationTempRoot </> "python-home" </> "bin"
      relocationCandidateInterpreter =
        relocationPythonHomeBin </> "python3.12"
      relocationSourceHome =
        "/opt/homebrew/opt/python@3.12/Frameworks/Python.framework/Versions/3.12/bin"
      relocationSourceExecutable =
        relocationSourceHome </> "python3.12"
  createDirectoryIfMissing True (takeDirectory residualPath)
  createDirectoryIfMissing True relocationBinRoot
  createDirectoryIfMissing True relocationPythonHomeBin
  writeFile relocationCandidateInterpreter "#!/bin/sh\nexit 0\n"
  interpreterPermissions <- getPermissions relocationCandidateInterpreter
  setPermissions
    relocationCandidateInterpreter
    interpreterPermissions {executable = True}
  writeFile
    relocationScriptPath
    ("#!" <> relocationTempRoot </> "venv" </> "bin" </> "python" <> "\n")
  writeFile
    relocationConfigPath
    ( "home = "
        <> relocationSourceHome
        <> "\nexecutable = "
        <> relocationSourceExecutable
        <> "\ncommand = "
        <> relocationSourceExecutable
        <> " -m venv --copies "
        <> (relocationTempRoot </> "venv")
        <> "\n"
    )
  relocationEnvironment <-
    Subprocess.clusterSubprocessEnv linuxMaterializationPaths
  let relocateFixture =
        Provisioning.withEngineProvisioningSession
          linuxMaterializationPaths
          (dataRoot linuxMaterializationPaths </> "engines")
          relocationEnvironment
          ( \writer _grant ->
              Provisioning.provisioningRelocateCandidateVenv
                writer
                relocationRoot
                relocationTempRoot
          )
  relocateFixture
  relocatedScript <- readFile relocationScriptPath
  relocatedConfig <- readFile relocationConfigPath
  assert
    ( relocationRoot `isInfixOf` relocatedScript
        && relocationRoot `isInfixOf` relocatedConfig
        && not (relocationTempRoot `isInfixOf` relocatedScript)
        && not (relocationTempRoot `isInfixOf` relocatedConfig)
    )
    "Sprint 1.20: candidate venv paths are rewritten to the final sibling root before smoke and hashing"
  assert
    ( ("home = " <> relocationRoot </> "python-home" </> "bin")
        `isInfixOf` relocatedConfig
        && ( "executable = "
               <> relocationRoot
               </> "python-home"
               </> "bin"
               </> "python3.12"
           )
          `isInfixOf` relocatedConfig
        && not ("/opt/homebrew" `isInfixOf` relocatedConfig)
    )
    "Sprint 1.20: pyvenv.cfg names the artifact-local Python home and retains no source runtime path"
  writeFile residualPath ("residual=" <> relocationTempRoot)
  residualResult <-
    try relocateFixture ::
      IO (Either IOError ())
  assert
    (isLeft residualResult)
    "Sprint 1.20: candidate relocation fails closed when any temp-root byte sequence remains"
  writeFile residualPath ("residual=" <> relocationSourceHome)
  sourceResidualResult <-
    try relocateFixture ::
      IO (Either IOError ())
  removeFile residualPath
  assert
    (isLeft sourceResidualResult)
    "Sprint 1.20: candidate relocation fails closed when any source Python runtime path remains"
  let relocationByteBound =
        Provisioning.relocationCandidateByteBoundForTest
  assert
    ( relocationByteBound == 4 * 1024 * 1024 * 1024
        && Provisioning.validateRelocationCandidateByteSequenceForTest
          [1, relocationByteBound - 1]
          == Right relocationByteBound
        && isLeft
          ( Provisioning.validateRelocationCandidateByteSequenceForTest
              [relocationByteBound, 1]
          )
        && isLeft
          ( Provisioning.validateRelocationCandidateByteSequenceForTest
              [-1]
          )
    )
    "Sprint 1.20: relocation scanning admits the exact positive 4 GiB bound and rejects over-bound or negative byte totals"
  let setupFixtureRoot =
        dataRoot linuxMaterializationPaths
          </> "engines"
          </> "setup-manifest-fixture"
      setupManifestPath =
        setupFixtureRoot </> "bootstrap.json"
      setupStagingPath =
        setupFixtureRoot </> ".bootstrap.json.incoming"
      setupExternalPath =
        testRoot </> "setup-manifest-external"
      expectedSetupManifest =
        "{\"adapterId\":\"transformers-python\",\"schemaVersion\":1}\n"
      withSetupWriter ::
        forall setupResult.
        ( forall w s q.
          Provisioning.EngineWriter w s q ->
          Provisioning.ProvisioningSession s setupResult
        ) ->
        IO setupResult
      withSetupWriter action =
        Provisioning.withEngineProvisioningSession
          linuxMaterializationPaths
          (dataRoot linuxMaterializationPaths </> "engines")
          relocationEnvironment
          (\writer _grant -> action writer)
  removePathForcibly setupFixtureRoot
  setupReady <-
    withSetupWriter $ \writer -> do
      Provisioning.provisioningCreateDirectory writer setupFixtureRoot
      Provisioning.provisioningPublishAppleSetupManifest
        writer
        Provisioning.transformersPoetrySetup
        setupFixtureRoot
      Provisioning.provisioningAppleSetupReady
        writer
        Provisioning.transformersPoetrySetup
        setupFixtureRoot
  setupManifest <- BS.readFile setupManifestPath
  assert
    (setupReady && setupManifest == ByteString8.pack expectedSetupManifest)
    "Sprint 1.20: setup bootstrap publication writes only the exact canonical adapter evidence"
  staleRecovered <-
    withSetupWriter $ \writer -> do
      Provisioning.provisioningRemovePath writer setupManifestPath
      Provisioning.provisioningWriteBytes
        writer
        setupStagingPath
        "stale"
      Provisioning.provisioningPublishAppleSetupManifest
        writer
        Provisioning.transformersPoetrySetup
        setupFixtureRoot
      Provisioning.provisioningAppleSetupReady
        writer
        Provisioning.transformersPoetrySetup
        setupFixtureRoot
  staleStagingExists <- doesPathExist setupStagingPath
  assert
    (staleRecovered && not staleStagingExists)
    "Sprint 1.20: setup bootstrap publication recovers an exact stale staging file"
  withSetupWriter $ \writer ->
    Provisioning.provisioningRemovePath writer setupManifestPath
  BS.writeFile setupExternalPath "external"
  createSymbolicLink setupExternalPath setupStagingPath
  nofollowResult <-
    try @SomeException $
      withSetupWriter $ \writer ->
        Provisioning.provisioningPublishAppleSetupManifest
          writer
          Provisioning.transformersPoetrySetup
          setupFixtureRoot
  nofollowManifestExists <- doesPathExist setupManifestPath
  externalContents <- BS.readFile setupExternalPath
  assert
    ( isLeft nofollowResult
        && not nofollowManifestExists
        && externalContents == "external"
    )
    "Sprint 1.20: setup bootstrap staging refuses a symlink without touching its target"
  removeLink setupStagingPath
  setupPauseEntered <- MVar.newEmptyMVar
  setupPauseResume <- MVar.newEmptyMVar
  setupCancellationResult <- MVar.newEmptyMVar
  setupPublisher <-
    forkIO $
      ( try @SomeException $
          withSetupWriter $ \writer ->
            Provisioning.provisioningPublishAppleSetupManifestWithPauseForTest
              writer
              Provisioning.transformersPoetrySetup
              setupFixtureRoot
              setupPauseEntered
              setupPauseResume
      )
        >>= MVar.putMVar setupCancellationResult
  MVar.takeMVar setupPauseEntered
  killThread setupPublisher
  cancelledSetup <- MVar.takeMVar setupCancellationResult
  cancelledManifestExists <- doesPathExist setupManifestPath
  cancelledStagingExists <- doesFileExist setupStagingPath
  recoveredAfterCancellation <-
    withSetupWriter $ \writer -> do
      Provisioning.provisioningPublishAppleSetupManifest
        writer
        Provisioning.transformersPoetrySetup
        setupFixtureRoot
      Provisioning.provisioningAppleSetupReady
        writer
        Provisioning.transformersPoetrySetup
        setupFixtureRoot
  recoveredStagingExists <- doesPathExist setupStagingPath
  assert
    ( isLeft cancelledSetup
        && not cancelledManifestExists
        && cancelledStagingExists
        && recoveredAfterCancellation
        && not recoveredStagingExists
    )
    "Sprint 1.20: cancellation cannot publish a partial setup manifest and the next locked session retires staging"

-- Phase 4 Sprint 4.13 — ClusterConfig renderer + decoder roundtrip.
assertClusterConfig :: FilePath -> FilePath -> IO ()
assertClusterConfig testRoot demoConfigPathValue = do
  let clusterConfig = unitTestClusterConfigFixture demoConfigPathValue
      clusterManifestRoot = testRoot </> "cluster-manifest"
      clusterManifestPath = clusterManifestRoot </> "infernix-cluster.dhall"
  createDirectoryIfMissing True clusterManifestRoot
  writeFile clusterManifestPath (renderClusterConfig clusterConfig)
  decoded <- decodeClusterConfigFile clusterManifestPath
  assert
    (decoded == clusterConfig)
    "ClusterConfig round-trip through renderClusterConfig + decodeClusterConfigFile preserves every field"
  rendered <- readFile clusterManifestPath
  assert
    (not ("commandOverrides" `isInfixOf` rendered))
    "ClusterConfig has no command-override binding surface"

-- | Sprint 1.20 Linux ELF/loader closure evidence.
--
-- | Sprint 1.20 regression: a live process group whose exact recorded leader
-- has already been reaped.
--
-- This is the shape both corrected classifications used to reject outright, and
-- nothing in the gate set reached it before — grepping @test/@ for any of the
-- refusal strings these paths emit returned nothing. It is built
-- deterministically: every step synchronises on a pipe or on a blocking reap, so
-- there is no sleep and no dependence on host load, which is what made the
-- original failures look like flakes.
--
-- The fixture asserts its own two preconditions rather than assuming them. The
-- absence semantics of 'readProcessBirthIdentity' differ by platform — procfs
-- allocation on Linux, registry membership on Darwin — and if either stopped
-- holding, the interesting assertions below would still pass while testing
-- nothing.
runLeaderlessProcessGroupAssertions :: IO ()
runLeaderlessProcessGroupAssertions = do
  (readyReader, readyWriter) <- PosixIO.createPipe
  (leaderReleaseReader, leaderReleaseWriter) <- PosixIO.createPipe
  (memberReadyReader, memberReadyWriter) <- PosixIO.createPipe
  (memberReleaseReader, memberReleaseWriter) <- PosixIO.createPipe
  leaderProcessId <-
    forkProcess $ do
      PosixIO.closeFd readyReader
      PosixIO.closeFd leaderReleaseWriter
      dropInheritedProcessIdentity
      processId <- getProcessID
      _ <- createProcessGroupFor processId
      _ <- registerCurrentProcessIdentity
      _ <- PosixByteString.fdWrite readyWriter "ready"
      PosixIO.closeFd readyWriter
      _ <- PosixByteString.fdRead leaderReleaseReader 1
      exitImmediately ExitSuccess
  PosixIO.closeFd readyWriter
  PosixIO.closeFd leaderReleaseReader
  leaderReady <- PosixByteString.fdRead readyReader 5
  PosixIO.closeFd readyReader
  -- The surviving member is forked by this process and joins the leader's
  -- group, rather than being forked by the leader. A grandchild would orphan
  -- when the leader is reaped, and the fixture would then depend on the init
  -- system reaping it — which is not something the container lanes can be
  -- assumed to do, and an unreaped zombie still answers 'kill(2)' as a live
  -- group member. Owning the member here keeps every transition a blocking
  -- reap this process performs itself.
  memberProcessId <-
    forkProcess $ do
      PosixIO.closeFd memberReadyReader
      PosixIO.closeFd memberReleaseWriter
      dropInheritedProcessIdentity
      joinProcessGroup (fromIntegral leaderProcessId)
      _ <- PosixByteString.fdWrite memberReadyWriter "ready"
      PosixIO.closeFd memberReadyWriter
      _ <- PosixByteString.fdRead memberReleaseReader 1
      exitImmediately ExitSuccess
  PosixIO.closeFd memberReadyWriter
  PosixIO.closeFd memberReleaseReader
  memberReady <- PosixByteString.fdRead memberReadyReader 5
  PosixIO.closeFd memberReadyReader
  leaderBirthIdentity <-
    maybe
      (fail "the leaderless-group fixture leader had no observable birth identity")
      pure
      =<< readProcessBirthIdentity (fromIntegral leaderProcessId)
  _ <- PosixByteString.fdWrite leaderReleaseWriter "x"
  PosixIO.closeFd leaderReleaseWriter
  leaderStatus <- getProcessStatus True False leaderProcessId
  reapedLeaderIdentity <-
    readProcessBirthIdentity (fromIntegral leaderProcessId)
  liveGroupProbe <-
    try @IOException
      (signalProcessGroup nullSignal leaderProcessId)
  assert
    ( leaderReady == "ready"
        && memberReady == "ready"
        && leaderStatus == Just (Exited ExitSuccess)
        && isNothing reapedLeaderIdentity
        && liveGroupProbe == Right ()
    )
    "the leaderless-group fixture reaches a live process group whose exact recorded leader is absent"
  recoverableStatus <-
    Subprocess.observeRecoverableProcessGroupActiveForTest
      (fromIntegral leaderProcessId)
      (fromIntegral leaderProcessId)
      leaderBirthIdentity
  assert
    recoverableStatus
    "abandoned-activity recovery classifies a reaped leader over a live group as active instead of refusing it"
  refusedWhileMemberLives <-
    try @IOException
      ( Subprocess.signalActivityProcessGroupForTest
          (fromIntegral leaderProcessId)
          (fromIntegral leaderProcessId)
          leaderBirthIdentity
      )
  -- The conservative discipline is the only acceptable outcome here. A reaped
  -- leader can no longer vouch for its group id, so the group must never be
  -- signalled by that bare number; the obligation is discharged by proving
  -- absence, and while the member is alive that proof must fail closed.
  let refusedForUnprovableAbsence =
        case refusedWhileMemberLives of
          Left failure ->
            "could not prove absent" `isInfixOf` displayException failure
          Right () -> False
  assert
    refusedForUnprovableAbsence
    "a reaped leader's group is never signalled by its bare process-group id, and an unprovable absence fails closed"
  _ <- PosixByteString.fdWrite memberReleaseWriter "x"
  PosixIO.closeFd memberReleaseWriter
  memberStatus <- getProcessStatus True False memberProcessId
  assert
    (memberStatus == Just (Exited ExitSuccess))
    "the leaderless-group fixture reaps its surviving member itself rather than relying on the init system"
  Subprocess.signalActivityProcessGroupForTest
    (fromIntegral leaderProcessId)
    (fromIntegral leaderProcessId)
    leaderBirthIdentity

-- The loader closure producer runs only on Linux, but every part of it that
-- decides what the evidence says is pure: the ELF parse, the dynamic-token
-- expansion, and the @ld.so.cache@ parse. Those are pinned here against
-- hand-built images and caches so the producer is provable without a Linux
-- host, which is what the closure bounds and the resolution order actually
-- turn on.
runElfLoaderClosureAssertions :: IO ()
runElfLoaderClosureAssertions = do
  runElfImageParseAssertions
  runElfExpansionAssertions
  runLdSoCacheAssertions

runElfImageParseAssertions :: IO ()
runElfImageParseAssertions = do
  inspection <-
    either
      (fail . ("synthetic ELF image did not parse: " <>))
      pure
      (ArtifactLoader.parseElfImageInspection syntheticElf64Image)
  assert
    (ArtifactLoader.elfInspectionClass inspection == ArtifactLoader.Elf64)
    "synthetic ELF image parses as 64-bit"
  assert
    ( ArtifactLoader.elfInspectionEndian inspection
        == ArtifactLoader.ElfLittleEndian
    )
    "synthetic ELF image parses as little-endian"
  assert
    (ArtifactLoader.elfInspectionMachine inspection == 183)
    "synthetic ELF image reports its declared machine"
  assert
    ( ArtifactLoader.elfInspectionInterpreter inspection
        == Just "/lib/ld-linux-aarch64.so.1"
    )
    "synthetic ELF image binds its PT_INTERP loader"
  assert
    (ArtifactLoader.elfInspectionSoname inspection == Just "libfoo.so.1")
    "synthetic ELF image reports its DT_SONAME"
  assert
    ( ArtifactLoader.elfInspectionNeeded inspection
        == ["libc.so.6", "libm.so.6"]
    )
    "synthetic ELF image reports its DT_NEEDED entries in declaration order"
  assert
    ( ArtifactLoader.elfInspectionRunPath inspection
        == ["$ORIGIN/../lib", "/opt/extra"]
    )
    "synthetic ELF image splits DT_RUNPATH on colons without expanding it"
  assert
    (null (ArtifactLoader.elfInspectionRPath inspection))
    "synthetic ELF image declaring only DT_RUNPATH reports no DT_RPATH"
  assert
    (ArtifactLoader.elfImageMagicPresent (BS.take 6 syntheticElf64Image))
    "ELF candidacy accepts a well-formed leading header"
  assert
    ( not
        ( ArtifactLoader.elfImageMagicPresent
            (ByteString8.pack "\x7f" <> ByteString8.pack "ELF\x09\x01")
        )
    )
    "ELF candidacy rejects an undefined class byte"
  assert
    ( not
        ( ArtifactLoader.elfImageMagicPresent
            (ByteString8.pack "\xca\xfe\xba\xbe\x00\x34")
        )
    )
    "ELF candidacy rejects a Java class file header"
  assert
    ( isLeftResult
        ( ArtifactLoader.parseElfImageInspection
            (BS.drop 1 syntheticElf64Image)
        )
    )
    "ELF parse rejects an image without the ELF magic"
  assert
    ( isLeftResult
        ( ArtifactLoader.parseElfImageInspection
            (replaceByteAt 18 0x00 (replaceByteAt 19 0x00 syntheticElf64Image))
        )
        || elfMachineRejected
          (ArtifactLoader.parseElfImageInspection (replaceByteAt 18 0x00 (replaceByteAt 19 0x00 syntheticElf64Image)))
    )
    "ELF parse surfaces an unsupported machine rather than guessing a platform"
  assert
    (isLeftResult (ArtifactLoader.parseElfImageInspection (replaceByteAt 4 0x09 syntheticElf64Image)))
    "ELF parse rejects an undefined class byte"
  assert
    (isLeftResult (ArtifactLoader.parseElfImageInspection (replaceByteAt 5 0x09 syntheticElf64Image)))
    "ELF parse rejects an undefined data encoding"
  assert
    (isLeftResult (ArtifactLoader.parseElfImageInspection (BS.take 400 syntheticElf64Image)))
    "ELF parse rejects an image whose dynamic string table is truncated"
  let relocatableElf =
        foldr
          (uncurry replaceByteAt)
          syntheticElf64Image
          [(54, 0), (55, 0), (56, 0), (57, 0)]
  assert
    ( either
        (const False)
        (const True)
        (ArtifactLoader.parseElfImageInspection relocatableElf)
    )
    "ELF parse admits a relocatable object with no program-header table"
  -- Sprint 1.28. A name the search cannot satisfy is still satisfied by a
  -- unique object the generation itself carries, because a runtime that loads
  -- each object by absolute path puts its SONAME in the namespace before the
  -- dependent object names it. JavaCPP is the measured case: each native
  -- library is extracted into its own jar directory and loaded by absolute
  -- path, so a dependent's `$ORIGIN/` runpath cannot reach the sibling jar
  -- directory holding its provider.
  loaderSeedRoot <- testRootPath "loader-seeded-soname"
  let seedProviderDirectory =
        loaderSeedRoot </> "provider.jar" </> "org" </> "fixture"
      seedRivalDirectory =
        loaderSeedRoot </> "rival.jar" </> "org" </> "fixture"
      seedDependentDirectory =
        loaderSeedRoot </> "dependent.jar" </> "org" </> "fixture"
      seedProviderName = "libinfernixseedprovider.so.6"
      seedDependentName = "libinfernixseeddependent.so.5"
      seedProviderPath = seedProviderDirectory </> seedProviderName
      seedDependentPath = seedDependentDirectory </> seedDependentName
      writeSeedObject path neededNames soname = do
        createDirectoryIfMissing True (takeDirectory path)
        BS.writeFile
          path
          (syntheticSharedObjectImage neededNames soname "$ORIGIN/")
        setFileMode path 0o600
  removeTestPathIfPresent loaderSeedRoot
  writeSeedObject seedProviderPath [] seedProviderName
  writeSeedObject seedDependentPath [seedProviderName] seedDependentName
  seededClosure <-
    try @SomeException
      ( ArtifactLoader.observeNativeArtifactLoaderEvidence
          seedDependentPath
          [loaderSeedRoot]
      )
  seededResolution <-
    case seededClosure of
      Left failure -> fail ("seeded loader closure failed: " <> show failure)
      Right evidence ->
        pure
          [ ArtifactTarget.loaderResolutionConfiguredPath resolution
          | resolution <- ArtifactTarget.loaderEvidenceResolutions evidence,
            ArtifactTarget.loaderResolutionNeeded resolution
              == seedProviderName
          ]
  canonicalSeedProvider <- canonicalizePath seedProviderPath
  assert
    (seededResolution == [canonicalSeedProvider])
    ( "a DT_NEEDED name the search cannot satisfy binds the unique seeded SONAME inside the same closure; observed "
        <> show (seededResolution, canonicalSeedProvider)
    )
  writeSeedObject
    (seedRivalDirectory </> seedProviderName)
    []
    seedProviderName
  ambiguousClosure <-
    try @SomeException
      ( ArtifactLoader.observeNativeArtifactLoaderEvidence
          seedDependentPath
          [loaderSeedRoot]
      )
  removeTestPathIfPresent loaderSeedRoot
  let seededAmbiguityRefused failure =
        "matches multiple seeded SONAME objects" `isInfixOf` show failure
          && seedDependentPath `isInfixOf` show failure
  assert
    (either seededAmbiguityRefused (const False) ambiguousClosure)
    ( "two seeded objects claiming one SONAME are not interchangeable evidence; observed "
        <> show ambiguousClosure
    )
  -- A seeded rebind is not the requester's dependency — something else mapped
  -- the provider by absolute path — so the provider's own edges must not be
  -- resolved through the requester's inherited DT_RPATH. Without that, a decoy
  -- outside the generation, reachable only through the requester's stack, is
  -- sealed in place of the object the runtime actually loads.
  let contextRoot = loaderSeedRoot <> "-context"
      contextDecoyRoot = contextRoot <> "-decoy"
      contextRequesterPath =
        contextRoot </> "requester.jar" </> "org" </> "librequester.so.1"
      contextProviderPath =
        contextRoot </> "provider.jar" </> "org" </> "libprovider.so.6"
      contextSharedName = "libshared.so.1"
      contextSharedPath =
        contextRoot </> "shared.jar" </> "org" </> contextSharedName
      contextDecoyPath = contextDecoyRoot </> contextSharedName
      writeContextObject path image = do
        createDirectoryIfMissing True (takeDirectory path)
        BS.writeFile path image
        setFileMode path 0o600
  mapM_ removeTestPathIfPresent [contextRoot, contextDecoyRoot]
  writeContextObject
    contextRequesterPath
    ( syntheticSharedObjectImageWithSearchPath
        15
        ["libprovider.so.6"]
        "librequester.so.1"
        contextDecoyRoot
    )
  writeContextObject
    contextProviderPath
    (syntheticSharedObjectImage [contextSharedName] "libprovider.so.6" "$ORIGIN/")
  writeContextObject
    contextSharedPath
    (syntheticSharedObjectImage [] contextSharedName "$ORIGIN/")
  writeContextObject
    contextDecoyPath
    (syntheticSharedObjectImage [] contextSharedName "$ORIGIN/")
  contextClosure <-
    try @SomeException
      ( ArtifactLoader.observeNativeArtifactLoaderEvidence
          contextRequesterPath
          [contextRoot]
      )
  canonicalContextShared <- canonicalizePath contextSharedPath
  contextSharedResolution <-
    case contextClosure of
      Left failure -> fail ("seeded rebind context closure failed: " <> show failure)
      Right evidence ->
        pure
          [ ArtifactTarget.loaderResolutionConfiguredPath resolution
          | resolution <- ArtifactTarget.loaderEvidenceResolutions evidence,
            ArtifactTarget.loaderResolutionNeeded resolution
              == contextSharedName
          ]
  mapM_ removeTestPathIfPresent [contextRoot, contextDecoyRoot]
  assert
    (contextSharedResolution == [canonicalContextShared])
    ( "a seeded rebind resolves the provider's own edges context-free, not through the requester's inherited DT_RPATH; observed "
        <> show (contextSharedResolution, canonicalContextShared)
    )

-- | The machine byte is only consulted during expansion, so an unsupported
-- machine is allowed to parse and must fail at the platform token instead.
elfMachineRejected ::
  Either String ArtifactLoader.ElfImageInspection ->
  Bool
elfMachineRejected parsed =
  case parsed of
    Left _ -> True
    Right inspection ->
      isLeftResult
        (ArtifactLoader.elfPlatformToken (ArtifactLoader.elfInspectionMachine inspection))

runElfExpansionAssertions :: IO ()
runElfExpansionAssertions = do
  assert
    ( ArtifactLoader.expandElfSearchPath elfTestContext "$ORIGIN/../lib"
        == Right "/opt/app/lib"
    )
    "ELF expansion resolves $ORIGIN against the object's own directory"
  assert
    ( ArtifactLoader.expandElfSearchPath elfTestContext "${ORIGIN}/plugins"
        == Right "/opt/app/bin/plugins"
    )
    "ELF expansion resolves the braced ${ORIGIN} spelling"
  assert
    ( ArtifactLoader.expandElfSearchPath elfTestContext "/usr/lib/$PLATFORM"
        == Right "/usr/lib/aarch64"
    )
    "ELF expansion resolves $PLATFORM"
  assert
    ( ArtifactLoader.expandElfSearchPath elfTestContext "/usr/$LIB"
        == Right "/usr/lib64"
    )
    "ELF expansion resolves $LIB"
  assert
    (isLeftResult (ArtifactLoader.expandElfSearchPath elfTestContext "relative/lib"))
    "ELF expansion rejects a search element that is not absolute"
  assert
    (isLeftResult (ArtifactLoader.expandElfSearchPath elfTestContext "$UNSUPPORTED/lib"))
    "ELF expansion rejects an unsupported dynamic token"
  assert
    (isLeftResult (ArtifactLoader.expandElfSearchPath elfTestContext "$LIB"))
    "ELF expansion rejects a bare $LIB, which expands to a relative element"
  assert
    (ArtifactLoader.elfLibToken ArtifactLoader.Elf64 == "lib64")
    "$LIB is lib64 for a 64-bit object"
  assert
    (ArtifactLoader.elfLibToken ArtifactLoader.Elf32 == "lib")
    "$LIB is lib for a 32-bit object"
  assert
    (ArtifactLoader.elfPlatformToken 62 == Right "x86_64")
    "$PLATFORM is x86_64 for EM_X86_64"
  assert
    (ArtifactLoader.elfPlatformToken 183 == Right "aarch64")
    "$PLATFORM is aarch64 for EM_AARCH64"
  assert
