      sealedFrames =
        [ "         7:\tfind library=libllama.so [0]; searching",
          "         7:\t  trying file=" <> artifactRoot <> "/lib/libllama.so",
          "         7:\tcalling init: /lib/ld-linux-aarch64.so.1",
