          "excludedPythonHomeShebangFile excludePythonHomeHostBindings closureRoot relativePath descriptor | not excludePythonHomeHostBindings = pure False | otherwise = do _ <- fdSeek descriptor AbsoluteSeek 0 leading <- readProvisioningDescriptorPrefix descriptor maximumShebangProbeBytes _ <- fdSeek descriptor AbsoluteSeek 0 pure ( pythonHomeClosureFileExcluded excludePythonHomeHostBindings closureRoot relativePath leading )",
          "maximumShebangProbeBytes = 512",
          "readProvisioningDescriptorPrefix descriptor maximumBytes = go maximumBytes [] where go remaining chunks | remaining == 0 = pure (ByteString.concat (reverse chunks)) | otherwise = do chunk <- readProvisioningDescriptorChunk descriptor remaining",
          "pythonHomeClosureFileExcluded excludePythonHomeHostBindings closureRoot relativePath leading = excludePythonHomeHostBindings && shebangBindsHostInstallation leading && ( pythonHomeBinEntry relativePath || shebangBindsExactPythonHome closureRoot leading )",
          "normalise (takeDirectory interpreterPath) == normalise (closureRoot </> \"bin\") && \"python\" `List.isPrefixOf` takeFileName interpreterPath",
          "excludedPythonHomeShebangFile excludeBaseSitePackages closureRoot relativePath descriptor if excluded then do recheckRetainedPackageClosureFile parentDescriptor entry path descriptor status pure state else digestPackageClosureFile",
          "closureCopySourceRoot = source",
          "excludedPythonHomeShebangFile excludeBaseSitePackages (closureCopySourceRoot context) relativePath sourceFileDescriptor unless excluded $ do",
          "recheckRetainedPackageClosureFile sourceParentDescriptor entry source sourceFileDescriptor sourceFileStatus pure (if excluded then entriesSeen else nextEntries)"
        ]
        && all
          (`isInfixOf` normalizedSubprocessClosureSource)
          [ "excludedPythonHomeShebangSnapshotFile excludePythonHomeHostBindings closureRoot relativePath descriptor | not excludePythonHomeHostBindings = pure False | otherwise = do _ <- fdSeek descriptor AbsoluteSeek 0 leading <- readRegularFdPrefix 512 descriptor _ <- fdSeek descriptor AbsoluteSeek 0 pure ( packageClosureFileExcluded excludePythonHomeHostBindings closureRoot relativePath leading )",
            "packageClosureFileExcluded excludePythonHomeHostBindings closureRoot relativePath leading = excludePythonHomeHostBindings && snapshotShebangBindsHostInstallation leading && ( snapshotPythonHomeBinEntry relativePath || snapshotShebangBindsExactPythonHome closureRoot leading )",
            "normalise (takeDirectory interpreterPath) == normalise (closureRoot </> \"bin\") && \"python\" `List.isPrefixOf` takeFileName interpreterPath",
            "excludedPythonHomeShebangSnapshotFile excludeBaseSitePackages sourceRoot relativePath sourceDescriptor if excluded then do recheckSnapshotPackageClosureFile sourceParentDescriptor entry sourcePath sourceDescriptor status pure state else copyPackageClosureFile",
            "excludedPythonHomeShebangSnapshotFile excludePythonHomeHostBindings closureRoot relativePath descriptor if excluded then do recheckSnapshotPackageClosureFile parentDescriptor entry path descriptor status pure state else digestSealedPackageClosureFile"
          ]
    )
    "Sprint 1.20: retained digest/copy and snapshot/verification walks carry the exact source root through stable bounded probes, while Provisioning verifies its filtered destination in sealed mode"
  assert
    ( "verifyPackageClosure SealedPackageClosureSnapshot expectation"
        `isInfixOf` normalizedSubprocessClosureSource
        && "verifyRetainedPackageClosure = verifyPackageClosure RetainedPackageClosureSource"
          `isInfixOf` normalizedSubprocessClosureSource
    )
    "Sprint 1.20: production sealed verification hashes every copied entry while retained-source verification alone applies role-aware Python-home exclusions"
  assert
    ( sourceDyldEnvironment
        == [ ( "DYLD_FRAMEWORK_PATH",
               sourceDyldFrameworkPath
             ),
             ( "DYLD_LIBRARY_PATH",
               sourceDyldLibraryPath
             ),
             ("DYLD_PRINT_LIBRARIES", "1")
           ]
        && sourceProfile == expectedSourceProfile
        && not
          ( any
              (`isInfixOf` sourceProfile)
              ( ProvisioningInternal.provisioningPackageClosureRoot sourceDirectory
                  : map ProvisioningInternal.provisioningRuntimeLibraryCanonicalPath sourceFiles
              )
          )
        && sourceArguments
          == [ "-p",
               expectedSourceProfile,
               "-D",
               "INFERNIX_SOURCE_DIRECTORY_0=/opt/homebrew/python-home",
               "-D",
               "INFERNIX_SOURCE_FILE_0=/opt/homebrew/python-home/Python",
               "-D",
               "INFERNIX_SOURCE_FILE_1=/opt/homebrew/lib/libb.dylib",
               ProvisioningInternal.installedPythonSourceIsolationAuditInjectorExecutable,
               "DYLD_FRAMEWORK_PATH=" <> sourceDyldFrameworkPath,
               "DYLD_LIBRARY_PATH=" <> sourceDyldLibraryPath,
               "DYLD_PRINT_LIBRARIES=1",
               artifactRoot </> ProvisioningInternal.fixedVenvPythonRelativePath,
               "lib" </> "apple_native_runner.py",
               "--adapter-id",
               "onnx-runtime-native",
               "--engine-name",
               "onnx-runtime-native",
               "--expected-python-prefix",
               artifactRoot </> "venv",
               "--smoke",
               "--expected-unavailable-source-directory",
               "/opt/homebrew/python-home",
               "--expected-unavailable-source-file",
               "/opt/homebrew/python-home/Python",
               "--expected-unavailable-source-file",
               "/opt/homebrew/lib/libb.dylib",
               "--expected-unavailable-source-write-probe",
               "/opt/homebrew/python-home/Python",
               "--source-isolation-receipt",
               Text.unpack sourceReceipt
             ]
    )
    "Sprint 1.20: the fixed SBPL program contains only bounded parameter names, source paths enter solely through exact -D bindings, and the inner env bridge exactly restores the renderer-owned DYLD roots and audit flag"
  assert
    ( Subprocess.sealedLinuxRunnerApplicationOutputForTest
        ownedRoots
        (ByteString8.pack (unlines sealedFrames))
        == Right (ByteString8.pack "version: 9870 (2d973636e)\n")
    )
    "Sprint 1.20: a sealed Linux run that loads from its own generation is admitted and yields only the runner's own diagnostics"
  assert
    ( isLeftResult
        ( Subprocess.sealedLinuxRunnerApplicationOutputForTest
            ownedRoots
            (ByteString8.pack "version: 9870 (2d973636e)\n")
        )
    )
    "Sprint 1.20: a sealed Linux run emitting no loader provenance fails closed"
  assert
    ( isLeftResult
        ( Subprocess.sealedLinuxRunnerApplicationOutputForTest
            ownedRoots
            ( ByteString8.pack
                ( unlines
                    [ "         7:\tcalling init: /lib/aarch64-linux-gnu/libc.so.6"
                    ]
                )
            )
        )
    )
    "Sprint 1.20: a sealed Linux run that loads nothing from its own generation fails closed"
  -- The Apple lane's most consequential finding, in its Linux form: a `dlopen`ed
  -- extension module pulling a host library in. `LD_DEBUG=libs` reports it.
  assert
    ( isLeftResult
        ( Subprocess.sealedLinuxRunnerApplicationOutputForTest
            ownedRoots
            ( ByteString8.pack
                ( unlines
                    ( sealedFrames
                        <> [ "         7:\tcalling init: /opt/host/lib/liblzma.so.5"
                           ]
                    )
                )
            )
        )
    )
    "Sprint 1.20: a sealed Linux run loading an unsealed non-system library fails closed"
  -- An installed target's closure root is the relative `.`, which resolves to
  -- `<generation>/.`. That is the shape the Apple lane actually passes, and it
  -- only works if the containment check drops the trailing separator: without
  -- that, every path under the generation reads as unsealed and the audit
  -- reports that the run loaded nothing from its own generation.
  assert
    ( Subprocess.sealedLinuxRunnerApplicationOutputForTest
        [artifactRoot <> "/."]
        (ByteString8.pack (unlines sealedFrames))
        == Right (ByteString8.pack "version: 9870 (2d973636e)\n")
    )
    "Sprint 1.20: an owned root spelled as the generation's own relative directory still contains its payload"
  llamaIdentity <-
    maybe
      (fail "closed native identity omitted llama-cpp-cli")
      pure
      (EngineArtifact.parseNativeArtifactIdentity "llama-cpp-cli")
  assert
    ( Subprocess.sealedRunLoaderAuditForTest
        ( ProvisioningInternal.LinuxNativeArtifactSmokeOperation
            llamaIdentity
            "amd64"
        )
        == Just Subprocess.ElfSealedRunAudit
        && Subprocess.sealedRunLoaderAuditForTest
          ( ProvisioningInternal.InstalledRunnerSmokeOperation
              ProvisioningInternal.LlamaCppCliAdapter
          )
          == Just Subprocess.DyldSealedRunAudit
        && Subprocess.sealedRunLoaderAuditForTest
          ( ProvisioningInternal.InstalledPythonSourceIsolationSmokeOperation
              ProvisioningInternal.OnnxRuntimeAdapter
          )
          == Just Subprocess.DyldSealedRunAudit
        && isNothing
          ( Subprocess.sealedRunLoaderAuditForTest
              ProvisioningInternal.AudiverisDownloadOperation
          )
    )
    "Sprint 1.20: the sealed-run loader audit is selected from the command's closed operation, so a Linux smoke can never be audited against dyld"

-- | Sprint 1.20: the settled closure bounds, covered positively and on
-- overflow through the same folds the materializer runs.
--
-- Before this, none of the four bounds was exported or had a pure validator, so
-- none was reachable from any gate — a bound that no test can reach is a bound
-- that can silently drift back to "raised to unblock a measurement".
runNativeArtifactArgumentAssertions :: IO ()
runNativeArtifactArgumentAssertions = do
  let llamaArguments =
        CappedEngineInternal.renderNativeArtifactArgumentsForTest
          "llama-cpp-cli"
          Nothing
          Nothing
      llamaArgumentList = fromRight [] llamaArguments
      whisperArguments =
        CappedEngineInternal.renderNativeArtifactArgumentsForTest
          "whisper-cpp-cli"
          Nothing
          (Just "/tmp/input.wav")
      jvmArguments =
        CappedEngineInternal.renderNativeArtifactArgumentsForTest
          "jvm-native"
          (Just "/tmp/output")
          (Just "/tmp/input.png")
      pythonArguments =
        CappedEngineInternal.renderNativeArtifactArgumentsForTest
          "onnx-runtime-native"
          (Just "/tmp/output")
          (Just "/tmp/input.wav")
  assert
    ( llamaArguments
        == Right
          [ "--model",
            "/var/lib/infernix/models/test-model/payload",
            "--n-predict",
            "32",
            "--ctx-size",
            "512",
            "--threads",
            "1",
            "--gpu-layers",
            "0",
            "--prompt",
            "test prompt",
            "--no-display-prompt",
            "--single-turn",
            "--simple-io"
          ]
    )
    "Sprint 1.20: llama.cpp receives its real bounded CLI grammar and cached payload path"
  -- Phase 3 Sprint 3.16 cohort follow-on: pin the two flags whose removal is
  -- load-bearing, so neither returns as a "harmless" tidy-up. Measured against
  -- the pinned b9704 payload: `--log-disable` produces a failed model load with
  -- 0 bytes on both streams, which is what made the first `linux-cpu` cohort
  -- failure undiagnosable; `--no-conversation` is rejected by `llama-cli` at
  -- runtime and leaks the chat-template marker into published output under
  -- `llama-completion`.
  assert
    ( not (null llamaArgumentList)
        && notElem "--log-disable" llamaArgumentList
        && notElem "--no-conversation" llamaArgumentList
    )
    "llama.cpp argv carries neither --log-disable (silences the only failure channel) nor --no-conversation (leaks chat-template markers into published output)"
  -- Phase 4 Sprint 4.35 Apple half. The lane-specific function is total over
  -- `RuntimeMode` under -Wall -Werror, so a new lane cannot be added without
  -- deciding this question for it; asserting every constructor is empty pins
  -- the decision itself rather than one lane's rendering of it. Measured
  -- against Homebrew llama.cpp 9870: the retired Apple argv reproduced the
  -- Linux defect exactly, exiting 1 with the front-end's unsupported-flag
  -- complaint on stdout and zero bytes of diagnostics.
  assert
    ( all
        (null . CappedEngineInternal.llamaLaneSpecificArguments)
        [AppleSilicon, LinuxCpu, LinuxGpu]
    )
    "no lane reinstates --log-disable or --no-conversation, including apple-silicon"
  assert
    ( whisperArguments
        == Right
          [ "--model",
            "/var/lib/infernix/models/test-model/payload",
            "--file",
            "/tmp/input.wav",
            "--threads",
            "1",
            "--no-timestamps",
            "--language",
            "en",
            "--no-gpu"
          ]
    )
    "Sprint 1.20: whisper.cpp receives its real bounded CLI grammar"
  assert
    ( jvmArguments
        == Right
          [ "-batch",
            "-export",
            "-output",
            "/tmp/output",
            "/tmp/input.png"
          ]
    )
    "Sprint 1.20: Audiveris receives its real headless export CLI grammar"
  assert
    (either (const False) (elem "--engine") pythonArguments)
    "Sprint 1.20: Python-backed native adapters retain the package-owned runner protocol"
  assert
    ( isLeftResult
        ( CappedEngineInternal.renderNativeArtifactArgumentsForTest
            "whisper-cpp-cli"
            Nothing
            Nothing
        )
        && isLeftResult
          ( CappedEngineInternal.renderNativeArtifactArgumentsForTest
              "jvm-native"
              Nothing
              (Just "/tmp/input.png")
          )
        && isLeftResult
          ( CappedEngineInternal.renderNativeArtifactArgumentsForTest
              "unregistered-native-adapter"
              Nothing
              Nothing
          )
    )
    "Sprint 1.20: missing raw-target operands and unknown adapters fail before process creation"
  assert
    ( CappedEngineInternal.parseResidentBytesForTest
        "Name:\ttarget\nState:\tZ (zombie)\n"
        == Right 0
        && CappedEngineInternal.parseResidentBytesForTest
          "Name:\ttarget\nState:\tX (dead)\n"
          == Right 0
    )
    "Sprint 1.20: a terminal /proc status that races the prior live stat sample contributes zero RSS"
  assert
    ( isLeftResult
        ( CappedEngineInternal.parseResidentBytesForTest
            "Name:\ttarget\nState:\tS (sleeping)\n"
        )
        && isLeftResult
          ( CappedEngineInternal.parseResidentBytesForTest
              "Name:\ttarget\n"
          )
    )
    "Sprint 1.20: a live or malformed /proc status without RssAnon still fails closed"
  -- Phase 4 Sprint 4.40: the sampled field is the anonymous residency the
  -- installed data-segment ceiling charges, not the resident-set total that
  -- also counts file-backed and shared pages the ceiling charges for none of.
  assert
    ( CappedEngineInternal.parseResidentBytesForTest
        "Name:\ttarget\nState:\tS (sleeping)\nVmRSS:\t  409600 kB\nRssAnon:\t  102400 kB\nRssFile:\t  307200 kB\n"
        == Right (102400 * 1024)
    )
    "Sprint 4.40: the Linux sampler reads RssAnon, not the resident-set total"
  assert
    ( isLeftResult
        ( CappedEngineInternal.parseResidentBytesForTest
            "Name:\ttarget\nState:\tS (sleeping)\nVmRSS:\t  409600 kB\nRssFile:\t  307200 kB\n"
        )
    )
    ( "Sprint 4.40: a status block carrying VmRSS but no RssAnon is an "
        <> "enforcement failure, not a fallback to the retired field"
    )
  assert
    ( CappedEngineInternal.missingResidentRecheckForTest Nothing == Right True
        && CappedEngineInternal.missingResidentRecheckForTest
          (Just "885 (target) Z 1 885\n")
          == Right True
        && CappedEngineInternal.missingResidentRecheckForTest
          (Just "885 (target) X 1 885\n")
          == Right True
    )
    "Sprint 1.20: the missing-RssAnon recheck accepts only vanished or terminal tasks"
  assert
    ( CappedEngineInternal.missingResidentRecheckForTest
        (Just "885 (target) R 1 885\n")
        == Right False
        && isLeftResult
          ( CappedEngineInternal.missingResidentRecheckForTest
              (Just "malformed stat\n")
          )
    )
    "Sprint 1.20: the missing-RssAnon recheck retries live tasks and rejects malformed stat evidence"
  runSharedWatchdogLoopAssertions
  runInstalledCeilingAssertions
  runEngineProjectionAssertions
  runHarnessConfigRecoveryAssertions

-- | Phase 4 Sprint 4.43 — the engine's own projection, and the ceiling it
-- widens.
--
-- The defect this closes was measured rather than argued: a derived requirement
-- of roughly 471 MiB refused an 11 MiB key/value cache allocation on a host with
-- 124 GiB free, because the derivation models the artifact's weights and cache
-- and cannot model the engine's own compute buffers. The projection is the
-- engine answering that question about itself.
runEngineProjectionAssertions :: IO ()
runEngineProjectionAssertions = do
  let payloadPath = "/var/lib/infernix/models/test-model/payload"
      carriedShape =
        ModelExecutionShape
          { executionContextLength = 1536,
            executionBatchSize = 1,
            executionGenerationBound = 96,
            executionCacheElementWidth = 2,
            executionLoadStrategy = LoadResidentHost
          }
      execution =
        Projection.LlamaNativeExecution
          { Projection.llamaExecutionContextLength = executionContextLength carriedShape,
            Projection.llamaExecutionGenerationBound = executionGenerationBound carriedShape,
            Projection.llamaExecutionThreads = 1,
            Projection.llamaExecutionGpuLayers = 0
          }
      llamaProbe =
        Projection.engineProjectionRequest "llama-cpp-cli" payloadPath execution
      sharedOperands =
        Projection.llamaNativeExecutionArguments payloadPath execution
      renderedEngineArguments =
        fromRight
          []
          ( CappedEngineInternal.renderNativeArtifactArgumentsForShapeForTest
              "llama-cpp-cli"
              carriedShape
              Nothing
              Nothing
          )
  -- The load-bearing property: the probe and the engine render the same
  -- execution operands from one value, so a projection can never describe a
  -- different execution than the one that runs.
  assert
    ( fmap
        (take (length sharedOperands) . Projection.projectionArguments)
        llamaProbe
        == Just sharedOperands
        && take (length sharedOperands) renderedEngineArguments == sharedOperands
    )
    ( "Sprint 4.42/4.43: the carried execution shape reaches both the native "
        <> "engine invocation and its projection probe through one value"
    )
  assert
    ( fmap Projection.projectionExecutableName llamaProbe
        == Just "llama-fit-params"
        && fmap
          (drop (length sharedOperands) . Projection.projectionArguments)
          llamaProbe
          == Just ["-fitp", "on"]
    )
    ( "Sprint 4.43: the probe is the upstream projection tool asked to print its "
        <> "estimate, named as a sibling file rather than as a path"
    )
  -- A family with no projection tool is a positive statement, not an omission.
  assert
    ( all
        ( \adapterId ->
            isNothing
              (Projection.engineProjectionRequest adapterId payloadPath execution)
        )
        [ "whisper-cpp-cli",
          "jvm-native",
          "onnx-runtime-native",
          "ctranslate2-native",
          "mlx-native",
          "coreml-native"
        ]
    )
    ( "Sprint 4.43: an engine family that ships no projection tool declares none, "
        <> "and its ceiling is the artifact-derived quantity"
    )
  -- The parser, against the tool's real output shape.
  assert
    (Projection.parseEngineProjectionMib "Host 426 11 70 \n" == Right 507)
    "Sprint 4.43: a host row's model, context, and compute estimates sum to the projection"
  assert
    ( Projection.parseEngineProjectionMib "CUDA0 4200 90 310\nHost 426 11 70\n"
        == Right 507
    )
    ( "Sprint 4.43: a device row is read and deliberately not summed into a host "
        <> "ceiling, which charges no device buffer"
    )
  assert
    ( isLeftResult (Projection.parseEngineProjectionMib "")
        && isLeftResult (Projection.parseEngineProjectionMib "loading model...\n")
        && isLeftResult (Projection.parseEngineProjectionMib "CUDA0 4200 90 310\n")
        && isLeftResult (Projection.parseEngineProjectionMib "Host 426 eleven 70\n")
        && isLeftResult (Projection.parseEngineProjectionMib "Host 0 0 0\n")
    )
    ( "Sprint 4.43: an unreadable, host-less, or non-positive projection is a "
        <> "reason rather than a small number"
    )
  -- The installed quantity is the greater of the two, and the derivation stays
  -- authoritative wherever it is larger.
  let derivedOnly =
        Ceiling.resolveEngineCeiling LinuxCpu PodRam 471 Ceiling.NoEngineProjection
      widened =
        Ceiling.resolveEngineCeiling LinuxCpu PodRam 471 (Ceiling.EngineProjectedMib 507)
      underReported =
        Ceiling.resolveEngineCeiling LinuxCpu PodRam 471 (Ceiling.EngineProjectedMib 64)
  assert
    ( Ceiling.installedCeilingMib widened == 507
        && Ceiling.installedCeilingDerivedMib widened == 471
        && Ceiling.installedCeilingProvenance widened
          == Ceiling.CeilingFromArtifactAndProjection 507
    )
    ( "Sprint 4.43: a projection above the derived requirement widens the "
        <> "installed ceiling and both quantities are retained"
    )
  assert
    ( Ceiling.installedCeilingMib underReported == 471
        && Ceiling.installedCeilingProvenance underReported
          == Ceiling.CeilingFromArtifactAndProjection 64
    )
    ( "Sprint 4.43: an engine that under-reports cannot widen its own bound below "
        <> "what its weights and cache provably need"
    )
  assert
    ( Ceiling.installedCeilingMib derivedOnly == 471
        && Ceiling.installedCeilingProvenance derivedOnly == Ceiling.CeilingFromArtifact
    )
    ( "Sprint 4.43: a ceiling derived from the artifact alone says so in its own "
        <> "provenance rather than implying a projection was consulted"
    )
  -- The prefix binds the installed quantity, not the derived one; installing a
  -- ceiling the projection widened and then rendering the narrower number would
  -- reintroduce the defect at the one site that matters.
  assert
    ( Ceiling.installedCeilingArgumentPrefix widened
        == ["/usr/bin/prlimit", "--data=531628032:531628032", "--"]
    )
    ( "Sprint 4.43: the launch prefix lowers both limits to the quantity actually "
        <> "installed"
    )
  -- The probe cannot be bounded by the quantity it exists to correct. Measured
  -- against the pinned payload, the upstream projection tool needs roughly 48
  -- MiB whatever model it is asked about, while a device-streaming placement's
  -- derived host term is the largest single tensor, which is 52 MiB for the row
  -- that produced this sprint and smaller for a smaller model.
  -- Phase 4 Sprint 4.43: a model is staged one of two ways and the cold-cache
  -- derivation has to read both. Asking only for the single-file `payload` key
  -- reported every snapshot-layout model as having no staged object at all,
  -- which named the wrong proposition: the object was there under a name this
  -- reader never asked for.
  assert
    ( Enforcer.selectStagedCheckpointKeyForTest
        ["llm-tinyllama-gguf/payload", "llm-tinyllama-gguf/.ready"]
        == Right "llm-tinyllama-gguf/payload"
    )
    "Sprint 4.43: the single-file staging layout still selects its payload object"
  assert
    ( Enforcer.selectStagedCheckpointKeyForTest
        [ "llm-smollm2-safetensors/config.json",
          "llm-smollm2-safetensors/model.safetensors",
          "llm-smollm2-safetensors/tokenizer.json",
          "llm-smollm2-safetensors/.ready"
        ]
        == Right "llm-smollm2-safetensors/model.safetensors"
    )
    ( "Sprint 4.43: a mirrored repository's checkpoint is selected among the "
        <> "upstream file names it was staged under"
    )
  assert
    ( isLeftResult (Enforcer.selectStagedCheckpointKeyForTest [])
        && isLeftResult
          ( Enforcer.selectStagedCheckpointKeyForTest
              ["audio-basic-pitch-onnx/model.onnx", "audio-basic-pitch-onnx/.ready"]
          )
    )
    ( "Sprint 4.43: an empty prefix and a prefix holding no readable checkpoint "
        <> "are both refusals, and they say different things"
    )
  -- The load-bearing negative: a sharded snapshot is refused rather than
  -- under-derived from one shard's tensor table.
  assert
    ( isLeftResult
        ( Enforcer.selectStagedCheckpointKeyForTest
            [ "llm-sharded/model-00001-of-00002.safetensors",
              "llm-sharded/model-00002-of-00002.safetensors"
            ]
        )
    )
    ( "Sprint 4.43: a sharded snapshot is refused, because a requirement summed "
        <> "from one shard understates the rest"
    )
  let probeCeiling = Ceiling.projectionProbeCeiling PodRam 52
  assert
    ( Ceiling.installedCeilingStrength probeCeiling == Ceiling.CeilingDetectionOnly
        && null (Ceiling.installedCeilingArgumentPrefix probeCeiling)
        && Ceiling.installedCeilingDerivedMib probeCeiling == 52
    )
    ( "Sprint 4.43: the projection probe installs nothing and still carries the "
        <> "quantity the plan would have installed"
    )

-- | Phase 4 Sprint 4.40 — the shared sampling kernel, driven over scripted
-- sample sequences with no platform branch, so both lanes' gate sets run the
-- same assertions. None of these decisions was reachable from a unit suite
-- while the loop lived inside conditional compilation, which is the mechanical
-- reason three copies of one algorithm were allowed to differ.
runSharedWatchdogLoopAssertions :: IO ()
runSharedWatchdogLoopAssertions = do
  breach <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      PodRam
      16
      2
      [Right (Just (24 * 1024 * 1024))]
      [Right 1]
  assert
    (breachOutcomeExceeds PodRam 16 breach)
    "Sprint 4.40: the shared loop breaches above its ceiling and names the resource"
  -- The ceiling is a bound the engine may reach, not one it may not touch:
  -- the loop breaches on @observed > ceiling@, so a sample landing exactly on
  -- it has to be survivable.
  --
  -- The outcome asserted is deliberately not @Nothing@. This harness cannot
  -- produce @Nothing@ at all: its target only reports termination once
  -- something has already recorded one, so an empty termination is
  -- unreachable and asserting it would be a test that can never pass. What
  -- distinguishes the boundary is *which* outcome ends the watch. Continuing
  -- past the at-ceiling sample lets the scripted group disappearance end it;
  -- had the comparison been @>=@, the first sample would have breached and
  -- this assertion would fail on a @CeilingBreached@ instead.
  atCeiling <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      PodRam
      16
      2
      [Right (Just (16 * 1024 * 1024)), Right Nothing]
      [Right 1]
  assert
    (enforcementUnavailableNames "no live group member" atCeiling)
    ( "Sprint 4.40: a sample exactly at the ceiling does not breach; the loop "
        <> "continues past it and only the scripted group disappearance ends the watch"
    )
  -- Phase 4 Sprint 4.44: the loop retains the highest complete observation it
  -- made, including observations that neither breach nor fail. A kernel-refused
  -- allocation is never resident, so this peak is the only observation such a
  -- refusal leaves behind, and a loop that discarded it would make the refusal
  -- undiagnosable from its own output.
  recordedPeak <-
    CappedEngineInternal.scriptedWatchdogPeakForTest
      PodRam
      64
      2
      [ Right (Just (12 * 1024 * 1024)),
        Right (Just (61 * 1024 * 1024)),
        Right (Just (30 * 1024 * 1024)),
        Right Nothing
      ]
      [Right 1]
  assert
    (recordedPeak == Just 61)
    ( "Sprint 4.44: the loop keeps the highest observation it made, not the last "
        <> "one, so a peak that has since fallen back is still reported"
    )
  noSamplePeak <-
    CappedEngineInternal.scriptedWatchdogPeakForTest
      PodRam
      64
      2
      [Right Nothing]
      [Right 1]
  assert
    (isNothing noSamplePeak)
    ( "Sprint 4.44: a loop that completed no observation records none, so a "
        <> "refusal cannot be classified from a peak that was never taken"
    )
  unreadable <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      PodRam
      16
      2
      [Left "scripted sampler could not read its evidence"]
      [Right 1]
  assert
    (enforcementUnavailableNames "could not read its evidence" unreadable)
    "Sprint 4.40: unreadable evidence is a terminal enforcement failure naming its reason"
  overMembers <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      PodRam
      4096
      2
      [Right (Just 1024)]
      [Right 5]
  assert
    ( enforcementUnavailableNames "5 live members" overMembers
        && enforcementUnavailableNames "2 its placement declares" overMembers
    )
    ( "Sprint 4.40: a group holding more members than its placement declared "
        <> "terminates as an enforcement failure naming both numbers"
    )
  absentGroup <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      PodRam
      4096
      2
      [Right Nothing]
      [Right 1]
  assert
    (enforcementUnavailableNames "no live group member" absentGroup)
    ( "Sprint 4.40: an absent group with a leader that never terminated settles "
        <> "and then fails closed"
    )
  deviceBreach <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      NvidiaVram
      64
      2
      [Right (Just (96 * 1024 * 1024))]
      [Right 1]
  assert
    (breachOutcomeExceeds NvidiaVram 64 deviceBreach)
    "Sprint 4.40: the same loop reports the device resource when it samples the device"
  hostBreach <-
    CappedEngineInternal.scriptedWatchdogOutcomeForTest
      HostRam
      64
      2
      [Right (Just (96 * 1024 * 1024))]
      [Right 1]
  assert
    (breachOutcomeExceeds HostRam 64 hostBreach)
    "Sprint 4.40: the same loop reports unified host RAM when it samples the Apple lane"

-- | Phase 4 Sprint 4.41 — the installed ceiling.
runInstalledCeilingAssertions :: IO ()
runInstalledCeilingAssertions = do
  let linuxCeiling =
        Ceiling.resolveEngineCeiling LinuxCpu PodRam 4096 Ceiling.NoEngineProjection
      appleCeiling =
        Ceiling.resolveEngineCeiling AppleSilicon HostRam 4096 Ceiling.NoEngineProjection
      linuxGpuHostCeiling =
        Ceiling.resolveEngineCeiling LinuxGpu PodRam 4096 Ceiling.NoEngineProjection
      deviceCeiling =
        Ceiling.resolveEngineCeiling LinuxGpu NvidiaVram 4096 Ceiling.NoEngineProjection
  assert
    ( Ceiling.installedCeilingArgumentPrefix linuxCeiling
        == ["/usr/bin/prlimit", "--data=4294967296:4294967296", "--"]
    )
    ( "Sprint 4.41: the launch prefix is exactly the pinned enforcement tool, "
        <> "both limits lowered to the admitted quantity, and the argument "
        <> "terminator"
    )
  assert
    (Ceiling.ceilingEnforcementTool == "/usr/bin/prlimit")
    "Sprint 4.41: the enforcement tool is a pinned absolute literal, not a manifest field"
  assert
    ( Ceiling.installedCeilingStrength linuxCeiling
        == Ceiling.CeilingInstalledDataSegment
    )
    "Sprint 4.41: the Linux lane installs a kernel data-segment ceiling"
  -- The Apple arm is total: no admitted quantity, on any lane pairing, makes it
  -- claim prevention.
  assert
    ( all
        ( \ceilingMib ->
            Ceiling.installedCeilingStrength
              ( Ceiling.resolveEngineCeiling
                  AppleSilicon
                  HostRam
                  ceilingMib
                  Ceiling.NoEngineProjection
              )
              == Ceiling.CeilingDetectionOnly
        )
        [1, 4096, 65536, 1048576]
    )
    "Sprint 4.41: no input makes the Apple arm claim prevention"
  assert
    (null (Ceiling.installedCeilingArgumentPrefix appleCeiling))
    "Sprint 4.41: a detection-only lane installs no launch prefix at all"
  assert
    ( Ceiling.installedCeilingStrength linuxGpuHostCeiling
        == Ceiling.CeilingInstalledDataSegment
        && Ceiling.installedCeilingArgumentPrefix linuxGpuHostCeiling
          == ["/usr/bin/prlimit", "--data=4294967296:4294967296", "--"]
    )
    ( "Sprint 6.51: the calibrated Linux GPU host lane declares prevention "
        <> "and installs the same closed data-segment prefix as Linux CPU"
    )
  assert
    ( isLeftResult
        ( Ceiling.requireCeilingStrength
            Ceiling.CeilingPreventionRequired
            (Ceiling.installedCeilingStrength appleCeiling)
        )
    )
    ( "Sprint 4.41: a prevention-required readiness contract refuses a lane "
        <> "that declares detection only"
    )
  assert
    ( all
        ((== Right ()) . Ceiling.validateRuntimeCeilingReadiness)
        [AppleSilicon, LinuxCpu, LinuxGpu]
    )
    ( "Sprint 4.41: each production runtime accepts exactly the strength its "
        <> "current calibrated contract requires"
    )
  -- The device column remains detection-only after the host column is
  -- calibrated; no absent device mechanism is promoted by the host result.
  assert
    (Ceiling.installedCeilingStrength deviceCeiling == Ceiling.CeilingDetectionOnly)
    ( "Sprint 6.51: no kernel mechanism bounds device memory on any lane, so "
        <> "the device column is admission and arena sizing plus detection"
    )
  assert
    (Ceiling.ceilingReadBackMatches linuxCeiling 4294967296 4294967296 == Right ())
    "Sprint 4.41: matching soft and hard read-back values proceed"
  assert
    ( isLeftResult (Ceiling.ceilingReadBackMatches linuxCeiling 4294967295 4294967296)
        && isLeftResult (Ceiling.ceilingReadBackMatches linuxCeiling 4294967296 8589934592)
    )
    ( "Sprint 4.41: either read-back value disagreeing with the installed "
        <> "quantity is a typed terminal failure"
    )
  assert
    (Ceiling.ceilingReadBackMatches appleCeiling 0 0 == Right ())
    "Sprint 4.41: a detection-only lane demands no read-back it cannot install"
  -- The capability-gating lint fires on an engine spawn that skips the region
  -- and passes a file that reaches it.
  assert
    ( not
        ( null
            ( unboundedCeilingInstallViolations
                "src/Infernix/Runtime/Daemon.hs"
                [(1, "      withCappedEngine watchdogs launch action")]
            )
        )
    )
    "Sprint 4.41: unboundedCeilingInstallViolations fires on a spawn that skips the region"
  assert
    ( null
        ( unboundedCeilingInstallViolations
            "src/Infernix/Runtime/Daemon.hs"
            [ (1, "      withEngineCeilingInstalled ceiling command $ \\launch ->"),
              (2, "        withCappedEngine watchdogs launch action")
            ]
        )
    )
    "Sprint 4.41: a spawn that reaches the installation region passes the lint"

-- | Phase 6 Sprint 6.52 — a restore-pending transaction whose subject
-- filesystem is gone must be reclaimable, and one whose subject is ours must
-- not be.
--
-- The reservation is durable while the config it describes is not: on the
-- container lane `/workspace` belongs to the image, so a killed launcher leaves
-- a record naming a config no host-side process can see. The retired arm refused
-- unconditionally, which made the slot unreclaimable by the supported
-- dead-owner path — found by executing the `linux-gpu` cohort.
runHarnessConfigRecoveryAssertions :: IO ()
runHarnessConfigRecoveryAssertions = do
  assert
    ( Cluster.classifyAbsentConfigRecovery Cluster.RecordedNamespaceIsForeign
        == Cluster.AbsentConfigReclaimable
    )
    ( "Sprint 6.52: a restore-pending transaction recorded in a foreign PID "
        <> "namespace is reclaimable, because its config and backup lived in a "
        <> "filesystem this process cannot see"
    )
  -- The two fail-closed arms are the point of the fix, not an afterthought: a
  -- reclamation rule that fired on our own namespace would silently swallow the
  -- operator's lost config, which is the failure the retired arm existed to
  -- prevent.
  assert
    (isUnrecoverableConfigRecovery Cluster.RecordedNamespaceMatches)
    ( "Sprint 6.52: a restore-pending transaction in our own namespace with "
        <> "both files absent is real config loss and stays fail-closed"
    )
  assert
    (isUnrecoverableConfigRecovery Cluster.RecordedNamespaceCannotBeCompared)
    ( "Sprint 6.52: a namespace that cannot be compared is not evidence the "
        <> "subject is foreign, so it stays fail-closed"
    )
  assert
    ( recoveryReasonMentions
        Cluster.RecordedNamespaceCannotBeCompared
        "cannot be compared"
    )
    "Sprint 6.52: the incomparable-namespace refusal names why it refused"

isUnrecoverableConfigRecovery :: Cluster.RecordedNamespaceRelation -> Bool
isUnrecoverableConfigRecovery relation =
  case Cluster.classifyAbsentConfigRecovery relation of
    Cluster.AbsentConfigUnrecoverable _ -> True
    Cluster.AbsentConfigReclaimable -> False

recoveryReasonMentions :: Cluster.RecordedNamespaceRelation -> String -> Bool
recoveryReasonMentions relation needle =
  case Cluster.classifyAbsentConfigRecovery relation of
    Cluster.AbsentConfigUnrecoverable reason -> needle `isInfixOf` reason
    Cluster.AbsentConfigReclaimable -> False

enforcementUnavailableNames :: String -> Maybe CappedEngineInternal.EngineOutcome -> Bool
enforcementUnavailableNames needle outcome =
  case outcome of
    Just (CappedEngineInternal.EngineEnforcementUnavailable reason) ->
      needle `isInfixOf` Text.unpack reason
    _ -> False

runClosureBoundAssertions :: IO ()
runClosureBoundAssertions = do
  let poetryClosureBytes =
        Provisioning.provisioningClosureBoundForTest
          Provisioning.PoetryClosureBytesBound
      poetryClosureFiles =
        Provisioning.provisioningClosureBoundForTest
          Provisioning.PoetryClosureFilesBound
      exactRuntimeFileBytes =
        Provisioning.provisioningClosureBoundForTest
          Provisioning.ExactRuntimeFileBytesBound
      stableCopyBytes =
        Provisioning.provisioningClosureBoundForTest
          Provisioning.StableCopyBytesBound
      machOInspectionBytes =
        Provisioning.provisioningClosureBoundForTest
          Provisioning.MachOInspectionBytesBound
      machORuntimeBytes =
        Provisioning.provisioningClosureBoundForTest
          Provisioning.MachORuntimeBytesBound
      measuredThinMachOHeader =
        machOThinHeaderForTest 28 3936
      fat32ArchitectureTable =
        BS.pack
          ( [0xca, 0xfe, 0xba, 0xbe]
              <> machOWord32BEForTest 2
              <> fat32ArchitectureForTest
                0x01000007
                4096
                8192
              <> fat32ArchitectureForTest
                0x0100000c
                16_777_216
                337_911_904
          )
      measuredFatMachOBytes =
        16_777_216 + 337_911_904
      oversizedLoadCommands =
        machOThinHeaderForTest 1 (4 * 1024 * 1024 + 1)
  assert
    ( poetryClosureBytes == 12 * 1024 * 1024 * 1024
        && poetryClosureFiles == 100000
        && exactRuntimeFileBytes == 2 * 1024 * 1024 * 1024
        && machOInspectionBytes == 4 * 1024 * 1024 * 1024
        && machORuntimeBytes == 4 * 1024 * 1024 * 1024
    )
    "Sprint 1.20: the closure bounds are the settled measured values"
  -- 'provisioningCopyFileStableBounded' refuses any bound greater than
  -- 'maximumStableCopyBytes', so the exact-runtime-file bound cannot be chosen
  -- independently of it. Pinning the equality is what keeps them moving
  -- together.
  assert
    (stableCopyBytes == exactRuntimeFileBytes)
    "Sprint 1.20: the exact-runtime-file bound and the stable-copy bound are the same value and must move together"
  -- The largest artifact measured on the Apple host, `coreml-native`: 1.345 GiB
  -- across 35,166 entries, 811.9 MiB of Mach-O images, largest single file
  -- 322.3 MiB. Every measured artifact must be admissible.
  assert
    ( Provisioning.admitPackageClosureFileForTest
        (1_444_000_000, 35_165)
        338_000_000
        == Right (1_782_000_000, 35_166)
    )
    "Sprint 1.20: the measured coreml-native closure and its largest single file are admitted"
  assert
    ( isLeft
        ( Provisioning.admitPackageClosureFileForTest
            (0, 0)
            (exactRuntimeFileBytes + 1)
        )
    )
    "Sprint 1.20: a single closure entry over the exact-runtime-file bound is refused"
  assert
    ( Provisioning.admitPackageClosureTotalsForTest
        (poetryClosureBytes - 1, 0)
        1
        == Right (poetryClosureBytes, 1)
        && isLeft
          ( Provisioning.admitPackageClosureTotalsForTest
              (poetryClosureBytes, 0)
              1
          )
    )
    "Sprint 1.20: the package-closure byte bound admits its exact total and refuses one byte more"
  assert
    ( Provisioning.admitPackageClosureTotalsForTest
        (0, poetryClosureFiles - 1)
        0
        == Right (0, poetryClosureFiles)
        && isLeft
          ( Provisioning.admitPackageClosureTotalsForTest
              (0, poetryClosureFiles)
              0
          )
    )
    "Sprint 1.20: the package-closure entry bound admits its exact total and refuses one entry more"
  assert
    (isLeft (Provisioning.admitPackageClosureTotalsForTest (0, 0) (-1)))
    "Sprint 1.20: a negative closure entry byte count is refused"
  assert
    ( Provisioning.planMachOMetadataReadsForTest
        337_911_904
        measuredThinMachOHeader
        Nothing
        == Right [(0, 3968)]
    )
    "Sprint 1.20: the measured 322.3 MiB libtorch_cpu image retains only its 3,968-byte thin Mach-O metadata table"
  assert
    ( Provisioning.planMachOMetadataReadsForTest
        measuredFatMachOBytes
        fat32ArchitectureTable
        (Just measuredThinMachOHeader)
        == Right
          [ (0, 48),
            (16_777_216, 3968)
          ]
    )
    "Sprint 1.20: a fat image reads only its bounded architecture table and the selected arm64 slice metadata"
  assert
    ( either
        (isInfixOf "load-command table exceeds its fixed bound")
        (const False)
        ( Provisioning.planMachOMetadataReadsForTest
            (4 * 1024 * 1024 + 64)
            oversizedLoadCommands
            Nothing
        )
        && either
          (isInfixOf "slice is out of bounds")
          (const False)
          ( Provisioning.planMachOMetadataReadsForTest
              (measuredFatMachOBytes - 1)
              fat32ArchitectureTable
              (Just measuredThinMachOHeader)
          )
    )
    "Sprint 1.20: oversized load-command metadata and an arm64 fat slice outside the exact image both fail closed"
  let measuredCoreMlClosure =
        Provisioning.MachOClosureDimensions
          { Provisioning.machOClosureLibraryCount = 480,
            Provisioning.machOClosureRuntimeBytes = 494_000_000,
            Provisioning.machOClosureEdges = 4000,
            Provisioning.machOClosureInspectionBytes = 852_000_000,
            Provisioning.machOClosureMetadataBytes = 3_000_000
          }
  assert
    ( Provisioning.admitMachOClosureDimensionsForTest measuredCoreMlClosure
        == Right ()
    )
    "Sprint 1.20: the measured coreml-native Mach-O closure is admitted on every dimension"
  assert
    ( refusedDimension
        "inspection byte"
        measuredCoreMlClosure
          { Provisioning.machOClosureInspectionBytes =
              machOInspectionBytes + 1
          }
        && refusedDimension
          "runtime byte"
          measuredCoreMlClosure
            { Provisioning.machOClosureRuntimeBytes = machORuntimeBytes + 1
            }
        && refusedDimension
          "runtime library count"
          measuredCoreMlClosure
            { Provisioning.machOClosureLibraryCount = 513
            }
    )
    "Sprint 1.20: each Mach-O closure dimension refuses its own overflow and names which dimension it was"

refusedDimension :: String -> Provisioning.MachOClosureDimensions -> Bool
refusedDimension dimension dimensions =
  case Provisioning.admitMachOClosureDimensionsForTest dimensions of
    Left failure -> dimension `isInfixOf` failure
    Right () -> False

machOThinHeaderForTest :: Integer -> Integer -> BS.ByteString
machOThinHeaderForTest commandCount commandBytes =
  BS.pack
    ( [0xcf, 0xfa, 0xed, 0xfe]
        <> machOWord32LEForTest 0x0100000c
        <> machOWord32LEForTest 0
        <> machOWord32LEForTest 6
        <> machOWord32LEForTest commandCount
        <> machOWord32LEForTest commandBytes
        <> machOWord32LEForTest 0
        <> machOWord32LEForTest 0
    )

fat32ArchitectureForTest :: Integer -> Integer -> Integer -> [Word8]
fat32ArchitectureForTest cpuType sliceOffset sliceBytes =
  machOWord32BEForTest cpuType
    <> machOWord32BEForTest 0
    <> machOWord32BEForTest sliceOffset
    <> machOWord32BEForTest sliceBytes
    <> machOWord32BEForTest 0

machOWord32LEForTest :: Integer -> [Word8]
machOWord32LEForTest value =
  [ fromIntegral ((value `shiftR` shift) .&. 0xff)
  | shift <- [0, 8, 16, 24]
  ]

machOWord32BEForTest :: Integer -> [Word8]
machOWord32BEForTest value =
  [ fromIntegral ((value `shiftR` shift) .&. 0xff)
  | shift <- [24, 16, 8, 0]
  ]

-- | Require a refusal and pin /why/ it was refused. An assertion that accepts
-- any failure passes for the wrong reason as readily as the right one.
refusedBecause :: String -> Either SomeException value -> Bool
refusedBecause expected outcome =
  case outcome of
    Left failure -> expected `isInfixOf` displayException failure
    Right _ -> False

-- | The observed refusal, quoted into the assertion message. A boundary
-- fixture that fails without naming what it saw cannot be diagnosed.
refusalDiagnostic :: Either SomeException value -> String
refusalDiagnostic outcome =
  case outcome of
    Left failure -> displayException failure
    Right _ -> "the effect was not refused at all"

-- | Sprint 1.20 writer-effect audit item 11 — the deterministic parent-swap
-- fixtures, at both effect boundaries the audit enumerates.
--
-- Every production writer effect is anchored on a parent descriptor that
-- 'withAuthorizedLeafParent' retains, rather than on the @FilePath@
-- @authorizedWriterPath@ returns. These assertions prove that anchoring by
-- planting an intermediate-parent swap in the exact window between the ancestry
-- check and the effect, and they include a pathname control so the
-- descriptor-anchored assertion is load-bearing rather than a tautology about
-- an untouched directory.
--
-- The excluded attack is redirection of an effect /outside/ the authority the
-- writer holds. A substitute that is itself a real directory inside the pinned
-- root is not that: mutating there is inside the writer's authority, and
-- concurrent writers are excluded by the exclusive materialization lock, not by
-- this boundary.
runWriterEffectParentSwapAssertions :: FilePath -> IO ()
runWriterEffectParentSwapAssertions testRoot = do
  let swapPaths =
        Paths
          { repoRoot = testRoot,
            buildRoot = testRoot </> ".build",
            dataRoot = testRoot </> ".data",
            runtimeRoot = testRoot </> ".data" </> "runtime",
            kindRoot = testRoot </> ".data" </> "kind",
            helmConfigRoot = testRoot </> ".data" </> "helm" </> "config",
            helmCacheRoot = testRoot </> ".data" </> "helm" </> "cache",
            helmDataRoot = testRoot </> ".data" </> "helm" </> "data",
            resultsRoot = testRoot </> ".data" </> "results",
            modelCacheRoot = testRoot </> ".data" </> "model-cache",
            pathsHostConfig =
              Just (HostConfig.defaultLinuxOuterContainerHostConfig "/root"),
            pathsHostConfigPath = Nothing
          }
      enginesRoot = dataRoot swapPaths </> "engines"
  removePathForcibly testRoot
  createDirectoryIfMissing True enginesRoot
  swapEnvironment <- Subprocess.clusterSubprocessEnv swapPaths
  let withSwapWriter ::
        forall swapResult.
        ( forall w s q.
          Provisioning.EngineWriter w s q ->
          Provisioning.ProvisioningSession s swapResult
        ) ->
        IO swapResult
      withSwapWriter action =
        Provisioning.withEngineProvisioningSession
          swapPaths
          enginesRoot
          swapEnvironment
          (\writer _grant -> action writer)
  runDirectWriteParentSwapAssertions testRoot enginesRoot withSwapWriter
  runRootMutationInterpreterAssertions testRoot enginesRoot withSwapWriter
  runExternalToolParentSwapAssertions testRoot swapEnvironment

-- | Boundary one: a direct in-process write effect.
runDirectWriteParentSwapAssertions ::
  FilePath ->
  FilePath ->
  ( forall swapResult.
    ( forall w s q.
      Provisioning.EngineWriter w s q ->
      Provisioning.ProvisioningSession s swapResult
    ) ->
    IO swapResult
  ) ->
  IO ()
runDirectWriteParentSwapAssertions testRoot enginesRoot withSwapWriter = do
  let fixtureRoot = enginesRoot </> "direct-write-swap"
      retainedParent = fixtureRoot </> "parent"
      detachedParent = fixtureRoot </> "parent-detached"
      substituteParent = fixtureRoot </> "parent-substitute"
      leafName = "target"
      anchoredBytes = ByteString8.pack "descriptor-anchored"
  createDirectoryIfMissing True retainedParent
  swapEntered <- MVar.newEmptyMVar
  swapResume <- MVar.newEmptyMVar
  swapResult <- MVar.newEmptyMVar
  _ <-
    forkIO $
      ( try @SomeException $
          withSwapWriter $ \writer ->
            Provisioning.provisioningWriteBytesWithParentSwapPauseForTest
              writer
              (retainedParent </> leafName)
              anchoredBytes
              swapEntered
              swapResume
      )
        >>= MVar.putMVar swapResult
  -- The writer has validated the ancestry and is holding the retained parent
  -- descriptor. This is the window a pathname-resolving writer loses.
  MVar.takeMVar swapEntered
  renameDirectory retainedParent detachedParent
  createDirectoryIfMissing True substituteParent
  renameDirectory substituteParent retainedParent
  MVar.putMVar swapResume ()
  anchoredOutcome <- MVar.takeMVar swapResult
  detachedContents <-
    try @IOException (BS.readFile (detachedParent </> leafName))
  substituteLeafPresent <- doesPathExist (retainedParent </> leafName)
  assert
    ( isRight anchoredOutcome
        && detachedContents == Right anchoredBytes
        && not substituteLeafPresent
    )
    "Sprint 1.20 item 11: a direct writer effect follows its retained parent descriptor across an intermediate-parent swap and never reaches the substitute"
  let controlRoot = testRoot </> "pathname-control"
      controlParent = controlRoot </> "parent"
      controlDetached = controlRoot </> "parent-detached"
      controlSubstitute = controlRoot </> "parent-substitute"
      controlBytes = ByteString8.pack "pathname-resolved"
  createDirectoryIfMissing True controlParent
  controlAncestryValid <- doesDirectoryExist controlParent
  renameDirectory controlParent controlDetached
  createDirectoryIfMissing True controlSubstitute
  renameDirectory controlSubstitute controlParent
  BS.writeFile (controlParent </> leafName) controlBytes
  controlSubstituteContents <- BS.readFile (controlParent </> leafName)
  controlDetachedPresent <- doesPathExist (controlDetached </> leafName)
  assert
    ( controlAncestryValid
        && controlSubstituteContents == controlBytes
        && not controlDetachedPresent
    )
    "Sprint 1.20 item 11: the same swap redirects a pathname-resolving write into the substitute, so the retained-descriptor assertion is load-bearing"
  let escapeFixtureRoot = enginesRoot </> "direct-write-escape"
      escapedParent = escapeFixtureRoot </> "parent"
      escapeTarget = testRoot </> "direct-write-escape-target"
  createDirectoryIfMissing True escapeFixtureRoot
  createDirectoryIfMissing True escapeTarget
  createSymbolicLink escapeTarget escapedParent
  escapeOutcome <-
    try @SomeException $
      withSwapWriter $ \writer ->
        Provisioning.provisioningWriteBytes
          writer
          (escapedParent </> leafName)
          (ByteString8.pack "escaped")
  escapeTargetPresent <- doesPathExist (escapeTarget </> leafName)
  -- The refusal must come from resolving the swapped component /through the
  -- retained parent descriptor/ with @nofollow@, not from a pathname probe.
  -- Darwin answers @ENOTDIR@ and Linux answers @ELOOP@ for the same open, so
  -- the mechanism and the component are pinned rather than the errno text.
  assert
    ( refusedBecause "openFdAt" escapeOutcome
        && refusedBecause "parent" escapeOutcome
        && not escapeTargetPresent
    )
    ( "Sprint 1.20 item 11: an intermediate parent replaced by a symbolic link out of the writer root is refused without touching its target; observed: "
        <> refusalDiagnostic escapeOutcome
    )

-- | Boundary one, continued: the production root-mutation interpreter, which
-- @infernix-artifact-transaction@ deliberately does not exercise.
runRootMutationInterpreterAssertions ::
  FilePath ->
  FilePath ->
  ( forall swapResult.
    ( forall w s q.
      Provisioning.EngineWriter w s q ->
      Provisioning.ProvisioningSession s swapResult
    ) ->
    IO swapResult
  ) ->
  IO ()
runRootMutationInterpreterAssertions testRoot enginesRoot withSwapWriter = do
  let mutationFixtureRoot = enginesRoot </> "root-mutation"
      mutationSource = mutationFixtureRoot </> "generation.tmp"
      mutationDestination = mutationFixtureRoot </> "generation"
      mutationNested = mutationFixtureRoot </> "nested"
      outsideRoot = testRoot </> "root-mutation-outside"
  createDirectoryIfMissing True mutationSource
  createDirectoryIfMissing True (mutationNested </> "generation.tmp")
  createDirectoryIfMissing True outsideRoot
  withSwapWriter $ \writer ->
    Provisioning.provisioningInterpretArtifactRootMutationForTest
      writer
      ( ArtifactInternal.RenameArtifactRootSibling
          mutationSource
          mutationDestination
      )
  renamedPresent <- doesDirectoryExist mutationDestination
  renameSourcePresent <- doesPathExist mutationSource
  assert
    (renamedPresent && not renameSourcePresent)
    "Sprint 1.20 item 11: the production root-mutation interpreter renames an authorized sibling through the descriptor-anchored kernel"
  nonSiblingOutcome <-
    try @SomeException $
      withSwapWriter $ \writer ->
        Provisioning.provisioningInterpretArtifactRootMutationForTest
          writer
          ( ArtifactInternal.RenameArtifactRootSibling
              (mutationNested </> "generation.tmp")
              mutationDestination
          )
  assert
    ( refusedBecause
        "artifact root rename operands are not siblings"
        nonSiblingOutcome
    )
    ( "Sprint 1.20 item 11: the production root-mutation interpreter refuses a rename whose operands do not share a parent; observed: "
        <> refusalDiagnostic nonSiblingOutcome
    )
  escapedOutcome <-
    try @SomeException $
      withSwapWriter $ \writer ->
        Provisioning.provisioningInterpretArtifactRootMutationForTest
          writer
          ( ArtifactInternal.RemoveArtifactRootSibling
              (outsideRoot </> "generation")
          )
  outsideStillPresent <- doesDirectoryExist outsideRoot
  assert
    ( refusedBecause "escaped its authorized" escapedOutcome
        && outsideStillPresent
    )
    ( "Sprint 1.20 item 11: the production root-mutation interpreter refuses an operand outside its authorized writer root; observed: "
        <> refusalDiagnostic escapedOutcome
    )
  let linkedParent = mutationFixtureRoot </> "linked"
  createSymbolicLink outsideRoot linkedParent
  createDirectoryIfMissing True (outsideRoot </> "generation")
  linkedOutcome <-
    try @SomeException $
      withSwapWriter $ \writer ->
        Provisioning.provisioningInterpretArtifactRootMutationForTest
          writer
          ( ArtifactInternal.RemoveArtifactRootSibling
              (linkedParent </> "generation")
          )
  linkedTargetPresent <- doesDirectoryExist (outsideRoot </> "generation")
  -- @authorizedWriterRelativeComponents@ validates containment /lexically/, so
  -- @linked/generation@ is inside the root by string and passes it. The escape
  -- is refused one layer down, by the isolated mutation target's own
  -- @nofollow@ component walk. That is the layer this audit item is about, so
  -- it is the layer the assertion pins.
  assert
    ( refusedBecause
        "provisioning mutation parent component is not a real directory"
        linkedOutcome
        && linkedTargetPresent
    )
    ( "Sprint 1.20 item 11: the production root-mutation interpreter refuses an intermediate parent swapped for a symbolic link out of the writer root; observed: "
        <> refusalDiagnostic linkedOutcome
    )
  withSwapWriter $ \writer ->
    Provisioning.provisioningInterpretArtifactRootMutationForTest
      writer
      (ArtifactInternal.RemoveArtifactRootSibling mutationDestination)
  removedPresent <- doesPathExist mutationDestination
  assert
    (not removedPresent)
    "Sprint 1.20 item 11: the production root-mutation interpreter retires an authorized root through one bounded descriptor-anchored kernel call"

-- | Boundary two: an external-tool effect, whose target enters a retained
-- descriptor by @fchdir@ and then names only relative operands.
runExternalToolParentSwapAssertions ::
  FilePath ->
  Subprocess.SubprocessEnv ->
  IO ()
runExternalToolParentSwapAssertions testRoot swapEnvironment = do
  let kernelRoot = testRoot </> "kernel-root"
      kernelDetached = testRoot </> "kernel-root-detached"
      kernelSubstitute = testRoot </> "kernel-root-substitute"
      linkRoot = testRoot </> "kernel-link-root"
      linkOutside = testRoot </> "kernel-link-outside"
      mutationTimeout = Subprocess.Timeout (120 * 1000 * 1000)
  createDirectoryIfMissing True kernelRoot
  observedRoot <-
    Subprocess.observeProvisioningMutationRoot kernelRoot
      >>= either
        (\outcome -> fail ("mutation root observation failed: " <> show outcome))
        pure
  -- The exact device, inode, and mode are now pinned. Swap the pathname the
  -- isolated mutation target will open.
  renameDirectory kernelRoot kernelDetached
  createDirectoryIfMissing True kernelSubstitute
  renameDirectory kernelSubstitute kernelRoot
  rootSwapOutcome <-
    either
      (\outcome -> fail ("mutation spec rejected: " <> show outcome))
      (Subprocess.runProvisioningFilesystemMutation swapEnvironment mutationTimeout)
      ( Subprocess.provisioningCreateDirectoryLeaf
          observedRoot
          []
          "leaf"
      )
  substituteLeafPresent <- doesPathExist (kernelRoot </> "leaf")
  detachedLeafPresent <- doesPathExist (kernelDetached </> "leaf")
  assert
    ( rootSwapOutcome /= Subprocess.ProvisioningMutationSucceeded
        && not substituteLeafPresent
        && not detachedLeafPresent
    )
    "Sprint 1.20 item 11: the external-tool mutation kernel refuses a root swapped after its exact identity was observed"
  createDirectoryIfMissing True linkRoot
  createDirectoryIfMissing True linkOutside
  createSymbolicLink linkOutside (linkRoot </> "parent")
  observedLinkRoot <-
    Subprocess.observeProvisioningMutationRoot linkRoot
      >>= either
        (\outcome -> fail ("mutation root observation failed: " <> show outcome))
        pure
  componentSwapOutcome <-
    either
      (\outcome -> fail ("mutation spec rejected: " <> show outcome))
      (Subprocess.runProvisioningFilesystemMutation swapEnvironment mutationTimeout)
      ( Subprocess.provisioningCreateDirectoryLeaf
          observedLinkRoot
          ["parent"]
          "leaf"
      )
  linkOutsideLeafPresent <- doesPathExist (linkOutside </> "leaf")
  assert
    ( componentSwapOutcome /= Subprocess.ProvisioningMutationSucceeded
        && not linkOutsideLeafPresent
    )
    "Sprint 1.20 item 11: the external-tool mutation kernel refuses an intermediate component swapped for a symbolic link and leaves its target untouched"
  assert
    ( Subprocess.safeRelativeOperandForTest
        "/work/dir"
        "/work/dir/Audiveris.dmg"
        == Right "Audiveris.dmg"
        && Subprocess.safeRelativeOperandForTest
          "/work/dir"
          "/work/dir/mount/Audiveris.dmg"
          == Right ("mount" </> "Audiveris.dmg")
        && isLeft
          ( Subprocess.safeRelativeOperandForTest
              "/work/dir"
              "/work/other/Audiveris.dmg"
          )
        && isLeft (Subprocess.safeRelativeOperandForTest "/work/dir" "/work")
        && isLeft (Subprocess.safeRelativeOperandForTest "/work/dir" "/work/dir")
        && isLeft
          ( Subprocess.safeRelativeOperandForTest
              "/work/dir"
              "Audiveris.dmg"
          )
        && isLeft
          ( Subprocess.safeRelativeOperandForTest
              "work/dir"
              "/work/dir/Audiveris.dmg"
          )
    )
    "Sprint 1.20 item 11: a rendered external-tool operand must be a safe descendant of its descriptor-derived working directory"

-- | A standalone new-format cache with two entries. The forty-eight byte
-- header and twenty-four byte entries are the layout glibc writes, and the
-- string offsets are relative to the start of that header.
newFormatLdSoCache :: BS.ByteString
newFormatLdSoCache =
  BS.concat
    [ ByteString8.pack "glibc-ld.so.cache1.1",
      elfLe 4 2, -- nlibs
      elfLe 4 (fromIntegral (BS.length newCacheStrings)),
      BS.replicate 20 0, -- flags, padding, extension offset, unused
      -- Offsets are relative to this header, not to the file, which is what
      -- makes the embedded arrangement below work unchanged.
      newCacheEntry 96 106,
      newCacheEntry 139 149,
      newCacheStrings
    ]

newCacheEntry :: Integer -> Integer -> BS.ByteString
newCacheEntry key value =
  BS.concat
    [ elfLe 4 1, -- flags
      elfLe 4 key,
      elfLe 4 value,
      elfLe 4 0, -- osversion
      elfLe 8 0 -- hwcap
    ]

newCacheStrings :: BS.ByteString
newCacheStrings =
  BS.concat
    [ nulTerminated "libc.so.6",
      nulTerminated "/lib/aarch64-linux-gnu/libc.so.6",
      nulTerminated "libm.so.6",
      nulTerminated "/lib/aarch64-linux-gnu/libm.so.6"
    ]

oldFormatLdSoCache :: BS.ByteString
oldFormatLdSoCache =
  BS.concat
    [ ByteString8.pack "ld.so-1.7.0",
      BS.singleton 0,
      elfLe 4 1, -- nlibs
      elfLe 4 1, -- flags
      elfLe 4 0, -- key offset, relative to the string base
      elfLe 4 10, -- value offset
      nulTerminated "libz.so.1",
      nulTerminated "/usr/lib/libz.so.1"
    ]

-- | The arrangement modern glibc actually writes: an old-format cache whose
-- entries are followed, at the next eight-byte boundary, by a complete
-- new-format cache. The new cache's own offsets are relative to its header,
-- which is why the embedded case cannot reuse the file start.
embeddedNewFormatLdSoCache :: BS.ByteString
embeddedNewFormatLdSoCache =
  BS.concat
    [ ByteString8.pack "ld.so-1.7.0",
      BS.singleton 0,
      elfLe 4 1, -- nlibs
      elfLe 4 1,
      elfLe 4 0,
      elfLe 4 10,
      BS.replicate 4 0, -- pad 28 -> 32
      newFormatLdSoCache
    ]

-- | Sprint 1.20: the generation identity a helper re-derives is lane-specific.
--
-- The superseded supervisor check asserted
-- @generationFingerprint == payloadDigest@ for every pre-manifest candidate.
-- That is only the @apple-silicon@ branch of
-- 'ArtifactInternal.engineArtifactGenerationFingerprint'. A @linux-native@
-- generation additionally binds the recipe, the closed target contract, and the
-- descriptor-derived image evidence, because a Linux metadata root deliberately
-- does not contain the image-owned payload it executes. Its identity is
-- therefore never its own payload digest, so the superseded assertion refused
-- every Linux generation that could ever exist and the Linux native smoke could
-- not pass on any input.
--
-- These assertions discriminate against that source: the first pins the Apple
-- construction the old check encoded, and the second pins that the same check
-- is unsatisfiable on the Linux lane. The remaining two pin that the two inputs
-- the payload digest does not cover are genuinely bound.
runArtifactGenerationIdentityAssertions :: IO ()
runArtifactGenerationIdentityAssertions = do
  let payloadDigest = canonicalTestDigest 'a'
      recipeFingerprint = canonicalTestDigest 'b'
      targetContractFingerprint = canonicalTestDigest 'c'
      evidence contract executableDigest =
        ArtifactTarget.NativeArtifactTargetEvidence
          { ArtifactTarget.targetEvidenceContractFingerprint = contract,
            ArtifactTarget.targetEvidenceExecutable =
              ArtifactTarget.NativeArtifactTargetExecutableEvidence
                { ArtifactTarget.targetExecutableConfiguredPath =
                    "/opt/infernix/native-payloads/llama.cpp/llama-cli",
                  ArtifactTarget.targetExecutableConfiguredDeviceId = 64,
                  ArtifactTarget.targetExecutableConfiguredFileId = 1234,
                  ArtifactTarget.targetExecutableConfiguredMode = 0o100755,
                  ArtifactTarget.targetExecutableConfiguredSize = 4096,
                  ArtifactTarget.targetExecutableCanonicalPath =
                    "/opt/infernix/native-payloads/llama.cpp/llama-cli",
                  ArtifactTarget.targetExecutableCanonicalDeviceId = 64,
                  ArtifactTarget.targetExecutableCanonicalFileId = 1234,
                  ArtifactTarget.targetExecutableCanonicalMode = 0o100755,
                  ArtifactTarget.targetExecutableCanonicalSize = 4096,
                  ArtifactTarget.targetExecutableDigest = executableDigest
                },
            ArtifactTarget.targetEvidenceClosures = [],
            ArtifactTarget.targetEvidenceLoader = Nothing
          }
      appleIdentity =
        ArtifactInternal.engineArtifactGenerationFingerprint
          "apple-silicon"
          payloadDigest
          recipeFingerprint
          targetContractFingerprint
          Nothing
      linuxIdentityWith recipe executableDigest =
        ArtifactInternal.engineArtifactGenerationFingerprint
          "linux-native"
          payloadDigest
          recipe
          targetContractFingerprint
          (Just (evidence targetContractFingerprint executableDigest))
      linuxIdentity =
        linuxIdentityWith recipeFingerprint (canonicalTestDigest 'd')
      originalEvidence = evidence targetContractFingerprint (canonicalTestDigest 'd')
      unusedCache digest =
        ArtifactTarget.NativeArtifactLoaderEvidence
          { ArtifactTarget.loaderEvidenceEntryObject =
              "/opt/infernix/native-payloads/llama.cpp/llama-cli",
            ArtifactTarget.loaderEvidenceCache =
              Just
                ArtifactTarget.NativeArtifactLoaderFileEvidence
                  { ArtifactTarget.loaderFileConfiguredPath = "/etc/ld.so.cache",
                    ArtifactTarget.loaderFileConfiguredDeviceId = 64,
                    ArtifactTarget.loaderFileConfiguredFileId = 2222,
                    ArtifactTarget.loaderFileConfiguredMode = 0o100644,
                    ArtifactTarget.loaderFileConfiguredSize = 4096,
                    ArtifactTarget.loaderFileCanonicalPath = "/etc/ld.so.cache",
                    ArtifactTarget.loaderFileCanonicalDeviceId = 64,
                    ArtifactTarget.loaderFileCanonicalFileId = 2222,
                    ArtifactTarget.loaderFileCanonicalMode = 0o100644,
                    ArtifactTarget.loaderFileCanonicalSize = 4096,
                    ArtifactTarget.loaderFileDigest = digest
                  },
            ArtifactTarget.loaderEvidenceObjects = [],
            ArtifactTarget.loaderEvidenceResolutions = [],
            ArtifactTarget.loaderEvidenceMaximumDepth = 0
          }
      originalEvidenceWithUnusedCache =
        originalEvidence
          { ArtifactTarget.targetEvidenceLoader =
              Just (unusedCache (canonicalTestDigest '1'))
          }
      unpackedEvidence =
        originalEvidenceWithUnusedCache
          { ArtifactTarget.targetEvidenceExecutable =
              (ArtifactTarget.targetEvidenceExecutable originalEvidence)
                { ArtifactTarget.targetExecutableConfiguredDeviceId = 91,
                  ArtifactTarget.targetExecutableConfiguredFileId = 5678,
                  ArtifactTarget.targetExecutableCanonicalDeviceId = 91,
                  ArtifactTarget.targetExecutableCanonicalFileId = 5678
                },
            ArtifactTarget.targetEvidenceLoader =
              Just (unusedCache (canonicalTestDigest '2'))
          }
  assert
    (appleIdentity == Right payloadDigest)
    "Sprint 1.20: an apple-silicon generation identity is exactly its payload digest"
  assert
    ( ArtifactInternal.portableImageTargetEvidenceForTest originalEvidenceWithUnusedCache
        == ArtifactInternal.portableImageTargetEvidenceForTest unpackedEvidence
    )
    "Sprint 1.20: OCI-assigned device/inode and unused loader-cache changes do not invalidate portable image evidence"
  -- Phase 6 Sprint 6.50. The case above is an *unused* cache. The `linux-gpu`
  -- cohort hit the used one: the NVIDIA container runtime runs `ldconfig` at
  -- container start to register the driver libraries it injects, so a GPU
  -- engine pod sees a different `/etc/ld.so.cache` — different digest, different
  -- size, and shifted entry ordinals — than the image the artifact was baked in,
  -- and every native artifact whose closure resolved through the cache was
  -- rejected. What must survive that rewrite is the artifact's own identity;
  -- what must not survive is a soname resolving somewhere else, or the same
  -- path holding different bytes.
  let cacheUsingLoader cacheDigest cacheSize entryIndex resolvedPath objectDigest =
        ArtifactTarget.NativeArtifactLoaderEvidence
          { ArtifactTarget.loaderEvidenceEntryObject =
              "/opt/infernix/native-payloads/llama.cpp/llama-completion",
            ArtifactTarget.loaderEvidenceCache =
              Just
                ArtifactTarget.NativeArtifactLoaderFileEvidence
                  { ArtifactTarget.loaderFileConfiguredPath = "/etc/ld.so.cache",
                    ArtifactTarget.loaderFileConfiguredDeviceId = 66,
                    ArtifactTarget.loaderFileConfiguredFileId = 3333,
                    ArtifactTarget.loaderFileConfiguredMode = 0o100644,
                    ArtifactTarget.loaderFileConfiguredSize = cacheSize,
                    ArtifactTarget.loaderFileCanonicalPath = "/etc/ld.so.cache",
                    ArtifactTarget.loaderFileCanonicalDeviceId = 66,
                    ArtifactTarget.loaderFileCanonicalFileId = 3333,
                    ArtifactTarget.loaderFileCanonicalMode = 0o100644,
                    ArtifactTarget.loaderFileCanonicalSize = cacheSize,
                    ArtifactTarget.loaderFileDigest = cacheDigest
                  },
            ArtifactTarget.loaderEvidenceObjects =
              [ ArtifactTarget.NativeArtifactLoaderObjectEvidence
                  { ArtifactTarget.loaderObjectConfiguredPath = resolvedPath,
                    ArtifactTarget.loaderObjectConfiguredDeviceId = 66,
                    ArtifactTarget.loaderObjectConfiguredFileId = 4444,
                    ArtifactTarget.loaderObjectConfiguredMode = 0o100644,
                    ArtifactTarget.loaderObjectConfiguredSize = 2048,
                    ArtifactTarget.loaderObjectCanonicalPath = resolvedPath,
                    ArtifactTarget.loaderObjectCanonicalDeviceId = 66,
                    ArtifactTarget.loaderObjectCanonicalFileId = 4444,
                    ArtifactTarget.loaderObjectCanonicalMode = 0o100644,
                    ArtifactTarget.loaderObjectCanonicalSize = 2048,
                    ArtifactTarget.loaderObjectDigest = objectDigest,
                    ArtifactTarget.loaderObjectClassBits = 64,
                    ArtifactTarget.loaderObjectEndian = "little",
                    ArtifactTarget.loaderObjectMachine = 62,
                    ArtifactTarget.loaderObjectInterpreter = Nothing,
                    ArtifactTarget.loaderObjectSoname = Just "libm.so.6",
                    ArtifactTarget.loaderObjectNeeded = [],
                    ArtifactTarget.loaderObjectRPath = [],
                    ArtifactTarget.loaderObjectRunPath = []
                  }
              ],
            ArtifactTarget.loaderEvidenceResolutions =
              [ ArtifactTarget.NativeArtifactLoaderResolutionEvidence
                  { ArtifactTarget.loaderResolutionRequester =
                      "/opt/infernix/native-payloads/llama.cpp/llama-completion",
                    ArtifactTarget.loaderResolutionNeeded = "libm.so.6",
                    ArtifactTarget.loaderResolutionSearchDirectories = ["/lib/x86_64-linux-gnu"],
                    ArtifactTarget.loaderResolutionUsedCache = True,
                    ArtifactTarget.loaderResolutionCacheEntryIndex = Just entryIndex,
                    ArtifactTarget.loaderResolutionConfiguredPath = resolvedPath,
                    ArtifactTarget.loaderResolutionCanonicalPath = resolvedPath
                  }
              ],
            ArtifactTarget.loaderEvidenceMaximumDepth = 1
          }
      withLoader loader =
        originalEvidence {ArtifactTarget.targetEvidenceLoader = Just loader}
      bakedLoader =
        cacheUsingLoader
          (canonicalTestDigest '1')
          43851
          17
          "/lib/x86_64-linux-gnu/libm.so.6"
          (canonicalTestDigest 'a')
      -- The same artifact observed inside a pod the NVIDIA runtime prepared.
      injectedLoader =
        cacheUsingLoader
          (canonicalTestDigest '2')
          47027
          42
          "/lib/x86_64-linux-gnu/libm.so.6"
          (canonicalTestDigest 'a')
      relocatedLoader =
        cacheUsingLoader
          (canonicalTestDigest '2')
          47027
          42
          "/opt/impostor/libm.so.6"
          (canonicalTestDigest 'a')
      substitutedLoader =
        cacheUsingLoader
          (canonicalTestDigest '2')
          47027
          42
          "/lib/x86_64-linux-gnu/libm.so.6"
          (canonicalTestDigest 'b')
  assert
    ( ArtifactInternal.portableImageTargetEvidenceForTest (withLoader bakedLoader)
        == ArtifactInternal.portableImageTargetEvidenceForTest (withLoader injectedLoader)
    )
    "Sprint 6.50: an injected-driver ld.so.cache rewrite does not invalidate an unchanged artifact"
  assert
    ( ArtifactInternal.portableImageTargetEvidenceForTest (withLoader bakedLoader)
        /= ArtifactInternal.portableImageTargetEvidenceForTest (withLoader relocatedLoader)
    )
    "Sprint 6.50: a soname that resolves to a different path still fails closed"
  assert
    ( ArtifactInternal.portableImageTargetEvidenceForTest (withLoader bakedLoader)
        /= ArtifactInternal.portableImageTargetEvidenceForTest (withLoader substitutedLoader)
    )
    "Sprint 6.50: the same resolved path holding different bytes still fails closed"
  assert
    (linuxIdentity /= Right payloadDigest)
    "Sprint 1.20: a linux-native generation identity is never its payload digest, so the superseded candidate equality refused every Linux generation"
  assert
    (either (const False) isCanonicalSha256Text linuxIdentity)
    "Sprint 1.20: a linux-native generation identity is a canonical sha256"
  assert
    (linuxIdentityWith (canonicalTestDigest 'e') (canonicalTestDigest 'd') /= linuxIdentity)
    "Sprint 1.20: the linux-native generation identity binds the recipe fingerprint the payload digest cannot cover"
  assert
    (linuxIdentityWith recipeFingerprint (canonicalTestDigest 'f') /= linuxIdentity)
    "Sprint 1.20: the linux-native generation identity binds the observed image-target evidence"
  assert
    ( isLeft
        ( ArtifactInternal.engineArtifactGenerationFingerprint
            "linux-native"
            payloadDigest
            recipeFingerprint
            targetContractFingerprint
            Nothing
        )
    )
    "Sprint 1.20: a linux-native generation without image-target evidence fails closed"
  assert
    ( isLeft
        ( ArtifactInternal.engineArtifactGenerationFingerprint
            "apple-silicon"
            payloadDigest
            recipeFingerprint
            targetContractFingerprint
            (Just (evidence targetContractFingerprint (canonicalTestDigest 'd')))
        )
    )
    "Sprint 1.20: an apple-silicon generation carrying image-target evidence fails closed"
  assert
    ( isLeft
        ( ArtifactInternal.engineArtifactGenerationFingerprint
            "linux-native"
            payloadDigest
            recipeFingerprint
            targetContractFingerprint
            (Just (evidence (canonicalTestDigest 'e') (canonicalTestDigest 'd')))
        )
    )
    "Sprint 1.20: evidence disagreeing with its closed target contract fails closed"

canonicalTestDigest :: Char -> Text.Text
canonicalTestDigest filler = "sha256:" <> Text.replicate 64 (Text.singleton filler)

isCanonicalSha256Text :: Text.Text -> Bool
isCanonicalSha256Text value =
  Text.isPrefixOf "sha256:" value && Text.length value == 71

-- | The Audiveris invocation declines JavaCPP symbolic-link creation.
--
-- JavaCPP owns one cross-jar alias inside its configured cache and re-establishes
-- it on every load: it rewrites a relative target to the absolute cache path,
-- deletes a regular file and replaces it with that link, re-creates the link when
-- absent, and — when it cannot write the cache at all — does not fail but escapes
-- to the operator's @~\/.javacpp\/cache@ and loads from there. Its one fixed point
-- therefore names whichever root the payload currently occupies, and this artifact
-- is smoked once at the candidate root and again after it is renamed onto its
-- final root, so no single spelling satisfies both.
--
-- Declining the alias removes the conflict instead of choosing a side: dyld never
-- traverses it, because every library loads from its own extracted jar directory.
-- The flag has to reach every producer, not just the shared consumer helper — the
-- two runs that actually create the caches are the Apple pre-extraction command
-- and the Linux image build, and a cache populated under a different JavaCPP
-- configuration than its consumer is a payload the first consumer rewrites.
runAudiverisJavaCppArgumentAssertions :: IO ()
runAudiverisJavaCppArgumentAssertions = do
  let appleRoot = "/work/.data/engines/jvm-native"
      appleArguments = ArtifactTarget.audiverisAppleLeadingArguments appleRoot
      linuxArguments = ArtifactTarget.audiverisLinuxImageLeadingArguments
      cacheRoot = appleRoot </> "javacpp-cache"
      linkPath =
        cacheRoot
          </> "tesseract-5.5.1-1.5.12-macosx-arm64.jar"
          </> "org"
          </> "bytedeco"
          </> "tesseract"
          </> "macosx-arm64"
          </> "libleptonica.6.dylib"
  assert
    ( appleArguments
        == [ "-Dorg.bytedeco.javacpp.cachedir=" <> cacheRoot,
             ArtifactTarget.audiverisJavaCppSymbolicLinkArgument,
             "-cp",
             appleRoot </> "Audiveris.app" </> "Contents" </> "app" </> "*",
             "Audiveris"
           ]
        && linuxArguments
          == [ "-Dorg.bytedeco.javacpp.cachedir="
                 <> ArtifactTarget.audiverisLinuxImageJavaCppCacheDirectory,
               ArtifactTarget.audiverisJavaCppSymbolicLinkArgument,
               "-cp",
               ArtifactTarget.audiverisLinuxImageApplicationClasspath,
               "Audiveris"
             ]
    )
    "Sprint 1.20: both Audiveris lanes render the same closed property set and decline JavaCPP symbolic-link creation"
  assert
    ( ArtifactTarget.audiverisJavaCppSymbolicLinkArgument
        == "-Dorg.bytedeco.javacpp.canCreateSymbolicLink=false"
    )
    "Sprint 1.20: the JavaCPP symbolic-link property is the exact upstream spelling"
  assert
    ( not
        ( Provisioning.validRelativeClosureLinkForTest
            (makeRelative cacheRoot linkPath)
            (cacheRoot </> "leptonica" </> "libleptonica.6.dylib")
        )
    )
    "Sprint 1.20: the generic package-closure policy still refuses an absolute cache link now that nothing normalizes one"

-- | Phase 0 Sprint 0.24 — the development-plan standards scans.
--
-- Every scan in @Infernix.Lint.Plan@ is a proxy for a rule rather than the rule
-- itself, so the negative cases below are the point of this block rather than an
-- afterthought: each pairs a rule with the false-positive class its tuning
-- removed. A scan that cries wolf is worse than no scan, and the corpus is large
-- enough that a single spurious class would have buried the real backlog.
runPlanStandardsScanAssertions :: IO ()
runPlanStandardsScanAssertions = do
  assert
    ( not (null (statusVocabularyViolations (planSprintBlocks "1.1" "Active — Validation Only" ["- the paired lane run is open"])))
        && null (statusVocabularyViolations (planSprintBlocks "1.1" "Active" ["- the paired lane run is open"]))
    )
    "plan status scan rejects a fifth status value and accepts the Section C vocabulary"
  assert
    ( null (remainingWorkViolations (planSprintBlocks "1.1" "Done" ["None."]))
        && null (remainingWorkViolations (planSprintBlocks "1.1" "Done" []))
        && null
          ( remainingWorkViolations
              (planSprintBlocks "1.1" "Done" ["None. Closed under [Wave V](cohort-validation-waves.md)."])
          )
    )
    "plan remaining-work scan discharges Done on a bare None, an empty body, and a None that records where closure happened"
  assert
    ( not
        ( null
            ( remainingWorkViolations
                (planSprintBlocks "1.1" "Done" ["None code-side. The cohort rebuild is the residual."])
            )
        )
        && not (null (remainingWorkViolations (planSprintBlocks "1.1" "Active" ["None."])))
    )
    "plan remaining-work scan rejects a Done sprint naming a residual and an Active sprint with nothing open"
  assert
    ( not (null (remainingWorkViolations (planSprintBlocks "2.14" "Blocked" ["- wait for the ordered closure"])))
        && null
          ( remainingWorkViolations
              (planBlockedSprintBlocks "2.14" "Sprint 1.20" ["- wait for the ordered closure"])
          )
    )
    "plan remaining-work scan requires a Blocked sprint to name its blocker"
  assert
    ( not (null (sprintBackwardEdgeViolations (planBlockedSprintBlocks "6.43" "Sprint 6.45" ["- wait"])))
        && null (sprintBackwardEdgeViolations (planBlockedSprintBlocks "6.43" "Sprint 6.42" ["- wait"]))
    )
    "plan forward-edge scan rejects a blocker naming a higher-numbered sibling sprint inside one phase"
  assert
    ( not
        ( null
            ( sprintBackwardEdgeViolations
                (planSprintBlocks "6.43" "Active" ["- this sprint cannot reach `Done` before Sprint 6.45 lands"])
            )
        )
        && null
          ( sprintBackwardEdgeViolations
              (planSprintBlocks "6.43" "Active" ["- Sprint 6.45 carries the three findings", "- the paired lane run cannot close yet"])
          )
    )
    "plan forward-edge scan reads a closure dependency out of Remaining Work only when the phrase and the sprint share a line"
  assert
    ( not (null (backwardEdgeViolations [(planPhaseDocumentPath 2, planBlockerDocument ["**Blocked by**: Phase 4"])]))
        && null (backwardEdgeViolations [(planPhaseDocumentPath 2, planBlockerDocument ["**Blocked by**: Phase 1"])])
        && not
          ( null
              ( backwardEdgeViolations
                  [ ( planPhaseDocumentPath 2,
                      planBlockerDocument ["**Blocked by**: the ordered closure of", "Phase 4 and its paired lane"]
                    )
                  ]
              )
          )
    )
    "plan backward-edge scan reads a blocker statement across its wrap to the next field marker"
  assert
    ( not
        ( null
            ( backwardEdgeViolations
                [(planPhaseDocumentPath 6, planBlockerDocument ["**Blocked by**: nothing; ordered before Sprint 6.43 can reach `Done`"])]
            )
        )
    )
    "plan backward-edge scan reports a dependency phrased from the dependee's side"
  -- Section Q scan 8. The forward-edge scan reads `Blocked by` lines, so it is
  -- structurally blind to the form the violation actually takes: a sentence
  -- placing an obligation with a later sprint. Asserted in both directions, plus
  -- the exclusion that keeps a closed sprint's sanctioned forward pointer legal.
  assert
    ( not
        ( null
            ( forwardOwnershipViolations
                [(planPhaseDocumentPath 4, "the broker-side claim is owned by Phase 8 Sprint 8.12\n")]
            )
        )
        && null
          ( forwardOwnershipViolations
              [(planPhaseDocumentPath 8, "the broker-side claim is owned by Phase 4 Sprint 4.34\n")]
          )
        && not
          ( null
              ( forwardOwnershipViolations
                  [(planPhaseDocumentPath 1, "the producer is re-homed to Phase 6 Sprint 6.12\n")]
              )
          )
        && null
          ( forwardOwnershipViolations
              [(planPhaseDocumentPath 4, "**Supersession note**: Phase 8 Sprint 8.12 owns the successor\n")]
          )
    )
    "plan forward-ownership scan reports an obligation placed with a later sprint, ignores one placed with an earlier sprint, and exempts a closed sprint's supersession pointer"
  assert
    ( not
        ( null
            ( dualAcceleratorGateViolations
                [(planPhaseDocumentPath 6, planValidationDocument ["- `./bootstrap/apple-silicon.sh test`", "- `./bootstrap/linux-gpu.sh test`"])]
            )
        )
        && null
          ( dualAcceleratorGateViolations
              [(planPhaseDocumentPath 6, planValidationDocument ["- `./bootstrap/apple-silicon.sh test`", "- the paired `linux-cpu` lane"])]
          )
    )
    "plan accelerator scan rejects one Validation gate spanning both accelerators and accepts one accelerator plus linux-cpu"
  assert
    ( not (null (receiptMarkerViolations [(planPhaseDocumentPath 1, "the run completed under owned PID 54839\n")]))
        && not (null (receiptMarkerViolations [(planPhaseDocumentPath 1, "readiness stayed clean through 03:02:07\n")]))
        && not (null (receiptMarkerViolations [(planPhaseDocumentPath 1, "quarantine retained at inode 210255552\n")]))
    )
    "plan declarative scan bans the process identifier, wall-clock time, and inode number a run log carries"
  assert
    ( null
        ( receiptMarkerViolations
            [(planPhaseDocumentPath 1, "the transaction is ordered so inode allocation cannot precede the fsync\n")]
        )
    )
    "plan declarative scan admits prose reasoning about inode allocation, which is prescriptive rather than a receipt"
  assert
    ( not (null (receiptMarkerViolations [(planPhaseDocumentPath 1, planReceiptDenseDocument 41)]))
        && null (receiptMarkerViolations [(planPhaseDocumentPath 1, planReceiptDenseDocument 40)])
    )
    "plan declarative scan caps receipt-bearing lines per phase document at the declared ceiling"
  assert
    ( not (null (ledgerDoubleListingViolations [(planLedgerDocumentPath, planLedgerDocument "Sprint 1.20" "Sprint 1.20")]))
        && null (ledgerDoubleListingViolations [(planLedgerDocumentPath, planLedgerDocument "Sprint 1.20" "Sprint 1.21")])
    )
    "plan ledger scan pairs two rows only when they share their owning sprint, because symbol overlap alone is not evidence"
  assert
    ( not
        ( null
            ( phaseStatusTableViolations
                [ (planPhaseDocumentPath 1, planStatusTableDocument),
                  (planLedgerDocumentPath, planStatusTableDocument)
                ]
            )
        )
        && null
          ( phaseStatusTableViolations
              [ (planPhaseDocumentPath 1, planStatusTableDocument),
                (planLedgerDocumentPath, "| Phase 3 Sprint 3.10 host-native status residual | Closed | Sprint 3.10 |\n")
              ]
          )
    )
    "plan status-table scan reads the header's cells, so a removal-ledger row owned by a phase is not a second status table"

planPhaseDocumentPath :: Int -> FilePath
planPhaseDocumentPath phase = "DEVELOPMENT_PLAN/phase-" <> show phase <> "-fixture.md"

planLedgerDocumentPath :: FilePath
planLedgerDocumentPath = "DEVELOPMENT_PLAN/legacy-tracking-for-deletion.md"

-- | One sprint block in the Section G shape, with the given Remaining Work body.
planSprintDocument :: String -> String -> [String] -> String
planSprintDocument identifier status remainingWork =
  unlines
    ( [ "## Sprint " <> identifier <> ": Fixture [" <> status <> "]",
        "",
        "**Status**: " <> status,
        "",
        "### Remaining Work",
        ""
      ]
        <> remainingWork
        <> ["", "---"]
    )

planSprintBlocks :: String -> String -> [String] -> [SprintBlock]
planSprintBlocks identifier status remainingWork =
  parseSprintBlocks (planPhaseDocumentPath 1) (planSprintDocument identifier status remainingWork)

planBlockedSprintBlocks :: String -> String -> [String] -> [SprintBlock]
planBlockedSprintBlocks identifier blocker remainingWork =
  parseSprintBlocks
    (planPhaseDocumentPath 1)
    ( unlines
        ( [ "## Sprint " <> identifier <> ": Fixture [Blocked]",
            "",
            "**Status**: Blocked",
            "**Blocked by**: " <> blocker,
            "",
            "### Remaining Work",
            ""
          ]
            <> remainingWork
            <> ["", "---"]
        )
    )

planBlockerDocument :: [String] -> String
planBlockerDocument statementLines = unlines (statementLines <> ["", "**Docs to update**: none"])

planValidationDocument :: [String] -> String
planValidationDocument gateLines = unlines (["### Validation", ""] <> gateLines <> ["", "### Remaining Work"])

planReceiptDenseDocument :: Int -> String
planReceiptDenseDocument markerLines =
  unlines (replicate markerLines "closed under the recorded 2026-07-20 attestation")

planLedgerDocument :: String -> String -> String
planLedgerDocument pendingOwner completedOwner =
  unlines
    [ "## Pending Removal",
      "",
      "| Location | Reason | Owner |",
      "|---|---|---|",
      "| `validateRenderedEnvironment` plus `poetrySnapshotNames` and `poetrySnapshotDyldNames` | pending | " <> pendingOwner <> " |",
      "",
      "## Completed",
      "",
      "| Location | Outcome | Owner |",
      "|---|---|---|",
      "| `validateRenderedEnvironment` plus `poetrySnapshotNames` and `poetrySnapshotDyldNames` | replaced | " <> completedOwner <> " |"
    ]

planStatusTableDocument :: String
planStatusTableDocument =
  unlines
    [ "| Phase | Current status | Current gate |",
      "|-------|----------------|--------------|",
      "| 0 | Done | none |"
    ]
